insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('avatars', 'avatars', true, 2097152, array['image/png', 'image/jpeg', 'image/webp'])
on conflict (id) do update set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists avatars_public_read on storage.objects;
drop policy if exists avatars_own_insert on storage.objects;
drop policy if exists avatars_own_update on storage.objects;
drop policy if exists avatars_own_delete on storage.objects;
create policy avatars_public_read on storage.objects for select to anon, authenticated using (bucket_id = 'avatars');
create policy avatars_own_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
create policy avatars_own_update on storage.objects for update to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
create policy avatars_own_delete on storage.objects for delete to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);


-- =====================================================================================================
--  9. ONLINE BOOKING (public website → /book)
--
--  Anonymous visitors never touch the tables directly. They call these SECURITY DEFINER functions:
--    public_doctors()                          bookable doctors (no private fields)
--    public_availability(doctor, from, to)     booked slots, approved leave/blocks, hospital holidays
--    booking_otp_config()                      { required, channels } — Settings → Security → "OTP on online booking"
--    booking_otp_channels()                    which channels can deliver the code ('whatsapp', 'sms', 'email')
--    request_booking_otp(phone, channel, email) sends a 6-digit code on the chosen channel (rate limited: 1 / 30 s, 5 / hour)
--    verify_booking_otp(phone, code)           5 attempts per code, 10 minute expiry → one-time token
--    public_book_appointment(token, …, phone)  re-validates the slot server-side, then creates (token = verified code;
--                                              with booking OTP switched off: phone instead, same per-connection limits)
--                                              patient (if new) → appointment → unpaid invoice
--
--  SMS: codes are queued by public.send_booking_otp() on the channels configured in Settings → Notifications
--  and delivered by the Edge Function `notify`. With no gateway configured — and the CMS setting
--  "Show the OTP on screen" ON — the code is returned to the browser for testing.
--  All dates/times are Indian Standard Time.
-- =====================================================================================================

drop function if exists public.public_doctors() cascade;
drop function if exists public.public_availability(uuid, date, date) cascade;
drop function if exists public.request_booking_otp(text) cascade;
drop function if exists public.request_booking_otp(text, text) cascade;
drop function if exists public.booking_otp_channels() cascade;
drop function if exists public.send_booking_otp(text, text, uuid) cascade;
drop function if exists public.send_booking_otp(text, text, uuid, text[]) cascade;
drop function if exists public.send_booking_otp(text, text, uuid, text[], text) cascade;
drop function if exists public.request_booking_otp(text, text, text) cascade;
drop function if exists public.public_book_appointment(uuid, uuid, date, text, text, text, date, text, text) cascade;
drop function if exists public.booking_otp_config() cascade;
drop function if exists public.verify_booking_otp(text, text) cascade;
drop function if exists public.public_book_appointment(uuid, uuid, date, text, text, text, date, text, text) cascade;
drop function if exists public.send_booking_otp(text, text) cascade;
drop function if exists public.booking_setting(text, text, text) cascade;
drop function if exists public.norm_phone(text) cascade;

alter table public.booking_otps add column if not exists ip_hash text;   -- hashed visitor connection (per-IP OTP limit)
create index if not exists booking_otps_ip_idx on public.booking_otps (ip_hash, created_at desc) where ip_hash is not null;
alter table public.booking_otps enable row level security;   -- no policies: unreachable through the API
revoke all on public.booking_otps from anon, authenticated;

create or replace function public.norm_phone(p text)
returns text language sql immutable as $$
  select right(regexp_replace(coalesce(p, ''), '\D', '', 'g'), 10)
$$;

-- reads site_content.settings → <group> → <key> (the CMS "Online booking" / "Billing" groups)
create or replace function public.booking_setting(p_key text, p_default text, p_group text default 'booking')
returns text language sql stable security definer set search_path = public as $$
  select coalesce((public.tenant_content('settings') -> p_group ->> p_key), p_default)
$$;

-- Queues the code on the given channels (from booking_otp_channels()) and returns how many messages were queued
-- (0 = nothing could be sent → the site says "please call"). Wording: the hospital's "Booking OTP" template, or the
-- built-in one. Delivery is done by the Edge Function `notify` (supabase/functions/notify), which reads the credentials.
drop function if exists public.send_booking_otp(text, text);
create or replace function public.send_booking_otp(p_phone text, p_code text, p_ref uuid default null, p_only text[] default null, p_email text default null)
returns int language plpgsql security definer set search_path = public as $$
declare v_tpl jsonb := coalesce(public.tenant_setting('app') -> 'notifications' -> 'templates' -> 'otp', '{}'::jsonb);
begin
  if coalesce(v_tpl ->> 'text', '') = '' then v_tpl := public.otp_default_template('otp') || (v_tpl - 'text'); end if;
  if coalesce(v_tpl ->> 'subject', '') = '' then v_tpl := v_tpl || jsonb_build_object('subject', 'Your booking code'); end if;
  return coalesce(public.notify_enqueue_raw('otp', v_tpl, coalesce(p_only, public.booking_otp_channels()), p_phone, p_email, null,
                    jsonb_build_object('code', p_code, 'otp', p_code), 'booking_otps', p_ref, null), 0);
exception when undefined_function then
  return 0;
end $$;

-- Settings → Security → "OTP on online booking" (otp_verify.sql → otp_config). Default: on.
create or replace function public.booking_otp_required()
returns boolean language plpgsql stable security definer set search_path = public as $$
begin
  return coalesce((public.otp_config(public.current_tenant()) -> 'booking' ->> 'enabled')::boolean, true);
exception when undefined_function then
  return true;
end $$;

-- Channels that can deliver the booking code right now, WhatsApp first. Public (the booking page shows the choice);
-- reveals no config. With channels picked in Settings → Security → "OTP on online booking": those that are switched on
-- in Settings → Notifications. Without (older settings): switched on AND ticked for the "Booking OTP" event.
create or replace function public.booking_otp_channels()
returns text[] language plpgsql stable security definer set search_path = public as $$
declare
  n       jsonb;
  cfg     jsonb;
  allowed text[];
  ch      text;
  out     text[] := '{}';
begin
  -- plpgsql (not sql): app_settings is created later in this file set (settings.sql)
  n := public.tenant_setting('app') -> 'notifications';
  if n is null then return out; end if;
  begin cfg := public.otp_config(public.current_tenant()) -> 'booking'; exception when undefined_function then cfg := null; end;
  if jsonb_typeof(cfg -> 'channels') = 'array' then
    select coalesce(array_agg(x), '{}') into allowed from jsonb_array_elements_text(cfg -> 'channels') x;
  end if;
  foreach ch in array array['whatsapp', 'sms', 'email'] loop
    continue when coalesce((n -> ch ->> 'enabled')::boolean, false) is not true;
    if allowed is not null then
      continue when not (ch = any (allowed));
    else
      continue when not coalesce((n -> 'events' -> 'otp' ->> ch)::boolean, false) or coalesce(n -> 'templates' -> 'otp' ->> 'text', '') = '';
    end if;
    out := out || ch;
  end loop;
  return out;
end $$;

-- what the booking page needs before the last step: is a code needed, and where can it go
create or replace function public.booking_otp_config()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('required', public.booking_otp_required(), 'channels', to_jsonb(public.booking_otp_channels()))
$$;

create or replace function public.public_doctors()
returns table (id uuid, full_name text, specialization text, department text, consultation_fee numeric,
               available_days text[], shift text, status text)
language sql stable security definer set search_path = public as $$
  select d.id, d.full_name, d.specialization, dep.name, d.consultation_fee, d.available_days, d.shift, d.status
  from public.doctors d
  left join public.departments dep on dep.id = d.department_id
  where d.status = 'active' and d.tenant_id = public.current_tenant()
  order by d.full_name
$$;

create or replace function public.public_availability(p_doctor uuid, p_from date, p_to date)
returns jsonb language sql stable security definer set search_path = public as $$
  with r as (select p_from as f, least(p_to, p_from + 62) as t)
  select jsonb_build_object(
    'booked', coalesce((
      select jsonb_agg(jsonb_build_object('doctor_id', a.doctor_id, 'appointment_date', a.appointment_date,
                                          'appointment_time', a.appointment_time, 'status', a.status))
      from public.appointments a, r
      where a.tenant_id = public.current_tenant() and (p_doctor is null or a.doctor_id = p_doctor) and a.appointment_date between r.f and r.t
        and a.status not in ('cancelled', 'no_show')), '[]'::jsonb),
    'leaves', coalesce((
      select jsonb_agg(jsonb_build_object('id', l.id, 'doctor_id', l.doctor_id, 'kind', l.kind, 'status', l.status,
                                          'start_date', l.start_date, 'end_date', l.end_date,
                                          'start_time', l.start_time, 'end_time', l.end_time))
      from public.doctor_leaves l, r
      where l.tenant_id = public.current_tenant() and (p_doctor is null or l.doctor_id = p_doctor) and l.status = 'approved'
        and l.start_date <= r.t and l.end_date >= r.f), '[]'::jsonb),
    'holidays', coalesce((
      select jsonb_agg(jsonb_build_object('id', h.id, 'holiday_date', h.holiday_date, 'name', h.name))
      from public.holidays h, r where h.tenant_id = public.current_tenant() and h.holiday_date between r.f and r.t), '[]'::jsonb))
$$;

-- p_channel: 'whatsapp', 'sms' or 'email' as picked by the visitor; null / unavailable → every available channel
-- (email only when p_email is given — the code goes to that address, the booking still belongs to the mobile number)
create or replace function public.request_booking_otp(p_phone text, p_channel text default null, p_email text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_phone  text := public.norm_phone(p_phone);
  v_code   text;
  v_queued int;
  v_id     uuid;
  v_avail  text[] := public.booking_otp_channels();
  v_use    text[];
  v_ip     text := public.client_ip_hash();
  v_email  text := nullif(lower(trim(coalesce(p_email, ''))), '');
begin
  if public.booking_setting('enabled', 'true') <> 'true' then
    raise exception 'Online booking is switched off right now. Please call the hospital to book.';
  end if;
  if v_phone !~ '^[6-9][0-9]{9}$' then
    raise exception 'Please enter a valid 10-digit Indian mobile number.';
  end if;
  if v_email is not null and v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'Please enter a valid email address.';
  end if;
  if p_channel = 'email' and v_email is null then
    raise exception 'Enter your email address to get the code by email.';
  end if;
  if exists (select 1 from public.booking_otps where tenant_id = public.current_tenant() and phone = v_phone and created_at > now() - interval '30 seconds') then
    raise exception 'Please wait 30 seconds before requesting another code.';
  end if;
  if (select count(*) from public.booking_otps where tenant_id = public.current_tenant() and phone = v_phone and created_at > now() - interval '1 hour') >= 5 then
    raise exception 'Too many codes requested for this number. Please try again in an hour.';
  end if;
  -- one connection can't cycle through numbers either (hashed IP; the whole-site cap below is the backstop)
  if v_ip is not null and (select count(*) from public.booking_otps where ip_hash = v_ip and created_at > now() - interval '1 hour')
     >= greatest(3, coalesce(nullif(public.booking_setting('otpIpHourlyLimit', '10'), '')::int, 10)) then
    raise exception 'Too many codes requested from this connection. Please try again in an hour or call the hospital.';
  end if;
  -- whole-site cap: stops bots cycling through thousands of numbers to run up the SMS bill ("SMS pumping")
  if (select count(*) from public.booking_otps where tenant_id = public.current_tenant() and created_at > now() - interval '1 hour')
     >= greatest(10, coalesce(nullif(public.booking_setting('otpHourlyLimit', '200'), '')::int, 200)) then
    raise exception 'Online booking is very busy right now. Please try again in a few minutes or call the hospital.';
  end if;

  v_code := lpad(((('x' || encode(extensions.gen_random_bytes(4), 'hex'))::bit(32)::bigint) % 1000000)::text, 6, '0');
  insert into public.booking_otps (phone, code_hash, expires_at, ip_hash)
  values (v_phone, extensions.crypt(v_code, extensions.gen_salt('bf', 6)), now() + interval '10 minutes', v_ip)
  returning id into v_id;
  v_use := case when p_channel = any (v_avail) then array[p_channel] else v_avail end;
  if v_email is null then v_use := array_remove(v_use, 'email'); end if;
  v_queued := case when cardinality(v_use) > 0 then public.send_booking_otp(v_phone, v_code, v_id, v_use, v_email) else 0 end;

  -- the code never goes back to the browser — only by SMS / WhatsApp (queued = 0 → the site says "please call")
  -- `ref` lets the browser ask the notify function to deliver exactly this message right away
  -- …except in the demo hospital when the team chose "show codes on screen" (demo.sql): nothing is sent there
  if public.demo_otp_screen(public.current_tenant()) then
    return jsonb_build_object('sent', true, 'expires_in', 600, 'queued', greatest(v_queued, 1), 'ref', v_id,
      'channels', to_jsonb(v_use), 'demo_code', v_code);
  end if;
  return jsonb_build_object('sent', v_queued > 0, 'expires_in', 600, 'queued', v_queued, 'ref', v_id,
    'channels', case when v_queued > 0 then to_jsonb(v_use) else '[]'::jsonb end);
end $$;

-- returns {ok:true, token} or {ok:false, error} (no exception, so the failed-attempt counter is kept)
create or replace function public.verify_booking_otp(p_phone text, p_code text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_phone text := public.norm_phone(p_phone);
  o       public.booking_otps;
  v_token uuid;
begin
  select * into o from public.booking_otps
  where tenant_id = public.current_tenant() and phone = v_phone and verified_at is null
  order by created_at desc limit 1
  for update;

  if not found or o.expires_at < now() then
    return jsonb_build_object('ok', false, 'error', 'This code has expired. Please request a new one.');
  end if;
  if o.attempts >= 5 then
    return jsonb_build_object('ok', false, 'error', 'Too many wrong attempts. Please request a new code.');
  end if;
  if coalesce(p_code, '') !~ '^[0-9]{6}$' or o.code_hash <> extensions.crypt(p_code, o.code_hash) then
    update public.booking_otps set attempts = attempts + 1 where id = o.id;
    return jsonb_build_object('ok', false, 'error',
      case when o.attempts + 1 >= 5 then 'Too many wrong attempts. Please request a new code.'
           else format('That code is not correct — %s attempt%s left.', 4 - o.attempts, case when 4 - o.attempts = 1 then '' else 's' end) end);
  end if;

  v_token := gen_random_uuid();
  update public.booking_otps set verified_at = now(), token = v_token where id = o.id;
  return jsonb_build_object('ok', true, 'token', v_token);
end $$;

-- Why a slot can't be booked (same rules as src/lib/schedule.ts), or null when it is free to book.
-- Double-booking itself is prevented by the unique index appointments_one_per_slot.
drop function if exists public.slot_problem(uuid, date, text, boolean) cascade;
create function public.slot_problem(p_doctor uuid, p_date date, p_time text, p_enforce_window boolean default true)
returns text language plpgsql stable security definer set search_path = public as $$
declare
  d         public.doctors;
  v_now     timestamp := now() at time zone 'Asia/Kolkata';
  v_min     int;
  v_shift   text[];
  v_advance int := coalesce(nullif(public.booking_setting('advanceDays', '30'), '')::int, 30);
  v_notice  int := coalesce(nullif(public.booking_setting('minNoticeMinutes', '60'), '')::int, 60);
begin
  if coalesce(p_time, '') !~ '^[0-2][0-9]:[0-5][0-9]$' then return 'Invalid time.'; end if;
  v_min := split_part(p_time, ':', 1)::int * 60 + split_part(p_time, ':', 2)::int;
  select * into d from public.doctors where id = p_doctor and tenant_id = public.current_tenant();
  if not found or d.status <> 'active' then return 'This doctor is not taking bookings right now.'; end if;
  if p_date < v_now::date then return 'This date is in the past.'; end if;
  if p_enforce_window and p_date > v_now::date + v_advance then return format('Please choose a date within the next %s days.', v_advance); end if;
  if p_enforce_window and p_date + make_interval(mins => v_min) < v_now + make_interval(mins => v_notice) then
    return 'This time is too soon — please pick a later slot.';
  end if;
  if not p_enforce_window and p_date + make_interval(mins => v_min) < v_now then return 'This time has already passed.'; end if;
  if v_min % 30 <> 0 or v_min < 480 or v_min > 1110 then return 'Invalid time.'; end if;
  if exists (select 1 from public.holidays where tenant_id = public.current_tenant() and holiday_date = p_date) then return 'The OPD is closed on this day.'; end if;
  if not (to_char(p_date, 'Dy') = any (coalesce(nullif(d.available_days, '{}'), array['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']))) then
    return 'The doctor does not consult on this day.';
  end if;
  v_shift := regexp_match(coalesce(d.shift, ''), '(\d{1,2}):(\d{2})\s*[-–—]\s*(\d{1,2}):(\d{2})');
  if v_shift is not null and (v_min < v_shift[1]::int * 60 + v_shift[2]::int or v_min >= v_shift[3]::int * 60 + v_shift[4]::int) then
    return 'Outside the doctor''s consulting hours.';
  end if;
  if exists (
    select 1 from public.doctor_leaves l
    where l.doctor_id = d.id and l.status = 'approved' and p_date between l.start_date and l.end_date
      and (l.start_time is null
           or (v_min >= split_part(l.start_time, ':', 1)::int * 60 + split_part(l.start_time, ':', 2)::int
               and v_min < split_part(l.end_time, ':', 1)::int * 60 + split_part(l.end_time, ':', 2)::int))
  ) then
    return 'The doctor is unavailable at this time.';
  end if;
  return null;
end $$;

-- Books a slot for an already-verified mobile number (OTP on the website, or the WhatsApp sender itself).
-- Internal: only called by public_book_appointment / whatsapp_book_appointment.
drop function if exists public.book_slot_internal(text, uuid, date, text, text, text, date, text, text, text) cascade;
create function public.book_slot_internal(
  p_phone text, p_doctor uuid, p_date date, p_time text,
  p_name text, p_gender text, p_dob date, p_email text, p_reason text, p_source text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  d         public.doctors;
  v_patient public.patients;
  v_appt    public.appointments;
  v_inv     public.invoices;
  v_dep     text;
  v_now     timestamp := now() at time zone 'Asia/Kolkata';
  v_new     boolean := false;
  v_name    text := regexp_replace(trim(coalesce(p_name, '')), '\s+', ' ', 'g');
  v_phone   text := public.norm_phone(p_phone);
  v_problem text;
  v_ref     text;
  v_seq     int;
  v_fee     numeric;
  v_rate    numeric;
  v_tax     numeric;
begin
  if public.booking_setting('enabled', 'true') <> 'true' then
    raise exception 'Online booking is switched off right now. Please call the hospital to book.';
  end if;
  if v_phone !~ '^[6-9][0-9]{9}$' then raise exception 'Please enter a valid 10-digit Indian mobile number.'; end if;

  -- input
  if char_length(v_name) < 2 or char_length(v_name) > 80 then raise exception 'Please enter the patient''s full name.'; end if;
  if p_gender is null or p_gender not in ('male', 'female', 'other') then p_gender := 'other'; end if;
  if p_dob is not null and (p_dob > v_now::date or p_dob < v_now::date - 43830) then raise exception 'Please check the date of birth.'; end if;
  if nullif(trim(p_email), '') is not null and trim(p_email) !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Please check the email address.'; end if;

  -- the slot must really be free
  v_problem := public.slot_problem(p_doctor, p_date, p_time, true);
  if v_problem is not null then raise exception 'SLOT_UNAVAILABLE: %', v_problem; end if;
  select * into d from public.doctors where id = p_doctor and tenant_id = public.current_tenant();

  -- patient: same mobile AND same name → existing record (families often share one phone)
  select * into v_patient from public.patients
  where tenant_id = public.current_tenant() and public.norm_phone(phone) = v_phone and lower(regexp_replace(trim(full_name), '\s+', ' ', 'g')) = lower(v_name)
  order by created_at limit 1;

  if v_patient.id is not null then
    if exists (select 1 from public.appointments where patient_id = v_patient.id and doctor_id = d.id
               and appointment_date = p_date and status not in ('cancelled', 'no_show')) then
      raise exception 'You already have a booking with this doctor on this day.';
    end if;
  else
    -- mrn '' → assign_record_number() numbers it per hospital
    insert into public.patients (mrn, full_name, gender, date_of_birth, phone, email, status)
    values ('', v_name, p_gender, p_dob, '+91 ' || substr(v_phone, 1, 5) || ' ' || substr(v_phone, 6),
            nullif(lower(trim(p_email)), ''), 'outpatient')
    returning * into v_patient;
    v_new := true;
  end if;

  -- appointment (the partial unique index settles a race for the same slot)
  v_ref := 'DCB-' || upper(encode(extensions.gen_random_bytes(3), 'hex'));
  begin
    insert into public.appointments (patient_id, doctor_id, appointment_date, appointment_time, type, status, reason, source, booking_ref)
    values (v_patient.id, d.id, p_date, p_time, 'consultation', 'scheduled', nullif(left(trim(p_reason), 500), ''), p_source, v_ref)
    returning * into v_appt;
  exception when unique_violation then
    raise exception 'SLOT_TAKEN: Sorry — someone just booked this slot. Please pick another time.';
  end;

  -- unpaid invoice (GST % from Settings → Billing; 0 = exempt → Bill of Supply)
  v_fee  := d.consultation_fee;
  v_rate := coalesce(nullif(public.booking_setting('gstRate', '0', 'billing'), '')::numeric, 0);
  v_tax  := round(v_fee * v_rate / 100, 2);
  -- invoice_number '' → assign_record_number() numbers it per hospital
  insert into public.invoices (invoice_number, patient_id, issue_date, due_date, items, subtotal, tax, discount, total, amount_paid, status, notes)
  values ('', v_patient.id, v_now::date, p_date,
          jsonb_build_array(jsonb_build_object(
            'description', format('Consultation — %s (%s) · %s, %s', d.full_name, d.specialization, to_char(p_date, 'DD Mon YYYY'), p_time),
            'quantity', 1, 'unit_price', v_fee)),
          v_fee, v_tax, 0, v_fee + v_tax, 0, 'unpaid', initcap(p_source) || ' booking ' || v_ref)
  returning * into v_inv;

  select name into v_dep from public.departments where id = d.department_id;
  return jsonb_build_object(
    'ref', v_ref,
    'is_new_patient', v_new,
    'appointment', to_jsonb(v_appt) - 'notes',
    'patient', jsonb_build_object('id', v_patient.id, 'full_name', v_patient.full_name, 'mrn', v_patient.mrn,
                                  'phone', v_patient.phone, 'email', v_patient.email, 'gender', v_patient.gender,
                                  'address', v_patient.address),
    'doctor', jsonb_build_object('id', d.id, 'full_name', d.full_name, 'specialization', d.specialization, 'department', v_dep),
    'invoice', to_jsonb(v_inv));
end $$;
revoke all on function public.book_slot_internal(text, uuid, date, text, text, text, date, text, text, text) from public, anon, authenticated;

create or replace function public.public_book_appointment(
  p_token uuid, p_doctor uuid, p_date date, p_time text,
  p_name text, p_gender text, p_dob date, p_email text, p_reason text, p_phone text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  o       public.booking_otps;
  v_res   jsonb;
  v_phone text := public.norm_phone(p_phone);
  v_ip    text := public.client_ip_hash();
begin
  perform set_config('app.actor_name', 'Website booking', true);
  perform set_config('app.actor_role', 'public', true);
  if public.booking_setting('enabled', 'true') <> 'true' then
    raise exception 'Online booking is switched off right now. Please call the hospital to book.';
  end if;
  -- booking OTP switched off (Settings → Security): the mobile number as typed, with the same per-number, per-connection
  -- and whole-site limits as the code requests (each booking is recorded as an already-used verification row)
  if p_token is null then
    if public.booking_otp_required() then
      raise exception 'OTP_REQUIRED: Please verify your mobile number first.';
    end if;
    if v_phone !~ '^[6-9][0-9]{9}$' then
      raise exception 'Please enter a valid 10-digit Indian mobile number.';
    end if;
    if (select count(*) from public.booking_otps where tenant_id = public.current_tenant() and phone = v_phone and created_at > now() - interval '1 hour') >= 5 then
      raise exception 'Too many bookings for this number. Please try again in an hour or call the hospital.';
    end if;
    if v_ip is not null and (select count(*) from public.booking_otps where ip_hash = v_ip and created_at > now() - interval '1 hour')
       >= greatest(3, coalesce(nullif(public.booking_setting('otpIpHourlyLimit', '10'), '')::int, 10)) then
      raise exception 'Too many bookings from this connection. Please try again in an hour or call the hospital.';
    end if;
    if (select count(*) from public.booking_otps where tenant_id = public.current_tenant() and created_at > now() - interval '1 hour')
       >= greatest(10, coalesce(nullif(public.booking_setting('otpHourlyLimit', '200'), '')::int, 200)) then
      raise exception 'Online booking is very busy right now. Please try again in a few minutes or call the hospital.';
    end if;
    v_res := public.book_slot_internal(v_phone, p_doctor, p_date, p_time, p_name, p_gender, p_dob, p_email, p_reason, 'website');
    insert into public.booking_otps (phone, code_hash, expires_at, ip_hash, verified_at, token_used_at)
    values (v_phone, '-', now(), v_ip, now(), now());
    return v_res;
  end if;
  -- verified phone (one booking per verification, valid 30 minutes)
  select * into o from public.booking_otps where token = p_token and tenant_id = public.current_tenant() for update;
  if not found or o.verified_at is null or o.token_used_at is not null or o.verified_at < now() - interval '30 minutes' then
    raise exception 'OTP_REQUIRED: Please verify your mobile number again.';
  end if;
  v_res := public.book_slot_internal(o.phone, p_doctor, p_date, p_time, p_name, p_gender, p_dob, p_email, p_reason, 'website');
  update public.booking_otps set token_used_at = now() where id = o.id;
  return v_res;
end $$;

-- WhatsApp chatbot bookings: the sender's number is already verified by WhatsApp. Service role only
-- (called by the Edge Function supabase/functions/whatsapp-bot).
drop function if exists public.whatsapp_book_appointment(text, uuid, date, text, text, text) cascade;
create function public.whatsapp_book_appointment(p_phone text, p_doctor uuid, p_date date, p_time text, p_name text, p_reason text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  perform set_config('app.actor_name', 'WhatsApp booking', true);
  perform set_config('app.actor_role', 'public', true);
  return public.book_slot_internal(p_phone, p_doctor, p_date, p_time, p_name, 'other', null, null, p_reason, 'whatsapp');
end $$;
revoke all on function public.whatsapp_book_appointment(text, uuid, date, text, text, text) from public, anon, authenticated;
grant execute on function public.whatsapp_book_appointment(text, uuid, date, text, text, text) to service_role;
grant execute on function public.public_doctors() to service_role;
grant execute on function public.public_availability(uuid, date, date) to service_role;

revoke all on function public.send_booking_otp(text, text, uuid, text[], text) from public, anon, authenticated;
revoke all on function public.slot_problem(uuid, date, text, boolean) from public, anon;
grant execute on function public.slot_problem(uuid, date, text, boolean) to authenticated;
revoke all on function public.booking_setting(text, text, text) from public, anon;
grant execute on function public.public_doctors() to anon, authenticated;
grant execute on function public.public_availability(uuid, date, date) to anon, authenticated;
grant execute on function public.request_booking_otp(text, text, text) to anon, authenticated;
grant execute on function public.booking_otp_config() to anon, authenticated;
revoke all on function public.booking_otp_required() from public;
grant execute on function public.booking_otp_required() to anon, authenticated, service_role;
grant execute on function public.booking_otp_channels() to anon, authenticated;
grant execute on function public.verify_booking_otp(text, text) to anon, authenticated;
grant execute on function public.public_book_appointment(uuid, uuid, date, text, text, text, date, text, text, text) to anon, authenticated;


-- =====================================================================================================
--  11. HOSPITAL SETTINGS · CREDENTIALS · NOTIFICATIONS (SMS / WhatsApp / Email)
--
--    app_settings          one row ('app') with the dashboard settings JSON. Everyone signed in can read it
--                          (theme, date format…); only the owner can change it.
--    app_secrets           API keys / passwords. WRITE-ONLY from the browser: the owner sets them through
--                          set_app_secret() and only sees a masked hint (app_secret_status()). The Edge Function
--                          `notify` reads them with the service-role key.
--    notification_outbox   messages queued by triggers (appointment booked, reminder, invoice, lab report…)
--                          and by the booking OTP. The Edge Function claims and delivers them.
--
--  These tables are NOT dropped when this file is re-run, so saved settings and credentials survive.
--  Deploy the sender once:   supabase functions deploy notify
--  Optional automatic delivery + reminders with pg_cron + pg_net (Database → Extensions), e.g.:
--    select cron.schedule('notify-flush', '* * * * *', $c$ select net.http_post(
--      url := 'https://<project-ref>.supabase.co/functions/v1/notify',
--      headers := jsonb_build_object('Authorization', 'Bearer <service-role-key>', 'Content-Type', 'application/json'),
--      body := '{"flush":true}'::jsonb) $c$);
--    select cron.schedule('appointment-reminders', '30 12 * * *', $c$ select public.queue_appointment_reminders() $c$);  -- 18:00 IST
-- =====================================================================================================

-- ------------------------------------------------------------------ settings
create table if not exists public.app_settings (
  key              text primary key,
  data             jsonb not null default '{}'::jsonb,
  updated_at       timestamptz not null default now(),
  updated_by       uuid,
  updated_by_name  text
);
alter table public.app_settings enable row level security;
revoke all on public.app_settings from anon;
grant select, insert, update on public.app_settings to authenticated;
grant all on public.app_settings to service_role;

drop policy if exists app_settings_read on public.app_settings;
drop policy if exists app_settings_owner_insert on public.app_settings;
drop policy if exists app_settings_owner_update on public.app_settings;
create policy app_settings_read on public.app_settings for select to authenticated using (true);
create policy app_settings_owner_insert on public.app_settings for insert to authenticated with check (public.has_role('owner'));
create policy app_settings_owner_update on public.app_settings for update to authenticated using (public.has_role('owner')) with check (public.has_role('owner'));

drop function if exists public.app_settings_stamp() cascade;
create function public.app_settings_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_changes jsonb := '{}'::jsonb;
  k text;
  v_name text := (select full_name from public.profiles where id = auth.uid());
begin
  new.updated_at := now();
  new.updated_by := auth.uid();
  new.updated_by_name := coalesce(v_name, 'Database');
  -- audit: which sections changed
  for k in select jsonb_object_keys(new.data) loop
    if tg_op = 'INSERT' or (new.data -> k) is distinct from (old.data -> k) then
      v_changes := v_changes || jsonb_build_object(k, jsonb_build_object('from', case when tg_op = 'UPDATE' then old.data -> k end, 'to', new.data -> k));
    end if;
  end loop;
  if v_changes <> '{}'::jsonb then
    insert into public.audit_log (table_name, record_id, action, actor_id, actor_name, actor_role, summary, changes)
    values ('app_settings', null, lower(tg_op), auth.uid(), coalesce(v_name, 'System'),
            coalesce((select role::text from public.profiles where id = auth.uid()), 'system'), 'Hospital settings', v_changes);
  end if;
  return new;
end $$;
create trigger trg_app_settings_stamp before insert or update on public.app_settings
  for each row execute function public.app_settings_stamp();

-- ------------------------------------------------------------------ credentials (write-only)
create table if not exists public.app_secrets (
  key              text primary key check (key ~ '^[a-z0-9_]{2,64}$'),
  value            text not null,
  updated_at       timestamptz not null default now(),
  updated_by_name  text
);
alter table public.app_secrets enable row level security;   -- no policies: unreachable through the API
revoke all on public.app_secrets from anon, authenticated;
grant all on public.app_secrets to service_role;

drop function if exists public.app_secret_status() cascade;
create function public.app_secret_status()
returns table (key text, hint text, updated_at timestamptz, updated_by_name text)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_role('owner') then
    raise exception 'Only the hospital owner can view credentials';
  end if;
  return query
    select s.key, '••••' || case when length(s.value) >= 12 then right(s.value, 4) else '' end, s.updated_at, s.updated_by_name
    from public.app_secrets s where s.tenant_id = public.current_tenant() order by s.key;
end $$;

drop function if exists public.set_app_secret(text, text) cascade;
create function public.set_app_secret(p_key text, p_value text)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_name text := (select full_name from public.profiles where id = auth.uid());
begin
  if not public.has_role('owner') then
    raise exception 'Only the hospital owner can change credentials';
  end if;
  perform public.module_guard('notifications');
  if p_key !~ '^[a-z0-9_]{2,64}$' then
    raise exception 'Invalid credential name';
  end if;
  if nullif(trim(coalesce(p_value, '')), '') is null then
    delete from public.app_secrets where key = p_key and tenant_id = public.current_tenant();
  else
    insert into public.app_secrets (key, value, updated_at, updated_by_name)
    values (p_key, trim(p_value), now(), v_name)
    on conflict (tenant_id, key) do update set value = excluded.value, updated_at = now(), updated_by_name = excluded.updated_by_name;
  end if;
  insert into public.audit_log (table_name, record_id, action, actor_id, actor_name, actor_role, summary, changes)
  values ('app_secrets', null, case when nullif(trim(coalesce(p_value, '')), '') is null then 'delete' else 'update' end,
          auth.uid(), coalesce(v_name, 'System'), 'owner', 'Credential ' || p_key,
          jsonb_build_object(p_key, jsonb_build_object('to', case when nullif(trim(coalesce(p_value, '')), '') is null then 'removed' else 'updated (hidden)' end)));
end $$;

revoke all on function public.app_secret_status() from public, anon;
revoke all on function public.set_app_secret(text, text) from public, anon;
grant execute on function public.app_secret_status() to authenticated;
grant execute on function public.set_app_secret(text, text) to authenticated;

-- ------------------------------------------------------------------ outbox
create table if not exists public.notification_outbox (
  id             uuid primary key default gen_random_uuid(),
  event          text not null,
  channel        text not null check (channel in ('sms', 'whatsapp', 'email')),
  recipient      text not null,
  subject        text,
  body           text not null default '',
  vars           jsonb not null default '{}'::jsonb,
  status         text not null default 'pending' check (status in ('pending', 'sending', 'sent', 'failed', 'skipped')),
  attempts       int not null default 0,
  error          text,
  provider_ref   text,
  related_table  text,
  related_id     uuid,
  created_at     timestamptz not null default now(),
  sent_at        timestamptz
);
-- retry bookkeeping (added later; `if not exists` keeps re-runs safe)
alter table public.notification_outbox add column if not exists last_attempt_at timestamptz;
alter table public.notification_outbox add column if not exists next_attempt_at timestamptz not null default now();
create index if not exists notification_outbox_queue_idx on public.notification_outbox (status, created_at);
create index if not exists notification_outbox_related_idx on public.notification_outbox (related_id, event);

alter table public.notification_outbox enable row level security;
revoke all on public.notification_outbox from anon, authenticated;
-- the delivery log is visible to the owner, but never the message body (it can contain an OTP)
grant select (id, event, channel, recipient, status, attempts, error, provider_ref, related_table, related_id, created_at, sent_at)
  on public.notification_outbox to authenticated;
grant all on public.notification_outbox to service_role;
drop policy if exists notification_outbox_owner_read on public.notification_outbox;
create policy notification_outbox_owner_read on public.notification_outbox for select to authenticated using (public.has_role('owner'));

-- Queue one message per enabled channel for an event. Never raises (a failed notification must not
-- roll back the booking / invoice that triggered it).
drop function if exists public.notify_enqueue(text, text, text, jsonb, text, uuid) cascade;
drop function if exists public.notify_enqueue(text, text, text, jsonb, text, uuid, text[]) cascade;
drop function if exists public.notify_enqueue(text, text, text, jsonb, text, uuid, text[], uuid) cascade;  -- section 18 version (re-run safety)
-- p_only: restrict to these channels (e.g. the booking OTP channel the visitor picked); null = every enabled channel
create function public.notify_enqueue(p_event text, p_phone text, p_email text, p_vars jsonb, p_related_table text default null, p_related_id uuid default null, p_only text[] default null)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  n        jsonb := (public.tenant_setting('app') -> 'notifications');
  site     jsonb := public.tenant_content('settings');
  tpl      jsonb;
  ch       text;
  v_to     text;
  v_body   text;
  v_subj   text;
  v_vars   jsonb;
  k        text;
  v_count  int := 0;
begin
  if n is null or n -> 'events' -> p_event is null then return 0; end if;
  tpl := n -> 'templates' -> p_event;
  v_vars := jsonb_build_object(
      'hospital', coalesce(nullif(site ->> 'name', ''), 'DC Hospital'),
      'hospital_phone', coalesce(nullif(site ->> 'appointmentsPhone', ''), site ->> 'phone', ''),
      'address', coalesce(site ->> 'address', ''),
      'site_url', rtrim(coalesce(site ->> 'siteUrl', ''), '/'))
    || coalesce(p_vars, '{}'::jsonb);

  foreach ch in array array['sms', 'whatsapp', 'email'] loop
    continue when coalesce((n -> 'events' -> p_event ->> ch)::boolean, false) is not true;
    continue when coalesce((n -> ch ->> 'enabled')::boolean, false) is not true;
    continue when p_only is not null and not (ch = any (p_only));
    if ch = 'email' then
      v_to := nullif(lower(trim(coalesce(p_email, ''))), '');
      continue when v_to is null or v_to !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$';
    else
      v_to := right(regexp_replace(coalesce(p_phone, ''), '\D', '', 'g'), 10);
      continue when v_to !~ '^[6-9][0-9]{9}$';
    end if;
    -- WhatsApp may have its own wording (bold, emoji, line breaks); otherwise the shared text is used
    v_body := case when ch = 'whatsapp' and coalesce(tpl ->> 'waText', '') <> '' then tpl ->> 'waText' else coalesce(tpl ->> 'text', '') end;
    v_subj := coalesce(tpl ->> 'subject', '');
    continue when v_body = '';
    for k in select jsonb_object_keys(v_vars) loop
      v_body := replace(v_body, '{' || k || '}', coalesce(v_vars ->> k, ''));
      v_subj := replace(v_subj, '{' || k || '}', coalesce(v_vars ->> k, ''));
    end loop;
    insert into public.notification_outbox (event, channel, recipient, subject, body, vars, related_table, related_id)
    values (p_event, ch, v_to, nullif(v_subj, ''), v_body, v_vars, p_related_table, p_related_id);
    v_count := v_count + 1;
  end loop;
  return v_count;
exception when others then
  raise warning 'notify_enqueue(%) failed: %', p_event, sqlerrm;
  return 0;
end $$;
revoke all on function public.notify_enqueue(text, text, text, jsonb, text, uuid, text[]) from public, anon, authenticated;

create or replace function public.fmt_appt_time(t text)
returns text language sql immutable as $$ select trim(to_char(t::time, 'FMHH12:MI AM')) $$;

-- ------------------------------------------------------------------ event triggers
drop function if exists public.notify_appointment() cascade;
create function public.notify_appointment()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  p public.patients;
  d public.doctors;
  v_event text;
begin
  if tg_op = 'INSERT' then
    if new.status = 'cancelled' then return new; end if;
    v_event := 'appointment_booked';
  elsif new.status = 'cancelled' and old.status is distinct from 'cancelled' then
    v_event := 'appointment_cancelled';
  elsif new.status <> 'cancelled' and (new.appointment_date, new.appointment_time) is distinct from (old.appointment_date, old.appointment_time) then
    v_event := 'appointment_rescheduled';
  else
    return new;
  end if;
  if new.appointment_date < (now() at time zone 'Asia/Kolkata')::date then return new; end if;  -- back-dated entry
  select * into p from public.patients where id = new.patient_id;
  select * into d from public.doctors where id = new.doctor_id;
  perform public.notify_enqueue(v_event, p.phone, p.email, jsonb_build_object(
    'name', split_part(p.full_name, ' ', 1), 'patient', p.full_name, 'doctor', d.full_name,
    'date', to_char(new.appointment_date, 'Dy, DD Mon YYYY'), 'time', public.fmt_appt_time(new.appointment_time),
    'ref', coalesce(new.booking_ref, upper(left(new.id::text, 8)))), 'appointments', new.id);
  return new;
exception when others then
  raise warning 'notify_appointment: %', sqlerrm;
  return new;
end $$;
create trigger trg_appointments_notify after insert or update on public.appointments
  for each row execute function public.notify_appointment();

drop function if exists public.notify_invoice() cascade;
create function public.notify_invoice()
returns trigger language plpgsql security definer set search_path = public as $$
declare p public.patients;
begin
  if new.status not in ('unpaid', 'partial', 'overdue') then return new; end if;
  select * into p from public.patients where id = new.patient_id;
  perform public.notify_enqueue('invoice_created', p.phone, p.email, jsonb_build_object(
    'name', split_part(p.full_name, ' ', 1), 'invoice', new.invoice_number,
    'amount', '₹' || trim(to_char(new.total, 'FM99,99,99,990.00')),
    'due_date', coalesce(to_char(new.due_date, 'DD Mon YYYY'), 'on receipt')), 'invoices', new.id);
  return new;
exception when others then
  raise warning 'notify_invoice: %', sqlerrm;
  return new;
end $$;
create trigger trg_invoices_notify after insert on public.invoices
  for each row execute function public.notify_invoice();

drop function if exists public.notify_payment() cascade;
create function public.notify_payment()
returns trigger language plpgsql security definer set search_path = public as $$
declare p public.patients; v_inv text;
begin
  select * into p from public.patients where id = new.patient_id;
  select invoice_number into v_inv from public.invoices where id = new.invoice_id;
  perform public.notify_enqueue('payment_received', p.phone, p.email, jsonb_build_object(
    'name', split_part(p.full_name, ' ', 1), 'invoice', coalesce(v_inv, ''),
    'amount', '₹' || trim(to_char(new.amount, 'FM99,99,99,990.00')),
    'method', initcap(replace(new.method, '_', ' '))), 'payments', new.id);
  return new;
exception when others then
  raise warning 'notify_payment: %', sqlerrm;
  return new;
end $$;
create trigger trg_payments_notify after insert on public.payments
  for each row execute function public.notify_payment();

drop function if exists public.notify_lab() cascade;
create function public.notify_lab()
returns trigger language plpgsql security definer set search_path = public as $$
declare p public.patients;
begin
  if new.status <> 'completed' or old.status = 'completed' then return new; end if;
  select * into p from public.patients where id = new.patient_id;
  perform public.notify_enqueue('lab_report_ready', p.phone, p.email, jsonb_build_object(
    'name', split_part(p.full_name, ' ', 1), 'test', new.test_name), 'lab_tests', new.id);
  return new;
exception when others then
  raise warning 'notify_lab: %', sqlerrm;
  return new;
end $$;
create trigger trg_lab_tests_notify after update on public.lab_tests
  for each row execute function public.notify_lab();

-- Queue tomorrow's reminders (idempotent). Run daily with pg_cron, or from Settings → Notifications.
drop function if exists public.queue_appointment_reminders() cascade;
create function public.queue_appointment_reminders()
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  r record;
  v_count int := 0;
  v_t uuid;
  v_day date := (now() at time zone 'Asia/Kolkata')::date + 1;
begin
  if auth.uid() is not null and not public.has_role('owner', 'receptionist') then
    raise exception 'Not allowed';
  end if;
  -- the daily cron job: once per hospital, so each reminder uses that hospital's templates and providers
  if auth.uid() is null and nullif(current_setting('app.tenant_id', true), '') is null then
    for v_t in select id from public.tenants where status <> 'suspended' order by created_at loop
      perform set_config('app.tenant_id', v_t::text, true);
      v_count := v_count + public.queue_appointment_reminders();
    end loop;
    perform set_config('app.tenant_id', '', true);
    return v_count;
  end if;
  for r in
    select a.*, p.full_name as p_name, p.phone as p_phone, p.email as p_email, d.full_name as d_name
    from public.appointments a
    join public.patients p on p.id = a.patient_id
    join public.doctors d on d.id = a.doctor_id
    where a.tenant_id = public.current_tenant() and a.appointment_date = v_day and a.status in ('scheduled', 'confirmed')
      and not exists (select 1 from public.notification_outbox o where o.related_id = a.id and o.event = 'appointment_reminder')
  loop
    v_count := v_count + public.notify_enqueue('appointment_reminder', r.p_phone, r.p_email, jsonb_build_object(
      'name', split_part(r.p_name, ' ', 1), 'patient', r.p_name, 'doctor', r.d_name,
      'date', to_char(r.appointment_date, 'Dy, DD Mon YYYY'), 'time', public.fmt_appt_time(r.appointment_time),
      'ref', coalesce(r.booking_ref, upper(left(r.id::text, 8)))), 'appointments', r.id);
  end loop;
  return v_count;
end $$;
revoke all on function public.queue_appointment_reminders() from public, anon;
grant execute on function public.queue_appointment_reminders() to authenticated, service_role;

-- Used by the Edge Function (service role) to take a batch of messages to deliver.
-- claim_notifications(p_limit, p_tenant) — the queue for the notify Edge Function — lives in messaging.sql.

-- Deliver specific fresh messages right away (e.g. the OTP a visitor just requested). Used by the notify
-- function for callers that may not flush the whole queue (anonymous visitors, patients).
drop function if exists public.claim_notifications_for(uuid[]) cascade;
create function public.claim_notifications_for(p_ids uuid[])
returns setof public.notification_outbox language plpgsql volatile security definer set search_path = public as $$
begin
  return query
    update public.notification_outbox o set status = 'sending', attempts = o.attempts + 1, last_attempt_at = now()
    where o.id in (
      select x.id from public.notification_outbox x
      where x.status = 'pending' and x.attempts = 0 and x.created_at > now() - interval '15 minutes'
        and (x.id = any (p_ids) or x.related_id = any (p_ids))
      order by x.created_at
      limit 10
      for update skip locked)
    returning o.*;
end $$;
revoke all on function public.claim_notifications_for(uuid[]) from public, anon, authenticated;
grant execute on function public.claim_notifications_for(uuid[]) to service_role;



-- =====================================================================================================
--  13. PATIENT SELF-SERVICE · FEEDBACK · STAFF INVITES · GO-LIVE HELPERS · WHATSAPP BOT STATE
-- =====================================================================================================

-- ------------------------------------------------------------------ helpers
create or replace function public.site_url()
returns text language sql stable security definer set search_path = public as $$
  select rtrim(coalesce((public.tenant_content('settings') ->> 'siteUrl'), ''), '/')
$$;

-- ------------------------------------------------------------------ patients book / reschedule / cancel their own visits
-- The patient portal writes to `appointments` directly (RLS: own rows). This trigger makes sure a patient
-- can only book a genuinely free slot for themselves, move a future visit to another free slot of the
-- same doctor, or cancel it — never change the doctor, status (other than cancel), notes or reference.
create or replace function public.guard_patient_appointment()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_problem text;
  v_now     timestamp := now() at time zone 'Asia/Kolkata';
  v_cutoff  int := coalesce(nullif(public.booking_setting('rescheduleCutoffHours', '4'), '')::int, 4);
begin
  if auth.uid() is null or not public.has_role('patient') then return new; end if;

  if tg_op = 'INSERT' then
    if new.patient_id is distinct from public.my_patient_id() then raise exception 'You can only book appointments for yourself.'; end if;
    new.status := 'scheduled';
    new.source := 'portal';
    new.notes := null;
    new.contacted_at := null;
    v_problem := public.slot_problem(new.doctor_id, new.appointment_date, new.appointment_time, true);
    if v_problem is not null then raise exception 'SLOT_UNAVAILABLE: %', v_problem; end if;
    return new;
  end if;

  -- UPDATE
  if old.status not in ('scheduled', 'confirmed') or old.appointment_date + old.appointment_time::time < v_now then
    raise exception 'This appointment can no longer be changed online. Please call the hospital.';
  end if;
  new.patient_id := old.patient_id;
  new.doctor_id := old.doctor_id;
  new.type := old.type;
  new.notes := old.notes;
  new.source := old.source;
  new.booking_ref := old.booking_ref;
  new.contacted_at := old.contacted_at;

  if new.status is distinct from old.status and new.status <> 'cancelled'
     and not (new.status = 'scheduled' and (new.appointment_date, new.appointment_time) is distinct from (old.appointment_date, old.appointment_time)) then
    raise exception 'You can only cancel an appointment.';
  end if;
  if new.status = 'cancelled' then
    new.appointment_date := old.appointment_date;
    new.appointment_time := old.appointment_time;
    return new;
  end if;

  if (new.appointment_date, new.appointment_time) is distinct from (old.appointment_date, old.appointment_time) then
    if old.appointment_date + old.appointment_time::time < v_now + make_interval(hours => v_cutoff) then
      raise exception 'Appointments can be rescheduled online up to % hours before the visit. Please call the hospital.', v_cutoff;
    end if;
    v_problem := public.slot_problem(new.doctor_id, new.appointment_date, new.appointment_time, true);
    if v_problem is not null then raise exception 'SLOT_UNAVAILABLE: %', v_problem; end if;
    new.status := 'scheduled';   -- a moved visit needs to be confirmed again
  end if;
  return new;
end $$;
drop trigger if exists trg_appointments_patient_guard on public.appointments;
create trigger trg_appointments_patient_guard before insert or update on public.appointments
  for each row execute function public.guard_patient_appointment();

-- ------------------------------------------------------------------ visit feedback
create or replace function public.guard_feedback()
returns trigger language plpgsql security definer set search_path = public as $$
declare a public.appointments;
begin
  select * into a from public.appointments where id = new.appointment_id;
  if not found then raise exception 'Appointment not found.'; end if;
  if a.status <> 'completed' then raise exception 'You can rate a visit once it is completed.'; end if;
  if auth.uid() is not null and public.has_role('patient') then
    if a.patient_id is distinct from public.my_patient_id() then raise exception 'You can only rate your own visits.'; end if;
    new.source := 'portal';
  end if;
  new.patient_id := a.patient_id;
  new.doctor_id := a.doctor_id;
  new.comment := nullif(left(trim(coalesce(new.comment, '')), 1000), '');
  new.tags := coalesce(new.tags, '{}');
  return new;
end $$;
drop trigger if exists trg_visit_feedback_guard on public.visit_feedback;
create trigger trg_visit_feedback_guard before insert on public.visit_feedback
  for each row execute function public.guard_feedback();

-- Public feedback link (/feedback/<appointment id>) sent after the visit. The appointment id is a random
-- UUID, so it works like a one-time token; nothing personal beyond the first name is returned.
drop function if exists public.feedback_context(uuid) cascade;
create function public.feedback_context(p_appt uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  a public.appointments;
  p public.patients;
  d public.doctors;
begin
  select * into a from public.appointments where id = p_appt and tenant_id = public.current_tenant();
  if not found or a.status <> 'completed' or a.appointment_date < current_date - 60 then
    return jsonb_build_object('ok', false, 'error', 'This feedback link has expired.');
  end if;
  select * into p from public.patients where id = a.patient_id;
  select * into d from public.doctors where id = a.doctor_id;
  return jsonb_build_object('ok', true,
    'first_name', split_part(p.full_name, ' ', 1),
    'doctor', d.full_name, 'specialization', d.specialization,
    'date', a.appointment_date,
    'submitted', exists (select 1 from public.visit_feedback f where f.appointment_id = a.id));
end $$;

drop function if exists public.submit_feedback(uuid, int, text, text[], boolean) cascade;
create function public.submit_feedback(p_appt uuid, p_rating int, p_comment text, p_tags text[] default '{}', p_recommend boolean default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare a public.appointments;
begin
  perform set_config('app.actor_name', 'Patient feedback', true);
  select * into a from public.appointments where id = p_appt and tenant_id = public.current_tenant();
  if not found or a.status <> 'completed' or a.appointment_date < current_date - 60 then
    raise exception 'This feedback link has expired.';
  end if;
  if p_rating is null or p_rating not between 1 and 5 then raise exception 'Please choose a rating from 1 to 5 stars.'; end if;
  begin
    insert into public.visit_feedback (appointment_id, patient_id, rating, comment, tags, would_recommend, source)
    values (p_appt, a.patient_id, p_rating, p_comment,
            (select coalesce(array_agg(t), '{}') from unnest(coalesce(p_tags, '{}')) t where t ~ '^[a-z_]{2,30}$'),
            p_recommend, case when auth.uid() is null then 'link' else 'portal' end);
  exception when unique_violation then
    raise exception 'Thank you — feedback for this visit has already been received.';
  end;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.feedback_context(uuid) from public;
revoke all on function public.submit_feedback(uuid, int, text, text[], boolean) from public;
grant execute on function public.feedback_context(uuid) to anon, authenticated;
grant execute on function public.submit_feedback(uuid, int, text, text[], boolean) to anon, authenticated;

-- ask for feedback when a visit is marked completed
create or replace function public.notify_feedback_request()
returns trigger language plpgsql security definer set search_path = public as $$
declare p public.patients; d public.doctors;
begin
  if new.status <> 'completed' or old.status = 'completed' or public.site_url() = '' then return new; end if;
  select * into p from public.patients where id = new.patient_id;
  select * into d from public.doctors where id = new.doctor_id;
  perform public.notify_enqueue('feedback_request', p.phone, p.email, jsonb_build_object(
    'name', split_part(p.full_name, ' ', 1), 'doctor', d.full_name,
    'link', public.site_url() || '/feedback/' || new.id), 'appointments', new.id);
  return new;
exception when others then
  raise warning 'notify_feedback_request: %', sqlerrm;
  return new;
end $$;
drop trigger if exists trg_appointments_feedback on public.appointments;
create trigger trg_appointments_feedback after update on public.appointments
  for each row execute function public.notify_feedback_request();

-- ------------------------------------------------------------------ staff invitations
create or replace function public.stamp_staff_invite()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.email := lower(trim(new.email));
  new.invited_by_name := coalesce(new.invited_by_name, (select full_name from public.profiles where id = auth.uid()));
  if exists (select 1 from auth.users u where lower(u.email) = new.email) then
    raise exception 'An account with this email already exists — change its role in Users & Roles instead.';
  end if;
  return new;
end $$;
drop trigger if exists trg_staff_invites_stamp on public.staff_invites;
create trigger trg_staff_invites_stamp before insert on public.staff_invites
  for each row execute function public.stamp_staff_invite();

create or replace function public.notify_staff_invite()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.site_url() = '' then return new; end if;   -- no website address yet: the owner shares the link manually
  perform public.notify_enqueue('staff_invite', new.phone, new.email, jsonb_build_object(
    'name', split_part(new.full_name, ' ', 1), 'role', initcap(new.role::text),
    'link', public.site_url() || '/register?invite=' || new.token), 'staff_invites', new.id);
  return new;
exception when others then
  raise warning 'notify_staff_invite: %', sqlerrm;
  return new;
end $$;
drop trigger if exists trg_staff_invites_notify on public.staff_invites;
create trigger trg_staff_invites_notify after insert on public.staff_invites
  for each row execute function public.notify_staff_invite();

-- the sign-up page shows who the invite is for
drop function if exists public.invite_lookup(text) cascade;
create function public.invite_lookup(p_token text)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(
    (select jsonb_build_object('ok', true, 'email', email, 'full_name', full_name, 'role', role, 'phone', phone)
     from public.staff_invites where token = p_token and status = 'pending' and expires_at > now() and tenant_id = public.current_tenant()),
    jsonb_build_object('ok', false, 'error', 'This invitation link is invalid or has expired. Ask the hospital to send a new one.'))
$$;
revoke all on function public.invite_lookup(text) from public;
grant execute on function public.invite_lookup(text) to anon, authenticated;

-- New auth users: an accepted staff invite gives the invited role; the hospital's bootstrap e-mail (app_settings
-- 'bootstrap' — set by production.sql for the first hospital, by supabase/snippets/add-hospital.sql for later ones)
-- becomes that hospital's first owner; everyone else is a patient.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  next_mrn int;
  v_name   text := coalesce(nullif(new.raw_user_meta_data ->> 'full_name', ''), split_part(new.email, '@', 1));
  v_phone  text := nullif(new.raw_user_meta_data ->> 'phone', '');
  v_inv    public.staff_invites;
  v_owner  text;
  v_meta   text := new.raw_user_meta_data ->> 'tenant_id';
  v_tenant uuid;
begin
  -- the hospital this sign-up belongs to (same rule as profiles_pick_tenant): an invite only counts there
  if v_meta ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    select id into v_tenant from public.tenants where id = v_meta::uuid and status <> 'suspended';
  end if;
  v_tenant := coalesce(v_tenant, public.current_tenant(), public.primary_tenant());
  select lower(data ->> 'owner_email') into v_owner from public.app_settings where tenant_id = v_tenant and key = 'bootstrap';

  select * into v_inv from public.staff_invites
  where token = new.raw_user_meta_data ->> 'invite_token' and email = lower(new.email) and tenant_id = v_tenant
    and status = 'pending' and expires_at > now()
  for update;

  if found then
    insert into public.profiles (id, full_name, email, role, phone)
    values (new.id, coalesce(nullif(v_name, ''), v_inv.full_name), new.email, v_inv.role, coalesce(v_phone, v_inv.phone))
    on conflict (id) do update set role = excluded.role;
    update public.staff_invites set status = 'accepted', accepted_at = now() where id = v_inv.id;
    -- link an existing doctor / staff record with the same e-mail
    if v_inv.role = 'doctor' then
      update public.doctors set profile_id = new.id where lower(email) = lower(new.email) and profile_id is null and tenant_id = v_tenant;
    else
      update public.staff set profile_id = new.id where lower(email) = lower(new.email) and profile_id is null and tenant_id = v_tenant;
    end if;
    return new;
  end if;

  if v_owner is not null and lower(new.email) = v_owner
     and not exists (select 1 from public.profiles where role = 'owner' and tenant_id = v_tenant) then
    insert into public.profiles (id, full_name, email, role, phone) values (new.id, v_name, new.email, 'owner', v_phone)
    on conflict (id) do update set role = 'owner';
    return new;
  end if;

  insert into public.profiles (id, full_name, email, role, phone)
  values (new.id, v_name, new.email, 'patient', v_phone)
  on conflict (id) do nothing;

  -- mrn '' → assign_record_number() gives the next number of this hospital (with its prefix)
  insert into public.patients (profile_id, mrn, full_name, email, phone, gender, status)
  values (new.id, '', v_name, new.email, v_phone, 'other', 'outpatient')
  on conflict (profile_id) do nothing;
  return new;
end $$;

-- ------------------------------------------------------------------ go-live helpers (owner only)
-- Demo seed rows use ids shaped d0cXXXXX-0000-4000-8000-XXXXXXXXXXXX, which random UUIDs never produce.
create or replace function public.is_demo_id(p uuid)
returns boolean language sql immutable as $$ select p::text ~ '^d0c[0-9]{5}-0000-4000-8000-[0-9]{12}$' $$;

drop function if exists public.demo_status() cascade;
create function public.demo_status()
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare u auth.users;
begin
  if not public.has_role('owner') then raise exception 'Only the hospital owner can do this.'; end if;
  if public.current_tenant() is distinct from public.primary_tenant() then
    return jsonb_build_object('demo_accounts_active', 0, 'owner_is_demo_email', false, 'owner_has_demo_password', false, 'demo_rows', 0);
  end if;
  select * into u from auth.users where id = auth.uid();
  return jsonb_build_object(
    'demo_accounts_active', (select count(*) from auth.users a where public.is_demo_id(a.id) and a.id <> auth.uid()
                             and (a.banned_until is null or a.banned_until < now())),
    'owner_is_demo_email', lower(u.email) like '%@dchospital.com',
    'owner_has_demo_password', coalesce(u.encrypted_password = extensions.crypt('Demo@123', u.encrypted_password), false),
    'demo_rows', (select count(*) from public.patients where public.is_demo_id(id))
               + (select count(*) from public.appointments where public.is_demo_id(id))
               + (select count(*) from public.invoices where public.is_demo_id(id)));
end $$;

-- Locks the demo logins (random password + banned), except the account running this.
drop function if exists public.lock_demo_accounts() cascade;
create function public.lock_demo_accounts()
returns int language plpgsql volatile security definer set search_path = public, extensions as $$
declare v_count int;
begin
  if not public.has_role('owner') then raise exception 'Only the hospital owner can do this.'; end if;
  if public.current_tenant() is distinct from public.primary_tenant() then return 0; end if;   -- demo logins live in the main hospital
  perform public.module_guard('data');
  update auth.users set encrypted_password = extensions.crypt(encode(extensions.gen_random_bytes(24), 'hex'), extensions.gen_salt('bf')),
                        banned_until = 'infinity'
  where public.is_demo_id(id) and id <> auth.uid();
  get diagnostics v_count = row_count;
  insert into public.audit_log (table_name, record_id, action, actor_id, actor_name, actor_role, summary, changes)
  values ('profiles', null, 'update', auth.uid(), (select full_name from public.profiles where id = auth.uid()), 'owner',
          'Locked ' || v_count || ' demo accounts', '{}'::jsonb);
  return v_count;
end $$;

-- Deletes the demo patients / visits / bills / staff records. Real records (random ids) are untouched.
drop function if exists public.clear_demo_data() cascade;
create function public.clear_demo_data()
returns int language plpgsql volatile security definer set search_path = public as $$
declare v_total int := 0; v_n int; t text; v_id uuid;
begin
  if not public.has_role('owner') then raise exception 'Only the hospital owner can do this.'; end if;
  if public.current_tenant() is distinct from public.primary_tenant() then return 0; end if;   -- demo rows live in the main hospital
  perform public.module_guard('data');
  perform set_config('app.actor_name', 'Go-live cleanup', true);
  foreach t in array array['visit_feedback', 'payments', 'invoices', 'admissions', 'lab_tests', 'prescriptions', 'appointments',
                           'doctor_leaves', 'site_enquiries', 'site_forms', 'notices', 'expenses', 'inventory', 'beds', 'wards', 'patients']
  loop
    begin
      execute format('delete from public.%I where public.is_demo_id(id)', t);
      get diagnostics v_n = row_count;
      v_total := v_total + v_n;
    exception when foreign_key_violation or restrict_violation then
      -- a real record points at a demo one (e.g. a real bill for a demo patient): keep those, delete the rest
      for v_id in execute format('select id from public.%I where public.is_demo_id(id)', t) loop
        begin
          execute format('delete from public.%I where id = $1', t) using v_id;
          v_total := v_total + 1;
        exception when foreign_key_violation or restrict_violation then null;
        end;
      end loop;
    end;
  end loop;
  return v_total;
end $$;
revoke all on function public.demo_status() from public, anon;
revoke all on function public.lock_demo_accounts() from public, anon;
revoke all on function public.clear_demo_data() from public, anon;
grant execute on function public.demo_status() to authenticated;
grant execute on function public.lock_demo_accounts() to authenticated;
grant execute on function public.clear_demo_data() to authenticated;

-- ------------------------------------------------------------------ WhatsApp chatbot state
alter table public.wa_sessions enable row level security;   -- no policies: Edge Function (service role) only
revoke all on public.wa_sessions from anon, authenticated;
grant all on public.wa_sessions to service_role;
grant select, insert, update on public.visit_feedback to service_role;
grant select on public.appointments, public.doctors, public.patients, public.departments to service_role;

-- tables created in this section need the standard grants too
grant select, insert, update, delete on public.visit_feedback, public.staff_invites to authenticated;

-- ------------------------------------------------------------------ WhatsApp chatbot helpers (service role only)
-- The sender's number is verified by WhatsApp itself, so the bot can book / list / cancel for that number.
create or replace function public.bot_free_slots(p_doctor uuid, p_limit int default 8)
returns table (slot_date date, slot_time text)
language sql stable security definer set search_path = public as $$
  with days as (
    select (now() at time zone 'Asia/Kolkata')::date + g as d
    from generate_series(0, least(coalesce(nullif(public.booking_setting('advanceDays', '30'), '')::int, 30), 60)) g
  ), times as (
    select to_char(time '08:00' + make_interval(mins => 30 * g), 'HH24:MI') as t from generate_series(0, 21) g
  )
  select days.d, times.t
  from days cross join times
  where public.slot_problem(p_doctor, days.d, times.t, true) is null
    and not exists (select 1 from public.appointments a
                    where a.tenant_id = public.current_tenant() and a.doctor_id = p_doctor and a.appointment_date = days.d and left(a.appointment_time, 5) = times.t
                      and a.status not in ('cancelled', 'no_show'))
  order by 1, 2
  limit greatest(1, least(p_limit, 20))
$$;

create or replace function public.bot_patient(p_phone text)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', p.id, 'full_name', p.full_name, 'mrn', p.mrn)
  from public.patients p
  where p.tenant_id = public.current_tenant() and public.norm_phone(p.phone) = public.norm_phone(p_phone)
  order by p.created_at
  limit 1
$$;

create or replace function public.bot_upcoming(p_phone text)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', a.id, 'ref', coalesce(a.booking_ref, upper(left(a.id::text, 8))), 'date', a.appointment_date,
           'time', left(a.appointment_time, 5), 'status', a.status, 'doctor', d.full_name) order by a.appointment_date, a.appointment_time), '[]'::jsonb)
  from public.appointments a
  join public.patients p on p.id = a.patient_id
  join public.doctors d on d.id = a.doctor_id
  where a.tenant_id = public.current_tenant() and public.norm_phone(p.phone) = public.norm_phone(p_phone)
    and a.appointment_date >= (now() at time zone 'Asia/Kolkata')::date
    and a.status in ('scheduled', 'confirmed')
$$;

create or replace function public.whatsapp_cancel_appointment(p_phone text, p_appt uuid)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare v_id uuid;
begin
  perform set_config('app.actor_name', 'WhatsApp bot', true);
  perform set_config('app.actor_role', 'public', true);
  update public.appointments a set status = 'cancelled'
  from public.patients p
  where a.id = p_appt and a.tenant_id = public.current_tenant() and p.id = a.patient_id and public.norm_phone(p.phone) = public.norm_phone(p_phone)
    and a.status in ('scheduled', 'confirmed') and a.appointment_date >= (now() at time zone 'Asia/Kolkata')::date
  returning a.id into v_id;
  if v_id is null then raise exception 'This appointment cannot be cancelled here. Please call the hospital.'; end if;
  return true;
end $$;

revoke all on function public.bot_free_slots(uuid, int) from public, anon, authenticated;
revoke all on function public.bot_patient(text) from public, anon, authenticated;
revoke all on function public.bot_upcoming(text) from public, anon, authenticated;
revoke all on function public.whatsapp_cancel_appointment(text, uuid) from public, anon, authenticated;
grant execute on function public.bot_free_slots(uuid, int) to service_role;
grant execute on function public.bot_patient(text) to service_role;
grant execute on function public.bot_upcoming(text) to service_role;
grant execute on function public.whatsapp_cancel_appointment(text, uuid) to service_role;


-- =====================================================================================================
--  15. SCALE — server-side pagination support (idempotent; also shipped in supabase/upgrade-2026-10.sql)
--
--  The dashboard never downloads whole tables: lists ask for one page (search / filters / sort run here),
--  dashboards read date windows and counts. These indexes keep those reads fast at lakhs of rows, and the
--  payment trigger keeps invoice totals correct without the browser having to read the invoice first.
-- =====================================================================================================

-- ---- sort / window indexes used by the paged lists and dashboards
create index if not exists patients_created_idx      on public.patients (created_at desc);
create index if not exists patients_status_idx       on public.patients (status);
create index if not exists invoices_issue_idx        on public.invoices (issue_date desc);
create index if not exists invoices_open_idx         on public.invoices (due_date) where status in ('unpaid', 'partial', 'overdue');
create index if not exists payments_paid_on_idx      on public.payments (paid_on desc);
create index if not exists prescriptions_date_idx    on public.prescriptions (prescribed_on desc);
create index if not exists prescriptions_follow_idx  on public.prescriptions (doctor_id, follow_up_date) where follow_up_date is not null;
create index if not exists lab_tests_requested_idx   on public.lab_tests (requested_on desc);
create index if not exists lab_tests_doctor_idx      on public.lab_tests (doctor_id, status);
create index if not exists admissions_status_idx     on public.admissions (status, admission_date desc);
create index if not exists admissions_doctor_idx     on public.admissions (doctor_id) where status = 'admitted';
create index if not exists appointments_status_date_idx on public.appointments (status, appointment_date);
create index if not exists visit_feedback_created_idx on public.visit_feedback (created_at desc);

-- ---- fast "contains" search on names / phones / numbers (pg_trgm). Optional: skipped where unavailable.
do $$
begin
  create extension if not exists pg_trgm with schema extensions;
  execute 'create index if not exists patients_name_trgm  on public.patients using gin (full_name extensions.gin_trgm_ops)';
  execute 'create index if not exists patients_phone_trgm on public.patients using gin (phone extensions.gin_trgm_ops)';
  execute 'create index if not exists patients_mrn_trgm   on public.patients using gin (mrn extensions.gin_trgm_ops)';
  execute 'create index if not exists invoices_number_trgm on public.invoices using gin (invoice_number extensions.gin_trgm_ops)';
exception when others then
  raise notice 'pg_trgm not available (%): search still works, just without trigram indexes', sqlerrm;
end $$;

-- ---- payments → invoice totals (single source of truth: the sum of the invoice's payments)
create or replace function public.invoice_recalc(p_invoice uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_paid numeric(12,2);
begin
  if p_invoice is null then return; end if;
  select coalesce(sum(amount), 0) into v_paid from public.payments where invoice_id = p_invoice;
  update public.invoices i set
    amount_paid = v_paid,
    status = case
      when i.status in ('draft', 'cancelled') then i.status
      when i.total > 0 and v_paid >= i.total then 'paid'
      when v_paid > 0 then 'partial'
      when i.due_date is not null and i.due_date < public.today_ist() then 'overdue'
      else 'unpaid' end
  where i.id = p_invoice
    and (i.amount_paid is distinct from v_paid or i.status is distinct from (case
      when i.status in ('draft', 'cancelled') then i.status
      when i.total > 0 and v_paid >= i.total then 'paid'
      when v_paid > 0 then 'partial'
      when i.due_date is not null and i.due_date < public.today_ist() then 'overdue'
      else 'unpaid' end));
end $$;
revoke execute on function public.invoice_recalc(uuid) from public, anon, authenticated;

-- the payment always belongs to the invoice's patient (the browser no longer has to look it up)
create or replace function public.payments_stamp_patient()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  select patient_id into new.patient_id from public.invoices where id = new.invoice_id;
  if new.patient_id is null then raise exception 'Invoice not found' using errcode = '23503'; end if;
  return new;
end $$;
revoke execute on function public.payments_stamp_patient() from public, anon, authenticated;

create or replace function public.payments_sync_invoice()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op in ('UPDATE', 'DELETE') then perform public.invoice_recalc(old.invoice_id); end if;
  if tg_op in ('INSERT', 'UPDATE') and (tg_op = 'INSERT' or new.invoice_id is distinct from old.invoice_id or new.amount is distinct from old.amount) then
    perform public.invoice_recalc(new.invoice_id);
  end if;
  return null;
end $$;
revoke execute on function public.payments_sync_invoice() from public, anon, authenticated;

drop trigger if exists trg_payments_stamp_patient on public.payments;
create trigger trg_payments_stamp_patient before insert or update of invoice_id on public.payments
  for each row execute function public.payments_stamp_patient();
drop trigger if exists trg_payments_sync_invoice on public.payments;
create trigger trg_payments_sync_invoice after insert or update or delete on public.payments
  for each row execute function public.payments_sync_invoice();

-- ---- Financial Reports totals (the Reports page never downloads every invoice). Runs with the caller's rights,
--      so RLS decides who sees what (owner / accountant). Buckets mirror src/lib/reports.ts.
create or replace function public.financial_report(p_from date)
returns jsonb language plpgsql stable security invoker set search_path = public as $$
declare r jsonb;
begin
  with inv as (
    select issue_date, total, items from public.invoices where issue_date >= p_from and status not in ('cancelled', 'draft')
  ), items as (
    select coalesce(it ->> 'description', '') d,
           coalesce((it ->> 'quantity')::numeric, 0) * coalesce((it ->> 'unit_price')::numeric, 0) amt
    from inv cross join lateral jsonb_array_elements(case when jsonb_typeof(inv.items) = 'array' then inv.items else '[]'::jsonb end) it
  )
  select jsonb_build_object(
    'billed', (select coalesce(jsonb_object_agg(m, v), '{}') from (select to_char(issue_date, 'YYYY-MM') m, sum(total) v from inv group by 1) x),
    'collected', (select coalesce(jsonb_object_agg(m, v), '{}') from (select to_char(paid_on, 'YYYY-MM') m, sum(amount) v from public.payments where paid_on >= p_from group by 1) x),
    'expenses', (select coalesce(jsonb_object_agg(m, v), '{}') from (select to_char(expense_date, 'YYYY-MM') m, sum(amount) v from public.expenses where expense_date >= p_from group by 1) x),
    'cats', (select coalesce(jsonb_object_agg(category, v), '{}') from (select category, sum(amount) v from public.expenses where expense_date >= p_from group by 1) x),
    'sources', (select coalesce(jsonb_object_agg(s, v), '{}') from (
      select case when d ~* '^Consultation' then 'Consultations' when d ~* '^Lab' then 'Laboratory'
                  when d ~* 'bed charges|Nursing' then 'IPD / Room' when d ~* 'Pharmacy' then 'Pharmacy'
                  when d ~* 'Procedure|OT' then 'Procedures' else 'Other' end s, sum(amt) v
      from items group by 1) x),
    'doctors', (select coalesce(jsonb_object_agg(n, v), '{}') from (
      select substring(d from '^Consultation – (.+)$') n, sum(amt) v from items where d ~ '^Consultation – .+' group by 1) x)
  ) into r;
  return r;
end $$;
revoke execute on function public.financial_report(date) from public, anon;
grant execute on function public.financial_report(date) to authenticated;

-- ---- Owner / accountant dashboard money widgets: 6 months of totals + the few rows the lists show, so the
--      dashboard never downloads every payment (a busy hospital has tens of thousands in 6 months). Caller's rights
--      (RLS: owner / accountant). Mirrors useFinance() in src/pages/dashboard/Dashboard.tsx (demo mode).
create or replace function public.dashboard_finance(p_from date)
returns jsonb language plpgsql stable security invoker set search_path = public as $$
declare r jsonb;
begin
  with open_inv as (
    select i.*, greatest(0, i.total - i.amount_paid) as balance
      from public.invoices i where i.status in ('unpaid', 'partial', 'overdue')
  )
  select jsonb_build_object(
    'revenue', (select coalesce(jsonb_object_agg(m, v), '{}') from (select to_char(paid_on, 'YYYY-MM') m, sum(amount) v from public.payments where paid_on >= p_from group by 1) x),
    'expenses', (select coalesce(jsonb_object_agg(m, v), '{}') from (select to_char(expense_date, 'YYYY-MM') m, sum(amount) v from public.expenses where expense_date >= p_from group by 1) x),
    'methods', (select coalesce(jsonb_object_agg(method, v), '{}') from (select method, sum(amount) v from public.payments where paid_on >= p_from group by 1) x),
    'outstanding', (select coalesce(sum(balance), 0) from open_inv),
    'open_count', (select count(*) from open_inv where balance > 0),
    'top_open', (select coalesce(jsonb_agg(to_jsonb(t) - 'balance' order by t.balance desc), '[]') from (select * from open_inv where balance > 0 order by balance desc, issue_date limit 5) t),
    'overdue', (select coalesce(jsonb_agg(to_jsonb(t) - 'balance' order by t.balance desc), '[]') from (select * from open_inv where status = 'overdue' and balance > 0 order by balance desc, due_date limit 6) t),
    'recent', (select coalesce(jsonb_agg(to_jsonb(t) order by t.paid_on desc, t.created_at desc), '[]') from (select * from public.payments order by paid_on desc, created_at desc limit 6) t)
  ) into r;
  return r;
end $$;
revoke execute on function public.dashboard_finance(date) from public, anon;
grant execute on function public.dashboard_finance(date) to authenticated;


-- =====================================================================================================
--  16. PASSWORD RESET BY MOBILE OTP (idempotent; also shipped in supabase/upgrade-2026-10.sql)
--
--  The second "Forgot password" option, next to the e-mail link:
--    request_password_otp(email, phone, channel)  sends a 6-digit code on WhatsApp / SMS — only when that e-mail and
--                                                 mobile belong to the same account (the answer is identical either
--                                                 way, so it never reveals which accounts exist)
--    verify_password_otp(email, phone, code)       5 attempts, 10 minute expiry → one-time token (valid 15 minutes)
--    reset_password_with_otp(token, password)      sets the new password and signs the account out everywhere
--  Unlike the booking OTP the code is NEVER shown on screen: without a connected SMS / WhatsApp gateway this
--  option reports itself unavailable and the e-mail link is used instead.
-- =====================================================================================================

create table if not exists public.password_reset_otps (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid references auth.users on delete cascade,   -- null = no matching account (kept for rate limits)
  phone          text not null,
  code_hash      text not null,
  attempts       int not null default 0,
  expires_at     timestamptz not null,
  verified_at    timestamptz,
  token          uuid unique,
  token_used_at  timestamptz,
  created_at     timestamptz not null default now()
);
-- tables created by this section get their hospital column right away (functions below refer to it)
select public.ensure_tenant_columns();
create index if not exists password_reset_otps_phone_idx on public.password_reset_otps (phone, created_at desc);
alter table public.password_reset_otps add column if not exists ip_hash text;   -- hashed visitor connection (per-IP limit)
create index if not exists password_reset_otps_ip_idx on public.password_reset_otps (ip_hash, created_at desc) where ip_hash is not null;
alter table public.password_reset_otps enable row level security;   -- no policies: unreachable through the API
revoke all on public.password_reset_otps from anon, authenticated;

-- the event whose channels / wording are used: "Password reset OTP" once saved in Settings, else the booking OTP's
create or replace function public.password_otp_event()
returns text language plpgsql stable security definer set search_path = public as $$
begin
  return case when (public.tenant_setting('app') -> 'notifications' -> 'events' ? 'password_otp')
              then 'password_otp' else 'otp' end;
end $$;

-- channels that can deliver the reset code right now (WhatsApp first). Public; reveals no credentials.
create or replace function public.password_otp_channels()
returns text[] language plpgsql stable security definer set search_path = public as $$
declare
  n   jsonb;
  ev  text := public.password_otp_event();
  ch  text;
  out text[] := '{}';
begin
  n := public.tenant_setting('app') -> 'notifications';
  if n is null then return out; end if;
  foreach ch in array array['whatsapp', 'sms'] loop
    if coalesce((n -> ch ->> 'enabled')::boolean, false)
       and coalesce((n -> 'events' -> ev ->> ch)::boolean, false)
       and coalesce(n -> 'templates' -> ev ->> 'text', '') <> '' then
      out := out || ch;
    end if;
  end loop;
  return out;
end $$;

create or replace function public.request_password_otp(p_email text, p_phone text, p_channel text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_phone  text := public.norm_phone(p_phone);
  v_email  text := lower(trim(coalesce(p_email, '')));
  v_avail  text[] := public.password_otp_channels();
  v_use    text[];
  v_user   uuid;
  v_code   text;
  v_id     uuid;
  v_ip     text := public.client_ip_hash();
begin
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'Please enter the e-mail you sign in with.';
  end if;
  if v_phone !~ '^[6-9][0-9]{9}$' then
    raise exception 'Please enter a valid 10-digit Indian mobile number.';
  end if;
  if cardinality(v_avail) = 0 then
    raise exception 'MOBILE_RESET_OFF: Reset by mobile is not set up at this hospital yet. Please use the e-mail link.';
  end if;
  if exists (select 1 from public.password_reset_otps where tenant_id = public.current_tenant() and phone = v_phone and created_at > now() - interval '30 seconds') then
    raise exception 'Please wait 30 seconds before requesting another code.';
  end if;
  if (select count(*) from public.password_reset_otps where tenant_id = public.current_tenant() and phone = v_phone and created_at > now() - interval '1 hour') >= 5 then
    raise exception 'Too many codes requested for this number. Please try again in an hour.';
  end if;
  if v_ip is not null and (select count(*) from public.password_reset_otps where ip_hash = v_ip and created_at > now() - interval '1 hour')
     >= greatest(3, coalesce(nullif(public.booking_setting('otpIpHourlyLimit', '10'), '')::int, 10)) then
    raise exception 'Too many reset requests from this connection. Please try again in an hour.';
  end if;
  if (select count(*) from public.password_reset_otps where tenant_id = public.current_tenant() and created_at > now() - interval '1 hour')
     >= greatest(10, coalesce(nullif(public.booking_setting('otpHourlyLimit', '200'), '')::int, 200)) then
    raise exception 'Too many reset requests right now. Please try again in a few minutes.';
  end if;

  -- the account must have BOTH this e-mail and this mobile (on the profile or the linked patient record)
  select u.id into v_user
  from auth.users u
  join public.profiles p on p.id = u.id
  where lower(u.email) = v_email and p.tenant_id = public.current_tenant()
    and (u.banned_until is null or u.banned_until < now())
    and (public.norm_phone(p.phone) = v_phone
         or exists (select 1 from public.patients pt where pt.profile_id = p.id and public.norm_phone(pt.phone) = v_phone))
  limit 1;

  v_code := lpad(((('x' || encode(extensions.gen_random_bytes(4), 'hex'))::bit(32)::bigint) % 1000000)::text, 6, '0');
  insert into public.password_reset_otps (user_id, phone, code_hash, expires_at, ip_hash)
  values (v_user, v_phone, extensions.crypt(v_code, extensions.gen_salt('bf', 6)), now() + interval '10 minutes', v_ip)
  returning id into v_id;

  v_use := case when p_channel = any (v_avail) then array[p_channel] else v_avail end;
  if v_user is not null then
    perform public.notify_enqueue(public.password_otp_event(), v_phone, null,
      jsonb_build_object('code', v_code, 'otp', v_code), 'password_reset_otps', v_id, v_use);
  end if;
  -- same answer whether or not an account matched
  return jsonb_build_object('sent', true, 'expires_in', 600, 'ref', v_id, 'channels', to_jsonb(v_use));
end $$;

create or replace function public.verify_password_otp(p_email text, p_phone text, p_code text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_phone text := public.norm_phone(p_phone);
  o       public.password_reset_otps;
  v_token uuid;
begin
  select * into o from public.password_reset_otps
  where tenant_id = public.current_tenant() and phone = v_phone and verified_at is null
  order by created_at desc limit 1
  for update;
  if not found or o.expires_at < now() then
    return jsonb_build_object('ok', false, 'error', 'This code has expired. Please request a new one.');
  end if;
  if o.attempts >= 5 then
    return jsonb_build_object('ok', false, 'error', 'Too many wrong attempts. Please request a new code.');
  end if;
  -- an unmatched request can never verify (no code was sent), and the e-mail must still be the account's
  if o.user_id is null
     or not exists (select 1 from auth.users u where u.id = o.user_id and lower(u.email) = lower(trim(coalesce(p_email, ''))))
     or coalesce(p_code, '') !~ '^[0-9]{6}$' or o.code_hash <> extensions.crypt(p_code, o.code_hash) then
    update public.password_reset_otps set attempts = attempts + 1 where id = o.id;
    return jsonb_build_object('ok', false, 'error',
      case when o.attempts + 1 >= 5 then 'Too many wrong attempts. Please request a new code.'
           else format('That code is not correct — %s attempt%s left.', 4 - o.attempts, case when 4 - o.attempts = 1 then '' else 's' end) end);
  end if;
  v_token := gen_random_uuid();
  update public.password_reset_otps set verified_at = now(), token = v_token where id = o.id;
  return jsonb_build_object('ok', true, 'token', v_token);
end $$;

create or replace function public.reset_password_with_otp(p_token uuid, p_password text)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  o public.password_reset_otps;
begin
  if length(coalesce(p_password, '')) < 8 then
    raise exception 'Use at least 8 characters.';
  end if;
  select * into o from public.password_reset_otps where token = p_token and tenant_id = public.current_tenant() for update;
  if not found or o.user_id is null or o.verified_at is null or o.token_used_at is not null
     or o.verified_at < now() - interval '15 minutes' then
    raise exception 'OTP_REQUIRED: This reset has expired. Please verify your mobile number again.';
  end if;
  update auth.users
     set encrypted_password = extensions.crypt(p_password, extensions.gen_salt('bf')),
         recovery_token = '', updated_at = now()
   where id = o.user_id;
  update public.password_reset_otps set token_used_at = now() where id = o.id;
  -- sign the account out on every device (tables exist on Supabase; skipped elsewhere)
  if to_regclass('auth.refresh_tokens') is not null then
    execute 'delete from auth.refresh_tokens where user_id::text = $1' using o.user_id::text;
  end if;
  if to_regclass('auth.sessions') is not null then
    execute 'delete from auth.sessions where user_id = $1' using o.user_id;
  end if;
  return jsonb_build_object('ok', true, 'email', (select email from auth.users where id = o.user_id));
end $$;

revoke all on function public.password_otp_event() from public, anon, authenticated;
grant execute on function public.password_otp_channels() to anon, authenticated;
grant execute on function public.request_password_otp(text, text, text) to anon, authenticated;
grant execute on function public.verify_password_otp(text, text, text) to anon, authenticated;
grant execute on function public.reset_password_with_otp(uuid, text) to anon, authenticated;


-- =====================================================================================================
--  17. WEBSITE FORMS (idempotent; also shipped in supabase/upgrade-2026-10.sql)
--
--  Settings → Forms: the owner manages the Contact form, the Patient review form and any custom form
--  (callback request, job application, health camp…). Every submission lands in the Enquiries inbox
--  (site_enquiries) with the form it came from (form_id, form_name) and all its answers (data).
--    site_forms                       owner: full access · receptionist: read · visitors: enabled forms only
--    submit_site_form(form, answers)  the only way visitors submit a form — validates every answer against the
--                                     form's fields (same rules as src/forms/schema.ts) and returns the reference
--  Older messages (sent before forms existed) are filed under the Contact form.
-- =====================================================================================================

create table if not exists public.site_forms (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique check (slug ~ '^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$'),
  name        text not null check (char_length(name) between 2 and 80),
  description text check (description is null or char_length(description) <= 500),
  kind        text not null default 'custom' check (kind in ('contact', 'review', 'custom')),
  enabled     boolean not null default true,
  fields      jsonb not null default '[]'::jsonb check (jsonb_typeof(fields) = 'array'),
  settings    jsonb not null default '{}'::jsonb check (jsonb_typeof(settings) = 'object'),
  sort        int not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
-- tables created by this section get their hospital column right away (functions below refer to it)
select public.ensure_tenant_columns();
drop trigger if exists trg_site_forms_updated_at on public.site_forms;
create trigger trg_site_forms_updated_at before update on public.site_forms
  for each row execute function public.set_updated_at();

alter table public.site_enquiries add column if not exists form_id uuid;
alter table public.site_enquiries add column if not exists form_name text;
alter table public.site_enquiries add column if not exists data jsonb;
create index if not exists site_enquiries_form_id_created_at_idx on public.site_enquiries (form_id, created_at desc);

-- built-in forms (kept as edited if they already exist)
insert into public.site_forms (id, slug, name, description, kind, enabled, fields, settings, sort) values
  ('f0000000-0000-4000-8000-000000000001', 'contact', 'Contact form', 'The form on the Contact page. Topics come from Website CMS → Contact page unless you set options here.', 'contact', true, '[{"id":"name","type":"text","label":"Full name","placeholder":"Priya Sharma","required":true,"role":"name","width":"half"},{"id":"phone","type":"phone","label":"Mobile number","placeholder":"98100 12345","required":true,"role":"phone","width":"half"},{"id":"email","type":"email","label":"Email","placeholder":"you@example.com","role":"email","width":"half"},{"id":"speciality","type":"select","label":"Speciality","placeholder":"Not sure / general","optionsFrom":"services","role":"speciality","width":"half"},{"id":"topic","type":"radio","label":"How can we help?","required":true,"options":[],"role":"topic"},{"id":"message","type":"textarea","label":"Message","placeholder":"Tell us how we can help…","required":true,"role":"message"},{"id":"consent","type":"consent","label":"I agree to be contacted about my enquiry and accept the privacy policy.","required":true}]'::jsonb, '{"submitLabel":"Send message","color":"brand"}'::jsonb, 0),
  ('f0000000-0000-4000-8000-000000000002', 'review', 'Patient review', 'Share your experience at our hospital. Reviews are read by the management.', 'review', true, '[{"id":"rating","type":"rating","label":"Overall experience","required":true},{"id":"name","type":"text","label":"Full name","placeholder":"Priya Sharma","required":true,"role":"name","width":"half"},{"id":"phone","type":"phone","label":"Mobile number","placeholder":"98100 12345","required":true,"role":"phone","width":"half"},{"id":"doctor","type":"text","label":"Doctor or department you visited","placeholder":"e.g. Dr. Arjun Mehta, Cardiology","width":"half"},{"id":"visit_date","type":"date","label":"Date of visit","width":"half"},{"id":"liked","type":"checkboxes","label":"What went well?","options":["Doctor consultation","Nursing care","Cleanliness","Waiting time","Billing & front desk"]},{"id":"message","type":"textarea","label":"Your review","placeholder":"Tell us about your visit…","required":true,"role":"message"},{"id":"publish","type":"consent","label":"You may publish my first name with this review on the website."}]'::jsonb, '{"topic":"Patient review","submitLabel":"Submit review","successTitle":"Thank you for your review!","successText":"Your feedback helps us care better for every patient.","color":"amber"}'::jsonb, 1)
on conflict do nothing;

-- messages without a form (older app versions, staff-added) belong to the Contact form
create or replace function public.site_enquiry_default_form()
returns trigger language plpgsql as $$
begin
  if new.form_id is null then
    -- this hospital's Contact form
    select id, coalesce(new.form_name, name) into new.form_id, new.form_name
      from public.site_forms where kind = 'contact' and tenant_id = new.tenant_id order by sort, created_at limit 1;
    new.form_name := coalesce(new.form_name, 'Contact form');
  end if;
  return new;
end $$;
drop trigger if exists trg_site_enquiries_form on public.site_enquiries;
create trigger trg_site_enquiries_form before insert on public.site_enquiries
  for each row execute function public.site_enquiry_default_form();
revoke all on function public.site_enquiry_default_form() from public, anon, authenticated;

update public.site_enquiries
   set form_id = 'f0000000-0000-4000-8000-000000000001', form_name = coalesce(form_name, 'Contact form')
 where form_id is null;

-- RLS (same names as the generated policies in master.sql, so re-running is harmless)
alter table public.site_forms enable row level security;
drop policy if exists site_forms_select on public.site_forms;
drop policy if exists site_forms_insert on public.site_forms;
drop policy if exists site_forms_update on public.site_forms;
drop policy if exists site_forms_delete on public.site_forms;
drop policy if exists site_forms_public_read on public.site_forms;
create policy site_forms_select on public.site_forms for select to authenticated
  using (public.has_role('owner', 'receptionist'));
create policy site_forms_insert on public.site_forms for insert to authenticated
  with check (public.has_role('owner'));
create policy site_forms_update on public.site_forms for update to authenticated
  using (public.has_role('owner')) with check (public.has_role('owner'));
create policy site_forms_delete on public.site_forms for delete to authenticated
  using (public.has_role('owner'));
create policy site_forms_public_read on public.site_forms for select to anon, authenticated
  using (enabled);

-- direct inserts (older app versions) can't fake form answers; forms go through submit_site_form()
drop policy if exists site_enquiries_public_insert on public.site_enquiries;
create policy site_enquiries_public_insert on public.site_enquiries for insert to anon, authenticated
  with check (status = 'new' and notes is null and starred = false and read_at is null and data is null);

grant select on public.site_forms to anon;
grant select, insert, update, delete on public.site_forms to authenticated;

-- one submission → one inbox message. Mirrors validateAnswers() + toEnquiry() in src/forms/schema.ts.
create or replace function public.submit_site_form(p_form uuid, p_answers jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  f        public.site_forms;
  fld      jsonb;
  v        jsonb;
  s        text;
  t        text;
  r        text;
  lbl      text;
  opts     jsonb;
  is_empty boolean;
  req      boolean;
  err      text;
  v_data   jsonb := '[]'::jsonb;
  v_lines  text[] := '{}';
  v_name   text := '';
  v_phone  text := '';
  v_email  text := '';
  v_topic  text := '';
  v_spec   text := '';
  v_msg    text := '';
  v_ref    text;
begin
  select * into f from public.site_forms where id = p_form and enabled and tenant_id = public.current_tenant();
  if not found then raise exception 'This form is not available any more. Please refresh the page.'; end if;
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then raise exception 'Please fill in the form.'; end if;

  for fld in select value from jsonb_array_elements(f.fields) loop
    t := fld ->> 'type';
    r := fld ->> 'role';
    lbl := coalesce(fld ->> 'label', 'This field');
    v := p_answers -> (fld ->> 'id');
    if v is not null and jsonb_typeof(v) = 'null' then v := null; end if;
    req := coalesce((fld ->> 'required')::boolean, false) or r in ('name', 'phone');
    opts := case when jsonb_typeof(fld -> 'options') = 'array' then fld -> 'options' else '[]'::jsonb end;

    if v is null then s := '';
    elsif jsonb_typeof(v) = 'array' then s := coalesce((select string_agg(x, ', ') from jsonb_array_elements_text(v) x), '');
    elsif jsonb_typeof(v) = 'string' then s := v #>> '{}';
    elsif jsonb_typeof(v) in ('number', 'boolean') then s := v::text;
    else raise exception '%: invalid answer', lbl;
    end if;
    s := btrim(s);

    if t = 'consent' then is_empty := v is distinct from 'true'::jsonb;
    elsif t = 'checkboxes' then
      if v is not null and jsonb_typeof(v) <> 'array' then raise exception '%: invalid answer', lbl; end if;
      is_empty := v is null or jsonb_array_length(v) = 0;
    else is_empty := s = '';
    end if;

    if is_empty then
      if req then
        raise exception '%', case t when 'consent' then 'Please accept: ' || lbl when 'rating' then 'Please choose a rating' else lbl || ' is required' end;
      end if;
      continue;
    end if;

    err := null;
    case t
      when 'text' then
        if char_length(s) > 200 then err := 'keep it under 200 characters';
        elsif r = 'name' and char_length(s) < 2 then err := 'please enter your full name'; end if;
      when 'textarea' then
        if char_length(s) > 2000 then err := 'keep it under 2000 characters';
        elsif r = 'message' and req and char_length(s) < 10 then err := 'tell us a little more (at least 10 characters)'; end if;
      when 'email' then
        if s !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' or char_length(s) > 200 then err := 'enter a valid email address'; end if;
      when 'phone' then
        if right(regexp_replace(s, '\D', '', 'g'), 10) !~ '^[6-9][0-9]{9}$' or s !~ '^[0-9\s+-]+$' then err := 'enter a valid 10-digit mobile number'; end if;
      when 'number' then
        if s !~ '^-?[0-9]{1,12}(\.[0-9]{1,4})?$' then err := 'enter a number'; end if;
      when 'date' then
        if s !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then err := 'pick a date'; end if;
      when 'rating' then
        if s not in ('1', '2', '3', '4', '5') then err := 'please choose a rating'; end if;
      when 'select', 'radio' then
        if jsonb_array_length(opts) > 0 and not opts ? s then err := 'please choose one of the options';
        elsif char_length(s) > 120 then err := 'invalid choice'; end if;
      when 'checkboxes' then
        if jsonb_array_length(opts) > 0 and exists (select 1 from jsonb_array_elements_text(v) x where not opts ? x) then err := 'please choose from the options';
        elsif char_length(s) > 1000 then err := 'too many choices'; end if;
      when 'consent' then null;
      else err := 'unsupported field';
    end case;
    if err is not null then raise exception '%: %', lbl, err; end if;

    v_data := v_data || jsonb_build_array(jsonb_build_object('id', fld ->> 'id', 'label', lbl, 'type', t, 'value',
      case when t = 'checkboxes' then (select coalesce(jsonb_agg(x), '[]'::jsonb) from jsonb_array_elements_text(v) x)
           when t in ('rating', 'number') then to_jsonb(s::numeric)
           when t = 'consent' then 'true'::jsonb
           else to_jsonb(s) end));

    case r
      when 'name' then v_name := s;
      when 'phone' then v_phone := s;
      when 'email' then v_email := s;
      when 'topic' then v_topic := s;
      when 'speciality' then v_spec := s;
      when 'message' then v_msg := s;
      else null;
    end case;
    if (r is null or r not in ('name', 'phone', 'email', 'topic', 'speciality')) and t <> 'consent' then
      v_lines := v_lines || (lbl || ': ' || case when t = 'rating' then s || '/5' else s end);
    end if;
  end loop;

  if v_name = '' or v_phone = '' then raise exception 'This form is missing its name or mobile field. Please contact the hospital.'; end if;

  insert into public.site_enquiries (name, phone, email, topic, speciality, message, form_id, form_name, data)
  values (left(v_name, 120), v_phone, nullif(v_email, ''),
          left(coalesce(nullif(v_topic, ''), nullif(btrim(f.settings ->> 'topic'), ''), f.name), 80),
          nullif(left(v_spec, 80), ''),
          left(coalesce(nullif(v_msg, ''), nullif(array_to_string(v_lines, E'\n'), ''), f.name), 2000),
          f.id, f.name, v_data)
  returning ref into v_ref;
  return jsonb_build_object('ref', v_ref);
end $$;

revoke all on function public.submit_site_form(uuid, jsonb) from public;
grant execute on function public.submit_site_form(uuid, jsonb) to anon, authenticated;


-- =====================================================================================================
--  18. MESSAGING: PUSH (FCM) · ACCOUNT MESSAGES · CUSTOM & SCHEDULED MESSAGES · SUPABASE CRON · USAGE · USER ADMIN
--      (idempotent; also shipped in supabase/upgrade-2026-10.sql)
--
--    push_tokens                     browsers / phones that allowed push notifications (Firebase Cloud Messaging)
--    notify_enqueue(… , p_profile)   now also queues a push message for the person's devices
--    account_created / account_updated / account_deleted / password_changed / notice_published   new automatic messages
--    notification_templates          custom messages written by the owner: send now, once, daily, weekly, monthly or on
--                                    a patient's birthday — run_scheduled_notifications() is called by Supabase cron
--    notify_cron_setup(on, url)      schedules the jobs with pg_cron + pg_net (Settings → Notifications → Automatic delivery)
--    notification_usage(from, to)    messages per day / channel / event / status for the owner and the accountant
--    admin_create_user / admin_update_user / admin_set_user_password / admin_set_user_active / admin_delete_user
--                                    owner-only account management (Settings → Users & accounts)
-- =====================================================================================================

-- ------------------------------------------------------------------ notice board columns (older databases)
alter table public.notices add column if not exists pinned boolean not null default false;
alter table public.notices add column if not exists expires_on date;
alter table public.notices add column if not exists author_name text;

create or replace function public.stamp_notice()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' and new.author_name is null then
    new.author_name := (select full_name from public.profiles where id = auth.uid());
  end if;
  return new;
end $$;
drop trigger if exists trg_notices_stamp on public.notices;
create trigger trg_notices_stamp before insert on public.notices for each row execute function public.stamp_notice();
revoke all on function public.stamp_notice() from public, anon, authenticated;

-- ------------------------------------------------------------------ custom message templates (older databases)
create table if not exists public.notification_templates (
  id              uuid primary key default gen_random_uuid(),
  name            text not null check (char_length(name) between 2 and 80),
  description     text,
  channels        text[] not null default array['sms']::text[] check (channels <@ array['sms', 'whatsapp', 'email', 'push']::text[] and cardinality(channels) > 0),
  subject         text check (subject is null or char_length(subject) <= 200),
  text            text not null check (char_length(text) between 1 and 2000),
  wa_text         text check (wa_text is null or char_length(wa_text) <= 2000),
  wa_template     text,
  wa_params       text,
  sms_template_id text,
  audience        text not null default 'patients' check (audience in ('patients', 'staff', 'everyone', 'roles')),
  roles           text[] not null default '{}'::text[],
  schedule        text not null default 'manual' check (schedule in ('manual', 'once', 'daily', 'weekly', 'monthly', 'birthday')),
  send_at         timestamptz,
  time_of_day     text not null default '10:00' check (time_of_day ~ '^[0-2][0-9]:[0-5][0-9]$'),
  weekday         int check (weekday between 0 and 6),
  month_day       int check (month_day between 1 and 28),
  enabled         boolean not null default false,
  last_run_at     timestamptz,
  last_run_count  int,
  next_run_at     timestamptz,
  created_by_name text,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
drop trigger if exists trg_notification_templates_updated_at on public.notification_templates;
create trigger trg_notification_templates_updated_at before update on public.notification_templates
  for each row execute function public.set_updated_at();
alter table public.notification_templates enable row level security;
drop policy if exists notification_templates_select on public.notification_templates;
drop policy if exists notification_templates_insert on public.notification_templates;
drop policy if exists notification_templates_update on public.notification_templates;
drop policy if exists notification_templates_delete on public.notification_templates;
create policy notification_templates_select on public.notification_templates for select to authenticated using (public.has_role('owner'));
create policy notification_templates_insert on public.notification_templates for insert to authenticated with check (public.has_role('owner'));
create policy notification_templates_update on public.notification_templates for update to authenticated using (public.has_role('owner')) with check (public.has_role('owner'));
create policy notification_templates_delete on public.notification_templates for delete to authenticated using (public.has_role('owner'));
grant select, insert, update, delete on public.notification_templates to authenticated;

-- ------------------------------------------------------------------ outbox: push channel + who / which template
alter table public.notification_outbox drop constraint if exists notification_outbox_channel_check;
alter table public.notification_outbox add constraint notification_outbox_channel_check check (channel in ('sms', 'whatsapp', 'email', 'push'));
alter table public.notification_outbox add column if not exists profile_id uuid;
alter table public.notification_outbox add column if not exists template_id uuid;
create index if not exists notification_outbox_usage_idx on public.notification_outbox (created_at, channel);
grant select (profile_id, template_id) on public.notification_outbox to authenticated;
-- phase 3: which account delivered it — the hospital's own, or Hospital Comrade's shared one (null = own, older rows)
alter table public.notification_outbox add column if not exists source text;
alter table public.notification_outbox drop constraint if exists notification_outbox_source_check;
alter table public.notification_outbox add constraint notification_outbox_source_check check (source is null or source in ('own', 'platform'));
grant select (source) on public.notification_outbox to authenticated;

-- ------------------------------------------------------------------ message usage (phase 3)
-- Delivered / failed messages per hospital, calendar month (India time), channel and account. Written only by the
-- notify Edge Function (record_message_usage, service role); kept even after the outbox is cleaned up, so it is the
-- basis for the platform message allowance now and the prepaid wallet later. The owner and accountant can read it.
create table if not exists public.message_usage (
  tenant_id   uuid not null default public.current_tenant() references public.tenants (id) on delete cascade,
  month       date not null,
  channel     text not null check (channel in ('sms', 'whatsapp', 'email', 'push')),
  source      text not null default 'own' check (source in ('own', 'platform')),
  sent        int not null default 0,
  failed      int not null default 0,
  updated_at  timestamptz not null default now(),
  primary key (tenant_id, month, channel, source)
);
alter table public.message_usage enable row level security;
revoke all on public.message_usage from anon, authenticated;
grant select on public.message_usage to authenticated;
grant all on public.message_usage to service_role;
drop policy if exists message_usage_read on public.message_usage;
create policy message_usage_read on public.message_usage for select to authenticated
  using (public.has_role('owner') or public.has_role('accountant'));

-- ------------------------------------------------------------------ push devices (FCM registration tokens)
create table if not exists public.push_tokens (
  id            uuid primary key default gen_random_uuid(),
  profile_id    uuid not null references public.profiles (id) on delete cascade,
  token         text not null unique check (char_length(token) between 20 and 4096),
  platform      text not null default 'web' check (platform in ('web', 'android', 'ios')),
  user_agent    text,
  created_at    timestamptz not null default now(),
  last_seen_at  timestamptz not null default now()
);
create index if not exists push_tokens_profile_idx on public.push_tokens (profile_id);
alter table public.push_tokens enable row level security;
revoke all on public.push_tokens from anon, authenticated;
grant select, delete on public.push_tokens to authenticated;
grant all on public.push_tokens to service_role;
drop policy if exists push_tokens_own_read on public.push_tokens;
drop policy if exists push_tokens_own_delete on public.push_tokens;
create policy push_tokens_own_read on public.push_tokens for select to authenticated using (profile_id = auth.uid() or public.has_role('owner'));
create policy push_tokens_own_delete on public.push_tokens for delete to authenticated using (profile_id = auth.uid());

-- tables created by this section get their hospital column right away (functions below refer to it)
select public.ensure_tenant_columns();

-- a device belongs to whoever signed in on it last (shared reception PCs)
create or replace function public.register_push_token(p_token text, p_platform text default 'web', p_user_agent text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  if char_length(coalesce(p_token, '')) < 20 then raise exception 'Invalid device token'; end if;
  insert into public.push_tokens (profile_id, token, platform, user_agent)
  values (auth.uid(), p_token, case when p_platform in ('web', 'android', 'ios') then p_platform else 'web' end, left(p_user_agent, 300))
  on conflict (token) do update set profile_id = excluded.profile_id, platform = excluded.platform, user_agent = excluded.user_agent, last_seen_at = now();
  -- keep at most 10 devices per person
  delete from public.push_tokens where profile_id = auth.uid() and id not in
    (select id from public.push_tokens where profile_id = auth.uid() order by last_seen_at desc limit 10);
end $$;
revoke all on function public.register_push_token(text, text, text) from public, anon;
grant execute on function public.register_push_token(text, text, text) to authenticated;

-- ------------------------------------------------------------------ settings defaults for the new events
-- (adds missing events / templates to a saved Settings row; anything the owner already changed is kept)
with d as (select $json${"events":{"account_created":{"sms":false,"whatsapp":true,"email":true,"push":false},"account_updated":{"sms":false,"whatsapp":false,"email":true,"push":true},"account_deleted":{"sms":false,"whatsapp":false,"email":true},"password_changed":{"sms":true,"whatsapp":false,"email":true,"push":true},"notice_published":{"sms":false,"whatsapp":false,"email":false,"push":true},"login_otp":{"sms":true,"whatsapp":true,"email":true}},"templates":{"account_created":{"text":"Welcome to {hospital}, {name}! Your {role} account is ready. Sign in at {link} with {email}.","subject":"Welcome to {hospital}","waTemplate":"","waParams":"name,role,link","smsTemplateId":"","waText":"👋 *Welcome to {hospital}*\n\nHi {name}, your *{role}* account is ready.\nSign in: {link}\nE-mail: {email}","pushText":"Your {role} account is ready. Welcome aboard!"},"account_updated":{"text":"Hi {name}, your {hospital} account was updated ({changes}). If this was not you, call {hospital_phone}.","subject":"Your {hospital} account was updated","waTemplate":"","waParams":"name,changes","smsTemplateId":"","waText":"","pushText":"Your account was updated: {changes}"},"account_deleted":{"text":"Hi {name}, your {hospital} sign-in ({email}) has been removed. Your medical records are kept safely. Questions? Call {hospital_phone}.","subject":"Your {hospital} account was removed","waTemplate":"","waParams":"name,email","smsTemplateId":"","waText":""},"password_changed":{"text":"Hi {name}, your {hospital} password was changed on {time}. Not you? Reset it now: {link} or call {hospital_phone}.","subject":"Your password was changed","waTemplate":"","waParams":"name,time,link","smsTemplateId":"","waText":"","pushText":"Your password was changed on {time}. Not you? Reset it right away."},"notice_published":{"text":"{hospital} notice: {title}. {notice} — {link}","subject":"📌 {title}","waTemplate":"","waParams":"title,notice","smsTemplateId":"","waText":"📌 *{title}*\n\n{notice}\n\nRead on the notice board: {link}\n— {hospital}","pushText":"{notice}"},"login_otp":{"text":"{code} is your {hospital} sign-in code. It is valid for 10 minutes. Do not share it with anyone.","subject":"Your sign-in code","waTemplate":"","waParams":"code","smsTemplateId":"","waText":"🔐 *{code}* is your {hospital} sign-in code.\n\nIt is valid for 10 minutes. Didn't just sign in? Change your password — someone knows it."}},"push":{"enabled":false,"apiKey":"","authDomain":"","projectId":"","messagingSenderId":"","appId":"","vapidKey":""},"rates":{"sms":0.25,"whatsapp":0.8,"email":0.05,"push":0}}$json$::jsonb as j)
update public.app_settings a set data = jsonb_set(a.data, '{notifications}', coalesce(a.data -> 'notifications', '{}'::jsonb) || jsonb_build_object(
    'events', (d.j -> 'events') || coalesce(a.data -> 'notifications' -> 'events', '{}'::jsonb),
    'templates', (d.j -> 'templates') || coalesce(a.data -> 'notifications' -> 'templates', '{}'::jsonb),
    'push', (d.j -> 'push') || coalesce(a.data -> 'notifications' -> 'push', '{}'::jsonb),
    'rates', (d.j -> 'rates') || coalesce(a.data -> 'notifications' -> 'rates', '{}'::jsonb)))
  from d
 where a.key = 'app' and jsonb_typeof(a.data -> 'notifications') = 'object';

-- ------------------------------------------------------------------ queue
-- One message per channel. p_tpl = {text, subject, waText, pushText}. Never raises.
create or replace function public.notify_enqueue_raw(p_event text, p_tpl jsonb, p_channels text[], p_phone text, p_email text, p_profile uuid,
  p_vars jsonb, p_related_table text default null, p_related_id uuid default null, p_template uuid default null)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  n        jsonb := (public.tenant_setting('app') -> 'notifications');
  site     jsonb := public.tenant_content('settings');
  ch       text;
  v_to     text;
  v_body   text;
  v_subj   text;
  v_vars   jsonb;
  k        text;
  v_count  int := 0;
  v_limit  int;
  v_used   bigint;
begin
  if n is null or p_tpl is null then return 0; end if;
  v_vars := jsonb_build_object(
      'hospital', coalesce(nullif(site ->> 'name', ''), 'DC Hospital'),
      'hospital_phone', coalesce(nullif(site ->> 'appointmentsPhone', ''), site ->> 'phone', ''),
      'address', coalesce(site ->> 'address', ''),
      'site_url', rtrim(coalesce(site ->> 'siteUrl', ''), '/'))
    || coalesce(p_vars, '{}'::jsonb);

  foreach ch in array array['sms', 'whatsapp', 'email', 'push'] loop
    continue when not (ch = any (coalesce(p_channels, '{}')));
    continue when coalesce((n -> ch ->> 'enabled')::boolean, false) is not true;
    if ch = 'email' then
      v_to := nullif(lower(trim(coalesce(p_email, ''))), '');
      continue when v_to is null or v_to !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$';
    elsif ch = 'push' then
      continue when p_profile is null or not exists (select 1 from public.push_tokens where profile_id = p_profile);
      v_to := p_profile::text;
    else
      v_to := right(regexp_replace(coalesce(p_phone, ''), '\D', '', 'g'), 10);
      continue when v_to !~ '^[6-9][0-9]{9}$';
    end if;
    v_body := case
      when ch = 'whatsapp' and coalesce(p_tpl ->> 'waText', '') <> '' then p_tpl ->> 'waText'
      when ch = 'push' and coalesce(p_tpl ->> 'pushText', '') <> '' then p_tpl ->> 'pushText'
      else coalesce(p_tpl ->> 'text', '') end;
    v_subj := coalesce(nullif(p_tpl ->> 'subject', ''), case when ch = 'push' then '{hospital}' else '' end);
    continue when v_body = '';
    -- monthly cap on the shared (platform) accounts, set by the Hospital Comrade team (control panel → Messaging)
    if ch <> 'push' and coalesce(n -> ch ->> 'source', 'own') = 'platform' then
      select (t.billing -> 'monthlyLimit' ->> ch)::int into v_limit from public.tenants t where t.id = public.current_tenant();
      if v_limit is not null then
        select coalesce(sum(u.sent), 0) into v_used from public.message_usage u
         where u.tenant_id = public.current_tenant() and u.channel = ch and u.source = 'platform'
           and u.month = date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
        v_used := v_used + (select count(*) from public.notification_outbox o
                             where o.tenant_id = public.current_tenant() and o.channel = ch and o.status in ('pending', 'sending'));
        continue when v_used >= v_limit;
      end if;
    end if;
    for k in select jsonb_object_keys(v_vars) loop
      v_body := replace(v_body, '{' || k || '}', coalesce(v_vars ->> k, ''));
      v_subj := replace(v_subj, '{' || k || '}', coalesce(v_vars ->> k, ''));
    end loop;
    insert into public.notification_outbox (event, channel, recipient, subject, body, vars, related_table, related_id, profile_id, template_id)
    values (p_event, ch, v_to, nullif(v_subj, ''), left(v_body, 4000), v_vars, p_related_table, p_related_id, p_profile, p_template);
    v_count := v_count + 1;
  end loop;
  return v_count;
exception when others then
  raise warning 'notify_enqueue_raw(%) failed: %', p_event, sqlerrm;
  return 0;
end $$;
revoke all on function public.notify_enqueue_raw(text, jsonb, text[], text, text, uuid, jsonb, text, uuid, uuid) from public, anon, authenticated;

-- Built-in events: wording + channels from Settings → Notifications. Same arguments as before plus p_profile (push).
drop function if exists public.notify_enqueue(text, text, text, jsonb, text, uuid, text[]) cascade;
create or replace function public.notify_enqueue(p_event text, p_phone text, p_email text, p_vars jsonb, p_related_table text default null,
  p_related_id uuid default null, p_only text[] default null, p_profile uuid default null)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  n    jsonb := (public.tenant_setting('app') -> 'notifications');
  chs  text[];
begin
  if n is null or n -> 'events' -> p_event is null then return 0; end if;
  select coalesce(array_agg(c), '{}') into chs from unnest(array['sms', 'whatsapp', 'email', 'push']) c
   where coalesce((n -> 'events' -> p_event ->> c)::boolean, false) and (p_only is null or c = any (p_only));
  return public.notify_enqueue_raw(p_event, n -> 'templates' -> p_event, chs, p_phone, p_email, p_profile, p_vars, p_related_table, p_related_id, null);
end $$;
revoke all on function public.notify_enqueue(text, text, text, jsonb, text, uuid, text[], uuid) from public, anon, authenticated;

create or replace function public.role_label(r text)
returns text language sql immutable as $$
  select case r when 'owner' then 'Hospital Owner' when 'receptionist' then 'Receptionist' when 'accountant' then 'Accountant'
                when 'doctor' then 'Doctor' when 'staff' then 'Staff' when 'patient' then 'Patient' else initcap(coalesce(r, '')) end
$$;

-- ------------------------------------------------------------------ account messages
-- welcome: checked at the end of the transaction, so an account created by the owner already has its final role
create or replace function public.notify_account_created()
returns trigger language plpgsql security definer set search_path = public as $$
declare p public.profiles;
begin
  select * into p from public.profiles where id = new.id;
  if not found then return null; end if;
  perform public.notify_enqueue('account_created', p.phone, p.email, jsonb_build_object(
    'name', split_part(p.full_name, ' ', 1), 'role', public.role_label(p.role::text), 'email', p.email,
    'link', public.site_url() || '/login'), 'profiles', p.id, null, p.id);
  return null;
exception when others then
  raise warning 'notify_account_created: %', sqlerrm;
  return null;
end $$;
drop trigger if exists trg_profiles_notify_created on public.profiles;
create constraint trigger trg_profiles_notify_created after insert on public.profiles
  deferrable initially deferred for each row execute function public.notify_account_created();

create or replace function public.notify_account_updated()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_changes text[] := '{}';
begin
  if new.role is distinct from old.role then v_changes := v_changes || ('role: ' || public.role_label(new.role::text)); end if;
  if lower(new.email) is distinct from lower(old.email) then v_changes := v_changes || ('e-mail: ' || new.email); end if;
  if coalesce(new.phone, '') is distinct from coalesce(old.phone, '') then v_changes := v_changes || ('mobile: ' || coalesce(new.phone, 'removed')); end if;
  if cardinality(v_changes) = 0 then return new; end if;
  -- tell both the old and the new address when the contact details change
  perform public.notify_enqueue('account_updated', coalesce(new.phone, old.phone), new.email, jsonb_build_object(
    'name', split_part(new.full_name, ' ', 1), 'role', public.role_label(new.role::text), 'changes', array_to_string(v_changes, ', '),
    'link', public.site_url() || '/profile'), 'profiles', new.id, null, new.id);
  if lower(new.email) is distinct from lower(old.email) then
    perform public.notify_enqueue('account_updated', null, old.email, jsonb_build_object(
      'name', split_part(new.full_name, ' ', 1), 'role', public.role_label(new.role::text), 'changes', array_to_string(v_changes, ', '),
      'link', public.site_url() || '/profile'), 'profiles', new.id, array['email'], null);
  end if;
  return new;
exception when others then
  raise warning 'notify_account_updated: %', sqlerrm;
  return new;
end $$;
drop trigger if exists trg_profiles_notify_updated on public.profiles;
create trigger trg_profiles_notify_updated after update on public.profiles
  for each row execute function public.notify_account_updated();

create or replace function public.notify_account_deleted()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.notify_enqueue('account_deleted', old.phone, old.email, jsonb_build_object(
    'name', split_part(old.full_name, ' ', 1), 'role', public.role_label(old.role::text), 'email', old.email), 'profiles', old.id,
    array['sms', 'whatsapp', 'email'], null);
  return old;
exception when others then
  raise warning 'notify_account_deleted: %', sqlerrm;
  return old;
end $$;
drop trigger if exists trg_profiles_notify_deleted on public.profiles;
create trigger trg_profiles_notify_deleted before delete on public.profiles
  for each row execute function public.notify_account_deleted();

-- security alert whenever a password changes (self-service, reset link, mobile OTP or the owner)
create or replace function public.notify_password_changed()
returns trigger language plpgsql security definer set search_path = public as $$
declare p public.profiles;
begin
  if coalesce(old.encrypted_password, '') = '' or new.encrypted_password is not distinct from old.encrypted_password then return new; end if;
  select * into p from public.profiles where id = new.id;
  if not found then return new; end if;
  perform public.notify_enqueue('password_changed', p.phone, p.email, jsonb_build_object(
    'name', split_part(p.full_name, ' ', 1), 'time', to_char(now() at time zone 'Asia/Kolkata', 'DD Mon YYYY, HH12:MI AM'),
    'link', public.site_url() || '/forgot-password'), 'profiles', p.id, null, p.id);
  return new;
exception when others then
  raise warning 'notify_password_changed: %', sqlerrm;
  return new;
end $$;
drop trigger if exists trg_auth_users_password_notify on auth.users;
create trigger trg_auth_users_password_notify after update of encrypted_password on auth.users
  for each row execute function public.notify_password_changed();

-- a new notice on the board reaches its audience (push by default; e-mail / SMS / WhatsApp if switched on)
create or replace function public.notify_notice()
returns trigger language plpgsql security definer set search_path = public as $$
declare r record;
begin
  if new.published_on > public.today_ist() then return new; end if;
  for r in
    select p.id, p.full_name, p.phone, p.email from public.profiles p
    where (new.audience = 'all'
        or (new.audience = 'staff' and p.role <> 'patient')
        or (new.audience = 'doctors' and p.role = 'doctor')
        or (new.audience = 'patients' and p.role = 'patient'))
      and p.tenant_id = new.tenant_id
      and p.id is distinct from auth.uid()
    limit 5000
  loop
    perform public.notify_enqueue('notice_published', r.phone, r.email, jsonb_build_object(
      'name', split_part(r.full_name, ' ', 1), 'title', new.title, 'notice', left(new.body, 300),
      'priority', initcap(new.priority), 'link', public.site_url() || '/notices'), 'notices', new.id, null, r.id);
  end loop;
  return new;
exception when others then
  raise warning 'notify_notice: %', sqlerrm;
  return new;
end $$;
drop trigger if exists trg_notices_notify on public.notices;
create trigger trg_notices_notify after insert on public.notices for each row execute function public.notify_notice();

revoke all on function public.notify_account_created() from public, anon, authenticated;
revoke all on function public.notify_account_updated() from public, anon, authenticated;
revoke all on function public.notify_account_deleted() from public, anon, authenticated;
revoke all on function public.notify_password_changed() from public, anon, authenticated;
revoke all on function public.notify_notice() from public, anon, authenticated;

-- ------------------------------------------------------------------ custom & scheduled messages
-- next time a template is due (India time), strictly after p_after; null = nothing more to send
create or replace function public.notify_next_run(t public.notification_templates, p_after timestamptz default now())
returns timestamptz language plpgsql stable as $$
declare
  v_local timestamp := p_after at time zone 'Asia/Kolkata';
  v_time  time := t.time_of_day::time;
  v_day   date := v_local::date;
  v_cand  timestamp;
  i       int;
begin
  if not t.enabled then return null; end if;
  case t.schedule
    when 'manual' then return null;
    when 'once' then return case when t.send_at > p_after then t.send_at else null end;
    when 'daily', 'birthday' then
      v_cand := v_day + v_time;
      if v_cand <= v_local then v_cand := v_cand + interval '1 day'; end if;
    when 'weekly' then
      for i in 0..7 loop
        v_cand := (v_day + i) + v_time;
        exit when extract(dow from v_day + i)::int = coalesce(t.weekday, 1) and v_cand > v_local;
      end loop;
    when 'monthly' then
      v_cand := (date_trunc('month', v_day)::date + (coalesce(t.month_day, 1) - 1)) + v_time;
      if v_cand <= v_local then v_cand := (date_trunc('month', v_day)::date + interval '1 month')::date + (coalesce(t.month_day, 1) - 1) + v_time; end if;
    else return null;
  end case;
  return v_cand at time zone 'Asia/Kolkata';
end $$;

create or replace function public.stamp_notification_template()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then new.created_by_name := coalesce(new.created_by_name, (select full_name from public.profiles where id = auth.uid())); end if;
  if new.audience = 'roles' and cardinality(new.roles) = 0 then raise exception 'Pick at least one role to send to.'; end if;
  if new.schedule = 'once' and new.enabled and new.send_at is null then raise exception 'Pick when to send it.'; end if;
  if tg_op = 'INSERT' or new.enabled is distinct from old.enabled or new.schedule is distinct from old.schedule or new.send_at is distinct from old.send_at
     or new.time_of_day is distinct from old.time_of_day or new.weekday is distinct from old.weekday or new.month_day is distinct from old.month_day then
    new.next_run_at := public.notify_next_run(new, now());
  end if;
  return new;
end $$;
drop trigger if exists trg_notification_templates_stamp on public.notification_templates;
create trigger trg_notification_templates_stamp before insert or update on public.notification_templates
  for each row execute function public.stamp_notification_template();
revoke all on function public.stamp_notification_template() from public, anon, authenticated;

-- who a template goes to (one row per mobile / e-mail; birthdays = patients born on this day)
create or replace function public.notify_template_recipients(t public.notification_templates)
returns table (profile_id uuid, full_name text, phone text, email text)
language sql stable security definer set search_path = public as $$
  with people as (
    select p.profile_id, p.full_name, p.phone, p.email, 1 as pri from public.patients p
     where p.tenant_id = t.tenant_id
       and (t.audience in ('patients', 'everyone') or t.schedule = 'birthday' or (t.audience = 'roles' and 'patient' = any (t.roles)))
       and (t.schedule <> 'birthday' or to_char(p.date_of_birth, 'MM-DD') = to_char(now() at time zone 'Asia/Kolkata', 'MM-DD'))
       -- phase 7: patients who said no to health tips & offers, and erased patients, get no custom messages
       -- (to_jsonb: the columns are added later, in compliance.sql)
       and coalesce((to_jsonb(p) ->> 'marketing_opt_out')::boolean, false) = false and (to_jsonb(p) ->> 'erased_at') is null
    union all
    select pr.id, pr.full_name, pr.phone, pr.email, 2 from public.profiles pr
     where pr.tenant_id = t.tenant_id and t.schedule <> 'birthday' and pr.role <> 'patient'
       and (t.audience in ('staff', 'everyone') or (t.audience = 'roles' and pr.role::text = any (t.roles)))
  )
  select distinct on (coalesce(right(regexp_replace(phone, '\D', '', 'g'), 10), lower(email), profile_id::text))
         profile_id, full_name, phone, email
    from people
   order by coalesce(right(regexp_replace(phone, '\D', '', 'g'), 10), lower(email), profile_id::text), pri
   limit 5000
$$;
revoke all on function public.notify_template_recipients(public.notification_templates) from public, anon, authenticated;

create or replace function public.notify_run_template(t public.notification_templates)
returns int language plpgsql volatile security definer set search_path = public as $$
declare r record; v_count int := 0; v_tpl jsonb;
begin
  v_tpl := jsonb_build_object('text', t.text, 'subject', coalesce(t.subject, ''), 'waText', coalesce(t.wa_text, ''));
  for r in select * from public.notify_template_recipients(t) loop
    v_count := v_count + public.notify_enqueue_raw('tpl:' || t.id, v_tpl, t.channels, r.phone, r.email, r.profile_id,
      jsonb_build_object('name', split_part(coalesce(r.full_name, ''), ' ', 1), 'full_name', coalesce(r.full_name, '')),
      'notification_templates', t.id, t.id);
  end loop;
  update public.notification_templates set last_run_at = now(), last_run_count = v_count where id = t.id;
  return v_count;
end $$;
revoke all on function public.notify_run_template(public.notification_templates) from public, anon, authenticated;

-- "Send now" (owner) and the recipient preview
create or replace function public.notify_send_template(p_id uuid)
returns int language plpgsql volatile security definer set search_path = public as $$
declare t public.notification_templates;
begin
  if not public.has_role('owner') then raise exception 'Only the hospital owner can send messages'; end if;
  perform public.module_guard('notifications');
  select * into t from public.notification_templates where id = p_id and tenant_id = public.current_tenant();
  if not found then raise exception 'Message not found'; end if;
  return public.notify_run_template(t);
end $$;
create or replace function public.notify_template_audience(p_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare t public.notification_templates;
begin
  if not public.has_role('owner') then raise exception 'Not allowed'; end if;
  select * into t from public.notification_templates where id = p_id and tenant_id = public.current_tenant();
  if not found then return jsonb_build_object('total', 0); end if;
  return (select jsonb_build_object('total', count(*), 'phone', count(*) filter (where right(regexp_replace(coalesce(phone, ''), '\D', '', 'g'), 10) ~ '^[6-9][0-9]{9}$'),
            'email', count(*) filter (where email ~ '@'), 'push', count(*) filter (where exists (select 1 from public.push_tokens k where k.profile_id = r.profile_id)))
          from public.notify_template_recipients(t) r);
end $$;
revoke all on function public.notify_send_template(uuid) from public, anon;
revoke all on function public.notify_template_audience(uuid) from public, anon;
grant execute on function public.notify_send_template(uuid) to authenticated;
grant execute on function public.notify_template_audience(uuid) to authenticated;

-- every few minutes (Supabase cron): send whatever is due and work out the next run
create or replace function public.run_scheduled_notifications()
returns int language plpgsql volatile security definer set search_path = public as $$
declare t public.notification_templates; v_total int := 0; v_all boolean;
begin
  if auth.uid() is not null and not public.has_role('owner') then raise exception 'Not allowed'; end if;
  -- the cron job serves every hospital; an owner's "run now" only their own
  v_all := auth.uid() is null and nullif(current_setting('app.tenant_id', true), '') is null;
  for t in select * from public.notification_templates where enabled and next_run_at is not null and next_run_at <= now()
             and (v_all or tenant_id = public.current_tenant())
           order by next_run_at limit 50 for update skip locked loop
    if v_all then perform set_config('app.tenant_id', t.tenant_id::text, true); end if;   -- messages queue under that hospital
    v_total := v_total + public.notify_run_template(t);
    update public.notification_templates
       set next_run_at = public.notify_next_run(t, greatest(now(), t.next_run_at)),
           enabled = case when t.schedule = 'once' then false else enabled end
     where id = t.id;
  end loop;
  if v_all then perform set_config('app.tenant_id', '', true); end if;
  return v_total;
end $$;
revoke all on function public.run_scheduled_notifications() from public, anon;
grant execute on function public.run_scheduled_notifications() to authenticated, service_role;

-- ------------------------------------------------------------------ usage report (owner + accountant)
create or replace function public.notification_usage(p_from date, p_to date)
returns table (day date, channel text, event text, status text, n bigint)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_role('owner', 'accountant') then raise exception 'Only the owner and the accountant can see messaging usage'; end if;
  if p_to < p_from or p_to - p_from > 400 then raise exception 'Pick a range of up to 400 days'; end if;
  return query
    select (o.created_at at time zone 'Asia/Kolkata')::date, o.channel,
           case when o.event like 'tpl:%' then 'custom' else o.event end, o.status, count(*)
      from public.notification_outbox o
     where o.tenant_id = public.current_tenant()
       and o.created_at >= (p_from::timestamp at time zone 'Asia/Kolkata')
       and o.created_at < ((p_to + 1)::timestamp at time zone 'Asia/Kolkata')
     group by 1, 2, 3, 4
     order by 1;
end $$;
revoke all on function public.notification_usage(date, date) from public, anon;
grant execute on function public.notification_usage(date, date) to authenticated;

-- ------------------------------------------------------------------ the queue for the notify Edge Function
-- Used by the Edge Function (service role) to take a batch of messages to deliver.
-- p_tenant: only that hospital's queue (a staff member's "deliver now"); null = every hospital (the scheduler).
-- Suspended hospitals' messages wait (they go out if the hospital is reactivated, or expire with the cleanup job).
drop function if exists public.claim_notifications(int) cascade;
drop function if exists public.claim_notifications(int, uuid) cascade;
create function public.claim_notifications(p_limit int default 25, p_tenant uuid default null)
returns setof public.notification_outbox language plpgsql volatile security definer set search_path = public as $$
begin
  -- give up on messages that got stuck mid-delivery three times
  update public.notification_outbox set status = 'failed', error = coalesce(error, 'Delivery timed out')
  where status = 'sending' and attempts >= 3 and coalesce(last_attempt_at, created_at) < now() - interval '10 minutes';

  return query
    update public.notification_outbox o set status = 'sending', attempts = o.attempts + 1, last_attempt_at = now()
    where o.id in (
      select x.id from public.notification_outbox x
      where ((x.status = 'pending' and x.next_attempt_at <= now())
          or (x.status = 'sending' and x.attempts < 3 and coalesce(x.last_attempt_at, x.created_at) < now() - interval '10 minutes'))
        and (p_tenant is null or x.tenant_id = p_tenant)
        and not exists (select 1 from public.tenants t where t.id = x.tenant_id and t.status = 'suspended')
      order by x.created_at
      limit greatest(1, least(p_limit, 100))
      for update skip locked)
    returning o.*;
end $$;
revoke all on function public.claim_notifications(int, uuid) from public, anon, authenticated;
grant execute on function public.claim_notifications(int, uuid) to service_role;

-- ------------------------------------------------------------------ Supabase cron (pg_cron + pg_net)
-- The job calls the `notify` Edge Function with the service-role key the owner saved (write-only, like every credential).
create or replace function public.notify_cron_flush()
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_url text; v_key text;
begin
  -- "sign in as user" time limit (control_panel_ops.sql) rides on this every-minute job
  if to_regprocedure('public.impersonation_expire()') is not null then execute 'select public.impersonation_expire()'; end if;
  -- control panel: team alerts, broadcasts and health checks (cp_notify.sql)
  if to_regprocedure('public.ops_cron_tick()') is not null then execute 'select public.ops_cron_tick()'; end if;
  if not exists (select 1 from public.notification_outbox where status = 'pending' and next_attempt_at <= now()) then return; end if;
  v_url := public.tenant_secret('notify_function_url');
  v_key := public.tenant_secret('service_role_key');
  if v_url is null or v_key is null then return; end if;
  execute 'select net.http_post(url := $1, headers := $2, body := $3, timeout_milliseconds := 55000)'
    using v_url, jsonb_build_object('Authorization', 'Bearer ' || v_key, 'Content-Type', 'application/json'), '{"flush":true}'::jsonb;
end $$;
revoke all on function public.notify_cron_flush() from public, anon, authenticated;

create or replace function public.notify_cron_status()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_cron boolean := exists (select 1 from pg_extension where extname = 'pg_cron');
        v_net boolean := exists (select 1 from pg_extension where extname = 'pg_net');
        v_jobs jsonb := '[]'::jsonb;
begin
  if not public.has_role('owner') then raise exception 'Not allowed'; end if;
  if v_cron then
    execute $q$ select coalesce(jsonb_agg(jsonb_build_object('name', j.jobname, 'schedule', j.schedule, 'active', j.active,
              'last_run', d.start_time, 'last_status', d.status, 'last_message', left(d.return_message, 200)) order by j.jobname), '[]'::jsonb)
           from cron.job j
           left join lateral (select start_time, status, return_message from cron.job_run_details r where r.jobid = j.jobid order by start_time desc limit 1) d on true
          where j.jobname like 'dch-%' $q$ into v_jobs;
  end if;
  return jsonb_build_object('pg_cron', v_cron, 'pg_net', v_net, 'jobs', v_jobs,
    'url_set', public.tenant_secret('notify_function_url') is not null,
    'key_set', public.tenant_secret('service_role_key') is not null,
    'pending', (select count(*) from public.notification_outbox where status = 'pending' and tenant_id = public.current_tenant()),
    'scheduled', (select count(*) from public.notification_templates where enabled and next_run_at is not null and tenant_id = public.current_tenant()));
end $$;

create or replace function public.notify_cron_setup(p_enable boolean, p_url text default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare j record;
begin
  if not public.has_role('owner') then raise exception 'Only the hospital owner can change automatic delivery'; end if;
  perform public.module_guard('notifications');
  -- one scheduler serves every hospital, using the main hospital's notify address and key
  if public.current_tenant() is distinct from public.primary_tenant() then
    raise exception 'Automatic delivery is managed by the platform — it already runs for your hospital.';
  end if;
  if p_url is not null and p_url <> '' then
    if p_url !~ '^https://[^ ]+/functions/v1/notify$' then raise exception 'The address should look like https://<project>.supabase.co/functions/v1/notify'; end if;
    insert into public.app_secrets (key, value, updated_at, updated_by_name) values ('notify_function_url', p_url, now(), (select full_name from public.profiles where id = auth.uid()))
    on conflict (tenant_id, key) do update set value = excluded.value, updated_at = now(), updated_by_name = excluded.updated_by_name;
  end if;
  if p_enable then
    -- Supabase lets the database owner switch these on; otherwise: Dashboard → Database → Extensions
    begin execute 'create extension if not exists pg_cron'; exception when others then null; end;
    begin execute 'create extension if not exists pg_net'; exception when others then null; end;
    if not exists (select 1 from pg_extension where extname = 'pg_cron') then raise exception 'CRON_MISSING: Turn on the pg_cron extension (Supabase → Database → Extensions) and try again.'; end if;
    if not exists (select 1 from pg_extension where extname = 'pg_net') then raise exception 'CRON_MISSING: Turn on the pg_net extension (Supabase → Database → Extensions) and try again.'; end if;
    if not public.tenant_secret('service_role_key') is not null then raise exception 'Save the service-role key first (it lets the scheduler call the notify function).'; end if;
    if not public.tenant_secret('notify_function_url') is not null then raise exception 'Save the notify function address first.'; end if;
    execute $c$ select cron.schedule('dch-notify-flush', '* * * * *', 'select public.notify_cron_flush()') $c$;
    execute $c$ select cron.schedule('dch-scheduled-messages', '*/5 * * * *', 'select public.run_scheduled_notifications()') $c$;
    execute $c$ select cron.schedule('dch-appointment-reminders', '30 12 * * *', 'select public.queue_appointment_reminders()') $c$;  -- 18:00 IST
    -- Hospital Comrade renewal reminders to owners (phase 6); the function exists once billing.sql is loaded
    execute $c$ select cron.schedule('dch-billing-reminders', '0 4 * * *', 'select public.queue_billing_reminders()') $c$;  -- 09:30 IST
    -- retention (phase 7): delivery log, audit logs, OTPs, enquiries… per Platform settings → Retention (was dch-outbox-cleanup)
    execute $c$ select cron.schedule('dch-retention', '30 21 * * *', 'select public.run_retention()') $c$;  -- 03:00 IST
    -- the public demo hospital back to its demo data (demo.sql; does nothing without a demo hospital)
    execute $c$ select cron.schedule('dch-demo-reset', '30 21 * * *', 'select public.demo_reset_nightly()') $c$;  -- 03:00 IST
  elsif exists (select 1 from pg_extension where extname = 'pg_cron') then
    for j in execute $q$ select jobid from cron.job where jobname like 'dch-%' $q$ loop
      execute 'select cron.unschedule($1)' using j.jobid;
    end loop;
  end if;
  return public.notify_cron_status();
end $$;
revoke all on function public.notify_cron_status() from public, anon;
revoke all on function public.notify_cron_setup(boolean, text) from public, anon;
grant execute on function public.notify_cron_status() to authenticated;
grant execute on function public.notify_cron_setup(boolean, text) to authenticated;

-- ------------------------------------------------------------------ user administration (owner only)
-- profiles.email follows auth.users; signed-in users can't change it directly — except through admin_update_user()
create or replace function public.protect_profile_role()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.role is distinct from old.role and auth.uid() is not null and not public.has_role('owner') then
    raise exception 'Only the hospital owner can change user roles';
  end if;
  if new.email is distinct from old.email and auth.uid() is not null and coalesce(current_setting('dch.admin_email', true), '') <> 'on' then
    new.email := old.email;
  end if;
  return new;
end $$;

create or replace function public.admin_guard()
returns void language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_role('owner') then raise exception 'Only the hospital owner can manage user accounts'; end if;
end $$;

-- the account must belong to the hospital the owner is managing
create or replace function public.admin_target(p_id uuid)
returns void language plpgsql stable security definer set search_path = public as $$
begin
  if not exists (select 1 from public.profiles where id = p_id and tenant_id = public.current_tenant()) then
    raise exception 'User not found';
  end if;
end $$;
revoke all on function public.admin_target(uuid) from public, anon, authenticated;

create or replace function public.admin_create_user(p_email text, p_full_name text, p_role text, p_phone text default null, p_password text default null)
returns uuid language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  v_id    uuid := gen_random_uuid();
  v_email text := lower(trim(coalesce(p_email, '')));
  v_pass  text := coalesce(nullif(p_password, ''), encode(gen_random_bytes(18), 'base64'));
begin
  perform public.admin_guard();
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then raise exception 'Enter a valid e-mail address'; end if;
  if char_length(trim(coalesce(p_full_name, ''))) < 2 then raise exception 'Enter the full name'; end if;
  if p_role not in ('owner', 'doctor', 'receptionist', 'accountant', 'staff', 'patient') then raise exception 'Choose a role'; end if;
  if p_password is not null and p_password <> '' and char_length(p_password) < 8 then raise exception 'Use at least 8 characters for the password'; end if;
  if exists (select 1 from auth.users where lower(email) = v_email) then raise exception 'An account with this e-mail already exists'; end if;

  insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
                          created_at, updated_at, confirmation_token, email_change, email_change_token_new, recovery_token)
  values ('00000000-0000-0000-0000-000000000000', v_id, 'authenticated', 'authenticated', v_email, crypt(v_pass, gen_salt('bf')), now(),
          '{"provider":"email","providers":["email"]}'::jsonb, jsonb_build_object('full_name', trim(p_full_name), 'phone', nullif(trim(coalesce(p_phone, '')), ''), 'tenant_id', public.current_tenant()),
          now(), now(), '', '', '', '');
  insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  values (gen_random_uuid(), v_id, v_id::text, jsonb_build_object('sub', v_id, 'email', v_email, 'email_verified', true), 'email', null, now(), now());

  -- handle_new_user() made a patient profile; give it the chosen role
  update public.profiles set role = p_role::public.app_role, full_name = trim(p_full_name), phone = nullif(trim(coalesce(p_phone, '')), '') where id = v_id;
  if p_role <> 'patient' then
    delete from public.patients where profile_id = v_id;
    if p_role = 'doctor' then update public.doctors set profile_id = v_id where lower(email) = v_email and profile_id is null and tenant_id = public.current_tenant();
    else update public.staff set profile_id = v_id where lower(email) = v_email and profile_id is null and tenant_id = public.current_tenant(); end if;
  end if;
  return v_id;
end $$;

create or replace function public.admin_update_user(p_id uuid, p_full_name text, p_role text, p_phone text default null, p_email text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare p public.profiles; v_email text := lower(trim(coalesce(p_email, '')));
begin
  perform public.admin_guard();
  select * into p from public.profiles where id = p_id and tenant_id = public.current_tenant() for update;
  if not found then raise exception 'User not found'; end if;
  if char_length(trim(coalesce(p_full_name, ''))) < 2 then raise exception 'Enter the full name'; end if;
  if p_role not in ('owner', 'doctor', 'receptionist', 'accountant', 'staff', 'patient') then raise exception 'Choose a role'; end if;
  if p.role = 'owner' and p_role <> 'owner' and (p_id = auth.uid() or (select count(*) from public.profiles where role = 'owner' and tenant_id = public.current_tenant()) <= 1) then
    raise exception 'You can''t remove your own owner access or the last owner';
  end if;
  if v_email <> '' and v_email <> lower(p.email) then
    if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then raise exception 'Enter a valid e-mail address'; end if;
    if exists (select 1 from auth.users where lower(email) = v_email and id <> p_id) then raise exception 'Another account already uses this e-mail'; end if;
    update auth.users set email = v_email, email_confirmed_at = coalesce(email_confirmed_at, now()), updated_at = now() where id = p_id;
  else
    v_email := p.email;
  end if;
  perform set_config('dch.admin_email', 'on', true);
  update public.profiles set full_name = trim(p_full_name), role = p_role::public.app_role, phone = nullif(trim(coalesce(p_phone, '')), ''), email = v_email
   where id = p_id;
  perform set_config('dch.admin_email', '', true);
end $$;

create or replace function public.admin_set_user_password(p_id uuid, p_password text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
begin
  perform public.admin_guard();
  if char_length(coalesce(p_password, '')) < 8 then raise exception 'Use at least 8 characters'; end if;
  perform public.admin_target(p_id);
  update auth.users set encrypted_password = crypt(p_password, gen_salt('bf')), updated_at = now() where id = p_id;
  if not found then raise exception 'User not found'; end if;
end $$;

-- disabled accounts can't sign in (Supabase honours banned_until); their records stay
create or replace function public.admin_set_user_active(p_id uuid, p_active boolean)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.admin_guard();
  if p_id = auth.uid() then raise exception 'You can''t disable your own account'; end if;
  perform public.admin_target(p_id);
  update auth.users set banned_until = case when p_active then null else 'infinity'::timestamptz end, updated_at = now() where id = p_id;
  if not found then raise exception 'User not found'; end if;
  if not p_active and to_regclass('auth.sessions') is not null then execute 'delete from auth.sessions where user_id = $1' using p_id; end if;
end $$;

drop function if exists public.admin_user_status();
create or replace function public.admin_user_status(p_ids uuid[])
returns table (id uuid, disabled boolean, last_sign_in_at timestamptz)
language plpgsql stable security definer set search_path = public as $$
begin
  perform public.admin_guard();
  return query execute
    case when exists (select 1 from information_schema.columns where table_schema = 'auth' and table_name = 'users' and column_name = 'last_sign_in_at')
         then 'select u.id, coalesce(u.banned_until > now(), false), u.last_sign_in_at from auth.users u where u.id = any ($1)'
         else 'select u.id, coalesce(u.banned_until > now(), false), null::timestamptz from auth.users u where u.id = any ($1)' end
    using array(select x.id from public.profiles x where x.id = any (p_ids[1:200]) and x.tenant_id = public.current_tenant());
end $$;

-- deletes the login; patient / doctor / staff records and their history stay (they are unlinked)
create or replace function public.admin_delete_user(p_id uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare p public.profiles;
begin
  perform public.admin_guard();
  if p_id = auth.uid() then raise exception 'You can''t delete your own account'; end if;
  select * into p from public.profiles where id = p_id and tenant_id = public.current_tenant();
  if not found then raise exception 'User not found'; end if;
  if p.role = 'owner' and (select count(*) from public.profiles where role = 'owner' and tenant_id = public.current_tenant()) <= 1 then raise exception 'You can''t delete the last owner'; end if;
  delete from public.profiles where id = p_id;   -- fires the account_deleted message while the details still exist
  delete from auth.users where id = p_id;
end $$;

revoke all on function public.admin_guard() from public, anon, authenticated;
revoke all on function public.admin_create_user(text, text, text, text, text) from public, anon;
revoke all on function public.admin_update_user(uuid, text, text, text, text) from public, anon;
revoke all on function public.admin_set_user_password(uuid, text) from public, anon;
revoke all on function public.admin_set_user_active(uuid, boolean) from public, anon;
revoke all on function public.admin_user_status(uuid[]) from public, anon;
revoke all on function public.admin_delete_user(uuid) from public, anon;
grant execute on function public.admin_create_user(text, text, text, text, text) to authenticated;
grant execute on function public.admin_update_user(uuid, text, text, text, text) to authenticated;
grant execute on function public.admin_set_user_password(uuid, text) to authenticated;
grant execute on function public.admin_set_user_active(uuid, boolean) to authenticated;
grant execute on function public.admin_user_status(uuid[]) to authenticated;
grant execute on function public.admin_delete_user(uuid) to authenticated;


-- =====================================================================================================
--  19. MULTI-TENANCY — Hospital Comrade (many hospitals on one database) + provider roles
--
--  Every hospital is a row in `tenants`. Every hospital table gets a `tenant_id` column and ONE extra
--  RESTRICTIVE policy, `tenant_isolation`, which Postgres ANDs with all the existing role policies:
--      tenant_id = current_tenant()
--  so nothing written before this section has to know about tenants for direct table access.
--
--  current_tenant() — which hospital this request belongs to:
--    1. app.tenant_id         set only by our own SQL (signup trigger, cron loops over hospitals)
--    2. provider              the hospital picked in the app (x-tenant-id header), if they may manage it
--    3. signed-in user        always their own hospital (profiles.tenant_id) — a header can't move them
--    4. visitor (anon)        the hospital whose website they're on (x-tenant-id header from the domain)
--    5. otherwise             the primary hospital → single-hospital installs keep working unchanged
--
--  Providers (the Hospital Comrade team) are not members of any hospital:
--    admin   everything, every hospital            → acts as owner
--    support assigned hospitals; patient records read-only → acts as owner (clinical writes blocked)
--    finance assigned hospitals; billing only      → acts as accountant
--  An admin can work in support / finance mode (x-provider-mode header) — the lower mode is the default in the app.
--
--  Idempotent: safe on a fresh database (master / production) and on a live one (upgrade).
-- =====================================================================================================

-- (tenants, provider tables and current_tenant() live in tenancy_core.sql, loaded right after the schema)

-- ------------------------------------------------------------------ roles are per hospital
create or replace function public.has_role(variadic roles public.app_role[])
returns boolean language plpgsql stable security definer set search_path = public as $$
declare t uuid := public.current_tenant(); m text;
begin
  if t is null then return false; end if;
  if exists (select 1 from public.profiles where id = auth.uid() and tenant_id = t and role = any (roles)) then return true; end if;
  m := public.provider_mode();
  if m is null then return false; end if;
  return (case m when 'finance' then 'accountant' else 'owner' end)::public.app_role = any (roles);
end $$;

create or replace function public.is_staff()
returns boolean language plpgsql stable security definer set search_path = public as $$
declare t uuid := public.current_tenant();
begin
  if t is null then return false; end if;
  return exists (select 1 from public.profiles where id = auth.uid() and tenant_id = t and role <> 'patient')
      or public.provider_mode() is not null;
end $$;

create or replace function public.current_app_role()
returns public.app_role language plpgsql stable security definer set search_path = public as $$
declare m text := public.provider_mode(); r public.app_role;
begin
  if m is not null then return (case m when 'finance' then 'accountant' else 'owner' end)::public.app_role; end if;
  select role into r from public.profiles where id = auth.uid() and tenant_id = public.current_tenant();
  return r;
end $$;

-- ------------------------------------------------------------------ tenant_id on every hospital table + isolation policy
select public.ensure_tenant_columns();   -- tables created after the core section (CMS, settings, forms, messaging…)

do $tenancy$
declare t text;
begin
  for t in select c.table_name from information_schema.columns c
            join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name and x.table_type = 'BASE TABLE'
           where c.table_schema = 'public' and c.column_name = 'tenant_id' and c.table_name not in ('tenant_domains', 'provider_assignments', 'provider_audit')
  loop
    execute format('drop policy if exists tenant_isolation on public.%I', t);
    if t = 'profiles' then
      execute 'create policy tenant_isolation on public.profiles as restrictive for all to anon, authenticated
                 using (tenant_id = (select public.current_tenant()) or id = auth.uid())
                 with check (tenant_id = (select public.current_tenant()) or id = auth.uid())';
    else
      execute format('create policy tenant_isolation on public.%I as restrictive for all to anon, authenticated
                        using (tenant_id = (select public.current_tenant()))
                        with check (tenant_id = (select public.current_tenant()))', t);
    end if;
  end loop;
end $tenancy$;

-- (sql functions are checked when created, so these come after the tenant_id columns exist)
create or replace function public.my_doctor_id()
returns uuid language sql stable security definer set search_path = public as $$
  select id from public.doctors where profile_id = auth.uid() and tenant_id = public.current_tenant() limit 1
$$;

create or replace function public.my_patient_id()
returns uuid language sql stable security definer set search_path = public as $$
  select id from public.patients where profile_id = auth.uid() and tenant_id = public.current_tenant() limit 1
$$;

-- a hospital's own record can't be moved to another hospital by an update
create or replace function public.keep_tenant()
returns trigger language plpgsql as $$
begin
  if new.tenant_id is distinct from old.tenant_id and current_setting('app.tenant_move', true) is distinct from 'on' then
    raise exception 'Records cannot be moved to another hospital' using errcode = '42501';
  end if;
  return new;
end $$;
do $keep$
declare t text;
begin
  for t in select c.table_name from information_schema.columns c
            join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name and x.table_type = 'BASE TABLE'
           where c.table_schema = 'public' and c.column_name = 'tenant_id' and c.table_name not in ('tenant_domains', 'provider_assignments')
  loop
    execute format('drop trigger if exists trg_keep_tenant on public.%I', t);
    execute format('create trigger trg_keep_tenant before update of tenant_id on public.%I for each row execute function public.keep_tenant()', t);
  end loop;
end $keep$;

-- ------------------------------------------------------------------ uniqueness is per hospital
do $uniq$
declare r record; cols text[];
begin
  for r in
    select c.conrelid::regclass::text as tbl, c.conname, c.contype,
           array_agg(a.attname::text order by k.ord) as cols
      from pg_constraint c
      cross join lateral unnest(c.conkey) with ordinality as k(attnum, ord)
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = k.attnum
     where c.contype in ('u', 'p') and c.connamespace = 'public'::regnamespace
       and c.conrelid::regclass::text in ('departments', 'wards', 'beds', 'patients', 'invoices', 'inventory', 'site_forms', 'holidays',
                                          'app_settings', 'site_content', 'app_secrets', 'wa_sessions')
     group by 1, 2, 3
  loop
    continue when 'tenant_id' = any (r.cols) or 'id' = any (r.cols)
               or not (r.cols && array['name', 'bed_number', 'mrn', 'invoice_number', 'sku', 'slug', 'holiday_date', 'key', 'phone']);   -- profile_id etc. stay globally unique
    cols := array_prepend('tenant_id', r.cols);
    execute format('alter table public.%I drop constraint %I', r.tbl, r.conname);
    if r.contype = 'p' then
      execute format('alter table public.%I add primary key (%s)', r.tbl, (select string_agg(quote_ident(x), ', ') from unnest(cols) x));
    else
      execute format('alter table public.%I add constraint %I unique (%s)', r.tbl, r.conname, (select string_agg(quote_ident(x), ', ') from unnest(cols) x));
    end if;
  end loop;
end $uniq$;

drop index if exists public.staff_invites_one_pending;
create unique index if not exists staff_invites_one_pending_t on public.staff_invites (tenant_id, lower(email)) where status = 'pending';

-- MRN / invoice numbers count per hospital, with the hospital's own prefix
create or replace function public.assign_record_number()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_code text;
begin
  if tg_table_name = 'patients' then
    perform pg_advisory_xact_lock(hashtext('dch_patient_mrn:' || new.tenant_id));
    if coalesce(new.mrn, '') = '' or exists (select 1 from public.patients where tenant_id = new.tenant_id and mrn = new.mrn) then
      select coalesce(code, 'HSP') into v_code from public.tenants where id = new.tenant_id;
      select v_code || '-' || (coalesce(max(nullif(regexp_replace(mrn, '\D', '', 'g'), '')::bigint), 100000) + 1) into new.mrn
        from public.patients where tenant_id = new.tenant_id;
    end if;
  else
    perform pg_advisory_xact_lock(hashtext('dch_invoice_number:' || new.tenant_id));
    if coalesce(new.invoice_number, '') = '' or exists (select 1 from public.invoices where tenant_id = new.tenant_id and invoice_number = new.invoice_number) then
      select 'INV-' || lpad((coalesce(max(nullif(regexp_replace(invoice_number, '\D', '', 'g'), '')::bigint), 10000) + 1)::text, 5, '0')
        into new.invoice_number from public.invoices where tenant_id = new.tenant_id;
    end if;
  end if;
  return new;
end $$;

-- ------------------------------------------------------------------ new accounts join the hospital they signed up at
-- Sign-ups arrive from Supabase Auth (no request headers), so the website passes its hospital in the sign-up metadata.
-- The choice is pinned for the rest of the transaction, so the patient record made by handle_new_user lands there too.
create or replace function public.profiles_pick_tenant()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_meta text; v uuid;
begin
  if new.tenant_id is null or new.tenant_id = public.primary_tenant() then
    select raw_user_meta_data ->> 'tenant_id' into v_meta from auth.users where id = new.id;
    if v_meta ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      select id into v from public.tenants where id = v_meta::uuid and status <> 'suspended';
    end if;
    new.tenant_id := coalesce(v, new.tenant_id, public.current_tenant(), public.primary_tenant());
  end if;
  perform set_config('app.tenant_id', new.tenant_id::text, true);
  return new;
end $$;
drop trigger if exists trg_profiles_pick_tenant on public.profiles;
create trigger trg_profiles_pick_tenant before insert on public.profiles for each row execute function public.profiles_pick_tenant();

-- ------------------------------------------------------------------ provider: support may read, not change, patient records
do $clinical$
declare t text;
begin
  foreach t in array array['patients', 'appointments', 'prescriptions', 'lab_tests', 'admissions', 'visit_feedback'] loop
    execute format('drop policy if exists provider_support_read_only on public.%I', t);
    execute format('create policy provider_support_read_only on public.%I as restrictive for insert to authenticated
                      with check (public.provider_mode() is distinct from %L)', t, 'support');
    execute format('drop policy if exists provider_support_no_update on public.%I', t);
    execute format('create policy provider_support_no_update on public.%I as restrictive for update to authenticated
                      using (public.provider_mode() is distinct from %L)', t, 'support');
    execute format('drop policy if exists provider_support_no_delete on public.%I', t);
    execute format('create policy provider_support_no_delete on public.%I as restrictive for delete to authenticated
                      using (public.provider_mode() is distinct from %L)', t, 'support');
  end loop;
end $clinical$;

-- ------------------------------------------------------------------ RLS on the tenancy tables
alter table public.tenants enable row level security;
alter table public.tenant_domains enable row level security;
alter table public.provider_users enable row level security;
alter table public.provider_assignments enable row level security;
alter table public.provider_audit enable row level security;
revoke all on public.tenants, public.tenant_domains, public.provider_users, public.provider_assignments, public.provider_audit from anon, authenticated;
grant select on public.tenants to anon, authenticated;
grant select, insert, update, delete on public.tenant_domains, public.provider_users, public.provider_assignments to authenticated;
grant update, insert, delete on public.tenants to authenticated;
grant select on public.provider_audit to authenticated;
grant all on public.tenants, public.tenant_domains, public.provider_users, public.provider_assignments, public.provider_audit to service_role;

drop policy if exists tenants_select on public.tenants;
drop policy if exists tenants_admin on public.tenants;
create policy tenants_select on public.tenants for select to anon, authenticated
  using (id = (select public.current_tenant()) or public.provider_can(id));
create policy tenants_admin on public.tenants for all to authenticated
  using (public.provider_mode() = 'admin') with check (public.provider_mode() = 'admin');

drop policy if exists tenant_domains_select on public.tenant_domains;
drop policy if exists tenant_domains_admin on public.tenant_domains;
create policy tenant_domains_select on public.tenant_domains for select to authenticated
  using (public.provider_can(tenant_id) or (tenant_id = (select public.current_tenant()) and public.has_role('owner')));
create policy tenant_domains_admin on public.tenant_domains for all to authenticated
  using (public.provider_mode() = 'admin') with check (public.provider_mode() = 'admin');

drop policy if exists provider_users_select on public.provider_users;
drop policy if exists provider_users_admin on public.provider_users;
create policy provider_users_select on public.provider_users for select to authenticated
  using (user_id = auth.uid() or public.provider_mode() = 'admin');
create policy provider_users_admin on public.provider_users for all to authenticated
  using (public.provider_mode() = 'admin') with check (public.provider_mode() = 'admin' and user_id <> auth.uid());

drop policy if exists provider_assignments_select on public.provider_assignments;
drop policy if exists provider_assignments_admin on public.provider_assignments;
create policy provider_assignments_select on public.provider_assignments for select to authenticated
  using (user_id = auth.uid() or public.provider_mode() = 'admin');
create policy provider_assignments_admin on public.provider_assignments for all to authenticated
  using (public.provider_mode() = 'admin') with check (public.provider_mode() = 'admin');

drop policy if exists provider_audit_select on public.provider_audit;
create policy provider_audit_select on public.provider_audit for select to authenticated
  using (public.provider_mode() = 'admin' or (user_id = auth.uid()));

-- ------------------------------------------------------------------ RPCs
-- the website asks "which hospital is this domain?" before anything else (multi-tenant mode).
-- A mapped domain always wins; only hosts without a mapping (preview / staging / localhost) may name a
-- hospital by slug (?hospital=city), so a hospital's own domain can never be made to show another one.
drop function if exists public.resolve_tenant(text);
drop function if exists public.resolve_tenant(text, text);   -- the columns grew (is_demo)
create or replace function public.resolve_tenant(p_host text, p_slug text default null)
returns table (id uuid, slug text, name text, status text, modules jsonb, is_primary boolean, is_demo boolean)
language sql stable security definer set search_path = public as $$
  select t.id, t.slug, t.name, public.tenant_license(t.id), t.modules, t.is_primary, t.is_demo   -- effective status (licence, phase 4)
    from public.tenants t
   where t.id = coalesce(
           (select d.tenant_id from public.tenant_domains d where d.domain = lower(split_part(trim(coalesce(p_host, '')), ':', 1))),
           (select x.id from public.tenants x where x.slug = lower(trim(coalesce(p_slug, '')))))
$$;

-- who am I here: hospital, my role in it, provider role / mode and which modules the hospital may edit itself
create or replace function public.my_context()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare t public.tenants; v_tid uuid := public.current_tenant();
begin
  select * into t from public.tenants where id = v_tid;
  return jsonb_build_object(
    'tenant', case when t.id is null then null else jsonb_build_object('id', t.id, 'slug', t.slug, 'name', t.name, 'status', public.tenant_license(t.id), 'plan', t.plan, 'modules', t.modules, 'is_primary', t.is_primary) end,
    -- licence dates for the banner; the wallet balance only for the people who pay (owner / accountant / platform team)
    'license', case when t.id is null then null else public.tenant_license_dates(t.id)
      || case when public.has_role('owner', 'accountant') then jsonb_build_object('wallet_paise', t.wallet_paise) else '{}'::jsonb end end,
    'role', public.current_app_role(),
    'provider_role', public.provider_role(),
    'provider_mode', public.provider_mode());
end $$;

-- hospitals a provider may open (switcher)
create or replace function public.provider_tenants()
returns table (id uuid, slug text, name text, status text, plan text, domain text)
language sql stable security definer set search_path = public as $$
  select t.id, t.slug, t.name, public.tenant_license(t.id), t.plan,
         (select d.domain from public.tenant_domains d where d.tenant_id = t.id order by d.is_primary desc, d.created_at limit 1)
    from public.tenants t
   where public.provider_can(t.id)
   order by t.is_primary desc, t.name
$$;

-- providers write to the audit log for anything sensitive they open (e.g. a patient chart)
create or replace function public.provider_log(p_action text, p_target text default null, p_detail jsonb default null)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  if public.provider_role() is null then return; end if;
  insert into public.provider_audit (user_id, user_name, mode, tenant_id, action, target, detail)
  values (auth.uid(), (select full_name from public.profiles where id = auth.uid()), public.provider_mode(), public.current_tenant(),
          left(p_action, 80), left(p_target, 200), p_detail);
end $$;

revoke all on function public.request_header(text), public.client_ip_hash(), public.primary_tenant(), public.keep_tenant(), public.profiles_pick_tenant() from public, anon, authenticated;
grant execute on function public.current_tenant(), public.provider_role(), public.provider_can(uuid), public.provider_mode(),
  public.has_role(public.app_role[]), public.is_staff(), public.current_app_role(), public.my_doctor_id(), public.my_patient_id()
  to anon, authenticated, service_role;
grant execute on function public.resolve_tenant(text, text) to anon, authenticated;
grant execute on function public.my_context(), public.provider_tenants(), public.provider_log(text, text, jsonb) to authenticated;
revoke all on function public.my_context(), public.provider_tenants(), public.provider_log(text, text, jsonb) from public, anon;

-- ------------------------------------------------------------------ module locks (phase 1.4)
-- Locked modules are hidden in the app; these triggers make sure a hospital user can't change them through the API
-- either. They only act on direct API writes (current_user = authenticated): RPCs check module_guard() themselves,
-- and the platform (SQL editor, service role, provider modes) is never blocked.

-- settings sections inside the shared rows: app_settings 'app' and site_content 'settings'
create or replace function public.locked_paths(p_table text)
returns text[] language plpgsql stable set search_path = public as $$
declare
  m record; out text[] := '{}';
  map jsonb := case p_table
    when 'app_settings' then '{"appearance": ["appearance", "modules", "announcement"], "dashboard": ["dashboard"],
                               "general": ["locale"], "security": ["security"], "notifications": ["notifications"]}'::jsonb
    else '{"general": ["name", "tagline", "address", "phone", "appointmentsPhone", "whatsapp", "email", "siteUrl", "brand"],
           "security": ["portal"],
           "cms": ["about", "topBar", "emergency", "hours", "directions", "map", "socials", "cta", "pages", "seoDescription"]}'::jsonb
  end;
begin
  for m in select key, value from jsonb_each(map) loop
    if public.module_locked(m.key) then
      out := out || array(select jsonb_array_elements_text(m.value));
    end if;
  end loop;
  return out;
end $$;

-- a locked section keeps its saved value (the owner's save of the other sections still goes through)
create or replace function public.keep_locked_sections()
returns trigger language plpgsql set search_path = public as $$
declare k text; v_paths text[];
begin
  if current_user <> 'authenticated' then return coalesce(new, old); end if;
  if tg_table_name = 'site_content' and coalesce(new.key, old.key) <> 'settings' then
    perform public.module_guard('cms');                      -- the website pages belong to the CMS module
    return coalesce(new, old);
  end if;
  if tg_table_name = 'app_settings' and coalesce(new.key, old.key) <> 'app' then return coalesce(new, old); end if;
  v_paths := public.locked_paths(tg_table_name);
  if cardinality(v_paths) = 0 then return coalesce(new, old); end if;
  if tg_op = 'DELETE' then
    raise exception 'MODULE_LOCKED: Some of these settings are managed for your hospital by the platform team.' using errcode = '42501';
  end if;
  foreach k in array v_paths loop
    if tg_op = 'UPDATE' and old.data ? k then
      new.data := jsonb_set(new.data, array[k], old.data -> k);
    else
      new.data := new.data - k;
    end if;
  end loop;
  return new;
end $$;

drop trigger if exists trg_app_settings_locked on public.app_settings;
create trigger trg_app_settings_locked before insert or update or delete on public.app_settings
  for each row execute function public.keep_locked_sections();
drop trigger if exists trg_site_content_locked on public.site_content;
create trigger trg_site_content_locked before insert or update or delete on public.site_content
  for each row execute function public.keep_locked_sections();

-- whole tables that belong to one module
create or replace function public.guard_locked_table()
returns trigger language plpgsql set search_path = public as $$
begin
  if current_user = 'authenticated' then perform public.module_guard(tg_argv[0]); end if;
  return coalesce(new, old);
end $$;
drop trigger if exists trg_site_forms_locked on public.site_forms;
create trigger trg_site_forms_locked before insert or update or delete on public.site_forms
  for each row execute function public.guard_locked_table('forms');
drop trigger if exists trg_notification_templates_locked on public.notification_templates;
create trigger trg_notification_templates_locked before insert or update or delete on public.notification_templates
  for each row execute function public.guard_locked_table('notifications');

revoke all on function public.keep_locked_sections(), public.guard_locked_table() from public, anon, authenticated;
grant execute on function public.module_locked(text) to anon, authenticated;

-- ------------------------------------------------------------------ internal helpers stay internal (phase 1.7)
-- master.sql grants EXECUTE on every function to authenticated after tenancy_core.sql ran, and new functions are
-- executable by PUBLIC by default — so the revokes are repeated here, at the very end. Only SECURITY DEFINER
-- functions call these (they run as the owner). tenant_secret reads credentials; tenant_setting the hospital's
-- private settings (gateway URLs, sessions); ensure_tenant_columns changes the schema.
revoke all on function public.tenant_secret(text), public.tenant_setting(text), public.tenant_content(text),
  public.ensure_tenant_columns() from public, anon, authenticated;

-- ------------------------------------------------------------------ a new hospital's starting point (phase 1.7)
-- Platform only (SQL editor / provider panel): the built-in website forms (Contact, Review — from src/forms/schema.ts)
-- and the hospital's identity on its website and invoices. Safe to run again; keeps whatever the hospital already changed.
create or replace function public.seed_hospital_defaults(p_tenant uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants;
begin
  select * into t from public.tenants where id = p_tenant;
  if not found then raise exception 'No hospital with id %', p_tenant; end if;
  insert into public.site_forms (tenant_id, slug, name, description, kind, enabled, fields, settings, sort)
  select p_tenant, v.slug, v.name, v.description, v.kind, v.enabled::boolean, v.fields::jsonb, v.settings::jsonb, v.sort::int
    from (values
  ('f0000000-0000-4000-8000-000000000001', 'contact', 'Contact form', 'The form on the Contact page. Topics come from Website CMS → Contact page unless you set options here.', 'contact', true, '[{"id":"name","type":"text","label":"Full name","placeholder":"Priya Sharma","required":true,"role":"name","width":"half"},{"id":"phone","type":"phone","label":"Mobile number","placeholder":"98100 12345","required":true,"role":"phone","width":"half"},{"id":"email","type":"email","label":"Email","placeholder":"you@example.com","role":"email","width":"half"},{"id":"speciality","type":"select","label":"Speciality","placeholder":"Not sure / general","optionsFrom":"services","role":"speciality","width":"half"},{"id":"topic","type":"radio","label":"How can we help?","required":true,"options":[],"role":"topic"},{"id":"message","type":"textarea","label":"Message","placeholder":"Tell us how we can help…","required":true,"role":"message"},{"id":"consent","type":"consent","label":"I agree to be contacted about my enquiry and accept the privacy policy.","required":true}]'::jsonb, '{"submitLabel":"Send message","color":"brand"}'::jsonb, 0),
  ('f0000000-0000-4000-8000-000000000002', 'review', 'Patient review', 'Share your experience at our hospital. Reviews are read by the management.', 'review', true, '[{"id":"rating","type":"rating","label":"Overall experience","required":true},{"id":"name","type":"text","label":"Full name","placeholder":"Priya Sharma","required":true,"role":"name","width":"half"},{"id":"phone","type":"phone","label":"Mobile number","placeholder":"98100 12345","required":true,"role":"phone","width":"half"},{"id":"doctor","type":"text","label":"Doctor or department you visited","placeholder":"e.g. Dr. Arjun Mehta, Cardiology","width":"half"},{"id":"visit_date","type":"date","label":"Date of visit","width":"half"},{"id":"liked","type":"checkboxes","label":"What went well?","options":["Doctor consultation","Nursing care","Cleanliness","Waiting time","Billing & front desk"]},{"id":"message","type":"textarea","label":"Your review","placeholder":"Tell us about your visit…","required":true,"role":"message"},{"id":"publish","type":"consent","label":"You may publish my first name with this review on the website."}]'::jsonb, '{"topic":"Patient review","submitLabel":"Submit review","successTitle":"Thank you for your review!","successText":"Your feedback helps us care better for every patient.","color":"amber"}'::jsonb, 1)
    ) as v (id, slug, name, description, kind, enabled, fields, settings, sort)
   where not exists (select 1 from public.site_forms f where f.tenant_id = p_tenant and f.slug = v.slug);
  -- the hospital's identity: its own name, and none of the sample hospital's contacts, tax / registration numbers or
  -- UPI id (they would print on its invoices); the owner fills them in under Settings → General / Billing
  insert into public.site_content (tenant_id, key, data)
  values (p_tenant, 'settings', jsonb_build_object(
    'name', t.name, 'tagline', '', 'about', '', 'address', '', 'phone', '', 'appointmentsPhone', '', 'whatsapp', '', 'email', '',
    'seoDescription', t.name, 'brand', jsonb_build_object('shortName', left(t.name, 30)),
    'billing', jsonb_build_object('legalName', t.name, 'gstin', '', 'regNo', '', 'pan', '', 'upiId', '')))
  on conflict (tenant_id, key) do nothing;
  -- default settings (phase 3): without this row nothing is ever queued for the hospital. SMS, WhatsApp and e-mail
  -- start on Hospital Comrade messaging (included in the plan); the owner can switch any channel to their own account.
  insert into public.app_settings (tenant_id, key, data)
  values (p_tenant, 'app', $json${"appearance":{"theme":"periwinkle","customColor":"#5c5c99","sidebar":"dark","size":"default","radius":"default"},"dashboard":{"hidden":[],"showGreeting":true},"modules":{"hidden":[]},"announcement":{"enabled":false,"text":"","tone":"info","audience":"staff","link":""},"locale":{"dateFormat":"dd MMM yyyy","timeFormat":"12h","weekStartsOn":1},"security":{"idleTimeoutMinutes":0},"notifications":{"email":{"enabled":true,"source":"platform","provider":"resend","fromName":"DC Hospital","fromEmail":"","replyTo":"","smtpHost":"","smtpPort":465,"smtpSecure":true,"smtpUser":""},"sms":{"enabled":true,"source":"platform","provider":"msg91","senderId":"","dltEntityId":"","twilioAccountSid":"","twilioFrom":"","webhookUrl":""},"whatsapp":{"enabled":true,"source":"platform","provider":"openwa","phoneNumberId":"","businessAccountId":"","language":"en","twilioAccountSid":"","twilioFrom":"","webhookUrl":"","openwaUrl":"","openwaSession":"","wacrmUrl":"","chatIdFormat":"91{phone}@c.us","msg91Number":"","msg91Namespace":"","aisensyTestCampaign":"","botEnabled":false},"push":{"enabled":false,"apiKey":"","authDomain":"","projectId":"","messagingSenderId":"","appId":"","vapidKey":""},"rates":{"sms":0.25,"whatsapp":0.8,"email":0.05,"push":0},"events":{"otp":{"sms":true,"whatsapp":true},"password_otp":{"sms":true,"whatsapp":true},"login_otp":{"sms":true,"whatsapp":true,"email":true},"appointment_booked":{"sms":true,"whatsapp":true,"email":true},"appointment_reminder":{"sms":true,"whatsapp":true,"email":false},"appointment_rescheduled":{"sms":true,"whatsapp":true,"email":true},"appointment_cancelled":{"sms":true,"whatsapp":false,"email":true},"invoice_created":{"sms":false,"whatsapp":false,"email":true},"payment_received":{"sms":false,"whatsapp":false,"email":true},"lab_report_ready":{"sms":true,"whatsapp":true,"email":false},"feedback_request":{"sms":true,"whatsapp":true,"email":true},"staff_invite":{"sms":false,"whatsapp":true,"email":true},"account_created":{"sms":false,"whatsapp":true,"email":true,"push":false},"account_updated":{"sms":false,"whatsapp":false,"email":true,"push":true},"account_deleted":{"sms":false,"whatsapp":false,"email":true},"password_changed":{"sms":true,"whatsapp":false,"email":true,"push":true},"notice_published":{"sms":false,"whatsapp":false,"email":false,"push":true}},"templates":{"otp":{"text":"{code} is your {hospital} booking code. It is valid for 10 minutes. Do not share it with anyone.","subject":"Your booking code","waTemplate":"","waParams":"code","smsTemplateId":"","waText":"🔐 *{code}* is your {hospital} verification code.\n\nIt is valid for 10 minutes. Do not share it with anyone — our staff will never ask for it."},"password_otp":{"text":"{code} is your {hospital} password reset code. It is valid for 10 minutes. If you did not ask for it, ignore this message.","subject":"Your password reset code","waTemplate":"","waParams":"code","smsTemplateId":"","waText":"🔑 *{code}* is your {hospital} password reset code.\n\nIt is valid for 10 minutes. Didn't ask for it? Ignore this message — your password stays the same."},"login_otp":{"text":"{code} is your {hospital} sign-in code. It is valid for 10 minutes. Do not share it with anyone.","subject":"Your sign-in code","waTemplate":"","waParams":"code","smsTemplateId":"","waText":"🔐 *{code}* is your {hospital} sign-in code.\n\nIt is valid for 10 minutes. Didn't just sign in? Change your password — someone knows it."},"appointment_booked":{"text":"Hi {name}, your appointment with {doctor} is confirmed for {date} at {time}. Ref {ref}. Please arrive 15 min early. {hospital} {hospital_phone}","subject":"Appointment confirmed — {date} at {time}","waTemplate":"","waParams":"name,doctor,date,time,ref","smsTemplateId":"","waText":"✅ *Appointment confirmed*\n\nHi {name},\n🩺 {doctor}\n🗓 {date} at {time}\n🔖 Ref: *{ref}*\n\nPlease arrive 15 minutes early with a photo ID. Pay at the reception.\n📍 {address}\n📞 {hospital_phone}\n\n— {hospital}"},"appointment_reminder":{"text":"Reminder: {name}, you have an appointment with {doctor} tomorrow, {date} at {time}. Ref {ref}. {hospital} {hospital_phone}","subject":"Reminder: your appointment tomorrow at {time}","waTemplate":"","waParams":"name,doctor,date,time","smsTemplateId":"","waText":"⏰ *Reminder*\n\nHi {name}, you have an appointment *tomorrow*.\n🩺 {doctor}\n🗓 {date} at {time}\n🔖 Ref: {ref}\n\nNeed to change it? Call {hospital_phone}.\n— {hospital}"},"appointment_rescheduled":{"text":"Hi {name}, your appointment with {doctor} has been moved to {date} at {time}. Ref {ref}. Call {hospital_phone} if this does not suit you. {hospital}","subject":"Your appointment has been rescheduled","waTemplate":"","waParams":"name,doctor,date,time","smsTemplateId":"","waText":"🔁 *Appointment rescheduled*\n\nHi {name}, your visit with {doctor} is now on\n🗓 *{date} at {time}*\n🔖 Ref: {ref}\n\nCall {hospital_phone} if this does not suit you.\n— {hospital}"},"appointment_cancelled":{"text":"Hi {name}, your appointment with {doctor} on {date} at {time} has been cancelled. Call {hospital_phone} to rebook. {hospital}","subject":"Your appointment was cancelled","waTemplate":"","waParams":"name,doctor,date,time","smsTemplateId":"","waText":"❌ *Appointment cancelled*\n\nHi {name}, your visit with {doctor} on {date} at {time} has been cancelled.\n\nTo book again, call {hospital_phone} or reply *1* here.\n— {hospital}"},"invoice_created":{"text":"Hi {name}, invoice {invoice} for {amount} has been generated at {hospital}. Due {due_date}.","subject":"Invoice {invoice} from {hospital}","waTemplate":"","waParams":"name,invoice,amount","smsTemplateId":"","waText":""},"payment_received":{"text":"Thank you {name}. We received {amount} by {method} against invoice {invoice}. {hospital}","subject":"Payment received — {amount}","waTemplate":"","waParams":"name,amount,invoice","smsTemplateId":"","waText":""},"lab_report_ready":{"text":"Hi {name}, your {test} report is ready. View it in the patient portal or collect it from the lab. {hospital} {hospital_phone}","subject":"Your {test} report is ready","waTemplate":"","waParams":"name,test","smsTemplateId":"","waText":""},"feedback_request":{"text":"Hi {name}, thank you for visiting {doctor} at {hospital}. How was your experience? Rate us in 10 seconds: {link}","subject":"How was your visit to {hospital}?","waTemplate":"","waParams":"name,doctor,link","smsTemplateId":"","waText":""},"staff_invite":{"text":"Hi {name}, you are invited to join {hospital} as {role}. Create your account here: {link} (valid 14 days)","subject":"You are invited to join {hospital}","waTemplate":"","waParams":"name,role,link","smsTemplateId":"","waText":""},"account_created":{"text":"Welcome to {hospital}, {name}! Your {role} account is ready. Sign in at {link} with {email}.","subject":"Welcome to {hospital}","waTemplate":"","waParams":"name,role,link","smsTemplateId":"","waText":"👋 *Welcome to {hospital}*\n\nHi {name}, your *{role}* account is ready.\nSign in: {link}\nE-mail: {email}","pushText":"Your {role} account is ready. Welcome aboard!"},"account_updated":{"text":"Hi {name}, your {hospital} account was updated ({changes}). If this was not you, call {hospital_phone}.","subject":"Your {hospital} account was updated","waTemplate":"","waParams":"name,changes","smsTemplateId":"","waText":"","pushText":"Your account was updated: {changes}"},"account_deleted":{"text":"Hi {name}, your {hospital} sign-in ({email}) has been removed. Your medical records are kept safely. Questions? Call {hospital_phone}.","subject":"Your {hospital} account was removed","waTemplate":"","waParams":"name,email","smsTemplateId":"","waText":""},"password_changed":{"text":"Hi {name}, your {hospital} password was changed on {time}. Not you? Reset it now: {link} or call {hospital_phone}.","subject":"Your password was changed","waTemplate":"","waParams":"name,time,link","smsTemplateId":"","waText":"","pushText":"Your password was changed on {time}. Not you? Reset it right away."},"notice_published":{"text":"{hospital} notice: {title}. {notice} — {link}","subject":"📌 {title}","waTemplate":"","waParams":"title,notice","smsTemplateId":"","waText":"📌 *{title}*\n\n{notice}\n\nRead on the notice board: {link}\n— {hospital}","pushText":"{notice}"}}}}$json$::jsonb)
  on conflict (tenant_id, key) do nothing;
end $$;
revoke all on function public.seed_hospital_defaults(uuid) from public, anon, authenticated;

-- ------------------------------------------------------------------ product page leads (phase 2.2)
-- "Talk to us" form on the Hospital Comrade product page (the platform domain). Platform-level: no tenant_id, only
-- Hospital Comrade admins can read or update them; visitors can only add one through submit_platform_lead().
create table if not exists public.platform_leads (
  id            uuid primary key default gen_random_uuid(),
  created_at    timestamptz not null default now(),
  name          text not null check (char_length(name) between 2 and 100),
  organisation  text not null check (char_length(organisation) between 2 and 150),
  phone         text not null check (phone ~ '^\+?[0-9]{10,13}$'),
  email         text check (email is null or char_length(email) <= 150),
  city          text check (city is null or char_length(city) <= 80),
  plan          text check (plan is null or plan in ('clinic', 'hospital', 'enterprise', 'custom', 'unsure')),
  message       text check (message is null or char_length(message) <= 2000),
  source        text check (source is null or char_length(source) <= 255),
  status        text not null default 'new' check (status in ('new', 'contacted', 'won', 'lost')),
  notes         text
);
create index if not exists platform_leads_created_idx on public.platform_leads (created_at desc);
alter table public.platform_leads enable row level security;
revoke all on public.platform_leads from anon, authenticated;
grant select, update, delete on public.platform_leads to authenticated;
grant all on public.platform_leads to service_role;
drop policy if exists platform_leads_admin on public.platform_leads;
create policy platform_leads_admin on public.platform_leads for all to authenticated
  using (public.provider_role() = 'admin') with check (public.provider_role() = 'admin');

create or replace function public.submit_platform_lead(
  p_name text, p_organisation text, p_phone text, p_email text default null, p_city text default null,
  p_plan text default null, p_message text default null, p_source text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_phone text := regexp_replace(coalesce(p_phone, ''), '[^0-9+]', '', 'g');
        v_email text := nullif(lower(trim(coalesce(p_email, ''))), '');
begin
  if char_length(trim(coalesce(p_name, ''))) < 2 then raise exception 'Please enter your name.'; end if;
  if char_length(trim(coalesce(p_organisation, ''))) < 2 then raise exception 'Please enter your hospital or clinic name.'; end if;
  if v_phone !~ '^\+?[0-9]{10,13}$' then raise exception 'Please enter a valid mobile number.'; end if;
  if v_email is not null and v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then raise exception 'Please enter a valid email or leave it empty.'; end if;
  -- spam guard: one request per number every 10 minutes, and a ceiling for the whole form
  if exists (select 1 from public.platform_leads where phone = v_phone and created_at > now() - interval '10 minutes') then
    return;   -- already received — quietly accept the repeat
  end if;
  if (select count(*) from public.platform_leads where created_at > now() - interval '1 hour') >= 60 then
    raise exception 'We are receiving a lot of requests right now. Please try again in a few minutes.';
  end if;
  insert into public.platform_leads (name, organisation, phone, email, city, plan, message, source)
  values (left(trim(p_name), 100), left(trim(p_organisation), 150), v_phone, left(v_email, 150), nullif(left(trim(coalesce(p_city, '')), 80), ''),
          case when p_plan in ('clinic', 'hospital', 'enterprise', 'custom', 'unsure') then p_plan end,
          nullif(left(trim(coalesce(p_message, '')), 2000), ''), left(p_source, 255));
end $$;
revoke all on function public.submit_platform_lead(text, text, text, text, text, text, text, text) from public;
grant execute on function public.submit_platform_lead(text, text, text, text, text, text, text, text) to anon, authenticated;

-- ------------------------------------------------------------------ Hospital Comrade messaging (phase 3)
-- Platform-wide settings, no tenant_id. 'messaging' = approved template / DLT IDs for the shared accounts:
--   { "templates": { "<event>": { "waTemplate": "…", "waParams": "name,date", "smsTemplateId": "…" } } }
-- (the shared accounts' credentials are Edge Function secrets — PLATFORM_* — never stored here).
-- Only Hospital Comrade admins read or change it; the notify function reads it with the service role.
create table if not exists public.platform_settings (
  key         text primary key,
  data        jsonb not null default '{}'::jsonb,
  updated_at  timestamptz not null default now(),
  updated_by  uuid
);
alter table public.platform_settings enable row level security;
revoke all on public.platform_settings from anon, authenticated;
grant select, insert, update on public.platform_settings to authenticated;
grant all on public.platform_settings to service_role;
drop policy if exists platform_settings_admin on public.platform_settings;
create policy platform_settings_admin on public.platform_settings for all to authenticated
  using (public.provider_role() = 'admin') with check (public.provider_role() = 'admin');
insert into public.platform_settings (key, data) values ('messaging', '{"templates": {}}'::jsonb) on conflict (key) do nothing;

-- record_message_usage(): see billing.sql (it also charges the wallet, phase 4)


-- =====================================================================================================
--  21. LICENCE, WALLET & PAYMENTS — Hospital Comrade phase 4 (loaded last: every hospital table exists)
-- =====================================================================================================
--  • Licence: tenants.trial_ends_at / paid_until → tenant_license() (tenancy_core.sql). In read_only (after the grace
--    period) and suspended hospitals nobody but the platform team can add or change anything: license_guard() runs on
--    every hospital table — also inside website RPCs such as online booking — while reading and signing in still work.
--  • Wallet: prepaid ₹ balance (tenants.wallet_paise) for messages on Hospital Comrade's shared accounts beyond the
--    plan's included messages. Every change is a row in wallet_ledger; usage is one row per day and channel.
--  • Payments: billing_payments (Razorpay orders from the `billing` Edge Function, or manual entries by the platform
--    team). apply_payment() is idempotent: renews the plan or tops up the wallet and numbers the tax invoice.
--  • Prices, GST, trial / grace days and message rates: platform_settings 'billing' (defaults from src/platform/billing.ts);
--    per-hospital overrides in tenants.billing (custom price, included messages, rates).

insert into public.platform_settings (key, data) values ('billing', $json${"currency":"INR","gstPercent":18,"trialDays":14,"graceDays":7,"yearlyMonths":10,"minTopup":500,"maxTopup":100000,"ratesPaise":{"sms":30,"whatsapp":40,"email":2},"plans":{"clinic":{"price":999,"included":{"sms":100,"whatsapp":300,"email":1000}},"hospital":{"price":2999,"included":{"sms":500,"whatsapp":1500,"email":5000}},"enterprise":{"price":7999,"included":{"sms":2000,"whatsapp":5000,"email":20000}},"custom":{"price":null,"included":{"sms":0,"whatsapp":0,"email":0}}},"seller":{"name":"Digital Comrade","gstin":"","address":"","state":"Bihar","email":"","sac":"998315"}}$json$::jsonb)
on conflict (key) do update set data = excluded.data || public.platform_settings.data;   -- new keys arrive, saved values win

create or replace function public.billing_config()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((select data from public.platform_settings where key = 'billing'), '{}'::jsonb)
$$;

-- ------------------------------------------------------------------ tables
create sequence if not exists public.billing_invoice_seq;

create table if not exists public.billing_payments (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null default public.current_tenant() references public.tenants (id) on delete cascade,
  created_at   timestamptz not null default now(),
  kind         text not null check (kind in ('plan', 'wallet')),
  plan         text,
  months       int check (months is null or months between 1 and 36),
  base_paise   bigint not null check (base_paise >= 0),
  gst_paise    bigint not null default 0 check (gst_paise >= 0),
  total_paise  bigint not null check (total_paise >= 0),
  status       text not null default 'created' check (status in ('created', 'paid', 'failed', 'refunded')),
  provider     text not null default 'razorpay' check (provider in ('razorpay', 'manual')),
  order_id     text unique,
  payment_id   text,
  method       text,
  paid_at      timestamptz,
  invoice_no   text unique,
  period_from  date,
  period_to    date,
  buyer        jsonb not null default '{}'::jsonb,       -- legal name / GSTIN / address at the time of payment
  note         text,
  created_by   uuid
);
-- phase 6: the seller printed on the tax invoice, as it was when the invoice was numbered (invoices never change later)
alter table public.billing_payments add column if not exists seller jsonb;
create index if not exists billing_payments_tenant_idx on public.billing_payments (tenant_id, created_at desc);

create table if not exists public.wallet_ledger (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null default public.current_tenant() references public.tenants (id) on delete cascade,
  created_at     timestamptz not null default now(),
  day            date not null default (now() at time zone 'Asia/Kolkata')::date,
  kind           text not null check (kind in ('topup', 'usage', 'refund', 'adjustment')),
  channel        text check (channel is null or channel in ('sms', 'whatsapp', 'email')),
  units          int not null default 0,
  amount_paise   bigint not null,                        -- + credit, − debit
  balance_paise  bigint not null,                        -- balance after this row
  payment        uuid references public.billing_payments (id) on delete set null,
  note           text,
  created_by     uuid
);
create index if not exists wallet_ledger_tenant_idx on public.wallet_ledger (tenant_id, created_at desc);
create unique index if not exists wallet_ledger_usage_day on public.wallet_ledger (tenant_id, day, channel) where kind = 'usage';

-- read: the hospital's owner and accountant (and the platform team working as them); writes only through the functions
do $rls$
declare t text;
begin
  foreach t in array array['billing_payments', 'wallet_ledger'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
    execute format('grant all on public.%I to service_role', t);
    execute format('drop policy if exists tenant_isolation on public.%I', t);
    execute format('create policy tenant_isolation on public.%I as restrictive for all to anon, authenticated
                      using (tenant_id = (select public.current_tenant())) with check (tenant_id = (select public.current_tenant()))', t);
    execute format('drop policy if exists billing_read on public.%I', t);
    execute format('create policy billing_read on public.%I for select to authenticated using (public.has_role(''owner'', ''accountant''))', t);
    execute format('drop trigger if exists trg_keep_tenant on public.%I', t);
    execute format('create trigger trg_keep_tenant before update of tenant_id on public.%I for each row execute function public.keep_tenant()', t);
  end loop;
end $rls$;

-- the wallet balance and billing overrides are not for visitors or staff (tenants is readable by anon for the website):
-- every other column stays readable, these two only through billing_summary() / my_context()
do $cols$
declare v_cols text;
begin
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into v_cols
    from information_schema.columns where table_schema = 'public' and table_name = 'tenants' and column_name not in ('wallet_paise', 'billing', 'close_reason');
  execute 'revoke select on public.tenants from anon, authenticated';
  execute format('grant select (%s) on public.tenants to anon, authenticated', v_cols);
end $cols$;

-- ------------------------------------------------------------------ licence guard
-- Raised for API callers (anon / authenticated — also inside SECURITY DEFINER RPCs, where `role` still names the
-- caller) in read_only / suspended hospitals. The platform team (admin / finance), the service role (Edge Functions)
-- and the database itself are never blocked.
create or replace function public.license_guard()
returns trigger language plpgsql set search_path = public as $$
declare v_tenant uuid; v_state text;
begin
  if coalesce(current_setting('role', true), '') not in ('anon', 'authenticated') then return coalesce(new, old); end if;
  if public.provider_role() in ('admin', 'finance') then return coalesce(new, old); end if;
  -- privacy rights (consent withdrawal, erasure — phase 7) work even when the plan has ended
  if current_setting('app.privacy', true) = 'on' then return coalesce(new, old); end if;
  v_tenant := case when tg_op = 'DELETE' then old.tenant_id else new.tenant_id end;
  v_state := public.tenant_license(v_tenant);
  if v_state in ('read_only', 'suspended') then
    raise exception 'LICENSE_READ_ONLY: This hospital''s Hospital Comrade plan has ended, so the account is read-only. The owner can renew it in Settings → Plan & billing.'
      using errcode = '42501';
  end if;
  return coalesce(new, old);
end $$;

-- every hospital table except the ones that must keep working while read-only (sign-in, password reset, devices,
-- delivery bookkeeping, logs and billing itself)
do $guard$
declare t text;
begin
  for t in select c.table_name from information_schema.columns c
            join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name and x.table_type = 'BASE TABLE'
           where c.table_schema = 'public' and c.column_name = 'tenant_id'
             and c.table_name not in ('tenant_domains', 'provider_assignments', 'provider_audit', 'profiles', 'push_tokens', 'password_reset_otps',
                                      'notification_outbox', 'message_usage', 'audit_log', 'billing_payments', 'wallet_ledger', 'billing_credit_notes',
                                      'privacy_requests', 'consent_log')  -- phase 7: patients' privacy rights work even when read-only
  loop
    execute format('drop trigger if exists trg_license_guard on public.%I', t);
    execute format('create trigger trg_license_guard before insert or update or delete on public.%I for each row execute function public.license_guard()', t);
  end loop;
end $guard$;

-- ------------------------------------------------------------------ wallet
create or replace function public.wallet_apply(p_tenant uuid, p_kind text, p_amount bigint, p_payment uuid default null,
  p_note text default null, p_channel text default null, p_units int default 0)
returns bigint language plpgsql volatile security definer set search_path = public as $$
declare v_bal bigint; v_day date := (now() at time zone 'Asia/Kolkata')::date;
begin
  update public.tenants set wallet_paise = wallet_paise + p_amount where id = p_tenant returning wallet_paise into v_bal;
  if not found then raise exception 'No hospital with id %', p_tenant; end if;
  if p_kind = 'usage' then   -- one row per day and channel
    insert into public.wallet_ledger (tenant_id, day, kind, channel, units, amount_paise, balance_paise)
    values (p_tenant, v_day, 'usage', p_channel, p_units, p_amount, v_bal)
    on conflict (tenant_id, day, channel) where kind = 'usage' do update
      set units = public.wallet_ledger.units + excluded.units, amount_paise = public.wallet_ledger.amount_paise + excluded.amount_paise,
          balance_paise = excluded.balance_paise, created_at = now();
  else
    insert into public.wallet_ledger (tenant_id, day, kind, channel, units, amount_paise, balance_paise, payment, note, created_by)
    values (p_tenant, v_day, p_kind, p_channel, coalesce(p_units, 0), p_amount, v_bal, p_payment, p_note, auth.uid());
  end if;
  return v_bal;
end $$;

-- the notify function adds each batch's outcome (service role only). Messages on the shared accounts beyond the
-- plan's included messages this month are charged to the wallet (the primary hospital is never charged).
create or replace function public.record_message_usage(p_tenant uuid, p_channel text, p_source text, p_sent int, p_failed int)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  v_month  date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
  v_src    text := coalesce(p_source, 'own');
  v_before int;
  v_inc    int;
  v_rate   int;
  v_units  int;
  t        public.tenants;
  cfg      jsonb := public.billing_config();
begin
  if coalesce(p_sent, 0) = 0 and coalesce(p_failed, 0) = 0 then return; end if;
  select sent into v_before from public.message_usage
   where tenant_id = p_tenant and month = v_month and channel = p_channel and source = v_src for update;
  insert into public.message_usage (tenant_id, month, channel, source, sent, failed)
  values (p_tenant, v_month, p_channel, v_src, greatest(coalesce(p_sent, 0), 0), greatest(coalesce(p_failed, 0), 0))
  on conflict (tenant_id, month, channel, source) do update
    set sent = public.message_usage.sent + excluded.sent, failed = public.message_usage.failed + excluded.failed, updated_at = now();
  if v_src <> 'platform' or coalesce(p_sent, 0) <= 0 or p_channel not in ('sms', 'whatsapp', 'email') then return; end if;
  select * into t from public.tenants where id = p_tenant;
  if not found or t.is_primary then return; end if;
  v_inc  := coalesce((t.billing -> 'included' ->> p_channel)::int, (cfg -> 'plans' -> t.plan -> 'included' ->> p_channel)::int, 0);
  v_rate := coalesce((t.billing -> 'ratesPaise' ->> p_channel)::int, (cfg -> 'ratesPaise' ->> p_channel)::int, 0);
  v_before := coalesce(v_before, 0);
  v_units := greatest(0, v_before + p_sent - greatest(v_inc, v_before));
  if v_units > 0 and v_rate > 0 then
    perform public.wallet_apply(p_tenant, 'usage', -(v_units::bigint * v_rate), null, null, p_channel, v_units);
  end if;
end $$;

-- ------------------------------------------------------------------ prices
-- What a plan renewal (1 or 12 months) or a wallet top-up (₹) costs this hospital, GST included.
-- p_plan (phase 6): renew on another plan — it switches when the payment arrives (custom-priced hospitals: ask the team)
drop function if exists public.billing_quote(uuid, text, int, numeric);
create or replace function public.billing_quote(p_tenant uuid, p_kind text, p_months int default 1, p_amount numeric default null, p_plan text default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  t      public.tenants;
  v_plan text;
  cfg    jsonb := public.billing_config();
  v_gst  numeric := coalesce((cfg ->> 'gstPercent')::numeric, 18);
  v_price numeric;
  v_base bigint;
  v_from date;
  v_today date := (now() at time zone 'Asia/Kolkata')::date;
begin
  select * into t from public.tenants where id = p_tenant;
  if not found then raise exception 'No hospital selected'; end if;
  if p_kind = 'plan' then
    if coalesce(p_months, 0) not in (1, 12) then raise exception 'Choose 1 month or 12 months.'; end if;
    v_plan := coalesce(nullif(p_plan, ''), t.plan);
    if v_plan <> t.plan then
      if not (cfg -> 'plans' ? v_plan) then raise exception 'Unknown plan %', v_plan; end if;
      if (t.billing ->> 'price') is not null then
        raise exception 'Your price was agreed with Hospital Comrade — ask them to change your plan.';
      end if;
    end if;
    v_price := case when v_plan = t.plan then coalesce((t.billing ->> 'price')::numeric, (cfg -> 'plans' -> t.plan ->> 'price')::numeric)
                    else (cfg -> 'plans' -> v_plan ->> 'price')::numeric end;
    if v_price is null or v_price <= 0 then
      raise exception 'Your plan is priced individually — Hospital Comrade will send you the payment details.';
    end if;
    v_base := round(v_price * 100 * case when p_months = 12 then coalesce((cfg ->> 'yearlyMonths')::int, 12) else 1 end);
    -- the new period starts after whatever is already paid (or the trial), never in the past
    v_from := greatest(v_today, (greatest(coalesce(t.paid_until, '-infinity'::timestamptz), coalesce(t.trial_ends_at, '-infinity'::timestamptz)) at time zone 'Asia/Kolkata')::date);
    return jsonb_build_object('kind', 'plan', 'plan', v_plan, 'months', p_months, 'base_paise', v_base,
      'gst_paise', round(v_base * v_gst / 100)::bigint, 'total_paise', v_base + round(v_base * v_gst / 100)::bigint, 'gst_percent', v_gst,
      'period_from', v_from, 'period_to', (v_from + make_interval(months => p_months) - interval '1 day')::date);
  elsif p_kind = 'wallet' then
    if p_amount is null or p_amount < coalesce((cfg ->> 'minTopup')::numeric, 500) or p_amount > coalesce((cfg ->> 'maxTopup')::numeric, 100000) then
      raise exception 'Top up between ₹% and ₹%.', coalesce(cfg ->> 'minTopup', '500'), coalesce(cfg ->> 'maxTopup', '100000');
    end if;
    v_base := round(p_amount * 100);
    return jsonb_build_object('kind', 'wallet', 'months', null, 'base_paise', v_base, 'gst_paise', round(v_base * v_gst / 100)::bigint,
      'total_paise', v_base + round(v_base * v_gst / 100)::bigint, 'gst_percent', v_gst);
  end if;
  raise exception 'Unknown payment type';
end $$;

-- ------------------------------------------------------------------ payments
-- Marks a payment paid (once — repeats are ignored), numbers the tax invoice (HC/2026-27/000001, Indian financial
-- year) and applies it: a plan renewal extends paid_until by its months, a top-up credits the wallet (GST excluded).
create or replace function public.apply_payment(p_payment uuid, p_ref text default null, p_method text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  p      public.billing_payments;
  v_d    date := (now() at time zone 'Asia/Kolkata')::date;
  v_fy   text;
  v_inv  text;
  t      public.tenants;
begin
  select * into p from public.billing_payments where id = p_payment for update;
  if not found then raise exception 'Payment not found'; end if;
  if p.status = 'paid' then return jsonb_build_object('ok', true, 'already', true, 'invoice_no', p.invoice_no); end if;
  v_fy := case when extract(month from v_d) >= 4 then to_char(v_d, 'YYYY') || '-' || to_char(v_d + interval '1 year', 'YY')
               else to_char(v_d - interval '1 year', 'YYYY') || '-' || to_char(v_d, 'YY') end;
  v_inv := 'HC/' || v_fy || '/' || lpad(nextval('public.billing_invoice_seq')::text, 6, '0');
  select * into t from public.tenants where id = p.tenant_id for update;
  update public.billing_payments set status = 'paid', paid_at = now(), invoice_no = v_inv,
         payment_id = coalesce(p_ref, payment_id), method = coalesce(p_method, method),
         seller = coalesce(seller, public.billing_config() -> 'seller'),
         buyer = case when buyer = '{}'::jsonb then jsonb_build_object('name', coalesce(t.billing ->> 'legalName', t.name), 'gstin', coalesce(t.billing ->> 'gstin', ''),
                                                                       'address', coalesce(t.billing ->> 'address', '')) else buyer end
   where id = p.id;
  if p.kind = 'plan' then
    update public.tenants
       set plan = coalesce(p.plan, plan),
           paid_until = greatest(now(), coalesce(paid_until, now()), coalesce(trial_ends_at, now())) + make_interval(months => coalesce(p.months, 1)),
           status = case when status = 'suspended' then status else 'active' end
     where id = p.tenant_id;
  else
    perform public.wallet_apply(p.tenant_id, 'topup', p.base_paise, p.id, 'Wallet top-up · ' || v_inv);
  end if;
  return jsonb_build_object('ok', true, 'already', false, 'invoice_no', v_inv);
end $$;

-- ------------------------------------------------------------------ for the app (owner / accountant / platform team)
create or replace function public.billing_summary()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  t      public.tenants;
  cfg    jsonb := public.billing_config();
  v_month date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
begin
  if not public.has_role('owner', 'accountant') then raise exception 'Only the owner or accountant can see billing.' using errcode = '42501'; end if;
  select * into t from public.tenants where id = public.current_tenant();
  if not found then return null; end if;
  return jsonb_build_object(
    'license', public.tenant_license_dates(t.id), 'is_primary', t.is_primary,
    'plan', t.plan,
    'price', coalesce((t.billing ->> 'price')::numeric, (cfg -> 'plans' -> t.plan ->> 'price')::numeric),
    'included', coalesce(cfg -> 'plans' -> t.plan -> 'included', '{}'::jsonb) || coalesce(t.billing -> 'included', '{}'::jsonb),
    'rates_paise', coalesce(cfg -> 'ratesPaise', '{}'::jsonb) || coalesce(t.billing -> 'ratesPaise', '{}'::jsonb),
    'wallet_paise', t.wallet_paise,
    'gst_percent', coalesce((cfg ->> 'gstPercent')::numeric, 18), 'yearly_months', coalesce((cfg ->> 'yearlyMonths')::int, 12),
    'min_topup', coalesce((cfg ->> 'minTopup')::numeric, 500), 'max_topup', coalesce((cfg ->> 'maxTopup')::numeric, 100000),
    'buyer', jsonb_build_object('legalName', coalesce(t.billing ->> 'legalName', t.name), 'gstin', coalesce(t.billing ->> 'gstin', ''), 'address', coalesce(t.billing ->> 'address', '')),
    -- phase 6: plan picker + invoices
    'custom_price', (t.billing ->> 'price') is not null,
    'plans', coalesce((select jsonb_object_agg(e.key, jsonb_build_object('price', e.value -> 'price', 'included', e.value -> 'included')) from jsonb_each(cfg -> 'plans') e), '{}'::jsonb),
    'seller', coalesce(cfg -> 'seller', '{}'::jsonb),
    'usage', coalesce((select jsonb_object_agg(channel, sent) from public.message_usage where tenant_id = t.id and month = v_month and source = 'platform'), '{}'::jsonb));
end $$;

drop function if exists public.my_billing_quote(text, int, numeric);
create or replace function public.my_billing_quote(p_kind text, p_months int default 1, p_amount numeric default null, p_plan text default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_role('owner', 'accountant') then raise exception 'Only the owner or accountant can see prices.' using errcode = '42501'; end if;
  return public.billing_quote(public.current_tenant(), p_kind, p_months, p_amount, p_plan);
end $$;

-- phase 6: during the free trial (nothing paid yet) the owner may try another plan straight away
create or replace function public.change_trial_plan(p_plan text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants; cfg jsonb := public.billing_config();
begin
  if not public.has_role('owner') then raise exception 'Only the owner can change the plan.' using errcode = '42501'; end if;
  select * into t from public.tenants where id = public.current_tenant() for update;
  if not found or t.is_primary then raise exception 'No plan to change here.'; end if;
  if not (cfg -> 'plans' ? coalesce(p_plan, '')) then raise exception 'Unknown plan %', p_plan; end if;
  if (cfg -> 'plans' -> p_plan ->> 'price') is null then raise exception 'That plan is priced individually — Hospital Comrade will get in touch.'; end if;
  if (t.billing ->> 'price') is not null then raise exception 'Your price was agreed with Hospital Comrade — ask them to change your plan.'; end if;
  if public.tenant_license(t.id) <> 'trial' or coalesce(t.paid_until > now(), false) then
    raise exception 'Your plan is paid — choose the new plan when you renew; it switches when the payment arrives.';
  end if;
  update public.tenants set plan = p_plan, updated_at = now() where id = t.id;
  return public.billing_summary();
end $$;

-- phase 6: messages per month on the shared accounts (sent, included, charged to the wallet) — the usage chart
create or replace function public.billing_usage_history(p_months int default 6)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_t   uuid := public.current_tenant();
  v_now date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
  v_n   int := least(greatest(coalesce(p_months, 6), 1), 24);
begin
  if not public.has_role('owner', 'accountant') then raise exception 'Only the owner or accountant can see billing.' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'month', to_char(m.month, 'YYYY-MM'),
      'sent', coalesce((select jsonb_object_agg(u.channel, u.sent) from public.message_usage u where u.tenant_id = v_t and u.month = m.month and u.source = 'platform' and u.channel <> 'push'), '{}'::jsonb),
      'own', coalesce((select sum(u.sent) from public.message_usage u where u.tenant_id = v_t and u.month = m.month and u.source = 'own'), 0),
      'charged_paise', coalesce((select -sum(l.amount_paise) from public.wallet_ledger l where l.tenant_id = v_t and l.kind = 'usage'
                                   and date_trunc('month', l.day)::date = m.month), 0)) order by m.month)
    from (select (v_now - make_interval(months => g))::date as month from generate_series(v_n - 1, 0, -1) g) m), '[]'::jsonb);
end $$;

-- phase 6: renewal reminders to each hospital's owner — 7, 3 and 1 day before the trial / plan ends, and once when the
-- grace period starts. E-mail (+ app push). Daily from the scheduler (Settings → Notifications → automatic delivery).
create or replace function public.queue_billing_reminders()
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  r       record;
  v_count int := 0;
  v_today date := (now() at time zone 'Asia/Kolkata')::date;
  v_left  int;
  v_m     text;
  v_end   timestamptz;
  v_name  text;
  v_mail  text;
  v_prof  uuid;
  v_subj  text;
  v_body  text;
  v_link  text;
  cfg     jsonb := public.billing_config();
begin
  if auth.uid() is not null and coalesce(public.provider_role(), '') <> 'admin' then raise exception 'Not allowed' using errcode = '42501'; end if;
  for r in select t.*, public.tenant_license(t.id) as lic from public.tenants t where not t.is_primary and t.status <> 'suspended' loop
    v_end := greatest(coalesce(r.paid_until, '-infinity'::timestamptz), coalesce(r.trial_ends_at, '-infinity'::timestamptz));
    continue when v_end = '-infinity'::timestamptz;
    v_left := ((v_end at time zone 'Asia/Kolkata')::date - v_today);
    v_m := case when r.lic in ('trial', 'active') and v_left in (7, 3, 1) then 'd' || v_left
                when r.lic = 'grace' then 'grace' end;
    continue when v_m is null;
    -- once per hospital, milestone and end date (paying moves the end date, so the next round starts fresh)
    continue when exists (select 1 from public.notification_outbox o where o.tenant_id = r.id and o.event = 'billing_reminder'
                            and o.vars ->> 'milestone' = v_m and o.vars ->> 'until' = to_char(v_end at time zone 'Asia/Kolkata', 'YYYY-MM-DD'));
    select p.id, p.full_name, p.email into v_prof, v_name, v_mail from public.profiles p where p.tenant_id = r.id and p.role = 'owner' order by p.created_at limit 1;
    v_mail := coalesce(v_mail, (select s.data ->> 'owner_email' from public.app_settings s where s.tenant_id = r.id and s.key = 'bootstrap'));
    continue when v_mail is null and v_prof is null;
    v_link := coalesce((select 'https://' || d.domain || '/billing' from public.tenant_domains d where d.tenant_id = r.id order by d.is_primary desc, (d.verified_at is null), d.created_at limit 1),
                       nullif(rtrim(coalesce((select c.data ->> 'siteUrl' from public.site_content c where c.tenant_id = r.id and c.key = 'settings'), ''), '/') || '/billing', '/billing'),
                       'the app → Billing & plan');
    v_subj := case when v_m = 'grace' then '{hospital}: renew now to keep adding records'
                   when r.lic = 'trial' then '{hospital}: your free trial ends {date}'
                   else '{hospital}: your plan renews {date}' end;
    v_body := case when v_m = 'grace'
      then 'Namaste {name}, the {plan} plan for {hospital} has ended. Everything still works until {read_only}; after that the app becomes read-only until you renew. Renew in a minute: {link}'
      else 'Namaste {name}, the ' || case when r.lic = 'trial' then 'free trial' else '{plan} plan' end
           || ' for {hospital} ends on {date} ({days}). Renew in a minute: {link} — UPI, cards and net banking, with a GST invoice.' end;
    perform set_config('app.tenant_id', r.id::text, true);
    v_count := v_count + public.notify_enqueue_raw('billing_reminder',
      jsonb_build_object('subject', v_subj, 'text', v_body), array['email', 'push'], null, v_mail, v_prof,
      jsonb_build_object('name', split_part(coalesce(v_name, 'there'), ' ', 1), 'milestone', v_m,
        'hospital', coalesce(nullif((select c.data ->> 'name' from public.site_content c where c.tenant_id = r.id and c.key = 'settings'), ''), r.name),
        'until', to_char(v_end at time zone 'Asia/Kolkata', 'YYYY-MM-DD'), 'date', to_char(v_end at time zone 'Asia/Kolkata', 'DD Mon YYYY'),
        'days', case when v_left = 1 then 'tomorrow' else 'in ' || v_left || ' days' end,
        'read_only', to_char((v_end + make_interval(days => coalesce((cfg ->> 'graceDays')::int, 7))) at time zone 'Asia/Kolkata', 'DD Mon YYYY'),
        'plan', initcap(r.plan), 'link', v_link),
      'tenants', r.id, null);
  end loop;
  perform set_config('app.tenant_id', '', true);
  return v_count;
end $$;

-- the owner keeps the name and GSTIN printed on Hospital Comrade's invoices up to date
create or replace function public.set_billing_details(p_legal_name text, p_gstin text, p_address text)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_gstin text := upper(regexp_replace(coalesce(p_gstin, ''), '\s', '', 'g'));
begin
  if not public.has_role('owner') then raise exception 'Only the owner can change billing details.' using errcode = '42501'; end if;
  if v_gstin <> '' and v_gstin !~ '^[0-9]{2}[A-Z0-9]{10}[0-9A-Z]Z[0-9A-Z]$' then raise exception 'That GSTIN does not look right (15 characters, e.g. 10ABCDE1234F1Z5).'; end if;
  update public.tenants set billing = billing || jsonb_build_object('legalName', left(trim(coalesce(p_legal_name, '')), 150), 'gstin', v_gstin, 'address', left(trim(coalesce(p_address, '')), 300))
   where id = public.current_tenant();
end $$;

-- ------------------------------------------------------------------ platform team tools (until the provider panel)
-- Works on the hospital chosen in the provider banner. admin: everything; finance: manual payments + wallet adjustments.
--   manual_payment  { kind: plan|wallet, months?, amount?, method: bank|upi|cash|cheque, reference?, note? }
--   wallet_adjust   { amount: ±₹, note }            extend_trial { days }            (admin)
--   set_plan        { plan?, price?, included?, ratesPaise? }  (admin; price null = plan price)
--   suspend / resume                                          (admin)
create or replace function public.provider_billing(p_action text, p_args jsonb default '{}'::jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_mode   text := public.provider_mode();
  v_tenant uuid := public.current_tenant();
  q        jsonb;
  v_id     uuid;
  r        jsonb;
  v_amt    numeric;
  cfg      jsonb := public.billing_config();
begin
  if v_mode not in ('admin', 'finance') or not public.provider_can(v_tenant) then
    raise exception 'Only Hospital Comrade admins or finance can do this.' using errcode = '42501';
  end if;
  if p_action in ('extend_trial', 'set_plan', 'suspend', 'resume') and v_mode <> 'admin' then
    raise exception 'Only a Hospital Comrade admin can do this.' using errcode = '42501';
  end if;
  if p_action = 'manual_payment' then
    q := public.billing_quote(v_tenant, p_args ->> 'kind', coalesce((p_args ->> 'months')::int, 1), (p_args ->> 'amount')::numeric, p_args ->> 'plan');
    insert into public.billing_payments (tenant_id, kind, plan, months, base_paise, gst_paise, total_paise, provider, method, payment_id, note,
                                         period_from, period_to, created_by)
    values (v_tenant, q ->> 'kind', q ->> 'plan', (q ->> 'months')::int, (q ->> 'base_paise')::bigint, (q ->> 'gst_paise')::bigint, (q ->> 'total_paise')::bigint,
            'manual', coalesce(nullif(p_args ->> 'method', ''), 'bank'), nullif(p_args ->> 'reference', ''), nullif(p_args ->> 'note', ''),
            (q ->> 'period_from')::date, (q ->> 'period_to')::date, auth.uid())
    returning id into v_id;
    r := public.apply_payment(v_id);
  elsif p_action = 'wallet_adjust' then
    v_amt := (p_args ->> 'amount')::numeric;
    if v_amt is null or v_amt = 0 or abs(v_amt) > 100000 then raise exception 'Enter an amount between -₹1,00,000 and ₹1,00,000.'; end if;
    if coalesce(trim(p_args ->> 'note'), '') = '' then raise exception 'Add a note saying why.'; end if;
    r := jsonb_build_object('wallet_paise', public.wallet_apply(v_tenant, 'adjustment', round(v_amt * 100)::bigint, null, left(p_args ->> 'note', 200)));
  elsif p_action = 'extend_trial' then
    if coalesce((p_args ->> 'days')::int, 0) not between 1 and 90 then raise exception 'Extend by 1 to 90 days.'; end if;
    update public.tenants set trial_ends_at = greatest(now(), coalesce(trial_ends_at, now())) + make_interval(days => (p_args ->> 'days')::int),
                              status = case when status in ('suspended', 'active') then status else 'trial' end
     where id = v_tenant;
  elsif p_action = 'set_plan' then
    if p_args ? 'plan' and not (cfg -> 'plans' ? (p_args ->> 'plan')) then raise exception 'Unknown plan'; end if;
    update public.tenants
       set plan = coalesce(p_args ->> 'plan', plan),
           billing = (billing - 'price' - 'included' - 'ratesPaise')
                     || case when p_args ? 'price' and p_args -> 'price' <> 'null'::jsonb then jsonb_build_object('price', (p_args ->> 'price')::numeric)
                             when not (p_args ? 'price') and billing ? 'price' then jsonb_build_object('price', billing -> 'price') else '{}'::jsonb end
                     || case when p_args ? 'included' then jsonb_build_object('included', p_args -> 'included')
                             when billing ? 'included' then jsonb_build_object('included', billing -> 'included') else '{}'::jsonb end
                     || case when p_args ? 'ratesPaise' then jsonb_build_object('ratesPaise', p_args -> 'ratesPaise')
                             when billing ? 'ratesPaise' then jsonb_build_object('ratesPaise', billing -> 'ratesPaise') else '{}'::jsonb end
     where id = v_tenant;
  elsif p_action = 'suspend' then
    update public.tenants set status = 'suspended' where id = v_tenant and not is_primary;
  elsif p_action = 'resume' then
    update public.tenants set status = case when paid_until > now() then 'active' when trial_ends_at > now() then 'trial' else 'active' end
     where id = v_tenant and status = 'suspended';
  else
    raise exception 'Unknown action %', p_action;
  end if;
  perform public.provider_log('billing:' || p_action, v_tenant::text, p_args);
  return coalesce(r, '{}'::jsonb) || jsonb_build_object('license', public.tenant_license_dates(v_tenant));
end $$;

-- ------------------------------------------------------------------ who may call what
revoke all on function public.billing_config(), public.license_guard(), public.wallet_apply(uuid, text, bigint, uuid, text, text, int),
  public.record_message_usage(uuid, text, text, int, int), public.billing_quote(uuid, text, int, numeric, text),
  public.apply_payment(uuid, text, text), public.queue_billing_reminders() from public, anon, authenticated;
grant execute on function public.record_message_usage(uuid, text, text, int, int), public.billing_quote(uuid, text, int, numeric, text),
  public.apply_payment(uuid, text, text), public.queue_billing_reminders() to service_role;
revoke all on function public.billing_summary(), public.my_billing_quote(text, int, numeric, text), public.set_billing_details(text, text, text),
  public.provider_billing(text, jsonb), public.change_trial_plan(text), public.billing_usage_history(int) from public, anon;
grant execute on function public.billing_summary(), public.my_billing_quote(text, int, numeric, text), public.set_billing_details(text, text, text),
  public.provider_billing(text, jsonb), public.change_trial_plan(text), public.billing_usage_history(int) to authenticated;
-- tenant_license (status word only) is needed by license_guard(), which runs as the caller. The dates (trial / paid until /
-- purge) are only handed out through my_context() / billing_summary() / the control panel — never for any hospital id.
grant execute on function public.tenant_license(uuid) to anon, authenticated, service_role;
revoke all on function public.tenant_license_dates(uuid) from public, anon, authenticated;
grant execute on function public.tenant_license_dates(uuid) to service_role;


-- =====================================================================================================
--  22. HOSPITAL COMRADE CONTROL PANEL — phase 5 (the separate /control-panel/ app; loaded after billing.sql)
-- =====================================================================================================
--  Every function checks the caller itself (SECURITY DEFINER, explicit provider checks):
--    admin   — every hospital; create / edit hospitals, team, platform settings, audit
--    finance — assigned hospitals; billing actions (manual payments, wallet) and payments
--    support — assigned hospitals; read-only here
--  Acting on one hospital reuses the hospital-scoped functions (provider_billing) with that hospital pinned in the
--  transaction (app.tenant_id), so the same rules and the same provider audit apply.

create or replace function public.cp_require(p_roles text[] default array['admin', 'support', 'finance'])
returns text language plpgsql stable security definer set search_path = public as $$
declare r text := public.provider_role();
begin
  if r is null or not (r = any (p_roles)) then
    raise exception 'Only the Hospital Comrade team (%) can do this.', array_to_string(p_roles, ' / ') using errcode = '42501';
  end if;
  return r;
end $$;

-- who is signed in to the panel (null = not a platform team member)
-- otp: the sign-in code state (otp_verify.sql) — while a code is required and not entered, every other cp_* refuses
drop function if exists public.cp_me() cascade;
create function public.cp_me()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare r jsonb;
begin
  select jsonb_build_object('user_id', u.user_id, 'role', u.role, 'email', a.email, 'full_name', coalesce(p.full_name, split_part(a.email, '@', 1))) into r
    from public.provider_users u join auth.users a on a.id = u.user_id left join public.profiles p on p.id = u.user_id
   where u.user_id = auth.uid() and u.active;
  if r is not null and to_regprocedure('public.login_otp_status()') is not null then
    r := r || jsonb_build_object('otp', public.login_otp_status());
  end if;
  return r;
end $$;

-- ------------------------------------------------------------------ hospitals
create or replace function public.cp_hospitals(p_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  cfg     jsonb := public.billing_config();
  v_month date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
  r       jsonb;
begin
  perform public.cp_require();
  select coalesce(jsonb_agg(h order by h ->> 'is_primary' desc, h ->> 'name'), '[]'::jsonb) into r from (
    select jsonb_build_object(
      'id', t.id, 'slug', t.slug, 'name', t.name, 'code', t.code, 'plan', t.plan, 'is_primary', t.is_primary, 'is_demo', t.is_demo, 'notes', t.notes,
      'closing_at', t.closing_at, 'purge_after', t.purge_after, 'close_reason', t.close_reason,
      'created_at', t.created_at, 'modules', t.modules, 'license', public.tenant_license_dates(t.id), 'wallet_paise', t.wallet_paise,
      'price', coalesce((t.billing ->> 'price')::numeric, (cfg -> 'plans' -> t.plan ->> 'price')::numeric), 'billing', t.billing,
      'domain', (select d.domain from public.tenant_domains d where d.tenant_id = t.id order by d.is_primary desc, d.created_at limit 1),
      'staff', (select count(*) from public.profiles p where p.tenant_id = t.id and p.role <> 'patient'),
      'patients', (select count(*) from public.patients x where x.tenant_id = t.id),
      'owner_joined', exists (select 1 from public.profiles p where p.tenant_id = t.id and p.role = 'owner'),
      'owner_email', coalesce((select p.email from public.profiles p where p.tenant_id = t.id and p.role = 'owner' order by p.created_at limit 1),
                              (select s.data ->> 'owner_email' from public.app_settings s where s.tenant_id = t.id and s.key = 'bootstrap')),
      'messages', (select coalesce(sum(m.sent), 0) from public.message_usage m where m.tenant_id = t.id and m.month = v_month)
    ) h
    from public.tenants t
    where public.provider_can(t.id) and (p_id is null or t.id = p_id)
  ) q;
  return r;
end $$;

-- one hospital with its domains, team, payments and this month's messages
create or replace function public.cp_hospital(p_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  h       jsonb;
  v_role  text := public.cp_require();
  v_month date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
begin
  h := public.cp_hospitals(p_id) -> 0;
  if h is null then raise exception 'Hospital not found or not assigned to you.'; end if;
  return h || jsonb_build_object(
    'domains', coalesce((select jsonb_agg(jsonb_build_object('domain', d.domain, 'is_primary', d.is_primary, 'method', d.method, 'status', d.status, 'ssl_status', d.ssl_status, 'verified_at', d.verified_at)
                                          order by d.is_primary desc, d.created_at) from public.tenant_domains d where d.tenant_id = p_id), '[]'::jsonb),
    'team', coalesce((select jsonb_agg(jsonb_build_object('user_id', u.user_id, 'role', u.role, 'name', coalesce(p.full_name, a.email)) order by u.role)
                        from public.provider_users u join auth.users a on a.id = u.user_id left join public.profiles p on p.id = u.user_id
                       where u.active and (u.role = 'admin' or exists (select 1 from public.provider_assignments x where x.user_id = u.user_id and x.tenant_id = p_id))), '[]'::jsonb),
    'usage', coalesce((select jsonb_object_agg(m.channel || ':' || m.source, m.sent) from public.message_usage m where m.tenant_id = p_id and m.month = v_month), '{}'::jsonb),
    'payments', case when v_role = 'support' then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(b) - 'tenant_id' - 'buyer' order by b.created_at desc)
                  from (select * from public.billing_payments where tenant_id = p_id and status <> 'created' order by created_at desc limit 20) b), '[]'::jsonb) end);
end $$;

-- a new hospital: tenants row, address, owner e-mail (first sign-up with it becomes the owner), default settings
--   { slug, name, code, plan, owner_email, domain?, status: trial|active, trial_days?, months? (active), modules?, notes? }
-- hospital_create() does the work (internal — also used by self-service sign-up); cp_create_hospital() is the admin's door
create or replace function public.hospital_create(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  cfg     jsonb := public.billing_config();
  v_slug  text := lower(trim(coalesce(p ->> 'slug', '')));
  v_name  text := trim(coalesce(p ->> 'name', ''));
  v_code  text := upper(trim(coalesce(p ->> 'code', '')));
  v_plan  text := coalesce(nullif(p ->> 'plan', ''), 'clinic');
  v_owner text := lower(trim(coalesce(p ->> 'owner_email', '')));
  v_dom   text := lower(trim(regexp_replace(coalesce(p ->> 'domain', ''), '^https?://|/.*$', '', 'g')));
  v_stat  text := coalesce(nullif(p ->> 'status', ''), 'trial');
  v_days  int := coalesce((p ->> 'trial_days')::int, (cfg ->> 'trialDays')::int, 14);
  v_mod   jsonb := coalesce(p -> 'modules', '{"dashboard": "hospital", "forms": "hospital", "notifications": "hospital", "security": "hospital"}'::jsonb);
  v_id    uuid;
begin
  if v_slug !~ '^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$' then raise exception 'Short name: 2–40 characters, a-z, 0-9 and -, e.g. citycare'; end if;
  if char_length(v_name) not between 2 and 120 then raise exception 'Enter the hospital''s name.'; end if;
  if v_code !~ '^[A-Z]{2,6}$' then raise exception 'Record prefix: 2–6 capital letters, e.g. CCC'; end if;
  if not (cfg -> 'plans' ? v_plan) then raise exception 'Unknown plan %', v_plan; end if;
  if v_owner !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Enter the owner''s e-mail.'; end if;
  if v_stat not in ('trial', 'active') then raise exception 'Start as trial or active.'; end if;
  if v_days not between 1 and 90 then raise exception 'Trial: 1 to 90 days.'; end if;
  if v_dom <> '' and v_dom !~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$' then raise exception 'That address does not look like a domain (e.g. citycareclinic.in).'; end if;
  if exists (select 1 from public.tenants where slug = v_slug) then raise exception 'The short name % is taken.', v_slug; end if;
  if v_dom <> '' and exists (select 1 from public.tenant_domains where domain = v_dom) then raise exception '% already belongs to a hospital.', v_dom; end if;
  if exists (select 1 from public.profiles where lower(email) = v_owner and tenant_id is not null and role <> 'patient')
     or exists (select 1 from public.provider_users u join auth.users a on a.id = u.user_id where lower(a.email) = v_owner) then
    raise exception '% is already used by another hospital or the platform team — one account = one hospital, please use another e-mail.', v_owner;
  end if;
  if exists (select 1 from jsonb_each_text(v_mod) m where m.key not in ('general', 'appearance', 'dashboard', 'notifications', 'forms', 'security', 'data', 'cms')
                                                         or m.value not in ('hospital', 'provider')) then
    raise exception 'Unknown module setting';
  end if;

  insert into public.tenants (slug, name, code, plan, status, modules, notes, trial_ends_at, paid_until)
  values (v_slug, v_name, v_code, v_plan, v_stat, v_mod, nullif(trim(coalesce(p ->> 'notes', '')), ''),
          case when v_stat = 'trial' then now() + make_interval(days => v_days) end,
          case when v_stat = 'active' then now() + make_interval(months => greatest(1, least(36, coalesce((p ->> 'months')::int, 12)))) end)
  returning id into v_id;
  perform set_config('app.tenant_id', v_id::text, true);   -- everything below (and its audit trail) belongs to the new hospital
  if v_dom <> '' then insert into public.tenant_domains (domain, tenant_id, is_primary) values (v_dom, v_id, true); end if;
  insert into public.app_settings (tenant_id, key, data) values (v_id, 'bootstrap', jsonb_build_object('owner_email', v_owner));
  perform public.seed_hospital_defaults(v_id);
  perform public.provider_log('hospital:create', v_slug, jsonb_build_object('plan', v_plan, 'status', v_stat, 'owner', v_owner, 'domain', nullif(v_dom, '')));
  return jsonb_build_object('id', v_id, 'slug', v_slug, 'domain', nullif(v_dom, ''), 'owner_email', v_owner);
end $$;

create or replace function public.cp_create_hospital(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return public.hospital_create(p);
end $$;

-- edit a hospital: { name?, code?, notes?, modules?, owner_email? (until the owner has signed up) }
create or replace function public.cp_update_hospital(p_id uuid, p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants; v_owner text;
begin
  perform public.cp_require(array['admin']);
  select * into t from public.tenants where id = p_id for update;
  if not found then raise exception 'Hospital not found'; end if;
  perform set_config('app.tenant_id', p_id::text, true);
  if p ? 'name' and char_length(trim(p ->> 'name')) not between 2 and 120 then raise exception 'Enter the hospital''s name.'; end if;
  if p ? 'code' and upper(trim(p ->> 'code')) !~ '^[A-Z]{2,6}$' then raise exception 'Record prefix: 2–6 capital letters'; end if;
  if p ? 'modules' and (jsonb_typeof(p -> 'modules') <> 'object' or exists (select 1 from jsonb_each_text(p -> 'modules') m
       where m.key not in ('general', 'appearance', 'dashboard', 'notifications', 'forms', 'security', 'data', 'cms') or m.value not in ('hospital', 'provider'))) then
    raise exception 'Unknown module setting';
  end if;
  update public.tenants set
    name = coalesce(trim(p ->> 'name'), name),
    code = coalesce(upper(trim(p ->> 'code')), code),
    notes = case when p ? 'notes' then nullif(trim(p ->> 'notes'), '') else notes end,
    modules = coalesce(p -> 'modules', modules),
    updated_at = now()
  where id = p_id;
  if p ? 'owner_email' then
    v_owner := lower(trim(p ->> 'owner_email'));
    if v_owner !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Enter the owner''s e-mail.'; end if;
    if exists (select 1 from public.profiles where tenant_id = p_id and role = 'owner') then raise exception 'The owner has already signed up — change owners in the hospital''s Users & accounts.'; end if;
    insert into public.app_settings (tenant_id, key, data) values (p_id, 'bootstrap', jsonb_build_object('owner_email', v_owner))
    on conflict (tenant_id, key) do update set data = excluded.data;
  end if;
  perform public.provider_log('hospital:update', t.slug, p);
  return public.cp_hospitals(p_id) -> 0;
end $$;

-- plan, trial, wallet, manual payments, suspend for one hospital — the same function the hospital app uses
create or replace function public.cp_billing(p_id uuid, p_action text, p_args jsonb default '{}'::jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin', 'finance']);
  if not public.provider_can(p_id) then raise exception 'Hospital not found or not assigned to you.' using errcode = '42501'; end if;
  perform set_config('app.tenant_id', p_id::text, true);
  return public.provider_billing(p_action, coalesce(p_args, '{}'::jsonb));
end $$;

-- ------------------------------------------------------------------ overview
create or replace function public.cp_overview()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_role  text := public.cp_require();
  h       jsonb := public.cp_hospitals();
  v_month date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
begin
  return jsonb_build_object(
    'hospitals', jsonb_array_length(h),
    'by_status', coalesce((select jsonb_object_agg(s, n) from (select x -> 'license' ->> 'status' s, count(*) n from jsonb_array_elements(h) x where not (x ->> 'is_primary')::boolean group by 1) q), '{}'::jsonb),
    'by_plan', coalesce((select jsonb_object_agg(s, n) from (select x ->> 'plan' s, count(*) n from jsonb_array_elements(h) x where not (x ->> 'is_primary')::boolean group by 1) q), '{}'::jsonb),
    -- monthly recurring revenue: paying hospitals' monthly price (₹, before GST)
    'mrr', coalesce((select sum((x ->> 'price')::numeric) from jsonb_array_elements(h) x where x -> 'license' ->> 'status' = 'active' and not (x ->> 'is_primary')::boolean and x -> 'license' ->> 'paid_until' is not null), 0),
    'wallet_paise', coalesce((select sum((x ->> 'wallet_paise')::bigint) from jsonb_array_elements(h) x where not (x ->> 'is_primary')::boolean), 0),
    'attention', coalesce((select jsonb_agg(jsonb_build_object('id', x -> 'id', 'name', x -> 'name', 'status', x -> 'license' ->> 'status',
                              'until', coalesce(x -> 'license' ->> 'paid_until', x -> 'license' ->> 'trial_ends_at'), 'read_only_from', x -> 'license' ->> 'read_only_from'))
                          from jsonb_array_elements(h) x
                         where not (x ->> 'is_primary')::boolean and (x -> 'license' ->> 'status' in ('grace', 'read_only')
                            or (x -> 'license' ->> 'status' in ('trial', 'active')
                                and coalesce((x -> 'license' ->> 'paid_until')::timestamptz, (x -> 'license' ->> 'trial_ends_at')::timestamptz) < now() + interval '7 days'))), '[]'::jsonb),
    'payments_30d_paise', case when v_role = 'support' then null else
      (select coalesce(sum(total_paise), 0) from public.billing_payments where status = 'paid' and paid_at > now() - interval '30 days' and public.provider_can(tenant_id)) end,
    'messages', coalesce((select jsonb_object_agg(channel, n) from (select m.channel, sum(m.sent) n from public.message_usage m
                           where m.month = v_month and m.source = 'platform' and public.provider_can(m.tenant_id) group by 1) q), '{}'::jsonb),
    'leads_new', case when v_role = 'admin' then (select count(*) from public.platform_leads where status = 'new') end);
end $$;

-- ------------------------------------------------------------------ team
create or replace function public.cp_team()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return coalesce((select jsonb_agg(jsonb_build_object(
      'user_id', u.user_id, 'email', a.email, 'name', coalesce(p.full_name, split_part(a.email, '@', 1)), 'role', u.role, 'active', u.active, 'since', u.created_at,
      'hospitals', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name) order by t.name) from public.provider_assignments x join public.tenants t on t.id = x.tenant_id where x.user_id = u.user_id), '[]'::jsonb),
      'last_action', (select max(at) from public.provider_audit pa where pa.user_id = u.user_id)) order by u.active desc, u.role, a.email)
    from public.provider_users u join auth.users a on a.id = u.user_id left join public.profiles p on p.id = u.user_id), '[]'::jsonb);
end $$;

-- add / change a team member: { email, role, active, hospitals: [tenant id…] }. They sign up once first (any address).
create or replace function public.cp_save_provider(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_email  text := lower(trim(coalesce(p ->> 'email', '')));
  v_role   text := coalesce(p ->> 'role', 'support');
  v_active boolean := coalesce((p ->> 'active')::boolean, true);
  v_user   uuid;
  v_hosp   text;
begin
  perform public.cp_require(array['admin']);
  if v_role not in ('admin', 'support', 'finance') then raise exception 'Role: admin, support or finance'; end if;
  select id into v_user from auth.users where lower(email) = v_email;
  if v_user is null then raise exception 'No account with % yet — ask them to create one first (Sign up on the platform site), then add them here.', v_email; end if;
  if v_user = auth.uid() and (v_role <> 'admin' or not v_active) then raise exception 'You can''t remove your own admin access — ask another admin.'; end if;
  if not exists (select 1 from public.provider_users where user_id = v_user) then
    select t.name into v_hosp from public.profiles pr join public.tenants t on t.id = pr.tenant_id where pr.id = v_user and pr.role <> 'patient';
    if v_hosp is not null then raise exception '% is a staff account at % — one account = one hospital, please use another e-mail.', v_email, v_hosp; end if;
    -- a platform account belongs to no hospital (its sign-up created a patient record there — removed)
    perform set_config('app.tenant_id', coalesce((select tenant_id::text from public.profiles where id = v_user), ''), true);   -- audit trail stays with that hospital
    perform set_config('app.tenant_move', 'on', true);
    update public.profiles set tenant_id = null, role = 'patient' where id = v_user;
    delete from public.patients where profile_id = v_user;
    perform set_config('app.tenant_move', '', true);
    perform set_config('app.tenant_id', '', true);
  end if;
  insert into public.provider_users (user_id, role, active) values (v_user, v_role, v_active)
  on conflict (user_id) do update set role = excluded.role, active = excluded.active;
  delete from public.provider_assignments where user_id = v_user;
  if v_role <> 'admin' then
    insert into public.provider_assignments (user_id, tenant_id)
    select v_user, t.id from public.tenants t where t.id::text in (select jsonb_array_elements_text(coalesce(p -> 'hospitals', '[]'::jsonb)));
  end if;
  perform public.provider_log('team:save', v_email, jsonb_build_object('role', v_role, 'active', v_active, 'hospitals', p -> 'hospitals'));
  return jsonb_build_object('user_id', v_user);
end $$;

-- ------------------------------------------------------------------ money, audit, settings
create or replace function public.cp_payments(p_tenant uuid default null, p_limit int default 200)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin', 'finance']);
  return coalesce((select jsonb_agg(to_jsonb(b) order by b.created_at desc) from (
    select bp.id, bp.created_at, bp.tenant_id, t.name as hospital, bp.kind, bp.plan, bp.months, bp.base_paise, bp.gst_paise, bp.total_paise,
           bp.status, bp.provider, bp.method, bp.payment_id, bp.order_id, bp.paid_at, bp.invoice_no, bp.period_from, bp.period_to, bp.buyer
      from public.billing_payments bp join public.tenants t on t.id = bp.tenant_id
     where public.provider_can(bp.tenant_id) and (p_tenant is null or bp.tenant_id = p_tenant) and bp.status <> 'created'
     order by bp.created_at desc limit least(greatest(coalesce(p_limit, 200), 1), 1000)) b), '[]'::jsonb);
end $$;

create or replace function public.cp_audit(p_tenant uuid default null, p_limit int default 300)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return coalesce((select jsonb_agg(to_jsonb(a) order by a.at desc) from (
    select pa.id, pa.at, pa.user_name, pa.mode, pa.tenant_id, t.name as hospital, pa.action, pa.target, pa.detail
      from public.provider_audit pa left join public.tenants t on t.id = pa.tenant_id
     where p_tenant is null or pa.tenant_id = p_tenant
     order by pa.at desc limit least(greatest(coalesce(p_limit, 300), 1), 2000)) a), '[]'::jsonb);
end $$;

create or replace function public.cp_settings()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return jsonb_build_object('billing', public.billing_config());
end $$;

-- prices, GST, trial / grace days, message rates, seller details (merged into platform_settings 'billing')
create or replace function public.cp_save_billing_settings(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare k text; n numeric;
begin
  perform public.cp_require(array['admin']);
  if jsonb_typeof(p) <> 'object' then raise exception 'Settings must be an object'; end if;
  for k in select jsonb_object_keys(p) loop
    if k not in ('gstPercent', 'trialDays', 'graceDays', 'yearlyMonths', 'minTopup', 'maxTopup', 'ratesPaise', 'plans', 'seller') then raise exception 'Unknown setting %', k; end if;
  end loop;
  foreach k in array array['gstPercent', 'trialDays', 'graceDays', 'yearlyMonths', 'minTopup', 'maxTopup'] loop
    if p ? k then
      n := (p ->> k)::numeric;
      if n is null or n < 0 or (k = 'gstPercent' and n > 40) or (k in ('trialDays', 'graceDays') and n > 90) or (k = 'yearlyMonths' and (n < 1 or n > 12)) then
        raise exception 'The value for % is out of range.', k;
      end if;
    end if;
  end loop;
  if (p ? 'minTopup' or p ? 'maxTopup')
     and coalesce((p ->> 'minTopup')::numeric, (public.billing_config() ->> 'minTopup')::numeric) > coalesce((p ->> 'maxTopup')::numeric, (public.billing_config() ->> 'maxTopup')::numeric) then
    raise exception 'The minimum top-up is above the maximum.';
  end if;
  if p ? 'ratesPaise' and exists (select 1 from jsonb_each(p -> 'ratesPaise') r where r.key not in ('sms', 'whatsapp', 'email') or jsonb_typeof(r.value) <> 'number' or (r.value)::text::numeric not between 0 and 1000) then
    raise exception 'Message rates: paise per message, 0–1000.';
  end if;
  if p ? 'plans' and exists (select 1 from jsonb_each(p -> 'plans') x where not (public.billing_config() -> 'plans' ? x.key)) then
    raise exception 'Unknown plan';
  end if;
  update public.platform_settings set data = data
    || (p - 'plans' - 'ratesPaise' - 'seller')
    || case when p ? 'ratesPaise' then jsonb_build_object('ratesPaise', coalesce(data -> 'ratesPaise', '{}'::jsonb) || (p -> 'ratesPaise')) else '{}'::jsonb end
    || case when p ? 'seller' then jsonb_build_object('seller', coalesce(data -> 'seller', '{}'::jsonb) || (p -> 'seller')) else '{}'::jsonb end
    || case when p ? 'plans' then jsonb_build_object('plans', (select jsonb_object_agg(e.key, case when p -> 'plans' ? e.key then e.value || (p -> 'plans' -> e.key) else e.value end)
                                                                 from jsonb_each(data -> 'plans') e)) else '{}'::jsonb end
   where key = 'billing';
  perform public.provider_log('settings:billing', null, p);
  return public.billing_config();
end $$;

-- ------------------------------------------------------------------ who may call what
revoke all on function public.cp_require(text[]), public.hospital_create(jsonb) from public, anon, authenticated;
revoke all on function public.cp_me(), public.cp_hospitals(uuid), public.cp_hospital(uuid), public.cp_create_hospital(jsonb), public.cp_update_hospital(uuid, jsonb),
  public.cp_billing(uuid, text, jsonb), public.cp_overview(), public.cp_team(), public.cp_save_provider(jsonb), public.cp_payments(uuid, int),
  public.cp_audit(uuid, int), public.cp_settings(), public.cp_save_billing_settings(jsonb) from public, anon;
grant execute on function public.cp_me(), public.cp_hospitals(uuid), public.cp_hospital(uuid), public.cp_create_hospital(jsonb), public.cp_update_hospital(uuid, jsonb),
  public.cp_billing(uuid, text, jsonb), public.cp_overview(), public.cp_team(), public.cp_save_provider(jsonb), public.cp_payments(uuid, int),
  public.cp_audit(uuid, int), public.cp_settings(), public.cp_save_billing_settings(jsonb) to authenticated;


-- =====================================================================================================
--  23. OPS & COMPLIANCE — phase 7 (loaded last, after the control panel)
-- =====================================================================================================
--  7.1 Privacy (DPDP Act 2023): a patient downloads everything held about them, withdraws marketing consent and asks
--      for a correction or erasure; the owner works the requests. Erasure = anonymise: the medical and GST records
--      stay (clinical-establishment and tax rules require them) but nothing identifies the person any more.
--  7.3 Offboarding: the platform closes a hospital (read-only, owner can export), then purges it after the notice
--      period — with a fresh password confirmation ("sudo"). GST invoices to the hospital are archived first.
--  7.4 Incident register (personal-data breaches: Board + affected people within 72 hours).
--  7.5 System health for the platform team.  7.6 Retention: old logs / OTPs / enquiries removed daily.
--  Session switches used here: app.skip_audit (no copy of removed data in the audit log), app.privacy (privacy
--  actions pass the licence guard). Only SECURITY DEFINER functions set them.

-- ------------------------------------------------------------------ helpers
-- did the signed-in user type their password in the last p_seconds? (Supabase puts the sign-in time in the JWT's amr)
create or replace function public.recent_reauth(p_seconds int default 600)
returns boolean language plpgsql stable security definer set search_path = public as $$
declare c jsonb; v_ts numeric;
begin
  begin c := nullif(current_setting('request.jwt.claims', true), '')::jsonb; exception when others then c := null; end;
  if c is null then return false; end if;
  select max((a ->> 'timestamp')::numeric) into v_ts from jsonb_array_elements(case when jsonb_typeof(c -> 'amr') = 'array' then c -> 'amr' else '[]'::jsonb end) a
   where a ->> 'method' in ('password', 'otp', 'totp');
  v_ts := coalesce(v_ts, (c ->> 'iat')::numeric);
  return v_ts is not null and to_timestamp(v_ts) > now() - make_interval(secs => greatest(coalesce(p_seconds, 600), 60));
end $$;

-- the hospital owner to write to (the first owner account, else the e-mail the owner will sign up with)
create or replace function public.tenant_owner_contact(p_tenant uuid)
returns table (profile_id uuid, full_name text, email text) language sql stable security definer set search_path = public as $$
  select p.id, p.full_name, p.email from public.profiles p where p.tenant_id = p_tenant and p.role = 'owner'
  union all
  select null, null, s.data ->> 'owner_email' from public.app_settings s
   where s.tenant_id = p_tenant and s.key = 'bootstrap' and not exists (select 1 from public.profiles p where p.tenant_id = p_tenant and p.role = 'owner')
  limit 1
$$;

-- ------------------------------------------------------------------ 7.1 privacy: tables
alter table public.patients add column if not exists marketing_opt_out boolean not null default false;
alter table public.patients add column if not exists erased_at timestamptz;

create table if not exists public.privacy_requests (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null default public.current_tenant() references public.tenants (id) on delete cascade,
  created_at        timestamptz not null default now(),
  profile_id        uuid references public.profiles (id) on delete set null,
  patient_id        uuid references public.patients (id) on delete set null,
  requester_name    text,
  kind              text not null check (kind in ('access', 'correction', 'erasure')),
  details           text check (char_length(details) <= 2000),
  status            text not null default 'open' check (status in ('open', 'done', 'rejected')),
  resolved_at       timestamptz,
  resolved_by       uuid,
  resolved_by_name  text,
  resolution        text check (char_length(resolution) <= 1000)
);
create index if not exists privacy_requests_tenant_idx on public.privacy_requests (tenant_id, status, created_at desc);

create table if not exists public.consent_log (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null default public.current_tenant() references public.tenants (id) on delete cascade,
  created_at  timestamptz not null default now(),
  profile_id  uuid references public.profiles (id) on delete set null,
  patient_id  uuid references public.patients (id) on delete set null,
  purpose     text not null,                       -- 'marketing' (health tips & offers)
  granted     boolean not null,
  source      text not null default 'portal'
);
create index if not exists consent_log_patient_idx on public.consent_log (tenant_id, patient_id, created_at desc);

do $rls$
declare t text;
begin
  foreach t in array array['privacy_requests', 'consent_log'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
    execute format('grant all on public.%I to service_role', t);
    execute format('drop policy if exists tenant_isolation on public.%I', t);
    execute format('create policy tenant_isolation on public.%I as restrictive for all to anon, authenticated
                      using (tenant_id = (select public.current_tenant())) with check (tenant_id = (select public.current_tenant()))', t);
    execute format('drop policy if exists privacy_read on public.%I', t);
    -- the person themself, and the owner who answers the requests
    execute format('create policy privacy_read on public.%I for select to authenticated using (profile_id = (select auth.uid()) or public.has_role(''owner''))', t);
    execute format('drop trigger if exists trg_keep_tenant on public.%I', t);
    execute format('create trigger trg_keep_tenant before update of tenant_id on public.%I for each row execute function public.keep_tenant()', t);
  end loop;
end $rls$;

-- scheduled / custom messages to patients skip those who said no to health tips & offers
create or replace function public.patient_accepts_marketing(p_patient uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select not marketing_opt_out and erased_at is null from public.patients where id = p_patient), true)
$$;

-- ------------------------------------------------------------------ 7.1 privacy: the patient
-- everything this hospital holds about the signed-in person, as one JSON document (logged as a fulfilled access request)
create or replace function public.my_data_export()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_pid uuid;
  r     jsonb;
  t     text;
  rows  jsonb;
begin
  if v_uid is null then raise exception 'Sign in first.' using errcode = '42501'; end if;
  select id into v_pid from public.patients where profile_id = v_uid and tenant_id = public.current_tenant();
  r := jsonb_build_object(
    'generated_at', now(),
    'hospital', (select name from public.tenants where id = public.current_tenant()),
    'account', (select to_jsonb(p) - 'tenant_id' from public.profiles p where p.id = v_uid),
    'patient', (select to_jsonb(x) - 'tenant_id' from public.patients x where x.id = v_pid));
  if v_pid is not null then
    foreach t in array array['appointments', 'prescriptions', 'lab_tests', 'admissions', 'invoices', 'payments', 'visit_feedback'] loop
      continue when to_regclass('public.' || t) is null;
      execute format('select coalesce(jsonb_agg(to_jsonb(x) - ''tenant_id'' order by x.created_at), ''[]''::jsonb) from public.%I x where x.patient_id = $1 and x.tenant_id = $2', t)
        into rows using v_pid, public.current_tenant();
      r := r || jsonb_build_object(t, rows);
    end loop;
  end if;
  r := r || jsonb_build_object(
    'consents', coalesce((select jsonb_agg(jsonb_build_object('at', c.created_at, 'purpose', c.purpose, 'granted', c.granted, 'source', c.source) order by c.created_at)
                            from public.consent_log c where c.profile_id = v_uid and c.tenant_id = public.current_tenant()), '[]'::jsonb),
    'requests', coalesce((select jsonb_agg(jsonb_build_object('at', q.created_at, 'kind', q.kind, 'status', q.status, 'details', q.details, 'resolution', q.resolution) order by q.created_at)
                            from public.privacy_requests q where q.profile_id = v_uid and q.tenant_id = public.current_tenant()), '[]'::jsonb));
  perform set_config('app.privacy', 'on', true);
  insert into public.privacy_requests (profile_id, patient_id, requester_name, kind, details, status, resolved_at, resolution)
  values (v_uid, v_pid, (select full_name from public.profiles where id = v_uid), 'access', 'Downloaded from the patient portal', 'done', now(), 'Self-service download');
  perform set_config('app.privacy', '', true);
  return r;
end $$;

-- marketing (health tips & offers) consent — appointment and health messages are part of the service and always sent
create or replace function public.set_marketing_consent(p_granted boolean)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v_pid uuid;
begin
  if auth.uid() is null then raise exception 'Sign in first.' using errcode = '42501'; end if;
  select id into v_pid from public.patients where profile_id = auth.uid() and tenant_id = public.current_tenant();
  if v_pid is null then raise exception 'Only patients have this choice.'; end if;
  perform set_config('app.privacy', 'on', true);
  update public.patients set marketing_opt_out = not coalesce(p_granted, false), updated_at = now() where id = v_pid;
  insert into public.consent_log (profile_id, patient_id, purpose, granted, source) values (auth.uid(), v_pid, 'marketing', coalesce(p_granted, false), 'portal');
  perform set_config('app.privacy', '', true);
  return jsonb_build_object('marketing', coalesce(p_granted, false));
end $$;

-- ask the hospital to correct or erase my data (one open request of each kind); the owner is e-mailed
create or replace function public.privacy_submit(p_kind text, p_details text default null)
returns uuid language plpgsql volatile security definer set search_path = public as $$
declare v_id uuid; v_pid uuid; v_name text; o record;
begin
  if auth.uid() is null then raise exception 'Sign in first.' using errcode = '42501'; end if;
  -- friendly messages instead of raw "null value in column …" errors
  if public.current_tenant() is null then raise exception 'Your account is not linked to a hospital yet.' using errcode = '42501'; end if;
  if not exists (select 1 from public.profiles where id = auth.uid() and role = 'patient') then
    raise exception 'Only patients can do this.' using errcode = '42501';
  end if;
  if p_kind is null or p_kind not in ('correction', 'erasure') then raise exception 'Choose correction or erasure.'; end if;
  if p_kind = 'correction' and coalesce(trim(p_details), '') = '' then raise exception 'Tell us what is wrong and what it should say.'; end if;
  if exists (select 1 from public.privacy_requests where profile_id = auth.uid() and kind = p_kind and status = 'open' and tenant_id = public.current_tenant()) then
    raise exception 'You already have an open % request — the hospital will get back to you.', p_kind;
  end if;
  select id into v_pid from public.patients where profile_id = auth.uid() and tenant_id = public.current_tenant();
  select full_name into v_name from public.profiles where id = auth.uid();
  perform set_config('app.privacy', 'on', true);
  insert into public.privacy_requests (profile_id, patient_id, requester_name, kind, details)
  values (auth.uid(), v_pid, v_name, p_kind, nullif(left(trim(coalesce(p_details, '')), 2000), '')) returning id into v_id;
  perform set_config('app.privacy', '', true);
  select * into o from public.tenant_owner_contact(public.current_tenant());
  if o.email is not null or o.profile_id is not null then
    perform public.notify_enqueue_raw('privacy_request',
      jsonb_build_object('subject', '{hospital}: new privacy request ({kind})',
        'text', 'A patient ({name}) asked for data {kind}. Please answer within 30 days: Privacy requests in the app.'),
      array['email', 'push'], null, o.email, o.profile_id, jsonb_build_object('kind', p_kind, 'name', coalesce(v_name, 'patient')), 'privacy_requests', v_id);
  end if;
  return v_id;
end $$;

-- ------------------------------------------------------------------ 7.1 privacy: erasure (anonymisation)
create or replace function public.erase_patient(p_patient uuid, p_reason text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare p public.patients; v_phone text;
begin
  select * into p from public.patients where id = p_patient for update;
  if not found then raise exception 'Patient not found'; end if;
  if p.erased_at is not null then return; end if;
  v_phone := right(regexp_replace(coalesce(p.phone, ''), '\D', '', 'g'), 10);
  perform set_config('app.skip_audit', 'on', true);
  perform set_config('app.privacy', 'on', true);
  update public.patients
     set full_name = 'Erased patient ' || p.mrn, phone = null, email = null, address = null, emergency_contact_name = null,
         emergency_contact_phone = null, insurance_provider = null,
         date_of_birth = case when p.date_of_birth is null then null else make_date(extract(year from p.date_of_birth)::int, 1, 1) end,
         marketing_opt_out = true, erased_at = now(), profile_id = null, updated_at = now()
   where id = p.id;
  update public.visit_feedback set comment = null where patient_id = p.id;
  if v_phone <> '' then
    delete from public.wa_sessions where right(regexp_replace(phone, '\D', '', 'g'), 10) = v_phone and tenant_id = p.tenant_id;
    delete from public.booking_otps where right(regexp_replace(phone, '\D', '', 'g'), 10) = v_phone and tenant_id = p.tenant_id;
    delete from public.site_enquiries where right(regexp_replace(phone, '\D', '', 'g'), 10) = v_phone and tenant_id = p.tenant_id;
  end if;
  -- the sign-in account goes (profile, devices, consents follow); clinical rows keep pointing at the anonymised patient
  if p.profile_id is not null then delete from auth.users where id = p.profile_id; end if;
  -- the audit trail keeps that something happened, not who it was about
  update public.audit_log set changes = jsonb_build_object('redacted', true), summary = 'Erased patient ' || p.mrn
   where record_id in (p.id, coalesce(p.profile_id, p.id));
  insert into public.audit_log (table_name, record_id, action, actor_id, actor_name, actor_role, summary, changes)
  values ('patients', p.id, 'update', auth.uid(), coalesce((select full_name from public.profiles where id = auth.uid()), 'System'),
          coalesce((select role::text from public.profiles where id = auth.uid()), 'system'), 'Erased patient ' || p.mrn,
          jsonb_build_object('erased', jsonb_build_object('to', true), 'reason', jsonb_build_object('to', left(coalesce(p_reason, 'privacy request'), 200))));
  perform set_config('app.skip_audit', '', true);
  perform set_config('app.privacy', '', true);
end $$;

-- the owner answers a request: done / rejected (+ a note to the person). Erasure "done" anonymises the patient.
create or replace function public.privacy_resolve(p_id uuid, p_status text, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare q public.privacy_requests;
begin
  if not public.has_role('owner') then raise exception 'Only the owner answers privacy requests.' using errcode = '42501'; end if;
  if p_status not in ('done', 'rejected') then raise exception 'Mark it done or rejected.'; end if;
  select * into q from public.privacy_requests where id = p_id and tenant_id = public.current_tenant() for update;
  if not found then raise exception 'Request not found'; end if;
  if q.status <> 'open' then raise exception 'This request was already answered.'; end if;
  if p_status = 'rejected' and coalesce(trim(p_note), '') = '' then raise exception 'Say why — the person sees this note.'; end if;
  if q.kind = 'erasure' and p_status = 'done' then
    if q.patient_id is not null then perform public.erase_patient(q.patient_id, 'privacy request');
    elsif q.profile_id is not null then delete from auth.users where id = q.profile_id; end if;
  end if;
  perform set_config('app.privacy', 'on', true);
  update public.privacy_requests set status = p_status, resolved_at = now(), resolved_by = auth.uid(),
         resolved_by_name = (select full_name from public.profiles where id = auth.uid()), resolution = nullif(left(trim(coalesce(p_note, '')), 1000), '')
   where id = p_id;
  perform set_config('app.privacy', '', true);
  return (select to_jsonb(r) from public.privacy_requests r where r.id = p_id);
end $$;

-- ------------------------------------------------------------------ 7.3 offboarding
create table if not exists public.tenant_purges (
  id              uuid primary key default gen_random_uuid(),
  hospital_id     uuid not null,          -- not "tenant_id": this platform table must stay out of the per-hospital loops
  slug            text not null,
  name            text not null,
  closed_at       timestamptz,
  close_reason    text,
  purged_at       timestamptz not null default now(),
  purged_by       uuid,
  purged_by_name  text,
  counts          jsonb not null default '{}'::jsonb,
  billing         jsonb not null default '[]'::jsonb      -- the platform's GST invoices to the hospital (kept 8 years)
);
alter table public.tenant_purges enable row level security;
revoke all on public.tenant_purges from anon, authenticated;
grant all on public.tenant_purges to service_role;

create or replace function public.cp_close_hospital(p_id uuid, p_reason text, p_days int default 30)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants; o record;
begin
  perform public.cp_require(array['admin']);
  select * into t from public.tenants where id = p_id for update;
  if not found then raise exception 'Hospital not found'; end if;
  if t.is_primary then raise exception 'The platform''s own hospital can''t be closed.'; end if;
  if t.closing_at is not null then raise exception 'This hospital is already closing.'; end if;
  if coalesce(p_days, 0) not between 7 and 90 then raise exception 'Give the hospital 7 to 90 days to export its data.'; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'Add the reason (it is kept with the record).'; end if;
  update public.tenants set closing_at = now(), purge_after = now() + make_interval(days => p_days), close_reason = left(trim(p_reason), 300), updated_at = now() where id = p_id;
  perform set_config('app.tenant_id', p_id::text, true);
  perform public.provider_log('hospital:close', t.slug, jsonb_build_object('reason', p_reason, 'days', p_days));
  select * into o from public.tenant_owner_contact(p_id);
  if o.email is not null or o.profile_id is not null then
    perform public.notify_enqueue_raw('hospital_closing',
      jsonb_build_object('subject', '{hospital}: your account is closing on {date}',
        'text', 'Your Hospital Comrade account for {hospital} is now read-only and will be deleted after {date}. Download your data before then: Settings → Data → Export all data.'),
      array['email', 'push'], null, o.email, o.profile_id,
      jsonb_build_object('date', to_char((now() + make_interval(days => p_days)) at time zone 'Asia/Kolkata', 'DD Mon YYYY')), 'tenants', p_id);
  end if;
  return public.cp_hospital(p_id);
end $$;

create or replace function public.cp_reopen_hospital(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants;
begin
  perform public.cp_require(array['admin']);
  select * into t from public.tenants where id = p_id for update;
  if not found or t.closing_at is null then raise exception 'This hospital is not closing.'; end if;
  update public.tenants set closing_at = null, purge_after = null, close_reason = null, updated_at = now() where id = p_id;
  perform set_config('app.tenant_id', p_id::text, true);
  perform public.provider_log('hospital:reopen', t.slug, null);
  return public.cp_hospital(p_id);
end $$;

-- delete everything of a closed hospital. Needs: admin, password typed in the last 10 minutes, the short name typed,
-- the notice period over. Keeps a tombstone with row counts and the platform's invoices to the hospital.
create or replace function public.cp_purge_hospital(p_id uuid, p_confirm text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  t       public.tenants;
  v_tabs  text[];
  v_left  text[];
  tab     text;
  v_pass  int := 0;
  v_count jsonb := '{}'::jsonb;
  n       bigint;
begin
  perform public.cp_require(array['admin']);
  if not public.recent_reauth(600) then
    raise exception 'REAUTH_REQUIRED: Confirm your password to delete a hospital.' using errcode = '42501';
  end if;
  select * into t from public.tenants where id = p_id for update;
  if not found then raise exception 'Hospital not found'; end if;
  if t.is_primary then raise exception 'The platform''s own hospital can''t be deleted.'; end if;
  if t.closing_at is null then raise exception 'Close the hospital first — it gets time to export its data.'; end if;
  if t.purge_after > now() then raise exception 'The hospital can export its data until % — delete after that.', to_char(t.purge_after at time zone 'Asia/Kolkata', 'DD Mon YYYY'); end if;
  if coalesce(p_confirm, '') <> t.slug then raise exception 'Type the hospital''s short name (%) to confirm.', t.slug; end if;

  perform set_config('app.tenant_id', p_id::text, true);
  perform set_config('app.skip_audit', 'on', true);
  select array_agg(c.table_name::text order by c.table_name) into v_tabs
    from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name and x.table_type = 'BASE TABLE'
   where c.table_schema = 'public' and c.column_name = 'tenant_id' and c.table_name not in ('tenants', 'provider_audit');
  foreach tab in array v_tabs loop
    execute format('select count(*) from public.%I where tenant_id = $1', tab) into n using p_id;
    if n > 0 then v_count := v_count || jsonb_build_object(tab, n); end if;
  end loop;
  insert into public.tenant_purges (hospital_id, slug, name, closed_at, close_reason, purged_by, purged_by_name, counts, billing)
  values (t.id, t.slug, t.name, t.closing_at, t.close_reason, auth.uid(), (select full_name from public.profiles where id = auth.uid()), v_count,
          coalesce((select jsonb_agg(to_jsonb(b) order by b.created_at) from public.billing_payments b where b.tenant_id = p_id and b.status in ('paid', 'refunded')), '[]'::jsonb));

  -- sign-in accounts first (a person belongs to one hospital), then the rows: tables referencing each other with
  -- ON DELETE RESTRICT are emptied children-first by retrying until nothing is left
  delete from auth.users where id in (select id from public.profiles where tenant_id = p_id) and id not in (select user_id from public.provider_users);
  v_left := v_tabs;
  while array_length(v_left, 1) > 0 and v_pass < 8 loop
    v_pass := v_pass + 1;
    v_tabs := v_left; v_left := '{}';
    foreach tab in array v_tabs loop
      begin
        execute format('delete from public.%I where tenant_id = $1', tab) using p_id;
      exception when foreign_key_violation or restrict_violation then v_left := v_left || tab;
      end;
    end loop;
  end loop;
  if array_length(v_left, 1) > 0 then raise exception 'Could not delete: %', array_to_string(v_left, ', '); end if;
  delete from public.tenants where id = p_id;
  perform set_config('app.skip_audit', '', true);
  perform public.provider_log('hospital:purge', t.slug, jsonb_build_object('name', t.name, 'counts', v_count));
  return jsonb_build_object('purged', t.slug, 'counts', v_count);
end $$;

-- ------------------------------------------------------------------ 7.4 incident register
create table if not exists public.platform_incidents (
  id                     uuid primary key default gen_random_uuid(),
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  detected_at            timestamptz not null default now(),
  title                  text not null check (char_length(title) between 3 and 200),
  description            text check (char_length(description) <= 5000),
  severity               text not null default 'medium' check (severity in ('low', 'medium', 'high', 'critical')),
  status                 text not null default 'open' check (status in ('open', 'contained', 'resolved')),
  personal_data          boolean not null default false,
  affected_tenants       uuid[] not null default '{}',
  affected_people        int check (affected_people >= 0),
  board_reported_at      timestamptz,
  hospitals_notified_at  timestamptz,
  resolved_at            timestamptz,
  timeline               jsonb not null default '[]'::jsonb,
  created_by             uuid,
  created_by_name        text
);
alter table public.platform_incidents enable row level security;
revoke all on public.platform_incidents from anon, authenticated;
grant all on public.platform_incidents to service_role;

create or replace function public.cp_incidents()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin', 'support']);
  return coalesce((select jsonb_agg(to_jsonb(i) || jsonb_build_object(
      'deadline', i.detected_at + interval '72 hours',
      'hospitals', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'slug', t.slug) order by t.name) from public.tenants t where t.id = any (i.affected_tenants)), '[]'::jsonb))
      order by (i.status = 'resolved'), i.detected_at desc)
    from public.platform_incidents i), '[]'::jsonb);
end $$;

-- create (no id) or update an incident; "note" appends to the timeline; board_reported: true stamps the time
create or replace function public.cp_save_incident(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v_id uuid := nullif(p ->> 'id', '')::uuid; v_name text := (select full_name from public.profiles where id = auth.uid()); i public.platform_incidents;
begin
  perform public.cp_require(array['admin']);
  if v_id is null then
    insert into public.platform_incidents (title, description, severity, personal_data, affected_tenants, affected_people, detected_at, created_by, created_by_name, timeline)
    values (trim(p ->> 'title'), p ->> 'description', coalesce(p ->> 'severity', 'medium'), coalesce((p ->> 'personal_data')::boolean, false),
            coalesce((select array_agg(x::uuid) from jsonb_array_elements_text(coalesce(p -> 'affected_tenants', '[]'::jsonb)) x), '{}'),
            (p ->> 'affected_people')::int, coalesce((p ->> 'detected_at')::timestamptz, now()), auth.uid(), v_name,
            jsonb_build_array(jsonb_build_object('at', now(), 'by', v_name, 'note', coalesce(nullif(p ->> 'note', ''), 'Incident recorded'))))
    returning id into v_id;
  else
    select * into i from public.platform_incidents where id = v_id for update;
    if not found then raise exception 'Incident not found'; end if;
    update public.platform_incidents set
      title = coalesce(nullif(trim(p ->> 'title'), ''), title),
      description = case when p ? 'description' then p ->> 'description' else description end,
      severity = coalesce(p ->> 'severity', severity),
      status = coalesce(p ->> 'status', status),
      personal_data = coalesce((p ->> 'personal_data')::boolean, personal_data),
      affected_tenants = case when p ? 'affected_tenants' then coalesce((select array_agg(x::uuid) from jsonb_array_elements_text(p -> 'affected_tenants') x), '{}') else affected_tenants end,
      affected_people = case when p ? 'affected_people' then (p ->> 'affected_people')::int else affected_people end,
      board_reported_at = case when coalesce((p ->> 'board_reported')::boolean, false) then coalesce(board_reported_at, now()) else board_reported_at end,
      resolved_at = case when p ->> 'status' = 'resolved' then coalesce(resolved_at, now()) when p ->> 'status' in ('open', 'contained') then null else resolved_at end,
      timeline = timeline || case when coalesce(p ->> 'note', '') <> '' or (p ->> 'status') is distinct from i.status and p ? 'status'
                                  then jsonb_build_array(jsonb_build_object('at', now(), 'by', v_name,
                                         'note', concat_ws(' — ', case when p ? 'status' and (p ->> 'status') <> i.status then 'Status: ' || (p ->> 'status') end, nullif(p ->> 'note', ''))))
                                  else '[]'::jsonb end,
      updated_at = now()
     where id = v_id;
  end if;
  perform public.provider_log('incident:save', v_id::text, p - 'description');
  return (select to_jsonb(x) from public.platform_incidents x where x.id = v_id);
end $$;

-- e-mail (+ push) the owners of the affected hospitals; returns who got it queued and who must be contacted by hand
create or replace function public.cp_notify_incident(p_id uuid, p_message text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare i public.platform_incidents; t record; o record; n int; r jsonb := '[]'::jsonb;
begin
  perform public.cp_require(array['admin']);
  select * into i from public.platform_incidents where id = p_id for update;
  if not found then raise exception 'Incident not found'; end if;
  if coalesce(trim(p_message), '') = '' then raise exception 'Write the notice: what happened, what data, what you are doing, what they should do.'; end if;
  if cardinality(i.affected_tenants) = 0 then raise exception 'Add the affected hospitals first.'; end if;
  for t in select id, name from public.tenants where id = any (i.affected_tenants) order by name loop
    perform set_config('app.tenant_id', t.id::text, true);
    select * into o from public.tenant_owner_contact(t.id);
    n := 0;
    if o.email is not null or o.profile_id is not null then
      n := public.notify_enqueue_raw('incident_notice', jsonb_build_object('subject', '{hospital}: security notice from Hospital Comrade', 'text', left(p_message, 3500)),
             array['email', 'push'], null, o.email, o.profile_id, jsonb_build_object('incident', i.id), 'platform_incidents', i.id);
    end if;
    r := r || jsonb_build_object('id', t.id, 'name', t.name, 'owner_email', o.email, 'queued', n);
  end loop;
  perform set_config('app.tenant_id', '', true);
  update public.platform_incidents set hospitals_notified_at = now(), updated_at = now(),
         timeline = timeline || jsonb_build_array(jsonb_build_object('at', now(), 'by', (select full_name from public.profiles where id = auth.uid()),
                                                                      'note', 'Hospitals notified (' || jsonb_array_length(r) || ')'))
   where id = p_id;
  perform public.provider_log('incident:notify', p_id::text, jsonb_build_object('hospitals', r));
  return r;
end $$;

-- ------------------------------------------------------------------ 7.6 retention
insert into public.platform_settings (key, data) values ('retention', jsonb_build_object(
  'auditDays', 1095, 'providerAuditDays', 1095, 'outboxDays', 400, 'otpDays', 7, 'enquiryDays', 1095, 'leadDays', 1095,
  'privacyDays', 1095, 'waSessionDays', 30))
on conflict (key) do nothing;

create or replace function public.retention_config()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((select data from public.platform_settings where key = 'retention'), '{}'::jsonb)
$$;

-- delete what is past its keep-by date (daily from the scheduler as dch-retention; a platform admin can run it too)
create or replace function public.run_retention()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c   jsonb := public.retention_config();
  r   jsonb := '{}'::jsonb;
  r_s jsonb;
  n   bigint;
  d   int;
begin
  if auth.uid() is not null and coalesce(public.provider_role(), '') <> 'admin' then raise exception 'Not allowed' using errcode = '42501'; end if;
  perform set_config('app.skip_audit', 'on', true);
  d := greatest(coalesce((c ->> 'auditDays')::int, 1095), 365);
  delete from public.audit_log where created_at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('audit_log', n);
  d := greatest(coalesce((c ->> 'providerAuditDays')::int, 1095), 365);
  delete from public.provider_audit where at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('provider_audit', n);
  d := greatest(coalesce((c ->> 'outboxDays')::int, 400), 30);
  delete from public.notification_outbox where created_at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('notification_outbox', n);
  d := greatest(coalesce((c ->> 'otpDays')::int, 7), 1);
  delete from public.booking_otps where created_at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('booking_otps', n);
  delete from public.password_reset_otps where created_at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('password_reset_otps', n);
  d := greatest(coalesce((c ->> 'enquiryDays')::int, 1095), 30);
  delete from public.site_enquiries where created_at < now() - make_interval(days => d) and status in ('resolved', 'spam'); get diagnostics n = row_count; r := r || jsonb_build_object('site_enquiries', n);
  d := greatest(coalesce((c ->> 'leadDays')::int, 1095), 30);
  delete from public.platform_leads where created_at < now() - make_interval(days => d) and status in ('won', 'lost'); get diagnostics n = row_count; r := r || jsonb_build_object('platform_leads', n);
  d := greatest(coalesce((c ->> 'privacyDays')::int, 1095), 365);
  delete from public.privacy_requests where status <> 'open' and resolved_at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('privacy_requests', n);
  d := greatest(coalesce((c ->> 'waSessionDays')::int, 30), 1);
  delete from public.wa_sessions where updated_at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('wa_sessions', n);
  -- self-service sign-ups (phase 8, signup.sql — loaded after this file)
  if to_regprocedure('public.signup_cleanup()') is not null then execute 'select public.signup_cleanup()' into r_s; r := r || jsonb_build_object('signups', r_s); end if;
  perform set_config('app.skip_audit', '', true);
  update public.platform_settings set data = data || jsonb_build_object('last_run', jsonb_build_object('at', now(), 'deleted', r)), updated_at = now() where key = 'retention';
  return r;
end $$;

create or replace function public.cp_retention()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return public.retention_config();
end $$;

create or replace function public.cp_save_retention(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare k text; v int;
  mins constant jsonb := '{"auditDays": 365, "providerAuditDays": 365, "outboxDays": 30, "otpDays": 1, "enquiryDays": 30, "leadDays": 30, "privacyDays": 365, "waSessionDays": 1}';
begin
  perform public.cp_require(array['admin']);
  for k in select jsonb_object_keys(coalesce(p, '{}'::jsonb)) loop
    if not (mins ? k) then raise exception 'Unknown setting %', k; end if;
    v := (p ->> k)::int;
    if v is null or v < (mins ->> k)::int or v > 3650 then raise exception '%: keep at least % days (at most 3650).', k, mins ->> k; end if;
  end loop;
  update public.platform_settings set data = data || (select jsonb_object_agg(key, (value #>> '{}')::int) from jsonb_each(p)), updated_at = now() where key = 'retention';
  perform public.provider_log('settings:retention', null, p);
  return public.retention_config();
end $$;

-- ------------------------------------------------------------------ 7.5 system health
create or replace function public.cp_health()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_role text := public.cp_require(array['admin', 'support']);
  v_cron boolean := exists (select 1 from pg_extension where extname = 'pg_cron');
  v_net  boolean := exists (select 1 from pg_extension where extname = 'pg_net');
  v_jobs jsonb := '[]'::jsonb;
  v_db   bigint;
begin
  if v_cron then
    execute $q$ select coalesce(jsonb_agg(jsonb_build_object('name', j.jobname, 'schedule', j.schedule, 'active', j.active,
              'last_run', d.start_time, 'last_status', d.status, 'last_message', left(d.return_message, 200)) order by j.jobname), '[]'::jsonb)
           from cron.job j
           left join lateral (select start_time, status, return_message from cron.job_run_details r where r.jobid = j.jobid order by start_time desc limit 1) d on true
          where j.jobname like 'dch-%' $q$ into v_jobs;
  end if;
  begin v_db := pg_database_size(current_database()); exception when others then v_db := null; end;
  return jsonb_build_object(
    'at', now(),
    'extensions', jsonb_build_object('pg_cron', v_cron, 'pg_net', v_net),
    'jobs', v_jobs,
    'messages', coalesce((select jsonb_agg(x order by (x ->> 'failed')::int desc, x ->> 'name') from (
        select jsonb_build_object('id', t.id, 'name', t.name,
          'sent', count(*) filter (where o.status = 'sent'), 'failed', count(*) filter (where o.status = 'failed'),
          'waiting', count(*) filter (where o.status in ('queued', 'sending')),
          'stuck', count(*) filter (where o.status in ('queued', 'sending') and o.created_at < now() - interval '15 minutes')) x
          from public.notification_outbox o join public.tenants t on t.id = o.tenant_id
         where o.created_at > now() - interval '24 hours' and (v_role = 'admin' or public.provider_can(t.id))
         group by t.id, t.name) s), '[]'::jsonb),
    'recent_failures', coalesce((select jsonb_agg(jsonb_build_object('at', o.created_at, 'hospital', t.name, 'event', o.event, 'channel', o.channel, 'error', left(o.error, 200)) order by o.created_at desc)
        from (select * from public.notification_outbox where status = 'failed' and created_at > now() - interval '7 days' order by created_at desc limit 20) o
        join public.tenants t on t.id = o.tenant_id where v_role = 'admin' or public.provider_can(t.id)), '[]'::jsonb),
    'payments', jsonb_build_object(
        'abandoned_7d', (select count(*) from public.billing_payments where status = 'created' and created_at between now() - interval '7 days' and now() - interval '1 hour'),
        'failed_7d', (select count(*) from public.billing_payments where status = 'failed' and created_at > now() - interval '7 days'),
        'paid_7d', (select count(*) from public.billing_payments where status = 'paid' and paid_at > now() - interval '7 days')),
    'database', jsonb_build_object('size_bytes', v_db,
        'largest_tables', case when v_role = 'admin' then coalesce((select jsonb_agg(jsonb_build_object('table', c.relname, 'bytes', pg_total_relation_size(c.oid)) order by pg_total_relation_size(c.oid) desc)
            from (select c.oid, c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r'
                  order by pg_total_relation_size(c.oid) desc limit 8) c), '[]'::jsonb) else '[]'::jsonb end),
    'hospitals', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'closing_at', t.closing_at, 'purge_after', t.purge_after,
          'patients', (select count(*) from public.patients p where p.tenant_id = t.id),
          'appointments', (select count(*) from public.appointments a where a.tenant_id = t.id),
          'invoices', (select count(*) from public.invoices i where i.tenant_id = t.id),
          'audit_log', (select count(*) from public.audit_log l where l.tenant_id = t.id)) order by t.is_primary desc, t.name)
        from public.tenants t where v_role = 'admin' or public.provider_can(t.id)), '[]'::jsonb),
    'retention', public.retention_config() -> 'last_run',
    'privacy_open', (select count(*) from public.privacy_requests where status = 'open'),
    'privacy_overdue', (select count(*) from public.privacy_requests where status = 'open' and created_at < now() - interval '30 days'),
    'incidents_open', (select count(*) from public.platform_incidents where status <> 'resolved'));
end $$;

-- ------------------------------------------------------------------ who may call what
revoke all on function public.recent_reauth(int), public.tenant_owner_contact(uuid), public.erase_patient(uuid, text),
  public.retention_config(), public.patient_accepts_marketing(uuid) from public, anon, authenticated;
grant execute on function public.run_retention(), public.patient_accepts_marketing(uuid) to service_role;
-- run_retention checks the caller itself (scheduler / service, or a platform admin from the panel)
revoke all on function public.run_retention() from public, anon;
grant execute on function public.run_retention() to authenticated;
revoke all on function public.my_data_export(), public.set_marketing_consent(boolean), public.privacy_submit(text, text), public.privacy_resolve(uuid, text, text),
  public.cp_close_hospital(uuid, text, int), public.cp_reopen_hospital(uuid), public.cp_purge_hospital(uuid, text), public.cp_incidents(),
  public.cp_save_incident(jsonb), public.cp_notify_incident(uuid, text), public.cp_retention(), public.cp_save_retention(jsonb), public.cp_health() from public, anon;
grant execute on function public.my_data_export(), public.set_marketing_consent(boolean), public.privacy_submit(text, text), public.privacy_resolve(uuid, text, text),
  public.cp_close_hospital(uuid, text, int), public.cp_reopen_hospital(uuid), public.cp_purge_hospital(uuid, text), public.cp_incidents(),
  public.cp_save_incident(jsonb), public.cp_notify_incident(uuid, text), public.cp_retention(), public.cp_save_retention(jsonb), public.cp_health() to authenticated;


-- =====================================================================================================
--  PHASE 8.2 — SELF-SERVICE FREE-TRIAL SIGN-UP (Hospital Comrade product page → /signup)
-- =====================================================================================================
--  • platform_settings 'signup' { enabled, mode: instant|approve, trialDays, plan, maxPerDay, unclaimedDays, platformUrl }
--    — the platform admin decides in the control panel (Settings → Free-trial sign-up).
--  • platform_trial_signup(p) — anyone (anon): validates, rate-limits, records the accepted Terms version and either
--    creates the hospital right away (instant) or waits for the admin (approve). The person then creates the owner
--    account on the new hospital with the same e-mail (app_settings 'bootstrap', as for panel-created hospitals).
--  • cp_signups / cp_signup_decide — the admin's list with approve / reject.
--  • signup_cleanup() (nightly, from run_retention): pending requests expire after 30 days; hospitals nobody claimed
--    within unclaimedDays are closed (the normal 7-day notice, then the admin may delete them).
--  Platform tables never use a column called tenant_id (the tenancy loops would scope them to a hospital).
-- =====================================================================================================

insert into public.platform_settings (key, data) values ('signup',
  '{"enabled": true, "mode": "approve", "trialDays": 14, "plan": "clinic", "maxPerDay": 25, "unclaimedDays": 14, "platformUrl": ""}'::jsonb)
on conflict (key) do nothing;

create table if not exists public.platform_signups (
  id               uuid primary key default gen_random_uuid(),
  created_at       timestamptz not null default now(),
  organisation     text not null check (char_length(organisation) between 2 and 120),
  contact_name     text not null check (char_length(contact_name) between 2 and 100),
  email            text not null check (char_length(email) <= 150),
  phone            text not null check (char_length(phone) <= 20),
  city             text check (char_length(city) <= 80),
  plan             text not null,
  trial_days       int not null,
  slug             text not null,
  code             text not null,
  status           text not null default 'pending' check (status in ('pending', 'created', 'rejected', 'expired')),
  hospital_id      uuid references public.tenants (id) on delete set null,
  terms_version    text not null check (char_length(terms_version) between 1 and 20),
  ip_hash          text,
  decided_at       timestamptz,
  decided_by       uuid,
  decided_by_name  text,
  reason           text check (char_length(reason) <= 300)
);
create index if not exists platform_signups_status_idx on public.platform_signups (status, created_at desc);
create index if not exists platform_signups_email_idx on public.platform_signups (lower(email));
alter table public.platform_signups enable row level security;
revoke all on public.platform_signups from anon, authenticated;
grant all on public.platform_signups to service_role;

create or replace function public.signup_config()
returns jsonb language sql stable security definer set search_path = public as $$
  select '{"enabled": true, "mode": "approve", "trialDays": 14, "plan": "clinic", "maxPerDay": 25, "unclaimedDays": 14, "platformUrl": ""}'::jsonb
      || coalesce((select data from public.platform_settings where key = 'signup'), '{}'::jsonb)
$$;

-- what the sign-up page needs to know (anyone)
create or replace function public.platform_signup_info()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare c jsonb := public.signup_config(); b jsonb := public.billing_config();
begin
  return jsonb_build_object('enabled', coalesce((c ->> 'enabled')::boolean, false), 'mode', c ->> 'mode',
    'trialDays', (c ->> 'trialDays')::int, 'plan', c ->> 'plan',
    'plans', coalesce((select jsonb_agg(k order by (b -> 'plans' -> k ->> 'monthly')::numeric nulls last) from jsonb_object_keys(b -> 'plans') k), '[]'::jsonb));
end $$;

-- a free short name for the hospital, from its name: "City Care Clinic" → citycareclinic, citycareclinic-2, …
create or replace function public.signup_slug(p_name text)
returns text language plpgsql stable security definer set search_path = public as $$
declare
  base text := left(trim(both '-' from regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', '', 'g')), 30);
  s    text;
  i    int := 1;
begin
  if char_length(base) < 3 then base := 'hospital'; end if;
  s := base;
  while s in ('main', 'www', 'app', 'api', 'admin', 'demo', 'mail', 'help', 'status', 'signup', 'legal', 'controlpanel')
     or exists (select 1 from public.tenants where slug = s)
     or exists (select 1 from public.platform_signups where slug = s and status = 'pending') loop
    i := i + 1;
    s := base || '-' || i;
  end loop;
  return s;
end $$;

-- record prefix from the initials: City Care Clinic → CCC, Apollo → APO
create or replace function public.signup_code(p_name text)
returns text language plpgsql immutable as $$
declare clean text := upper(regexp_replace(coalesce(p_name, ''), '[^A-Za-z ]', ' ', 'g')); v text;
begin
  select string_agg(left(w, 1), '') into v from regexp_split_to_table(trim(clean), '\s+') w where w <> '' and w not in ('THE', 'AND', 'OF', 'PVT', 'LTD');
  if char_length(coalesce(v, '')) < 2 then v := left(replace(clean, ' ', ''), 3); end if;
  v := left(coalesce(v, ''), 6);
  return case when char_length(v) >= 2 then v else 'HC' end;
end $$;

-- turns a sign-up request into a hospital (internal) and writes the welcome e-mail
create or replace function public.signup_activate(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare s public.platform_signups; r jsonb;
begin
  select * into s from public.platform_signups where id = p_id for update;
  if not found or s.status <> 'pending' then raise exception 'This sign-up was already handled.'; end if;
  if exists (select 1 from public.tenants where slug = s.slug) then
    update public.platform_signups set slug = public.signup_slug(s.organisation) where id = p_id returning * into s;
  end if;
  r := public.hospital_create(jsonb_build_object('slug', s.slug, 'name', s.organisation, 'code', s.code, 'plan', s.plan,
         'owner_email', s.email, 'status', 'trial', 'trial_days', s.trial_days,
         'notes', 'Self-service sign-up · ' || s.contact_name || ' · ' || s.phone || coalesce(' · ' || nullif(s.city, ''), '') || ' · Terms ' || s.terms_version));
  update public.platform_signups set status = 'created', hospital_id = (r ->> 'id')::uuid where id = p_id;
  -- welcome e-mail (Hospital Comrade messaging; best effort — the sign-up page shows the same link)
  perform set_config('app.tenant_id', r ->> 'id', true);
  perform public.notify_enqueue_raw('signup_welcome',
    jsonb_build_object('subject', 'Your free trial of {hospital} is ready',
      'text', 'Namaste {name}, {hospital} is ready — free for {days} days. Create your owner account with this e-mail ({email}) here: {link} . After that, invite your team from Users & Roles. Reply to this e-mail if you need help.'),
    array['email'], s.phone, s.email, null,
    jsonb_build_object('name', split_part(regexp_replace(s.contact_name, '^(dr|mr|mrs|ms|shri|smt)\.?\s+', '', 'i'), ' ', 1),
      'hospital', s.organisation, 'days', s.trial_days, 'email', s.email, 'link', rtrim(coalesce(public.signup_config() ->> 'platformUrl', ''), '/') || '/register?hospital=' || s.slug),
    'tenants', (r ->> 'id')::uuid, null);
  return r;
end $$;

-- the public sign-up form
--   { organisation, name, email, phone, city?, plan?, terms_version, website? (honeypot — must stay empty) }
create or replace function public.platform_trial_signup(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c       jsonb := public.signup_config();
  b       jsonb := public.billing_config();
  v_org   text := trim(regexp_replace(coalesce(p ->> 'organisation', ''), '\s+', ' ', 'g'));
  v_name  text := trim(regexp_replace(coalesce(p ->> 'name', ''), '\s+', ' ', 'g'));
  v_mail  text := lower(trim(coalesce(p ->> 'email', '')));
  v_phone text := right(regexp_replace(coalesce(p ->> 'phone', ''), '\D', '', 'g'), 10);
  v_city  text := nullif(left(trim(coalesce(p ->> 'city', '')), 80), '');
  v_plan  text := coalesce(nullif(p ->> 'plan', ''), c ->> 'plan', 'clinic');
  v_terms text := trim(coalesce(p ->> 'terms_version', ''));
  v_ip    text;
  v_hash  text;
  v_id    uuid;
  v_slug  text;
  r       jsonb;
begin
  if not coalesce((c ->> 'enabled')::boolean, false) then raise exception 'Online sign-up is closed right now — please use the contact form and we will set you up.'; end if;
  if coalesce(p ->> 'website', '') <> '' then raise exception 'Could not sign up.'; end if;
  if char_length(v_org) not between 2 and 120 then raise exception 'Enter your hospital or clinic''s name.'; end if;
  if char_length(v_name) not between 2 and 100 then raise exception 'Enter your name.'; end if;
  if v_mail !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]{2,}$' or char_length(v_mail) > 150 then raise exception 'Enter a valid e-mail — you will sign in with it.'; end if;
  if v_phone !~ '^[6-9][0-9]{9}$' then raise exception 'Enter a 10-digit Indian mobile number.'; end if;
  if v_terms = '' or char_length(v_terms) > 20 then raise exception 'Please accept the Terms of Service and the Data Processing Agreement.'; end if;
  if not (b -> 'plans' ? v_plan) then v_plan := coalesce(c ->> 'plan', 'clinic'); end if;

  -- one account = one hospital
  if exists (select 1 from public.profiles where lower(email) = v_mail and tenant_id is not null and role <> 'patient')
     or exists (select 1 from public.provider_users u join auth.users a on a.id = u.user_id where lower(a.email) = v_mail)
     or exists (select 1 from public.app_settings s where s.key = 'bootstrap' and lower(s.data ->> 'owner_email') = v_mail) then
    raise exception 'This e-mail already belongs to a hospital here — sign in there, or use another e-mail.';
  end if;
  if exists (select 1 from public.platform_signups where lower(email) = v_mail and status = 'pending') then
    raise exception 'We already have a request from this e-mail — we will be in touch soon.';
  end if;

  -- rate limits: per address, per phone, per day for everyone
  begin
    v_ip := nullif(trim(split_part(coalesce(nullif(current_setting('request.headers', true), '')::json ->> 'cf-connecting-ip',
                                         nullif(current_setting('request.headers', true), '')::json ->> 'x-forwarded-for', ''), ',', 1)), '');
  exception when others then v_ip := null; end;
  v_hash := case when v_ip is null then null else md5('hc-signup:' || v_ip) end;
  if v_hash is not null and (select count(*) from public.platform_signups where ip_hash = v_hash and created_at > now() - interval '1 day') >= 3 then
    raise exception 'Too many sign-ups from your network today — please try tomorrow or use the contact form.';
  end if;
  if (select count(*) from public.platform_signups where phone = v_phone and created_at > now() - interval '1 day') >= 2 then
    raise exception 'Too many sign-ups with this mobile number today — please use the contact form.';
  end if;
  if (select count(*) from public.platform_signups where created_at > now() - interval '1 day') >= greatest(coalesce((c ->> 'maxPerDay')::int, 25), 1) then
    raise exception 'We are getting a lot of sign-ups today — please leave your details in the contact form and we will set you up.';
  end if;

  v_slug := public.signup_slug(v_org);
  insert into public.platform_signups (organisation, contact_name, email, phone, city, plan, trial_days, slug, code, terms_version, ip_hash)
  values (v_org, v_name, v_mail, v_phone, v_city, v_plan, greatest(1, least(90, coalesce((c ->> 'trialDays')::int, 14))), v_slug, public.signup_code(v_org), v_terms, v_hash)
  returning id into v_id;

  if c ->> 'mode' = 'instant' then
    r := public.signup_activate(v_id);
    return jsonb_build_object('status', 'created', 'slug', r ->> 'slug', 'email', v_mail, 'trial_days', greatest(1, least(90, coalesce((c ->> 'trialDays')::int, 14))));
  end if;
  return jsonb_build_object('status', 'pending', 'email', v_mail);
end $$;

-- ------------------------------------------------------------------ control panel
create or replace function public.cp_signups(p_status text default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return coalesce((select jsonb_agg(to_jsonb(s) - 'ip_hash' || jsonb_build_object(
      'hospital_slug', t.slug,
      'owner_joined', exists (select 1 from public.profiles p where p.tenant_id = s.hospital_id and p.role = 'owner'))
      order by (s.status = 'pending') desc, s.created_at desc)
    from (select * from public.platform_signups where p_status is null or status = p_status order by created_at desc limit 300) s
    left join public.tenants t on t.id = s.hospital_id), '[]'::jsonb);
end $$;

-- approve (creates the hospital) or reject a pending request
create or replace function public.cp_signup_decide(p_id uuid, p_action text, p_reason text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare s public.platform_signups; r jsonb;
begin
  perform public.cp_require(array['admin']);
  select * into s from public.platform_signups where id = p_id for update;
  if not found then raise exception 'Sign-up not found'; end if;
  if s.status <> 'pending' then raise exception 'This sign-up was already handled.'; end if;
  if p_action = 'approve' then
    r := public.signup_activate(p_id);
    perform set_config('app.tenant_id', '', true);
  elsif p_action = 'reject' then
    update public.platform_signups set status = 'rejected', reason = nullif(left(trim(coalesce(p_reason, '')), 300), '') where id = p_id;
  else
    raise exception 'Unknown action %', p_action;
  end if;
  update public.platform_signups set decided_at = now(), decided_by = auth.uid(), decided_by_name = (select full_name from public.profiles where id = auth.uid()) where id = p_id;
  perform public.provider_log('signup:' || p_action, s.organisation, jsonb_build_object('email', s.email, 'slug', r ->> 'slug', 'reason', p_reason));
  return (select to_jsonb(x) - 'ip_hash' from public.platform_signups x where x.id = p_id);
end $$;

create or replace function public.cp_signup_settings()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return public.signup_config() || jsonb_build_object('pending', (select count(*) from public.platform_signups where status = 'pending'));
end $$;

create or replace function public.cp_save_signup_settings(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare k text; v jsonb := coalesce(p, '{}'::jsonb);
begin
  perform public.cp_require(array['admin']);
  for k in select jsonb_object_keys(v) loop
    if k not in ('enabled', 'mode', 'trialDays', 'plan', 'maxPerDay', 'unclaimedDays', 'platformUrl') then raise exception 'Unknown setting %', k; end if;
  end loop;
  if v ? 'enabled' and jsonb_typeof(v -> 'enabled') <> 'boolean' then raise exception 'enabled: true or false'; end if;
  if v ? 'mode' and v ->> 'mode' not in ('instant', 'approve') then raise exception 'Mode: instant or approve.'; end if;
  if v ? 'trialDays' and coalesce((v ->> 'trialDays')::int, 0) not between 1 and 90 then raise exception 'Trial: 1 to 90 days.'; end if;
  if v ? 'plan' and not (public.billing_config() -> 'plans' ? (v ->> 'plan')) then raise exception 'Unknown plan %', v ->> 'plan'; end if;
  if v ? 'maxPerDay' and coalesce((v ->> 'maxPerDay')::int, 0) not between 1 and 1000 then raise exception 'Sign-ups per day: 1 to 1000.'; end if;
  if v ? 'platformUrl' and coalesce(v ->> 'platformUrl', '') !~ '^(https://[a-z0-9.-]+(:[0-9]+)?/?)?$' then raise exception 'Website: https://your-domain (or leave empty).'; end if;
  if v ? 'unclaimedDays' and coalesce((v ->> 'unclaimedDays')::int, 0) not between 3 and 90 then raise exception 'Unclaimed trials: close after 3 to 90 days.'; end if;
  update public.platform_settings set data = data || v, updated_at = now() where key = 'signup';
  perform public.provider_log('settings:signup', null, v);
  return public.cp_signup_settings();
end $$;

-- nightly (run_retention): expire old requests, close hospitals nobody claimed
create or replace function public.signup_cleanup()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare c jsonb := public.signup_config(); n_exp bigint; n_close bigint := 0; r record;
begin
  update public.platform_signups set status = 'expired', reason = 'No decision within 30 days' where status = 'pending' and created_at < now() - interval '30 days';
  get diagnostics n_exp = row_count;
  for r in select s.id, s.hospital_id from public.platform_signups s join public.tenants t on t.id = s.hospital_id
            where s.status = 'created' and t.closing_at is null and not t.is_primary and t.paid_until is null
              and s.created_at < now() - make_interval(days => greatest(coalesce((c ->> 'unclaimedDays')::int, 14), 3))
              and not exists (select 1 from public.profiles p where p.tenant_id = s.hospital_id and p.role = 'owner') loop
    update public.tenants set closing_at = now(), purge_after = now() + interval '7 days', close_reason = 'Unclaimed free trial (self-service sign-up)', updated_at = now() where id = r.hospital_id;
    update public.platform_signups set status = 'expired', reason = 'Owner never signed up' where id = r.id;
    n_close := n_close + 1;
  end loop;
  delete from public.platform_signups where status in ('rejected', 'expired') and hospital_id is null
     and created_at < now() - make_interval(days => greatest(coalesce((public.retention_config() ->> 'leadDays')::int, 1095), 30));
  return jsonb_build_object('expired', n_exp, 'closed', n_close);
end $$;

revoke all on function public.signup_config(), public.signup_slug(text), public.signup_activate(uuid), public.signup_cleanup() from public, anon, authenticated;
revoke all on function public.platform_signup_info(), public.platform_trial_signup(jsonb) from public;
grant execute on function public.platform_signup_info(), public.platform_trial_signup(jsonb) to anon, authenticated;
revoke all on function public.cp_signups(text), public.cp_signup_decide(uuid, text, text), public.cp_signup_settings(), public.cp_save_signup_settings(jsonb) from public, anon;
grant execute on function public.cp_signups(text), public.cp_signup_decide(uuid, text, text), public.cp_signup_settings(), public.cp_save_signup_settings(jsonb) to authenticated;
grant execute on function public.signup_cleanup() to service_role;


-- =====================================================================================================
--  PHASE 8.3 — LAUNCH CHECK (control panel → System health → Launch checklist)
-- =====================================================================================================
--  cp_launch_check() looks at what the database can see and answers ok / warn / fail per item:
--  demo logins left over, platform admins, seller details on invoices, scheduled jobs, row-level security on every
--  table, the nightly clean-up, sign-up settings, failing messages. Things outside the database (Razorpay live keys,
--  SMTP, backups, DNS) are listed by the panel as manual checks — see docs/GO_LIVE.md.
-- =====================================================================================================

create or replace function public.cp_launch_check()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  out     jsonb := '[]'::jsonb;
  b       jsonb := public.billing_config();
  s       jsonb := public.signup_config();
  v_cron  boolean := exists (select 1 from pg_extension where extname = 'pg_cron');
  v_jobs  text[] := '{}';
  v_miss  text[];
  v_list  text;
  v_n     bigint;
  v_m     bigint;
  v_at    timestamptz;
begin
  perform public.cp_require(array['admin']);

  -- 1. sample logins (master.sql) must not exist on a live platform
  select string_agg(email, ', ' order by email), count(*) into v_list, v_n from auth.users
   where lower(email) like '%@dchospital.com' or lower(email) like '%@citycare.demo' or lower(email) like '%@hospitalcomrade.demo';
  out := out || jsonb_build_object('id', 'demo_logins', 'title', 'No demo logins', 'status', case when v_n = 0 then 'ok' else 'fail' end,
    'detail', case when v_n = 0 then 'No sample accounts (Demo@123) exist.' else v_n || ' sample account(s) with the public password Demo@123: ' || left(v_list, 300) || ' — install with production.sql or delete them.' end);

  -- 2. the City Care sample hospital
  select count(*) into v_n from public.tenants where id = 'b0000000-0000-4000-8000-000000000002';
  out := out || jsonb_build_object('id', 'demo_hospital', 'title', 'No sample hospital', 'status', case when v_n = 0 then 'ok' else 'warn' end,
    'detail', case when v_n = 0 then 'The City Care sample clinic is not installed.' else 'The City Care sample clinic is installed — close and delete it before you invite customers.' end);

  -- 3. platform admins (two, so nobody gets locked out)
  select count(*) into v_n from public.provider_users where active and role = 'admin';
  out := out || jsonb_build_object('id', 'admins', 'title', 'Platform admins', 'status', case when v_n >= 2 then 'ok' when v_n = 1 then 'warn' else 'fail' end,
    'detail', case when v_n >= 2 then v_n || ' active admins.' when v_n = 1 then 'Only one admin — add a second one (Team) so the platform is never locked out.' else 'No active admin.' end);

  -- 4. seller details printed on every invoice
  v_miss := array_remove(array[
    case when coalesce(b -> 'seller' ->> 'name', '') = '' then 'legal name' end,
    case when coalesce(b -> 'seller' ->> 'gstin', '') = '' then 'GSTIN' end,
    case when coalesce(b -> 'seller' ->> 'address', '') = '' then 'address' end,
    case when coalesce(b -> 'seller' ->> 'email', '') = '' then 'e-mail' end], null);
  out := out || jsonb_build_object('id', 'seller', 'title', 'Invoice details (seller)', 'status', case when cardinality(v_miss) = 0 then 'ok' else 'fail' end,
    'detail', case when cardinality(v_miss) = 0 then 'Printed on invoices as ' || (b -> 'seller' ->> 'name') || ', GSTIN ' || (b -> 'seller' ->> 'gstin') || '.'
                   else 'Missing: ' || array_to_string(v_miss, ', ') || ' — Platform settings → Seller.' end);

  -- 5. scheduled jobs (reminders, message delivery, nightly clean-up)
  if v_cron then
    execute $q$ select coalesce(array_agg(jobname::text), '{}') from cron.job where active and jobname like 'dch-%' $q$ into v_jobs;
  end if;
  v_miss := array(select j from unnest(array['dch-notify-flush', 'dch-appointment-reminders', 'dch-billing-reminders', 'dch-retention']) j where not (j = any (v_jobs)));
  out := out || jsonb_build_object('id', 'jobs', 'title', 'Scheduled jobs', 'status', case when not v_cron then 'fail' when cardinality(v_miss) = 0 then 'ok' else 'fail' end,
    'detail', case when not v_cron then 'pg_cron is not enabled (Supabase → Database → Extensions).'
                   when cardinality(v_miss) = 0 then 'Message delivery, reminders and the nightly clean-up are scheduled.'
                   else 'Not scheduled: ' || array_to_string(v_miss, ', ') || ' — switch automatic delivery off and on once in the main hospital''s Settings → Notifications.' end);

  -- 6. pg_net (the database calls the notify / billing functions)
  out := out || jsonb_build_object('id', 'pg_net', 'title', 'Outgoing calls (pg_net)', 'status', case when exists (select 1 from pg_extension where extname = 'pg_net') then 'ok' else 'fail' end,
    'detail', case when exists (select 1 from pg_extension where extname = 'pg_net') then 'Enabled.' else 'Enable pg_net (Supabase → Database → Extensions) — messages are not delivered without it.' end);

  -- 7. row-level security on every table
  select string_agg(c.relname, ', ' order by c.relname), count(*) into v_list, v_n from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind = 'r' and not c.relrowsecurity;
  out := out || jsonb_build_object('id', 'rls', 'title', 'Row-level security', 'status', case when v_n = 0 then 'ok' else 'fail' end,
    'detail', case when v_n = 0 then 'Every table is protected.' else 'Without RLS: ' || left(v_list, 300) end);

  -- 8. every per-hospital table keeps hospitals apart
  select string_agg(c.table_name, ', ' order by c.table_name), count(*) into v_list, v_n from information_schema.columns c
    join information_schema.tables t on t.table_schema = c.table_schema and t.table_name = c.table_name and t.table_type = 'BASE TABLE'
   where c.table_schema = 'public' and c.column_name = 'tenant_id' and c.table_name not in ('tenants', 'tenant_domains', 'provider_audit', 'provider_assignments')
     and not exists (select 1 from pg_policies p where p.schemaname = 'public' and p.tablename = c.table_name and p.policyname = 'tenant_isolation');
  out := out || jsonb_build_object('id', 'isolation', 'title', 'Hospital isolation', 'status', case when v_n = 0 then 'ok' else 'fail' end,
    'detail', case when v_n = 0 then 'Every per-hospital table has the tenant_isolation policy.' else 'Missing tenant_isolation: ' || left(v_list, 300) || ' — run supabase/upgrade-2026-10.sql again.' end);

  -- 9. nightly clean-up actually ran
  v_at := (public.retention_config() -> 'last_run' ->> 'at')::timestamptz;
  out := out || jsonb_build_object('id', 'retention', 'title', 'Nightly clean-up', 'status', case when v_at > now() - interval '2 days' then 'ok' else 'warn' end,
    'detail', case when v_at is null then 'Has never run yet — it runs at 03:00 IST once jobs are scheduled.' when v_at > now() - interval '2 days' then 'Last ran ' || to_char(v_at at time zone 'Asia/Kolkata', 'DD Mon HH24:MI') || ' IST.'
                   else 'Last ran ' || to_char(v_at at time zone 'Asia/Kolkata', 'DD Mon YYYY') || ' — check System health → Scheduled jobs.' end);

  -- 10. free-trial sign-up
  out := out || jsonb_build_object('id', 'signup', 'title', 'Free-trial sign-up', 'status',
      case when not coalesce((s ->> 'enabled')::boolean, false) then 'ok' when coalesce(s ->> 'platformUrl', '') = '' then 'warn' else 'ok' end,
    'detail', case when not coalesce((s ->> 'enabled')::boolean, false) then 'Closed — people use the contact form.'
                   when coalesce(s ->> 'platformUrl', '') = '' then 'Open, but the product website address is empty — the welcome e-mail''s link will be relative. Set it in Sign-ups.'
                   else 'Open (' || case when s ->> 'mode' = 'instant' then 'created instantly' else 'reviewed first' end || ', ' || (s ->> 'trialDays') || ' days).' end);

  -- 11. messages failing in the last 24 hours
  select count(*) filter (where status = 'failed'), count(*) into v_n, v_m from public.notification_outbox where created_at > now() - interval '24 hours';
  out := out || jsonb_build_object('id', 'messages', 'title', 'Messages delivered', 'status', case when v_m = 0 or v_n * 5 <= v_m then 'ok' else 'warn' end,
    'detail', case when v_m = 0 then 'No messages in the last 24 hours.' else v_n || ' of ' || v_m || ' failed in the last 24 hours' || case when v_n * 5 > v_m then ' — see System health → Recent failures.' else '.' end end);

  -- 12. the platform's own hospital has its owner
  select count(*) into v_n from public.profiles p join public.tenants t on t.id = p.tenant_id where t.is_primary and p.role = 'owner';
  out := out || jsonb_build_object('id', 'primary_owner', 'title', 'Main hospital owner', 'status', case when v_n > 0 then 'ok' else 'warn' end,
    'detail', case when v_n > 0 then 'The main hospital has an owner account.' else 'Nobody has signed up as the main hospital''s owner yet (the bootstrap e-mail in production.sql).' end);

  return jsonb_build_object('at', now(), 'checks', out);
end $$;

revoke all on function public.cp_launch_check() from public, anon;
grant execute on function public.cp_launch_check() to authenticated;


-- =====================================================================================================
--  DATA INTEGRITY (production audit, October 2026)
--  The database — not the browser — guarantees the money and bed rules, so a stale tab, a second receptionist
--  or a hand-made API call cannot leave the books or the ward wrong. Idempotent: safe in master / production /
--  upgrade. Checked by tests/sql/integrity.test.ts.
--
--   1. same hospital   every reference (patient_id, bed_id, invoice_id …) points at a row of the SAME hospital
--   2. invoices        subtotal / total are recomputed from the line items; amount paid always = sum of payments;
--                      paid / partial / overdue derived; no cancelling a bill that has payments
--   3. payments        never more than the balance due; never on a draft / cancelled bill (row-locked, so two
--                      counters recording at once cannot overpay)
--   4. admissions      one admitted patient per bed, one live admission per patient, only into a free bed;
--                      discharge date stamped
--   5. beds            an occupied bed cannot be freed / deleted while its patient is admitted
--   6. lab tests       completion date stamped
-- =====================================================================================================

-- ------------------------------------------------------------------ 1. references stay inside one hospital
-- RLS checks a row's own tenant_id; this checks the rows it points at. Without it a user of hospital A who knew an id
-- of hospital B could attach B's bed / invoice / doctor to A's rows (and definer triggers would then update B's rows).
create or replace function public.enforce_same_tenant()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  i int := 0;
  v_col text; v_parent text; v_ref text; v_parent_tenant uuid;
  n jsonb := to_jsonb(new);
  o jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) end;
begin
  while i < tg_nargs loop
    v_col := tg_argv[i]; v_parent := tg_argv[i + 1]; i := i + 2;
    v_ref := n ->> v_col;
    continue when v_ref is null;
    continue when tg_op = 'UPDATE' and v_ref is not distinct from (o ->> v_col) and (n ->> 'tenant_id') is not distinct from (o ->> 'tenant_id');
    execute format('select tenant_id from public.%I where id = $1', v_parent) into v_parent_tenant using v_ref::uuid;
    -- a parent without a hospital (a platform team member's profile) may be referenced from anywhere
    if v_parent_tenant is not null and v_parent_tenant is distinct from (n ->> 'tenant_id')::uuid then
      raise exception 'The selected % belongs to another hospital.', replace(regexp_replace(v_col, '_id$', ''), '_', ' ')
        using errcode = '42501';
    end if;
  end loop;
  return new;
end $$;
revoke execute on function public.enforce_same_tenant() from public, anon, authenticated;

-- one trigger per table, built from the foreign keys themselves (single-column FKs to `id` of a table that also has
-- tenant_id) — new tables are covered the next time this file runs
do $same$
declare r record;
begin
  for r in
    select c.conrelid::regclass::text as child,
           string_agg(format('%L, %L', a.attname, p.relname), ', ' order by a.attname) as args
      from pg_constraint c
      join pg_class ch on ch.oid = c.conrelid
      join pg_namespace ns on ns.oid = ch.relnamespace and ns.nspname = 'public'
      join pg_class p on p.oid = c.confrelid
      join pg_namespace pns on pns.oid = p.relnamespace and pns.nspname = 'public'
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
      join pg_attribute pa on pa.attrelid = c.confrelid and pa.attnum = c.confkey[1] and pa.attname = 'id'
     where c.contype = 'f' and array_length(c.conkey, 1) = 1 and c.conrelid <> c.confrelid
       and exists (select 1 from pg_attribute x where x.attrelid = c.conrelid and x.attname = 'tenant_id' and not x.attisdropped)
       and exists (select 1 from pg_attribute x where x.attrelid = c.confrelid and x.attname = 'tenant_id' and not x.attisdropped)
       and a.attname <> 'tenant_id'
     group by c.conrelid
  loop
    execute format('drop trigger if exists trg_zz_same_tenant on %s', r.child);
    -- "zz": runs after the other BEFORE triggers, so tenant_id / stamped columns are final
    execute format('create trigger trg_zz_same_tenant before insert or update on %s for each row execute function public.enforce_same_tenant(%s)', r.child, r.args);
  end loop;
end $same$;

-- ------------------------------------------------------------------ 2. invoices: totals from the line items
create or replace function public.invoices_integrity()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  it jsonb; q numeric; p numeric;
  v_sub numeric := 0;
  v_paid numeric := 0;
begin
  if jsonb_typeof(coalesce(new.items, '[]'::jsonb)) <> 'array' then
    raise exception 'Invoice items must be a list.' using errcode = '22023';
  end if;
  for it in select value from jsonb_array_elements(coalesce(new.items, '[]'::jsonb)) loop
    begin
      q := coalesce(nullif(it ->> 'quantity', '')::numeric, 0);
      p := coalesce(nullif(it ->> 'unit_price', '')::numeric, 0);
    exception when others then
      raise exception 'Every line item needs a number for quantity and price.' using errcode = '22023';
    end;
    if q <= 0 then raise exception 'Every line item needs a quantity above 0.' using errcode = '23514'; end if;
    if p < 0 then raise exception 'Line item prices cannot be negative.' using errcode = '23514'; end if;
    v_sub := v_sub + q * p;
  end loop;

  new.subtotal := round(v_sub, 2);
  new.discount := round(coalesce(new.discount, 0), 2);
  new.tax := round(coalesce(new.tax, 0), 2);
  if new.discount < 0 or new.tax < 0 then raise exception 'Discount and tax cannot be negative.' using errcode = '23514'; end if;
  if new.discount > new.subtotal + new.tax then raise exception 'The discount is larger than the bill.' using errcode = '23514'; end if;
  new.total := new.subtotal - new.discount + new.tax;

  -- amount paid is never typed in: it is the sum of the payments
  if tg_op = 'UPDATE' then select coalesce(sum(amount), 0) into v_paid from public.payments where invoice_id = new.id; end if;
  new.amount_paid := v_paid;
  if v_paid > 0 and new.status in ('draft', 'cancelled') then
    raise exception 'This invoice already has payments (₹%). Delete those payments before making it %.', v_paid, new.status
      using errcode = '23514';
  end if;
  if v_paid > new.total + 0.005 then
    raise exception 'The total (₹%) cannot be less than what has already been paid (₹%).', new.total, v_paid using errcode = '23514';
  end if;
  new.status := case
    when new.status in ('draft', 'cancelled') then new.status
    when new.total > 0 and v_paid >= new.total then 'paid'
    when v_paid > 0 then 'partial'
    when new.due_date is not null and new.due_date < public.today_ist() then 'overdue'
    else 'unpaid' end;
  return new;
end $$;
revoke execute on function public.invoices_integrity() from public, anon, authenticated;
drop trigger if exists trg_invoices_integrity on public.invoices;
create trigger trg_invoices_integrity before insert or update on public.invoices
  for each row execute function public.invoices_integrity();

-- ------------------------------------------------------------------ 3. payments: never more than the balance
create or replace function public.payments_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare inv record; v_other numeric;
begin
  -- the row lock serialises two payments on the same bill (two counters, a double click)
  select id, invoice_number, total, status, tenant_id into inv from public.invoices where id = new.invoice_id for update;
  if not found then raise exception 'Invoice not found' using errcode = '23503'; end if;
  if inv.status in ('draft', 'cancelled') then
    raise exception 'Invoice % is %. Payments can only be recorded on issued invoices.', inv.invoice_number, inv.status using errcode = '23514';
  end if;
  select coalesce(sum(amount), 0) into v_other from public.payments where invoice_id = new.invoice_id and id is distinct from new.id;
  if v_other + new.amount > inv.total + 0.005 then
    raise exception 'This payment (₹%) is more than the balance due on % (₹%).', new.amount, inv.invoice_number, greatest(inv.total - v_other, 0)
      using errcode = '23514';
  end if;
  return new;
end $$;
revoke execute on function public.payments_guard() from public, anon, authenticated;
drop trigger if exists trg_payments_guard on public.payments;
create trigger trg_payments_guard before insert or update of amount, invoice_id on public.payments
  for each row execute function public.payments_guard();

-- ------------------------------------------------------------------ 4. admissions: one patient per bed
create or replace function public.admissions_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare b record;
begin
  if new.status = 'discharged' and new.discharge_date is null then new.discharge_date := greatest(public.today_ist(), new.admission_date); end if;
  if new.status = 'admitted' then new.discharge_date := null; end if;
  if new.status = 'admitted' and new.bed_id is not null
     and (tg_op = 'INSERT' or old.status <> 'admitted' or old.bed_id is distinct from new.bed_id) then
    select bed_number, status into b from public.beds where id = new.bed_id for update;
    if found and b.status not in ('available', 'reserved') then
      raise exception 'Bed % is %. Choose an available bed.', b.bed_number,
        case b.status when 'occupied' then 'already occupied' else 'under maintenance' end using errcode = '23514';
    end if;
  end if;
  if new.status = 'admitted' and exists (select 1 from public.admissions a where a.patient_id = new.patient_id and a.status = 'admitted' and a.id <> new.id) then
    raise exception 'This patient is already admitted. Discharge or transfer the current admission instead.' using errcode = '23505';
  end if;
  return new;
end $$;
revoke execute on function public.admissions_guard() from public, anon, authenticated;
drop trigger if exists trg_admissions_guard on public.admissions;
create trigger trg_admissions_guard before insert or update on public.admissions
  for each row execute function public.admissions_guard();

-- bed + patient status follow the admissions (replaces the 5d version: a patient with another live admission keeps
-- "inpatient", and deleting an admission without a bed resets the patient too)
create or replace function public.sync_admission()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_patient uuid := case when tg_op = 'DELETE' then old.patient_id else new.patient_id end;
begin
  if tg_op = 'DELETE' then
    if old.status = 'admitted' and old.bed_id is not null then
      update public.beds set status = 'available' where id = old.bed_id and status = 'occupied';
    end if;
  else
    if tg_op = 'UPDATE' and old.bed_id is distinct from new.bed_id and old.bed_id is not null then
      update public.beds set status = 'available' where id = old.bed_id and status = 'occupied';
    end if;
    if new.bed_id is not null then
      update public.beds set status = case when new.status = 'admitted' then 'occupied' else 'available' end
       where id = new.bed_id and status is distinct from (case when new.status = 'admitted' then 'occupied' else 'available' end);
    end if;
  end if;
  update public.patients set status = case
      when exists (select 1 from public.admissions a where a.patient_id = v_patient and a.status = 'admitted') then 'inpatient'
      when tg_op = 'DELETE' then 'outpatient'
      else 'discharged' end
   where id = v_patient;
  return case when tg_op = 'DELETE' then old else new end;
end $$;

-- the uniqueness itself (also catches two inserts racing past the trigger). An existing database with duplicates
-- keeps working — the warning tells the hospital what to fix — and the index arrives on the next run.
do $idx$
begin
  if exists (select 1 from public.admissions where status = 'admitted' and bed_id is not null group by bed_id having count(*) > 1) then
    raise warning 'Some beds have two admitted patients — discharge or move one, then run this file again (index admissions_one_per_bed).';
  else
    create unique index if not exists admissions_one_per_bed on public.admissions (bed_id) where status = 'admitted' and bed_id is not null;
  end if;
  if exists (select 1 from public.admissions where status = 'admitted' group by patient_id having count(*) > 1) then
    raise warning 'Some patients have two live admissions — discharge one, then run this file again (index admissions_one_per_patient).';
  else
    create unique index if not exists admissions_one_per_patient on public.admissions (patient_id) where status = 'admitted';
  end if;
end $idx$;

-- ------------------------------------------------------------------ 5. beds follow their patient
create or replace function public.beds_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_id uuid := case when tg_op = 'DELETE' then old.id else new.id end;
        v_busy boolean;
begin
  select exists (select 1 from public.admissions where bed_id = v_id and status = 'admitted') into v_busy;
  if tg_op = 'DELETE' then
    -- restrict_violation: a hospital purge retries children-first (admissions go, then the beds)
    if v_busy then raise exception 'Bed % has an admitted patient. Discharge or transfer them first.', old.bed_number using errcode = '23001'; end if;
    return old;
  end if;
  if new.status is distinct from old.status then
    if new.status <> 'occupied' and v_busy then
      raise exception 'Bed % has an admitted patient. Discharge or transfer them first.', new.bed_number using errcode = '23514';
    end if;
    if new.status = 'occupied' and not v_busy then
      raise exception 'A bed becomes occupied when a patient is admitted to it (Admissions).' using errcode = '23514';
    end if;
  end if;
  return new;
end $$;
revoke execute on function public.beds_guard() from public, anon, authenticated;
drop trigger if exists trg_beds_guard on public.beds;
create trigger trg_beds_guard before update of status or delete on public.beds
  for each row execute function public.beds_guard();

-- ------------------------------------------------------------------ 6. lab tests: completion date
create or replace function public.lab_tests_stamp()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.status = 'completed' and new.completed_on is null then new.completed_on := public.today_ist(); end if;
  if new.status <> 'completed' then new.completed_on := null; end if;
  return new;
end $$;
revoke execute on function public.lab_tests_stamp() from public, anon, authenticated;
drop trigger if exists trg_lab_tests_stamp on public.lab_tests;
create trigger trg_lab_tests_stamp before insert or update of status, completed_on on public.lab_tests
  for each row execute function public.lab_tests_stamp();

-- ------------------------------------------------------------------ 7. a hospital always keeps an owner
-- admin_update_user() / admin_delete_user() already say no; this also covers a direct API call (PATCH / DELETE
-- on profiles). The platform team (closing / purging a hospital) and the SQL editor are not limited.
create or replace function public.profiles_keep_owner()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.provider_role() is not null then return coalesce(new, old); end if;
  if old.role <> 'owner' or (tg_op = 'UPDATE' and new.role = 'owner') then return coalesce(new, old); end if;
  if tg_op = 'UPDATE' and old.id = auth.uid() then
    raise exception 'You can''t remove your own owner access. Ask another owner to do it.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles p where p.role = 'owner' and p.id <> old.id and p.tenant_id is not distinct from old.tenant_id) then
    raise exception 'This is the last owner of the hospital. Make someone else an owner first.' using errcode = '42501';
  end if;
  return coalesce(new, old);
end $$;
drop trigger if exists trg_profiles_keep_owner on public.profiles;
create trigger trg_profiles_keep_owner before update of role or delete on public.profiles
  for each row execute function public.profiles_keep_owner();
revoke all on function public.profiles_keep_owner() from public, anon, authenticated;


-- =====================================================================================================
--  CONTROL PANEL — HOSPITAL OPERATIONS (A–F + sign in as user)
-- =====================================================================================================
-- What the Hospital Comrade team can do *for* a hospital from the control panel, without opening it:
--   A  details (website contact, legal / GST details, logo), owner transfer, resend the owner's invite
--   B  the hospital's user accounts (list, change role, block, invite, remove — last-owner rule kept)
--   C  record counts, read-only lists (patients / doctors / appointments / bills), CSV import of patients / doctors
--   D  messaging channels on/off and a monthly cap on the shared (platform) accounts
--   E  wallet history and GST credit notes against paid Hospital Comrade invoices
--   F  announcements shown inside the hospital app
--   +  "sign in as user" (admins only, reason required, 30 minutes, banner, everything logged)
--
-- Roles: admin — everything · support — their assigned hospitals, no money and no deleting · finance — billing only.
-- Each function pins the hospital first (cp_pin) so the existing per-hospital rules, triggers and provider_log apply
-- exactly as when the team member opens the hospital app.

-- ------------------------------------------------------------------ helper
-- check the role + assignment and work "inside" the hospital for the rest of this transaction
create or replace function public.cp_pin(p_id uuid, p_roles text[] default array['admin', 'support', 'finance'])
returns text language plpgsql volatile security definer set search_path = public as $$
declare r text := public.cp_require(p_roles);
begin
  if p_id is null or not exists (select 1 from public.tenants where id = p_id) then raise exception 'Hospital not found.'; end if;
  if not public.provider_can(p_id) then raise exception 'This hospital is not assigned to you.' using errcode = '42501'; end if;
  perform set_config('app.tenant_id', p_id::text, true);
  return r;
end $$;

-- ------------------------------------------------------------------ A · details
create or replace function public.cp_hospital_profile(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants; s jsonb;
begin
  perform public.cp_pin(p_id);
  select * into t from public.tenants where id = p_id;
  s := coalesce(public.tenant_content('settings'), '{}'::jsonb);
  return jsonb_build_object(
    'name', coalesce(nullif(s ->> 'name', ''), t.name),
    'tagline', coalesce(s ->> 'tagline', ''),
    'address', coalesce(s ->> 'address', ''),
    'phone', coalesce(s ->> 'phone', ''),
    'appointmentsPhone', coalesce(s ->> 'appointmentsPhone', ''),
    'whatsapp', coalesce(s ->> 'whatsapp', ''),
    'email', coalesce(s ->> 'email', ''),
    'logoUrl', coalesce(s -> 'brand' ->> 'logoUrl', ''),
    'legalName', coalesce(t.billing ->> 'legalName', ''),
    'gstin', coalesce(t.billing ->> 'gstin', ''),
    'pan', coalesce(t.billing ->> 'pan', ''),
    'billingAddress', coalesce(t.billing ->> 'address', ''));
end $$;

create or replace function public.cp_save_hospital_profile(p_id uuid, p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  t      public.tenants;
  k      text;
  v      text;
  s      jsonb;
  site   jsonb := '{}'::jsonb;
  bill   jsonb := '{}'::jsonb;
  lens   jsonb := '{"name":120,"tagline":160,"address":300,"phone":20,"appointmentsPhone":20,"whatsapp":20,"email":120,
                   "logoUrl":500,"legalName":150,"gstin":15,"pan":10,"billingAddress":300}';
begin
  perform public.cp_pin(p_id, array['admin', 'support']);
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'Nothing to save.'; end if;
  for k, v in select key, trim(coalesce(value, '')) from jsonb_each_text(p) loop
    if not lens ? k then raise exception 'Unknown field "%".', k; end if;
    if char_length(v) > (lens ->> k)::int then raise exception '% is too long (at most % characters).', k, lens ->> k; end if;
    if k = 'name' and char_length(v) < 2 then raise exception 'Enter the hospital name.'; end if;
    if k in ('phone', 'appointmentsPhone', 'whatsapp') and v <> '' and regexp_replace(v, '\D', '', 'g') !~ '^[0-9]{10,13}$' then
      raise exception 'Enter a valid phone number (10 digits, optional +91).';
    end if;
    if k = 'email' and v <> '' and v !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Enter a valid e-mail address.'; end if;
    if k = 'logoUrl' and v <> '' and v !~* '^https://[^\s]+$' then raise exception 'The logo must be an https:// link to an image.'; end if;
    if k = 'gstin' then
      v := upper(regexp_replace(v, '\s', '', 'g'));
      if v <> '' and v !~ '^[0-9]{2}[A-Z0-9]{10}[0-9A-Z]Z[0-9A-Z]$' then raise exception 'That GSTIN does not look right (15 characters, e.g. 10ABCDE1234F1Z5).'; end if;
    end if;
    if k = 'pan' then
      v := upper(regexp_replace(v, '\s', '', 'g'));
      if v <> '' and v !~ '^[A-Z]{5}[0-9]{4}[A-Z]$' then raise exception 'That PAN does not look right (e.g. ABCDE1234F).'; end if;
    end if;
    if k in ('legalName', 'gstin', 'pan') then bill := bill || jsonb_build_object(k, v);
    elsif k = 'billingAddress' then bill := bill || jsonb_build_object('address', v);
    else site := site || jsonb_build_object(k, v);
    end if;
  end loop;

  if site <> '{}'::jsonb then
    s := coalesce(public.tenant_content('settings'), '{}'::jsonb);
    if site ? 'logoUrl' then
      s := jsonb_set(s, '{brand}', coalesce(s -> 'brand', '{}'::jsonb) || jsonb_build_object('logoUrl', site ->> 'logoUrl'), true);
      site := site - 'logoUrl';
    end if;
    s := s || site;
    insert into public.site_content (tenant_id, key, data) values (p_id, 'settings', s)
    on conflict (tenant_id, key) do update set data = excluded.data;
    if site ? 'name' then update public.tenants set name = site ->> 'name' where id = p_id; end if;
  end if;
  if bill <> '{}'::jsonb then update public.tenants set billing = billing || bill where id = p_id; end if;

  select * into t from public.tenants where id = p_id;
  perform public.provider_log('hospital:profile', t.slug, p);
  return public.cp_hospital_profile(p_id);
end $$;

-- make another staff account the owner; the current owner(s) become p_old_role (or stay owners)
create or replace function public.cp_transfer_owner(p_id uuid, p_user uuid, p_old_role text default 'staff')
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v public.profiles; v_slug text;
begin
  perform public.cp_pin(p_id, array['admin']);
  if coalesce(p_old_role, '') not in ('owner', 'doctor', 'receptionist', 'accountant', 'staff') then
    raise exception 'Choose what the current owner becomes.';
  end if;
  select * into v from public.profiles where id = p_user and tenant_id = p_id;
  if not found then raise exception 'That user is not in this hospital.'; end if;
  if v.role = 'patient' then raise exception 'A patient account can’t become the owner — invite them as staff first.'; end if;
  if exists (select 1 from public.provider_users where user_id = p_user) then raise exception 'A Hospital Comrade team account can’t own a hospital.'; end if;
  if v.role = 'owner' and p_old_role = 'owner' then raise exception '% is already an owner.', v.full_name; end if;

  update public.profiles set role = 'owner' where id = p_user;              -- promote first: a hospital always keeps an owner
  if p_old_role <> 'owner' then
    update public.profiles set role = p_old_role::public.app_role where tenant_id = p_id and role = 'owner' and id <> p_user;
  end if;
  insert into public.app_settings (tenant_id, key, data) values (p_id, 'bootstrap', jsonb_build_object('owner_email', lower(v.email)))
  on conflict (tenant_id, key) do update set data = public.app_settings.data || excluded.data;

  select slug into v_slug from public.tenants where id = p_id;
  perform public.provider_log('hospital:owner', v_slug, jsonb_build_object('new_owner', v.email, 'previous_owner_becomes', p_old_role));
  return jsonb_build_object('owner', v.email);
end $$;

-- e-mail the owner their sign-up link again (only while nobody has signed up as owner)
create or replace function public.cp_resend_owner_invite(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants; v_email text; v_path text; v_base text; v_link text; n int := 0;
begin
  perform public.cp_pin(p_id, array['admin', 'support']);
  select * into t from public.tenants where id = p_id;
  if exists (select 1 from public.profiles where tenant_id = p_id and role = 'owner') then
    raise exception 'The owner has already signed up — use “Send password reset” in Users instead.';
  end if;
  select lower(data ->> 'owner_email') into v_email from public.app_settings where tenant_id = p_id and key = 'bootstrap';
  if coalesce(v_email, '') = '' or v_email = 'owner@your-hospital.in' then raise exception 'Set the owner’s e-mail first (Settings → Details).'; end if;
  v_path := '/register?hospital=' || t.slug;
  v_base := rtrim(coalesce(public.signup_config() ->> 'platformUrl', ''), '/');
  if v_base <> '' then
    v_link := v_base || v_path;
    n := public.notify_enqueue_raw('owner_invite',
      jsonb_build_object('subject', 'Your {hospital} account is ready',
        'text', 'Namaste! {hospital} is ready on {platform}. Create the owner account with this e-mail ({email}) here: {link}'),
      array['email'], null, v_email, null,
      jsonb_build_object('email', v_email, 'link', v_link, 'platform', coalesce(nullif(public.billing_config() -> 'seller' ->> 'name', ''), 'Hospital Comrade')),
      'tenants', p_id);
  end if;
  perform public.provider_log('hospital:owner_invite', t.slug, jsonb_build_object('email', v_email, 'queued', n));
  return jsonb_build_object('email', v_email, 'path', v_path, 'link', v_link, 'queued', n);
end $$;

-- ------------------------------------------------------------------ B · users
create or replace function public.cp_hospital_users(p_id uuid, p_search text default null, p_role text default null,
  p_offset int default 0, p_limit int default 50)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare q text := nullif(lower(trim(coalesce(p_search, ''))), ''); r text := nullif(p_role, ''); v_total int; v_rows jsonb; v_inv jsonb;
begin
  perform public.cp_pin(p_id, array['admin', 'support']);
  select count(*) into v_total from public.profiles p
   where p.tenant_id = p_id
     and (r is null or (r = 'staff_all' and p.role <> 'patient') or p.role::text = r)
     and (q is null or strpos(lower(p.full_name), q) > 0 or strpos(lower(coalesce(p.email, '')), q) > 0 or strpos(coalesce(p.phone, ''), q) > 0);
  select coalesce(jsonb_agg(to_jsonb(x) - 'ord' order by x.ord), '[]'::jsonb) into v_rows from (
    select p.id, p.full_name, p.email, p.phone, p.role::text as role, p.created_at,
           (u.banned_until is not null and u.banned_until > now()) as blocked,
           to_jsonb(u) ->> 'last_sign_in_at' as last_sign_in_at,
           row_number() over (order by (p.role = 'patient'), p.role, lower(p.full_name)) as ord
      from public.profiles p left join auth.users u on u.id = p.id
     where p.tenant_id = p_id
       and (r is null or (r = 'staff_all' and p.role <> 'patient') or p.role::text = r)
       and (q is null or strpos(lower(p.full_name), q) > 0 or strpos(lower(coalesce(p.email, '')), q) > 0 or strpos(coalesce(p.phone, ''), q) > 0)
     order by (p.role = 'patient'), p.role, lower(p.full_name)
     offset greatest(coalesce(p_offset, 0), 0) limit least(greatest(coalesce(p_limit, 50), 1), 200)) x;
  select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'full_name', i.full_name, 'email', i.email, 'phone', i.phone, 'role', i.role,
           'token', i.token, 'expires_at', i.expires_at, 'created_at', i.created_at) order by i.created_at desc), '[]'::jsonb)
    into v_inv from public.staff_invites i where i.tenant_id = p_id and i.status = 'pending' and i.expires_at > now();
  return jsonb_build_object('total', v_total, 'rows', v_rows, 'invites', v_inv);
end $$;

-- create | update | disable | enable | delete | invite | revoke_invite | password_reset (the e-mail itself is sent by Supabase Auth)
create or replace function public.cp_user_action(p_id uuid, p_action text, p_user uuid default null, p jsonb default '{}'::jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v public.profiles; v_new uuid; v_inv uuid; v_tok text; p_ jsonb := coalesce(p, '{}'::jsonb);
begin
  perform public.cp_pin(p_id, case when p_action = 'delete' then array['admin'] else array['admin', 'support'] end);
  if p_action in ('update', 'disable', 'enable', 'delete', 'password_reset') then
    select * into v from public.profiles where id = p_user and tenant_id = p_id;
    if not found then raise exception 'That user is not in this hospital.'; end if;
  end if;
  case p_action
    when 'create' then
      v_new := public.admin_create_user(p_ ->> 'email', p_ ->> 'full_name', p_ ->> 'role', nullif(p_ ->> 'phone', ''), null);
    when 'update' then
      perform public.admin_update_user(p_user, coalesce(p_ ->> 'full_name', v.full_name), coalesce(p_ ->> 'role', v.role::text),
                                       case when p_ ? 'phone' then nullif(p_ ->> 'phone', '') else v.phone end, coalesce(p_ ->> 'email', v.email));
    when 'disable' then perform public.admin_set_user_active(p_user, false);
    when 'enable' then perform public.admin_set_user_active(p_user, true);
    when 'delete' then perform public.admin_delete_user(p_user);
    when 'invite' then
      if coalesce(p_ ->> 'role', '') not in ('owner', 'doctor', 'receptionist', 'accountant', 'staff') then raise exception 'Choose a staff role.'; end if;
      insert into public.staff_invites (full_name, email, phone, role)
      values (trim(coalesce(p_ ->> 'full_name', '')), trim(coalesce(p_ ->> 'email', '')), nullif(trim(coalesce(p_ ->> 'phone', '')), ''), (p_ ->> 'role')::public.app_role)
      returning id, token into v_inv, v_tok;
    when 'revoke_invite' then
      update public.staff_invites set status = 'revoked', updated_at = now()
       where id = nullif(p_ ->> 'invite_id', '')::uuid and tenant_id = p_id and status = 'pending';
      if not found then raise exception 'That invitation is no longer pending.'; end if;
    when 'password_reset' then null;
    else raise exception 'Unknown action "%".', p_action;
  end case;
  perform public.provider_log('user:' || p_action, coalesce(v.email, p_ ->> 'email', p_ ->> 'invite_id'), p_ - 'password');
  return jsonb_build_object('ok', true, 'user_id', coalesce(v_new, p_user), 'email', coalesce(v.email, lower(p_ ->> 'email')), 'invite_id', v_inv, 'token', v_tok);
end $$;

-- ------------------------------------------------------------------ C · data
create or replace function public.cp_hospital_data(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare c jsonb := '{}'::jsonb; t text; n bigint; v_today date := (now() at time zone 'Asia/Kolkata')::date;
begin
  perform public.cp_pin(p_id);
  foreach t in array array['patients', 'doctors', 'staff', 'departments', 'appointments', 'prescriptions', 'lab_tests', 'admissions',
                           'wards', 'beds', 'invoices', 'payments', 'expenses', 'inventory', 'notices', 'site_enquiries', 'visit_feedback',
                           'doctor_leaves', 'holidays', 'audit_log'] loop
    continue when to_regclass('public.' || t) is null;
    execute format('select count(*) from public.%I where tenant_id = $1', t) into n using p_id;
    c := c || jsonb_build_object(t, n);
  end loop;
  return jsonb_build_object('counts', c,
    'users', (select count(*) from public.profiles where tenant_id = p_id and role <> 'patient'),
    'appointments_30d', (select count(*) from public.appointments where tenant_id = p_id and appointment_date > v_today - 30),
    'admitted_now', (select count(*) from public.admissions where tenant_id = p_id and status = 'admitted'),
    'billed_30d', (select coalesce(sum(total), 0) from public.invoices where tenant_id = p_id and issue_date > v_today - 30 and status not in ('draft', 'cancelled')),
    'outstanding', (select coalesce(sum(total - amount_paid), 0) from public.invoices where tenant_id = p_id and status in ('unpaid', 'partial', 'overdue')),
    'last_activity', (select max(created_at) from public.audit_log where tenant_id = p_id));
end $$;

-- read-only lists; every look is logged. finance sees bills only.
create or replace function public.cp_browse(p_id uuid, p_kind text, p_search text default null, p_offset int default 0, p_limit int default 25)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_role text := public.cp_pin(p_id);
  q      text := nullif(lower(trim(coalesce(p_search, ''))), '');
  lim    int  := least(greatest(coalesce(p_limit, 25), 1), 100);
  off    int  := greatest(coalesce(p_offset, 0), 0);
  v_total int;
  v_rows jsonb;
begin
  if v_role = 'finance' and p_kind <> 'invoices' then raise exception 'Finance can look at bills only.' using errcode = '42501'; end if;
  if p_kind = 'patients' then
    select count(*) into v_total from public.patients p where p.tenant_id = p_id
       and (q is null or strpos(lower(p.full_name), q) > 0 or strpos(lower(coalesce(p.mrn, '')), q) > 0 or strpos(coalesce(p.phone, ''), q) > 0);
    select coalesce(jsonb_agg(to_jsonb(x) - 'ord' order by x.ord), '[]'::jsonb) into v_rows from (
      select p.id, p.mrn, p.full_name, p.gender, p.date_of_birth, p.phone, p.created_at, row_number() over (order by p.created_at desc, p.id) ord
        from public.patients p where p.tenant_id = p_id
         and (q is null or strpos(lower(p.full_name), q) > 0 or strpos(lower(coalesce(p.mrn, '')), q) > 0 or strpos(coalesce(p.phone, ''), q) > 0)
       order by p.created_at desc, p.id offset off limit lim) x;
  elsif p_kind = 'doctors' then
    select count(*) into v_total from public.doctors d where d.tenant_id = p_id
       and (q is null or strpos(lower(d.full_name), q) > 0 or strpos(lower(coalesce(d.specialization, '')), q) > 0);
    select coalesce(jsonb_agg(to_jsonb(x) - 'ord' order by x.ord), '[]'::jsonb) into v_rows from (
      select d.id, d.full_name, d.specialization, d.phone, d.email, d.consultation_fee, d.status, dp.name as department,
             row_number() over (order by lower(d.full_name), d.id) ord
        from public.doctors d left join public.departments dp on dp.id = d.department_id
       where d.tenant_id = p_id
         and (q is null or strpos(lower(d.full_name), q) > 0 or strpos(lower(coalesce(d.specialization, '')), q) > 0)
       order by lower(d.full_name), d.id offset off limit lim) x;
  elsif p_kind = 'appointments' then
    select count(*) into v_total from public.appointments a
      left join public.patients pt on pt.id = a.patient_id left join public.doctors d on d.id = a.doctor_id
     where a.tenant_id = p_id and (q is null or strpos(lower(coalesce(pt.full_name, '')), q) > 0 or strpos(lower(coalesce(d.full_name, '')), q) > 0);
    select coalesce(jsonb_agg(to_jsonb(x) - 'ord' order by x.ord), '[]'::jsonb) into v_rows from (
      select a.id, a.appointment_date, a.appointment_time, a.status, a.type, pt.full_name as patient, d.full_name as doctor,
             row_number() over (order by a.appointment_date desc, a.appointment_time desc, a.id) ord
        from public.appointments a
        left join public.patients pt on pt.id = a.patient_id left join public.doctors d on d.id = a.doctor_id
       where a.tenant_id = p_id and (q is null or strpos(lower(coalesce(pt.full_name, '')), q) > 0 or strpos(lower(coalesce(d.full_name, '')), q) > 0)
       order by a.appointment_date desc, a.appointment_time desc, a.id offset off limit lim) x;
  elsif p_kind = 'invoices' then
    select count(*) into v_total from public.invoices i left join public.patients pt on pt.id = i.patient_id
     where i.tenant_id = p_id and (q is null or strpos(lower(i.invoice_number), q) > 0 or strpos(lower(coalesce(pt.full_name, '')), q) > 0);
    select coalesce(jsonb_agg(to_jsonb(x) - 'ord' order by x.ord), '[]'::jsonb) into v_rows from (
      select i.id, i.invoice_number, i.issue_date, i.total, i.amount_paid, i.status, pt.full_name as patient,
             row_number() over (order by i.issue_date desc, i.created_at desc, i.id) ord
        from public.invoices i left join public.patients pt on pt.id = i.patient_id
       where i.tenant_id = p_id and (q is null or strpos(lower(i.invoice_number), q) > 0 or strpos(lower(coalesce(pt.full_name, '')), q) > 0)
       order by i.issue_date desc, i.created_at desc, i.id offset off limit lim) x;
  else
    raise exception 'Unknown list "%".', p_kind;
  end if;
  perform public.provider_log('data:browse', p_kind, jsonb_build_object('search', q, 'offset', off));
  return jsonb_build_object('total', v_total, 'rows', v_rows);
end $$;

-- CSV import (rows already parsed by the panel). Every row is checked on its own; a bad row never stops the rest.
-- Duplicates (same name + phone for patients, same name + speciality for doctors) are skipped.
create or replace function public.cp_import(p_id uuid, p_kind text, p_rows jsonb, p_dry_run boolean default false)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  x jsonb; i int := 0; ok int := 0; dup int := 0; errs jsonb := '[]'::jsonb; nerr int := 0;
  v_name text; v_phone text; v_email text; v_g text; v_dob date; v_bg text; v_dept uuid; v_fee numeric; v_exp int; v_spec text; v_raw text;
begin
  perform public.cp_pin(p_id, array['admin']);
  if p_kind not in ('patients', 'doctors') then raise exception 'You can import patients or doctors.'; end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then raise exception 'Nothing to import.'; end if;
  if jsonb_array_length(p_rows) > 1000 then raise exception 'Import at most 1,000 rows at a time — split the file.'; end if;

  for x in select value from jsonb_array_elements(p_rows) loop
    i := i + 1;
    begin
      if jsonb_typeof(x) <> 'object' then raise exception 'not a row'; end if;
      v_name := trim(regexp_replace(coalesce(x ->> 'full_name', ''), '\s+', ' ', 'g'));
      if char_length(v_name) < 2 then raise exception 'name is missing'; end if;
      if char_length(v_name) > 120 then raise exception 'name is too long'; end if;
      v_raw := regexp_replace(coalesce(x ->> 'phone', ''), '\D', '', 'g');
      v_phone := nullif(right(v_raw, 10), '');
      if v_phone is not null and v_phone !~ '^[6-9][0-9]{9}$' then raise exception 'phone "%" is not a 10-digit mobile number', x ->> 'phone'; end if;
      v_email := nullif(lower(trim(coalesce(x ->> 'email', ''))), '');
      if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'e-mail "%" is not valid', v_email; end if;

      if p_kind = 'patients' then
        v_g := case lower(left(trim(coalesce(x ->> 'gender', '')), 1)) when 'm' then 'male' when 'f' then 'female' else 'other' end;
        v_dob := null;
        if coalesce(trim(x ->> 'date_of_birth'), '') <> '' then
          begin v_dob := (trim(x ->> 'date_of_birth'))::date;
          exception when others then raise exception 'date of birth "%" — use YYYY-MM-DD', x ->> 'date_of_birth'; end;
          if v_dob > current_date or v_dob < date '1900-01-01' then raise exception 'date of birth % is not possible', v_dob; end if;
        end if;
        v_bg := nullif(upper(replace(trim(coalesce(x ->> 'blood_group', '')), ' ', '')), '');
        if v_bg is not null and v_bg not in ('A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-') then raise exception 'blood group "%" is not valid', v_bg; end if;
        if exists (select 1 from public.patients where tenant_id = p_id and lower(full_name) = lower(v_name) and coalesce(phone, '') = coalesce(v_phone, '')) then
          dup := dup + 1; continue;
        end if;
        if not p_dry_run then
          insert into public.patients (full_name, gender, date_of_birth, blood_group, phone, email, address)
          values (v_name, v_g, v_dob, v_bg, v_phone, v_email, nullif(left(trim(coalesce(x ->> 'address', '')), 300), ''));
        end if;
      else
        v_spec := trim(coalesce(x ->> 'specialization', ''));
        if char_length(v_spec) < 2 then raise exception 'specialization is missing'; end if;
        v_fee := 0;
        if coalesce(trim(x ->> 'consultation_fee'), '') <> '' then
          begin v_fee := replace(trim(x ->> 'consultation_fee'), ',', '')::numeric;
          exception when others then raise exception 'fee "%" is not a number', x ->> 'consultation_fee'; end;
          if v_fee < 0 or v_fee > 100000 then raise exception 'fee % is not possible', v_fee; end if;
        end if;
        v_exp := 0;
        if coalesce(trim(x ->> 'experience_years'), '') <> '' then
          begin v_exp := trim(x ->> 'experience_years')::int;
          exception when others then raise exception 'experience "%" is not a whole number', x ->> 'experience_years'; end;
          if v_exp < 0 or v_exp > 70 then raise exception 'experience % is not possible', v_exp; end if;
        end if;
        v_dept := null;
        if coalesce(trim(x ->> 'department'), '') <> '' then
          select id into v_dept from public.departments where tenant_id = p_id and lower(name) = lower(trim(x ->> 'department')) limit 1;
          if v_dept is null then raise exception 'department "%" does not exist in this hospital', trim(x ->> 'department'); end if;
        end if;
        if exists (select 1 from public.doctors where tenant_id = p_id and lower(full_name) = lower(v_name) and lower(coalesce(specialization, '')) = lower(v_spec)) then
          dup := dup + 1; continue;
        end if;
        if not p_dry_run then
          insert into public.doctors (full_name, specialization, qualification, phone, email, experience_years, consultation_fee, department_id, available_days)
          values (v_name, v_spec, nullif(left(trim(coalesce(x ->> 'qualification', '')), 200), ''), v_phone, v_email, v_exp, v_fee, v_dept,
                  array['Mon', 'Tue', 'Wed', 'Thu', 'Fri']);
        end if;
      end if;
      ok := ok + 1;
    exception when others then
      nerr := nerr + 1;
      if nerr <= 200 then errs := errs || jsonb_build_object('row', i, 'error', sqlerrm); end if;
    end;
  end loop;
  if not p_dry_run then
    perform public.provider_log('data:import', p_kind, jsonb_build_object('imported', ok, 'duplicates', dup, 'failed', nerr));
  end if;
  return jsonb_build_object('dry_run', coalesce(p_dry_run, false), 'imported', ok, 'duplicates', dup, 'failed', nerr, 'errors', errs);
end $$;

-- ------------------------------------------------------------------ D · messaging
create or replace function public.cp_messaging(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants; n jsonb; cfg jsonb := public.billing_config(); v_month date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
begin
  perform public.cp_pin(p_id);
  select * into t from public.tenants where id = p_id;
  n := coalesce(public.tenant_setting('app') -> 'notifications', '{}'::jsonb);
  return jsonb_build_object(
    'channels', (select jsonb_object_agg(ch, jsonb_build_object('enabled', coalesce((n -> ch ->> 'enabled')::boolean, false),
                                                                'source', coalesce(n -> ch ->> 'source', 'own')))
                   from unnest(array['sms', 'whatsapp', 'email']) ch),
    'monthlyLimit', coalesce(t.billing -> 'monthlyLimit', '{}'::jsonb),
    'included', coalesce(t.billing -> 'included', cfg -> 'plans' -> t.plan -> 'included', '{}'::jsonb),
    'usage', coalesce((select jsonb_object_agg(u.channel || ':' || u.source, jsonb_build_object('sent', u.sent, 'failed', u.failed))
                         from public.message_usage u where u.tenant_id = p_id and u.month = v_month), '{}'::jsonb),
    'pending', coalesce((select jsonb_object_agg(o.channel, o.n) from (select channel, count(*) n from public.notification_outbox
                          where tenant_id = p_id and status in ('pending', 'sending') group by channel) o), '{}'::jsonb),
    'wallet_paise', t.wallet_paise,
    'is_primary', t.is_primary);
end $$;

-- { channels?: { sms|whatsapp|email: { enabled?, source?: own|platform } }, monthlyLimit?: { sms|whatsapp|email: int | null } }
create or replace function public.cp_save_messaging(p_id uuid, p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare d jsonb; ch text; v jsonb; k text; lim jsonb; v_slug text;
begin
  perform public.cp_pin(p_id, array['admin']);
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'Nothing to save.'; end if;
  for k in select jsonb_object_keys(p) loop
    if k not in ('channels', 'monthlyLimit') then raise exception 'Unknown field "%".', k; end if;
  end loop;
  if p ? 'channels' then
    d := coalesce(public.tenant_setting('app'), '{}'::jsonb);
    if jsonb_typeof(coalesce(d -> 'notifications', 'null')) <> 'object' then d := jsonb_set(d, '{notifications}', '{}'::jsonb, true); end if;
    for ch, v in select key, value from jsonb_each(p -> 'channels') loop
      if ch not in ('sms', 'whatsapp', 'email') then raise exception 'Unknown channel "%".', ch; end if;
      if exists (select 1 from jsonb_object_keys(v) kk where kk not in ('enabled', 'source')) then raise exception 'Unknown setting for %.', ch; end if;
      if v ? 'source' and v ->> 'source' not in ('own', 'platform') then raise exception 'Source must be own or platform.'; end if;
      d := jsonb_set(d, array['notifications', ch], coalesce(d -> 'notifications' -> ch, '{}'::jsonb)
             || jsonb_strip_nulls(jsonb_build_object('enabled', (v ->> 'enabled')::boolean, 'source', v ->> 'source')), true);
    end loop;
    insert into public.app_settings (tenant_id, key, data) values (p_id, 'app', d)
    on conflict (tenant_id, key) do update set data = excluded.data;
  end if;
  if p ? 'monthlyLimit' then
    lim := '{}'::jsonb;
    for ch, v in select key, value from jsonb_each(p -> 'monthlyLimit') loop
      if ch not in ('sms', 'whatsapp', 'email') then raise exception 'Unknown channel "%".', ch; end if;
      continue when v is null or v = 'null'::jsonb;
      if jsonb_typeof(v) <> 'number' or (v #>> '{}')::numeric <> trunc((v #>> '{}')::numeric) or (v #>> '{}')::numeric not between 0 and 1000000 then
        raise exception 'The % limit must be a whole number between 0 and 10,00,000 (blank = no limit).', ch;
      end if;
      lim := lim || jsonb_build_object(ch, (v #>> '{}')::int);
    end loop;
    update public.tenants set billing = case when lim = '{}'::jsonb then billing - 'monthlyLimit' else billing || jsonb_build_object('monthlyLimit', lim) end
     where id = p_id;
  end if;
  select slug into v_slug from public.tenants where id = p_id;
  perform public.provider_log('hospital:messaging', v_slug, p);
  return public.cp_messaging(p_id);
end $$;

-- ------------------------------------------------------------------ E · wallet history + credit notes
create sequence if not exists public.billing_credit_note_seq;
create table if not exists public.billing_credit_notes (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null default public.current_tenant() references public.tenants (id) on delete cascade,
  payment_id       uuid not null references public.billing_payments (id) on delete cascade,
  credit_no        text not null unique,
  created_at       timestamptz not null default now(),
  base_paise       bigint not null check (base_paise >= 0),
  gst_paise        bigint not null default 0 check (gst_paise >= 0),
  total_paise      bigint not null check (total_paise > 0),
  mode             text not null check (mode in ('wallet', 'refund')),
  reason           text not null check (char_length(reason) between 5 and 300),
  seller           jsonb,
  buyer            jsonb not null default '{}'::jsonb,
  created_by       uuid,
  created_by_name  text
);
create index if not exists billing_credit_notes_tenant_idx on public.billing_credit_notes (tenant_id, created_at desc);
create index if not exists billing_credit_notes_payment_idx on public.billing_credit_notes (payment_id);
alter table public.billing_credit_notes enable row level security;
revoke all on public.billing_credit_notes from anon, authenticated;
grant select on public.billing_credit_notes to authenticated;
grant all on public.billing_credit_notes to service_role;
drop policy if exists tenant_isolation on public.billing_credit_notes;
create policy tenant_isolation on public.billing_credit_notes as restrictive for all to anon, authenticated
  using (tenant_id = (select public.current_tenant())) with check (tenant_id = (select public.current_tenant()));
drop policy if exists billing_read on public.billing_credit_notes;
create policy billing_read on public.billing_credit_notes for select to authenticated using (public.has_role('owner', 'accountant'));
drop trigger if exists trg_keep_tenant on public.billing_credit_notes;
create trigger trg_keep_tenant before update of tenant_id on public.billing_credit_notes for each row execute function public.keep_tenant();
-- (integrity.sql builds this from the foreign keys on its next run; here so a fresh install matches)
drop trigger if exists trg_zz_same_tenant on public.billing_credit_notes;
create trigger trg_zz_same_tenant before insert or update on public.billing_credit_notes
  for each row execute function public.enforce_same_tenant('payment_id', 'billing_payments');

create or replace function public.cp_wallet_ledger(p_id uuid, p_limit int default 200)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.cp_pin(p_id, array['admin', 'finance']);
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (
    select l.id, l.created_at, l.day, l.kind, l.channel, l.units, l.amount_paise, l.balance_paise, l.note, b.invoice_no
      from public.wallet_ledger l left join public.billing_payments b on b.id = l.payment
     where l.tenant_id = p_id order by l.created_at desc limit least(greatest(coalesce(p_limit, 200), 1), 1000)) x), '[]'::jsonb);
end $$;

create or replace function public.cp_credit_notes(p_tenant uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin', 'finance']);
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (
    select c.*, b.invoice_no, b.kind, b.plan, b.months, b.total_paise as invoice_total_paise, b.paid_at as invoice_date, t.name as hospital
      from public.billing_credit_notes c join public.billing_payments b on b.id = c.payment_id join public.tenants t on t.id = c.tenant_id
     where (p_tenant is null or c.tenant_id = p_tenant) and public.provider_can(c.tenant_id)
     order by c.created_at desc limit 500) x), '[]'::jsonb);
end $$;

-- { amount?: ₹ incl. GST (blank = everything left), reason, mode: wallet (credit the hospital's wallet) | refund (money paid back) }
create or replace function public.cp_credit_note(p_payment uuid, p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  bp       public.billing_payments;
  p_       jsonb := coalesce(p, '{}'::jsonb);
  v_mode   text := coalesce(nullif(p_ ->> 'mode', ''), 'wallet');
  v_reason text := trim(coalesce(p_ ->> 'reason', ''));
  v_left   bigint;
  v_total  bigint;
  v_gst    bigint;
  v_base   bigint;
  v_wallet bigint;
  v_d      date := (now() at time zone 'Asia/Kolkata')::date;
  v_fy     text;
  v_no     text;
  r        public.billing_credit_notes;
begin
  perform public.cp_require(array['admin', 'finance']);
  select * into bp from public.billing_payments where id = p_payment for update;
  if not found or not public.provider_can(bp.tenant_id) then raise exception 'Invoice not found.' using errcode = '42501'; end if;
  perform set_config('app.tenant_id', bp.tenant_id::text, true);
  if bp.status <> 'paid' or bp.invoice_no is null then raise exception 'Only a paid invoice can get a credit note.'; end if;
  if v_mode not in ('wallet', 'refund') then raise exception 'Choose wallet credit or refund.'; end if;
  if v_mode = 'wallet' and bp.kind = 'wallet' then raise exception 'A wallet top-up can only be refunded (the money is already in the wallet).'; end if;
  if char_length(v_reason) < 5 then raise exception 'Write the reason (at least 5 characters) — it is printed on the credit note.'; end if;

  v_left := bp.total_paise - coalesce((select sum(total_paise) from public.billing_credit_notes where payment_id = bp.id), 0);
  if nullif(trim(coalesce(p_ ->> 'amount', '')), '') is null then v_total := v_left;
  else v_total := round((p_ ->> 'amount')::numeric * 100)::bigint;
  end if;
  if v_total is null or v_total < 100 or v_total > v_left then
    raise exception 'The credit must be between ₹1 and ₹% (what is left on this invoice).', to_char(v_left / 100.0, 'FM99999990.00');
  end if;
  v_gst := case when bp.total_paise = 0 then 0 else round(v_total::numeric * bp.gst_paise / bp.total_paise)::bigint end;
  v_base := v_total - v_gst;

  if v_mode = 'refund' and bp.kind = 'wallet' then        -- money back for a top-up: the credit (before GST) leaves the wallet
    select wallet_paise into v_wallet from public.tenants where id = bp.tenant_id for update;
    if v_wallet < v_base then raise exception 'The wallet has only ₹% left — refund at most that much (before GST).', to_char(v_wallet / 100.0, 'FM99999990.00'); end if;
  end if;

  v_fy := case when extract(month from v_d) >= 4 then to_char(v_d, 'YYYY') || '-' || to_char(v_d + interval '1 year', 'YY')
               else to_char(v_d - interval '1 year', 'YYYY') || '-' || to_char(v_d, 'YY') end;
  v_no := 'HC-CN/' || v_fy || '/' || lpad(nextval('public.billing_credit_note_seq')::text, 5, '0');
  insert into public.billing_credit_notes (tenant_id, payment_id, credit_no, base_paise, gst_paise, total_paise, mode, reason, seller, buyer, created_by, created_by_name)
  values (bp.tenant_id, bp.id, v_no, v_base, v_gst, v_total, v_mode, v_reason, coalesce(bp.seller, public.billing_config() -> 'seller'),
          coalesce(bp.buyer, '{}'::jsonb), auth.uid(), (select full_name from public.profiles where id = auth.uid()))
  returning * into r;

  if v_mode = 'wallet' then
    perform public.wallet_apply(bp.tenant_id, 'refund', v_total, bp.id, 'Credit note ' || v_no || ' — ' || v_reason);
  elsif bp.kind = 'wallet' then
    perform public.wallet_apply(bp.tenant_id, 'refund', -v_base, bp.id, 'Refund, credit note ' || v_no);
  end if;
  if v_left - v_total = 0 then update public.billing_payments set status = 'refunded' where id = bp.id; end if;

  perform public.provider_log('billing:credit_note', bp.invoice_no,
    jsonb_build_object('credit_no', v_no, 'total_paise', v_total, 'mode', v_mode, 'reason', v_reason));
  return to_jsonb(r) || jsonb_build_object('invoice_no', bp.invoice_no, 'invoice_date', bp.paid_at, 'kind', bp.kind, 'plan', bp.plan, 'months', bp.months);
end $$;

-- ------------------------------------------------------------------ F · announcements
create table if not exists public.platform_announcements (
  id               uuid primary key default gen_random_uuid(),
  title            text not null check (char_length(title) between 3 and 120),
  body             text not null default '' check (char_length(body) <= 1000),
  level            text not null default 'info' check (level in ('info', 'warning', 'critical')),
  hospital_ids     uuid[],                                   -- null = every hospital
  roles            text[] not null default array['owner'],   -- which hospital roles see it
  starts_at        timestamptz not null default now(),
  ends_at          timestamptz,
  active           boolean not null default true,
  created_by       uuid,
  created_by_name  text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  check (ends_at is null or ends_at > starts_at)
);
alter table public.platform_announcements enable row level security;
revoke all on public.platform_announcements from anon, authenticated;
grant all on public.platform_announcements to service_role;

create or replace function public.cp_announcements()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin', 'support']);
  return coalesce((select jsonb_agg(to_jsonb(a) || jsonb_build_object(
      'hospitals', (select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name) order by t.name), '[]'::jsonb) from public.tenants t where t.id = any (a.hospital_ids)),
      'live', a.active and a.starts_at <= now() and (a.ends_at is null or a.ends_at > now()))
    order by a.created_at desc) from public.platform_announcements a), '[]'::jsonb);
end $$;

create or replace function public.cp_save_announcement(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  p_ jsonb := coalesce(p, '{}'::jsonb);
  v_id uuid := nullif(p_ ->> 'id', '')::uuid;
  v_roles text[]; v_ids uuid[]; r public.platform_announcements;
begin
  perform public.cp_require(array['admin']);
  v_roles := coalesce((select array_agg(distinct x) from jsonb_array_elements_text(coalesce(p_ -> 'roles', '["owner"]'::jsonb)) x), array['owner']);
  if exists (select 1 from unnest(v_roles) x where x not in ('owner', 'doctor', 'receptionist', 'accountant', 'staff')) then
    raise exception 'Announcements go to staff roles only.';
  end if;
  if jsonb_typeof(p_ -> 'hospital_ids') = 'array' and jsonb_array_length(p_ -> 'hospital_ids') > 0 then
    v_ids := (select array_agg(distinct x::uuid) from jsonb_array_elements_text(p_ -> 'hospital_ids') x);
    if exists (select 1 from unnest(v_ids) x where not exists (select 1 from public.tenants t where t.id = x)) then raise exception 'Unknown hospital in the list.'; end if;
  end if;
  if v_id is null then
    insert into public.platform_announcements (title, body, level, hospital_ids, roles, starts_at, ends_at, active, created_by, created_by_name)
    values (trim(coalesce(p_ ->> 'title', '')), trim(coalesce(p_ ->> 'body', '')), coalesce(nullif(p_ ->> 'level', ''), 'info'), v_ids, v_roles,
            coalesce(nullif(p_ ->> 'starts_at', '')::timestamptz, now()), nullif(p_ ->> 'ends_at', '')::timestamptz, coalesce((p_ ->> 'active')::boolean, true),
            auth.uid(), (select full_name from public.profiles where id = auth.uid()))
    returning * into r;
  else
    update public.platform_announcements set title = trim(coalesce(p_ ->> 'title', title)), body = trim(coalesce(p_ ->> 'body', body)),
           level = coalesce(nullif(p_ ->> 'level', ''), level), hospital_ids = v_ids, roles = v_roles,
           starts_at = coalesce(nullif(p_ ->> 'starts_at', '')::timestamptz, starts_at),
           ends_at = case when p_ ? 'ends_at' then nullif(p_ ->> 'ends_at', '')::timestamptz else ends_at end,
           active = coalesce((p_ ->> 'active')::boolean, active), updated_at = now()
     where id = v_id returning * into r;
    if not found then raise exception 'Announcement not found.'; end if;
  end if;
  perform public.provider_log('announcement:save', r.title, jsonb_build_object('id', r.id, 'level', r.level, 'hospitals', coalesce(cardinality(r.hospital_ids), 0), 'roles', r.roles));
  return to_jsonb(r);
end $$;

create or replace function public.cp_delete_announcement(p_id uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_title text;
begin
  perform public.cp_require(array['admin']);
  delete from public.platform_announcements where id = p_id returning title into v_title;
  if not found then raise exception 'Announcement not found.'; end if;
  perform public.provider_log('announcement:delete', v_title, jsonb_build_object('id', p_id));
end $$;

-- what the signed-in hospital user should see now
create or replace function public.my_announcements()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_role text := public.current_app_role()::text; v_t uuid := public.current_tenant();
begin
  if auth.uid() is null or v_role is null or v_role = 'patient' then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'title', a.title, 'body', a.body, 'level', a.level, 'starts_at', a.starts_at)
                     order by case a.level when 'critical' then 0 when 'warning' then 1 else 2 end, a.starts_at desc)
    from (select * from public.platform_announcements a
           where a.active and a.starts_at <= now() and (a.ends_at is null or a.ends_at > now())
             and (a.hospital_ids is null or v_t = any (a.hospital_ids)) and v_role = any (a.roles)
           order by a.starts_at desc limit 5) a), '[]'::jsonb);
end $$;

-- ------------------------------------------------------------------ sign in as user (admins only)
-- The impersonate Edge Function calls impersonation_start as the admin, then makes a one-time sign-in link for the
-- user. The new tab signs in with it, binds its session here (impersonation_bind) and shows a banner with a countdown.
-- When it ends — button, or 30 minutes (notify_cron_flush → impersonation_expire) — that session is deleted.
create table if not exists public.impersonations (
  id            uuid primary key default gen_random_uuid(),
  admin_id      uuid not null,
  admin_name    text,
  target_id     uuid not null,
  target_email  text,
  target_role   text,
  hospital_id   uuid not null references public.tenants (id) on delete cascade,
  reason        text not null check (char_length(reason) between 10 and 300),
  created_at    timestamptz not null default now(),
  expires_at    timestamptz not null,
  session_id    text,
  bound_at      timestamptz,
  ended_at      timestamptz,
  end_reason    text
);
create index if not exists impersonations_target_idx on public.impersonations (target_id, created_at desc);
create index if not exists impersonations_open_idx on public.impersonations (expires_at) where ended_at is null;
alter table public.impersonations enable row level security;
revoke all on public.impersonations from anon, authenticated;
grant all on public.impersonations to service_role;

-- the Supabase session id of this request (in every access token)
create or replace function public.jwt_session_id()
returns text language plpgsql stable set search_path = public as $$
declare c jsonb;
begin
  begin c := nullif(current_setting('request.jwt.claims', true), '')::jsonb; exception when others then c := null; end;
  return nullif(c ->> 'session_id', '');
end $$;

create or replace function public.impersonation_close(p_row public.impersonations, p_reason text)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  update public.impersonations set ended_at = coalesce(ended_at, now()), end_reason = coalesce(end_reason, p_reason) where id = p_row.id;
  if p_row.session_id is not null and to_regclass('auth.sessions') is not null then
    begin
      execute 'delete from auth.sessions where id = $1::uuid and user_id = $2' using p_row.session_id, p_row.target_id;
    exception when others then raise warning 'impersonation_close: %', sqlerrm;
    end;
  end if;
end $$;

create or replace function public.impersonation_start(p_user uuid, p_reason text, p_minutes int default 30)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v public.profiles; t public.tenants; u record; o public.impersonations; r public.impersonations; v_min int := least(greatest(coalesce(p_minutes, 30), 5), 30);
begin
  perform public.cp_require(array['admin']);
  if not public.recent_reauth(600) then raise exception 'REAUTH_REQUIRED: confirm your password to sign in as a user.' using errcode = '42501'; end if;
  if char_length(trim(coalesce(p_reason, ''))) < 10 then raise exception 'Write why you need to sign in as this user (at least 10 characters).'; end if;
  select * into v from public.profiles where id = p_user;
  if not found or v.tenant_id is null then raise exception 'User not found.'; end if;
  if v.role = 'patient' then raise exception 'Signing in as a patient is not allowed.'; end if;
  if exists (select 1 from public.provider_users where user_id = p_user) then raise exception 'You can’t sign in as a Hospital Comrade team member.'; end if;
  if p_user = auth.uid() then raise exception 'That is your own account.'; end if;
  select * into t from public.tenants where id = v.tenant_id;
  if public.tenant_license(t.id) = 'suspended' then raise exception 'This hospital is suspended — resume it first.'; end if;
  select a.email, a.banned_until into u from auth.users a where a.id = p_user;
  if u.email is null then raise exception 'This user has no sign-in e-mail.'; end if;
  if u.banned_until is not null and u.banned_until > now() then raise exception 'This user is blocked — unblock them first.'; end if;

  for o in select * from public.impersonations where admin_id = auth.uid() and ended_at is null loop   -- one at a time per admin
    perform public.impersonation_close(o, 'replaced');
  end loop;
  insert into public.impersonations (admin_id, admin_name, target_id, target_email, target_role, hospital_id, reason, expires_at)
  values (auth.uid(), (select full_name from public.profiles where id = auth.uid()), p_user, lower(u.email), v.role::text, t.id,
          trim(p_reason), now() + make_interval(mins => v_min))
  returning * into r;
  perform set_config('app.tenant_id', t.id::text, true);
  perform public.provider_log('impersonate:start', lower(u.email), jsonb_build_object('id', r.id, 'role', v.role, 'reason', r.reason, 'minutes', v_min));
  return jsonb_build_object('id', r.id, 'email', r.target_email, 'full_name', v.full_name, 'role', v.role, 'hospital_id', t.id,
                            'slug', t.slug, 'hospital', t.name, 'expires_at', r.expires_at);
end $$;

-- the impersonation tab, right after signing in: remember which session is the impersonated one
create or replace function public.impersonation_bind(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare r public.impersonations; v_sid text := public.jwt_session_id();
begin
  select * into r from public.impersonations where id = p_id for update;
  if not found or r.target_id is distinct from auth.uid() or r.ended_at is not null or r.expires_at <= now()
     or r.bound_at is not null or r.created_at < now() - interval '5 minutes' then
    raise exception 'This sign-in link has expired — start again from the control panel.' using errcode = '42501';
  end if;
  update public.impersonations set session_id = v_sid, bound_at = now() where id = p_id;
  return jsonb_build_object('id', r.id, 'expires_at', r.expires_at, 'admin_name', r.admin_name, 'reason', r.reason);
end $$;

-- the banner checks this: is my current session still a running impersonation?
create or replace function public.impersonation_status(p_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare r public.impersonations;
begin
  select * into r from public.impersonations where id = p_id and target_id = auth.uid();
  if not found then return null; end if;
  return jsonb_build_object('id', r.id, 'expires_at', r.expires_at, 'admin_name', r.admin_name,
                            'active', r.ended_at is null and r.expires_at > now() and r.session_id is not distinct from public.jwt_session_id());
end $$;

-- end it: the impersonated tab itself, or the admin who started it
create or replace function public.impersonation_end(p_id uuid, p_reason text default 'ended')
returns void language plpgsql volatile security definer set search_path = public as $$
declare r public.impersonations;
begin
  select * into r from public.impersonations where id = p_id for update;
  if not found then return; end if;
  if r.target_id is distinct from auth.uid() and r.admin_id is distinct from auth.uid() then
    raise exception 'Not allowed.' using errcode = '42501';
  end if;
  if r.ended_at is not null then return; end if;
  perform public.impersonation_close(r, left(coalesce(nullif(p_reason, ''), 'ended'), 40));
  insert into public.provider_audit (user_id, user_name, mode, tenant_id, action, target, detail)
  values (r.admin_id, r.admin_name, 'admin', r.hospital_id, 'impersonate:end', r.target_email,
          jsonb_build_object('id', r.id, 'reason', p_reason, 'minutes', round(extract(epoch from now() - r.created_at) / 60)));
end $$;

-- time limit (every minute from notify_cron_flush)
create or replace function public.impersonation_expire()
returns int language plpgsql volatile security definer set search_path = public as $$
declare r public.impersonations; n int := 0;
begin
  for r in select * from public.impersonations where ended_at is null and expires_at <= now() for update skip locked loop
    perform public.impersonation_close(r, 'expired');
    insert into public.provider_audit (user_id, user_name, mode, tenant_id, action, target, detail)
    values (r.admin_id, r.admin_name, 'admin', r.hospital_id, 'impersonate:end', r.target_email, jsonb_build_object('id', r.id, 'reason', 'expired'));
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.cp_impersonations(p_limit int default 50)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (
    select i.id, i.admin_name, i.target_email, i.target_role, i.reason, i.created_at, i.expires_at, i.bound_at, i.ended_at, i.end_reason,
           t.name as hospital, i.hospital_id, (i.ended_at is null and i.expires_at > now()) as active
      from public.impersonations i join public.tenants t on t.id = i.hospital_id
     order by i.created_at desc limit least(greatest(coalesce(p_limit, 50), 1), 500)) x), '[]'::jsonb);
end $$;

-- ------------------------------------------------------------------ grants
revoke all on function public.cp_pin(uuid, text[]), public.impersonation_close(public.impersonations, text), public.impersonation_expire(),
  public.jwt_session_id() from public, anon, authenticated;
revoke all on function public.cp_hospital_profile(uuid), public.cp_save_hospital_profile(uuid, jsonb), public.cp_transfer_owner(uuid, uuid, text),
