  public.cp_hospital_data(uuid), public.cp_browse(uuid, text, text, int, int), public.cp_import(uuid, text, jsonb, boolean),
  public.cp_messaging(uuid), public.cp_save_messaging(uuid, jsonb), public.cp_wallet_ledger(uuid, int), public.cp_credit_notes(uuid),
  public.cp_credit_note(uuid, jsonb), public.cp_announcements(), public.cp_save_announcement(jsonb), public.cp_delete_announcement(uuid),
  public.my_announcements(), public.impersonation_start(uuid, text, int), public.impersonation_bind(uuid), public.impersonation_status(uuid),
  public.impersonation_end(uuid, text), public.cp_impersonations(int) from public, anon;
grant execute on function public.cp_hospital_profile(uuid), public.cp_save_hospital_profile(uuid, jsonb), public.cp_transfer_owner(uuid, uuid, text),
  public.cp_resend_owner_invite(uuid), public.cp_hospital_users(uuid, text, text, int, int), public.cp_user_action(uuid, text, uuid, jsonb),
  public.cp_hospital_data(uuid), public.cp_browse(uuid, text, text, int, int), public.cp_import(uuid, text, jsonb, boolean),
  public.cp_messaging(uuid), public.cp_save_messaging(uuid, jsonb), public.cp_wallet_ledger(uuid, int), public.cp_credit_notes(uuid),
  public.cp_credit_note(uuid, jsonb), public.cp_announcements(), public.cp_save_announcement(jsonb), public.cp_delete_announcement(uuid),
  public.my_announcements(), public.impersonation_start(uuid, text, int), public.impersonation_bind(uuid), public.impersonation_status(uuid),
  public.impersonation_end(uuid, text), public.cp_impersonations(int) to authenticated;


-- =====================================================================================================
--  PLATFORM WEBSITE CMS  (control panel → Website)
--  The Hospital Comrade product site on PLATFORM_DOMAIN: pages, legal pages and the blog. Not per hospital —
--  these tables have no tenant_id. Re-running keeps every edit, revision, post and image.
--
--  platform_content            one row per page key (home, features, legal, …): published `data` + unpublished `draft`.
--                              A key with no row (or no published data) shows the defaults shipped with the app.
--  platform_content_revisions  the previous published version, saved on every publish / reset (latest 30 per key).
--  platform_posts              blog articles (draft / published).
--  storage "platform-media"    public images uploaded from the panel (platform admins only).
--
--  Reading: anyone, through platform_site() / platform_blog() / platform_blog_post() — published content only;
--  drafts only for the platform team (preview). Writing: platform admins (support can look, not change).
-- =====================================================================================================
create table if not exists public.platform_content (
  key           text primary key check (key ~ '^[a-z]{2,30}$'),
  data          jsonb,
  draft         jsonb,
  published_at  timestamptz,
  published_by  text,
  updated_at    timestamptz not null default now(),
  updated_by    text
);
create table if not exists public.platform_content_revisions (
  id          uuid primary key default gen_random_uuid(),
  key         text not null,
  data        jsonb not null,
  created_at  timestamptz not null default now(),
  created_by  text
);
create index if not exists platform_content_revisions_key_idx on public.platform_content_revisions (key, created_at desc);

create table if not exists public.platform_posts (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(slug) <= 80),
  title         text not null check (length(btrim(title)) between 3 and 160),
  excerpt       text not null default '' check (length(excerpt) <= 400),
  cover         text check (cover is null or cover ~ '^(https://|/)'),
  body          text not null default '' check (length(body) <= 100000),
  tags          text[] not null default '{}',
  author        text check (author is null or length(author) <= 80),
  status        text not null default 'draft' check (status in ('draft', 'published')),
  published_at  timestamptz,
  seo           jsonb not null default '{}'::jsonb,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  updated_by    text
);
create index if not exists platform_posts_published_idx on public.platform_posts (status, published_at desc);

-- only through the functions below
alter table public.platform_content enable row level security;
alter table public.platform_content_revisions enable row level security;
alter table public.platform_posts enable row level security;
revoke all on public.platform_content, public.platform_content_revisions, public.platform_posts from public, anon, authenticated;
grant all on public.platform_content, public.platform_content_revisions, public.platform_posts to service_role;

-- the page keys the site knows (keeps typos and junk out)
create or replace function public.platform_page_keys()
returns text[] language sql immutable as $$
  select array['brand', 'home', 'features', 'pricing', 'solutions', 'security', 'about', 'contact', 'faq', 'blog', 'legal']
$$;

create or replace function public.platform_me_name()
returns text language sql stable security definer set search_path = public as $$
  select coalesce((select full_name from public.profiles where id = auth.uid()), (select email from auth.users where id = auth.uid()), 'Platform')
$$;

-- ------------------------------------------------------------------ public reading
-- every published page as { key: data }; p_preview = drafts too (platform team only — others get published)
create or replace function public.platform_site(p_preview boolean default false)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_draft boolean := coalesce(p_preview, false) and public.provider_role() is not null;
begin
  return coalesce((
    select jsonb_object_agg(key, case when v_draft then coalesce(draft, data) else data end)
      from public.platform_content
     where (case when v_draft then coalesce(draft, data) else data end) is not null
  ), '{}'::jsonb);
end $$;

create or replace function public.platform_blog(p_tag text default null, p_offset int default 0, p_limit int default 12)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_limit int := least(greatest(coalesce(p_limit, 12), 1), 50); v_off int := greatest(coalesce(p_offset, 0), 0);
begin
  return jsonb_build_object(
    'total', (select count(*) from public.platform_posts where status = 'published' and published_at <= now() and (p_tag is null or p_tag = any (tags))),
    'tags', coalesce((select jsonb_agg(t order by t) from (select distinct unnest(tags) t from public.platform_posts where status = 'published' and published_at <= now()) x), '[]'::jsonb),
    'rows', coalesce((
      select jsonb_agg(jsonb_build_object('slug', slug, 'title', title, 'excerpt', excerpt, 'cover', cover, 'tags', tags, 'author', author, 'published_at', published_at) order by published_at desc)
        from (select * from public.platform_posts
               where status = 'published' and published_at <= now() and (p_tag is null or p_tag = any (tags))
               order by published_at desc offset v_off limit v_limit) p
    ), '[]'::jsonb));
end $$;

create or replace function public.platform_blog_post(p_slug text, p_preview boolean default false)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare p public.platform_posts; v_draft boolean := coalesce(p_preview, false) and public.provider_role() is not null;
begin
  select * into p from public.platform_posts where slug = lower(p_slug) and (v_draft or (status = 'published' and published_at <= now()));
  if not found then return null; end if;
  return jsonb_build_object('slug', p.slug, 'title', p.title, 'excerpt', p.excerpt, 'cover', p.cover, 'body', p.body, 'tags', p.tags,
    'author', p.author, 'status', p.status, 'published_at', p.published_at, 'updated_at', p.updated_at, 'seo', p.seo);
end $$;

-- ------------------------------------------------------------------ control panel: pages
create or replace function public.cp_site()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare r text := public.cp_require(array['admin', 'support']);
begin
  return jsonb_build_object('canEdit', r = 'admin', 'pages', coalesce((
    select jsonb_agg(jsonb_build_object('key', key, 'data', data, 'draft', draft, 'published_at', published_at, 'published_by', published_by,
      'updated_at', updated_at, 'updated_by', updated_by) order by key) from public.platform_content), '[]'::jsonb));
end $$;

-- save a draft, or publish (p_publish) — publishing keeps the replaced version in the history
create or replace function public.cp_site_save(p_key text, p_data jsonb, p_publish boolean default false)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v_old public.platform_content; v_name text := public.platform_me_name(); v_row public.platform_content;
begin
  perform public.cp_require(array['admin']);
  if p_key is null or not (p_key = any (public.platform_page_keys())) then raise exception 'Unknown page "%".', p_key using errcode = '22023'; end if;
  if p_data is null or jsonb_typeof(p_data) <> 'object' then raise exception 'Page content must be an object.' using errcode = '22023'; end if;
  if length(p_data::text) > 300000 then raise exception 'This page is too large (over 300 KB). Shorten it or split it up.' using errcode = '22023'; end if;

  select * into v_old from public.platform_content where key = p_key for update;
  if coalesce(p_publish, false) then
    if v_old.data is not null and v_old.data is distinct from p_data then
      insert into public.platform_content_revisions (key, data, created_at, created_by) values (p_key, v_old.data, coalesce(v_old.published_at, v_old.updated_at), v_old.published_by);
    end if;
    insert into public.platform_content as c (key, data, draft, published_at, published_by, updated_at, updated_by)
    values (p_key, p_data, null, now(), v_name, now(), v_name)
    on conflict (key) do update set data = excluded.data, draft = null, published_at = now(), published_by = v_name, updated_at = now(), updated_by = v_name
    returning * into v_row;
  else
    insert into public.platform_content as c (key, draft, updated_at, updated_by) values (p_key, p_data, now(), v_name)
    on conflict (key) do update set draft = excluded.draft, updated_at = now(), updated_by = v_name
    returning * into v_row;
  end if;
  delete from public.platform_content_revisions
   where key = p_key and id not in (select id from public.platform_content_revisions where key = p_key order by created_at desc limit 30);
  insert into public.provider_audit (user_id, user_name, mode, action, target, detail)
  values (auth.uid(), v_name, 'admin', case when coalesce(p_publish, false) then 'site:publish' else 'site:draft' end, p_key, '{}'::jsonb);
  return to_jsonb(v_row);
end $$;

create or replace function public.cp_site_discard(p_key text)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  update public.platform_content set draft = null, updated_at = now(), updated_by = public.platform_me_name() where key = p_key;
  delete from public.platform_content where key = p_key and data is null and draft is null;
end $$;

-- back to the built-in text (the published version goes to the history)
create or replace function public.cp_site_reset(p_key text)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_old public.platform_content;
begin
  perform public.cp_require(array['admin']);
  select * into v_old from public.platform_content where key = p_key for update;
  if not found then return; end if;
  if v_old.data is not null then
    insert into public.platform_content_revisions (key, data, created_at, created_by) values (p_key, v_old.data, coalesce(v_old.published_at, v_old.updated_at), v_old.published_by);
  end if;
  delete from public.platform_content where key = p_key;
  insert into public.provider_audit (user_id, user_name, mode, action, target, detail)
  values (auth.uid(), public.platform_me_name(), 'admin', 'site:reset', p_key, '{}'::jsonb);
end $$;

create or replace function public.cp_site_history(p_key text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin', 'support']);
  return coalesce((select jsonb_agg(jsonb_build_object('id', id, 'key', key, 'data', data, 'created_at', created_at, 'created_by', created_by) order by created_at desc)
    from (select * from public.platform_content_revisions where key = p_key order by created_at desc limit 20) r), '[]'::jsonb);
end $$;

-- an old version becomes the draft (review it, then publish)
create or replace function public.cp_site_restore(p_rev uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v public.platform_content_revisions;
begin
  perform public.cp_require(array['admin']);
  select * into v from public.platform_content_revisions where id = p_rev;
  if not found then raise exception 'That version no longer exists.' using errcode = 'P0002'; end if;
  return public.cp_site_save(v.key, v.data, false);
end $$;

-- ------------------------------------------------------------------ control panel: blog
create or replace function public.cp_posts()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin', 'support']);
  return coalesce((select jsonb_agg(to_jsonb(p) order by coalesce(p.published_at, p.updated_at) desc) from (select * from public.platform_posts order by updated_at desc limit 500) p), '[]'::jsonb);
end $$;

create or replace function public.cp_save_post(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_slug text := lower(btrim(coalesce(p->>'slug', '')));
  v_status text := coalesce(nullif(p->>'status', ''), 'draft');
  v_pub timestamptz := nullif(p->>'published_at', '')::timestamptz;
  v_tags text[];
  v_name text := public.platform_me_name();
  v_row public.platform_posts;
begin
  perform public.cp_require(array['admin']);
  if v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or length(v_slug) > 80 then
    raise exception 'The web address (slug) may only have small letters, numbers and dashes — e.g. "gst-for-clinics".' using errcode = '22023';
  end if;
  if length(btrim(coalesce(p->>'title', ''))) < 3 then raise exception 'Give the article a title.' using errcode = '22023'; end if;
  if v_status not in ('draft', 'published') then raise exception 'Unknown status.' using errcode = '22023'; end if;
  if coalesce(p->>'cover', '') <> '' and p->>'cover' !~ '^(https://|/)' then raise exception 'The cover image must be an https:// link.' using errcode = '22023'; end if;
  select coalesce(array_agg(distinct left(lower(btrim(t)), 30)) filter (where btrim(t) <> ''), '{}') into v_tags
    from jsonb_array_elements_text(coalesce(p->'tags', '[]'::jsonb)) t;
  if v_status = 'published' and v_pub is null then v_pub := now(); end if;
  if exists (select 1 from public.platform_posts where slug = v_slug and id is distinct from v_id) then
    raise exception 'Another article already uses the address "%".', v_slug using errcode = '23505';
  end if;

  if v_id is null then
    insert into public.platform_posts (slug, title, excerpt, cover, body, tags, author, status, published_at, seo, updated_by)
    values (v_slug, btrim(p->>'title'), coalesce(p->>'excerpt', ''), nullif(p->>'cover', ''), coalesce(p->>'body', ''), v_tags,
            nullif(btrim(coalesce(p->>'author', '')), ''), v_status, v_pub, coalesce(p->'seo', '{}'::jsonb), v_name)
    returning * into v_row;
  else
    update public.platform_posts set slug = v_slug, title = btrim(p->>'title'), excerpt = coalesce(p->>'excerpt', ''), cover = nullif(p->>'cover', ''),
      body = coalesce(p->>'body', ''), tags = v_tags, author = nullif(btrim(coalesce(p->>'author', '')), ''), status = v_status, published_at = v_pub,
      seo = coalesce(p->'seo', '{}'::jsonb), updated_at = now(), updated_by = v_name
     where id = v_id returning * into v_row;
    if not found then raise exception 'Article not found.' using errcode = 'P0002'; end if;
  end if;
  insert into public.provider_audit (user_id, user_name, mode, action, target, detail)
  values (auth.uid(), v_name, 'admin', 'blog:save', v_row.slug, jsonb_build_object('status', v_row.status));
  return to_jsonb(v_row);
end $$;

create or replace function public.cp_delete_post(p_id uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_slug text;
begin
  perform public.cp_require(array['admin']);
  delete from public.platform_posts where id = p_id returning slug into v_slug;
  if v_slug is not null then
    insert into public.provider_audit (user_id, user_name, mode, action, target, detail)
    values (auth.uid(), public.platform_me_name(), 'admin', 'blog:delete', v_slug, '{}'::jsonb);
  end if;
end $$;

-- ------------------------------------------------------------------ media (public read, platform admins write)
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('platform-media', 'platform-media', true, 5242880, array['image/png', 'image/jpeg', 'image/webp', 'image/gif', 'image/svg+xml'])
on conflict (id) do update set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
drop policy if exists platform_media_public_read on storage.objects;
drop policy if exists platform_media_admin_insert on storage.objects;
drop policy if exists platform_media_admin_update on storage.objects;
drop policy if exists platform_media_admin_delete on storage.objects;
create policy platform_media_public_read on storage.objects for select to anon, authenticated using (bucket_id = 'platform-media');
create policy platform_media_admin_insert on storage.objects for insert to authenticated with check (bucket_id = 'platform-media' and public.provider_role() = 'admin');
create policy platform_media_admin_update on storage.objects for update to authenticated using (bucket_id = 'platform-media' and public.provider_role() = 'admin');
create policy platform_media_admin_delete on storage.objects for delete to authenticated using (bucket_id = 'platform-media' and public.provider_role() = 'admin');

revoke all on function public.platform_me_name(), public.cp_site(), public.cp_site_save(text, jsonb, boolean), public.cp_site_discard(text),
  public.cp_site_reset(text), public.cp_site_history(text), public.cp_site_restore(uuid), public.cp_posts(), public.cp_save_post(jsonb),
  public.cp_delete_post(uuid) from public, anon;
grant execute on function public.cp_site(), public.cp_site_save(text, jsonb, boolean), public.cp_site_discard(text), public.cp_site_reset(text),
  public.cp_site_history(text), public.cp_site_restore(uuid), public.cp_posts(), public.cp_save_post(jsonb), public.cp_delete_post(uuid) to authenticated;
grant execute on function public.platform_site(boolean), public.platform_blog(text, int, int), public.platform_blog_post(text, boolean),
  public.platform_page_keys() to anon, authenticated;

-- ------------------------------------------------------------------ starter articles (once — deleting them keeps them deleted)
do $seed$
begin
  if exists (select 1 from public.platform_settings where key = 'blog_seeded') then return; end if;
  insert into public.platform_posts (slug, title, excerpt, body, tags, author, status, published_at) values
  ('reduce-opd-no-shows', '7 ways to reduce OPD no-shows at your clinic',
   'Empty slots cost money and lengthen waiting lists. These simple habits help more booked patients actually turn up.',
$md$Every missed appointment is a slot another patient could have used. In many Indian clinics, a noticeable share of booked patients simply do not arrive — and the doctor's day becomes unpredictable. The good news: most no-shows are forgotten appointments, not lost patients. Here is what works.

## 1. Confirm the booking straight away

A confirmation message with the doctor's name, date, time and address — sent the moment the slot is booked — turns a vague plan into a commitment. WhatsApp works best in India because people actually read it.

## 2. Send a reminder the day before

A short reminder the evening before (or a few hours before a morning slot) is the single most effective step. Keep it simple: who, when, where, and how to reschedule.

## 3. Make rescheduling easy

Patients who cannot come often do not cancel because calling feels like a hassle. A simple "reply or call to change your time" line frees the slot for someone else.

## 4. Verify mobile numbers at booking

An OTP check on online bookings means reminders reach the right person — and filters out fake or mistyped bookings.

## 5. Keep walk-ins and bookings in one queue

When reception can see free slots in real time, a walk-in can fill a gap left by a no-show instead of waiting until the end.

## 6. Watch the numbers

Track no-shows by doctor, day of week and time of day. Monday mornings and late evenings often behave differently — adjust slot lengths and reminders accordingly.

## 7. Follow up kindly

A polite message after a missed visit ("We missed you today — would you like a new time?") brings many patients back and shows you care.

---

**In short:** confirm, remind, make changes easy, and measure. With a system that sends these messages automatically, your staff do not have to remember to call anyone.$md$,
   array['opd', 'patients'], 'Editorial team', 'published', now()),

  ('choosing-hospital-software-checklist', 'Choosing hospital management software: a 12-point checklist',
   'Before you sign up for any HMS, ask these twelve questions — about data, cost, support and how your staff will actually use it.',
$md$Hospital software is a long-term decision: your patient records, bills and daily routine will live inside it. Demos all look good, so use this checklist to compare options fairly.

## Data and safety

1. **Who owns the data?** It should be clearly yours, with a full export available at any time — not only when you leave.
2. **Where is it stored?** Ask which country and which provider, and whether backups are automatic and encrypted.
3. **Is each hospital's data isolated?** In cloud software, your records must be separated from other customers' at the database level.
4. **Is there a Data Processing Agreement?** Under India's DPDP Act, 2023, your hospital is responsible for patient data — your software provider should sign up to protect it.

## Daily use

5. **Can reception learn it in an hour?** Ask for a trial and let your actual front-desk staff try booking and billing.
6. **Does each role see only what it needs?** Doctors, reception and accounts should have separate access; salaries and settings should not be visible to everyone.
7. **Does it work on the devices you have?** Browser-based software that runs on ordinary laptops and phones saves you buying new hardware.
8. **Does it talk to patients?** Booking confirmations and reminders on WhatsApp or SMS save hours of phone calls.

## Cost and support

9. **What is the full price?** Check setup fees, per-user charges, message costs and annual increases — not just the headline monthly price.
10. **What does support look like?** Hours, language, response times — and whether they are written down.
11. **How often is it updated?** Cloud software should improve regularly without paid upgrades.
12. **Can you leave easily?** Make sure you can take all your data with you in a usable format.

---

Print this list, take it into every demo, and score each option. The right choice is usually the one your staff are happiest using after a week of trial.$md$,
   array['software', 'guides'], 'Editorial team', 'published', now() - interval '1 day'),

  ('dpdp-act-for-clinics', 'DPDP Act, 2023: what clinics and hospitals should know',
   'India''s data protection law applies to every hospital that keeps patient records digitally. A plain-language overview of what it asks of you.',
$md$The **Digital Personal Data Protection Act, 2023** (DPDP Act) is India's law on how organisations collect and use personal data. The **DPDP Rules** were notified in November 2025, with most obligations applying after a transition period. Hospitals and clinics hold some of the most sensitive data there is, so it is worth preparing now.

> This article is general information, not legal advice. Please consult a lawyer for your hospital's specific situation.

## Your hospital is the "Data Fiduciary"

Under the Act, the organisation that decides why and how personal data is used is the **Data Fiduciary**. For patient records, that is your hospital. Your software provider is a **Data Processor** that handles the data on your behalf — under a written agreement.

## What the law expects

- **A clear notice and consent** — tell people what data you collect and why, in simple language, and get consent where it is needed (for example, for marketing messages).
- **Use data only for its purpose** — data collected for treatment and billing should not be reused for unrelated things.
- **Keep it accurate and secure** — reasonable security safeguards are mandatory, and access should be limited to people who need it.
- **Respect people's rights** — patients can ask to access, correct or erase their data (subject to records you must keep by law) and to nominate someone to act for them.
- **Have a grievance process** — publish how people can complain, and answer within the set time.
- **Report breaches** — if personal data is breached, you must inform the Data Protection Board of India and the affected people. The Rules set short deadlines, so have a plan ready.
- **Delete data you no longer need** — keep records for as long as medical and tax laws require, and not indefinitely beyond that.

Penalties for serious failures — such as not taking reasonable security safeguards — can be very large, up to ₹250 crore.

## A practical checklist for clinics

1. Give each staff member their own login with the right role — no shared passwords.
2. Make sure your software keeps an audit log of who changed what.
3. Sign a Data Processing Agreement with your software provider.
4. Put a short privacy notice on your website and booking forms.
5. Record consent for promotional messages separately from appointment messages.
6. Name a person responsible for privacy requests and complaints.
7. Write down what you will do if a laptop is lost or data leaks.

---

Good software makes most of this routine: role-based access, audit logs, consent records and data export are built in, so your team can focus on patients.$md$,
   array['compliance', 'privacy'], 'Editorial team', 'published', now() - interval '2 days')
  on conflict (slug) do nothing;
  insert into public.platform_settings (key, data) values ('blog_seeded', jsonb_build_object('at', now())) on conflict (key) do nothing;
end $seed$;


-- =====================================================================================================
-- Control panel → Messaging & alerts, Broadcasts and System health (live checks)
--
--  1. Shared accounts   platform_settings 'messaging_accounts' (provider names, sender IDs, from-address — not secret)
--                       + platform_secrets (API keys; encrypted in Supabase Vault when the extension is on, write-only).
--                       Keys use the PLATFORM_* names the Edge Functions already know; a key saved here wins over the
--                       Edge secret of the same name. platform_env() hands the merged set to the Edge Functions only.
--  2. platform_outbox   messages sent on the shared accounts that belong to no hospital's queue: team alerts,
--                       broadcasts to hospital staff (e-mail / SMS / WhatsApp) and control-panel test messages.
--                       Delivered by the `ops` Edge Function (pg_cron → ops_cron_tick → ops { flush }).
--  3. Alerts            raise_platform_alert(): one alert → bell inbox + e-mail / WhatsApp / browser push per member,
--                       limited by the channels and events an admin switched on (platform_settings 'ops') and each
--                       member's own choices (platform_alert_prefs). Repeats are folded with a dedupe key.
--  4. Broadcasts        to hospital staff by hospital / plan / status / role: in-app banner (platform_announcements),
--                       e-mail / SMS / WhatsApp (platform accounts, never the hospital's wallet) and push (the
--                       hospital's own Firebase devices, through its notification queue).
--  5. Health            the `ops` function checks the site, database, auth, storage, every Edge Function and the
--                       shared providers every 5 minutes; record_health() adds the database's own checks, keeps 30 days
--                       of history and raises alerts when a service goes down, crosses a limit or recovers.
-- Checked by tests/sql/cp_notify.test.ts.
-- =====================================================================================================

-- ------------------------------------------------------------------ settings
create or replace function public.ops_defaults()
returns jsonb language sql immutable as $$
  select '{
    "channels":   {"bell": true, "email": true, "push": false, "whatsapp": false},
    "events":     {},
    "thresholds": {"queueBacklog": 200, "failurePct": 10, "dbPct": 80, "dbLimitMb": 8192, "latencyMs": 3000, "walletLowPaise": 20000, "trialDays": 3,
                   "connPct": 80, "storagePct": 80, "storageLimitMb": 102400, "webhookHours": 24, "sslDays": 14},
    "health":     {"enabled": true, "siteUrl": ""}
  }'::jsonb
$$;

-- what can raise an alert, who receives it by default and how loud it is
create or replace function public.ops_alert_catalog()
returns jsonb language sql immutable as $$
  select '[
    {"key": "signup_new",       "label": "New sign-up",                              "group": "Sales",  "severity": "info",     "roles": ["admin"]},
    {"key": "lead_new",         "label": "New call-back request",                    "group": "Sales",  "severity": "info",     "roles": ["admin"]},
    {"key": "trial_ending",     "label": "Trial ending soon",                        "group": "Sales",  "severity": "info",     "roles": ["admin"]},
    {"key": "payment_paid",     "label": "Payment received",                         "group": "Money",  "severity": "info",     "roles": ["admin", "finance"]},
    {"key": "payment_failed",   "label": "Payment failed",                           "group": "Money",  "severity": "warning",  "roles": ["admin", "finance"]},
    {"key": "wallet_low",       "label": "Hospital wallet running low",              "group": "Money",  "severity": "warning",  "roles": ["admin", "finance"]},
    {"key": "incident_new",     "label": "Incident logged",                          "group": "Safety", "severity": "critical", "roles": ["admin", "support"]},
    {"key": "health_down",      "label": "Service down",                             "group": "System", "severity": "critical", "roles": ["admin", "support"]},
    {"key": "job_late",         "label": "Scheduled job late or failing",            "group": "System", "severity": "warning",  "roles": ["admin", "support"]},
    {"key": "delivery_spike",   "label": "Message failures spiking",                 "group": "System", "severity": "warning",  "roles": ["admin", "support"]},
    {"key": "threshold",        "label": "Limit crossed (queue, database, storage, SSL…)", "group": "System", "severity": "warning",  "roles": ["admin", "support"]},
    {"key": "health_recovered", "label": "Service back to normal",                   "group": "System", "severity": "info",     "roles": ["admin", "support"]}
  ]'::jsonb
$$;

insert into public.platform_settings (key, data) values ('ops', '{}'::jsonb), ('messaging_accounts', '{}'::jsonb) on conflict (key) do nothing;

-- saved 'ops' settings over the defaults (one level deep, so a new default threshold appears automatically)
create or replace function public.ops_config()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare d jsonb := public.ops_defaults(); s jsonb := coalesce((select data from public.platform_settings where key = 'ops'), '{}'::jsonb); k text;
begin
  for k in select jsonb_object_keys(d) loop
    if jsonb_typeof(s -> k) = 'object' then d := jsonb_set(d, array[k], (d -> k) || (s -> k)); end if;
  end loop;
  return d;
end $$;

-- ------------------------------------------------------------------ 1. shared accounts
create table if not exists public.platform_secrets (
  key              text primary key check (key ~ '^PLATFORM_[A-Z0-9_]{2,60}$'),
  value            text,          -- only when Supabase Vault is not available
  vault_id         uuid,          -- vault.secrets.id
  hint             text,
  updated_at       timestamptz not null default now(),
  updated_by       uuid,
  updated_by_name  text
);
alter table public.platform_secrets enable row level security;   -- no policies: unreachable through the API
revoke all on public.platform_secrets from anon, authenticated;
grant all on public.platform_secrets to service_role;

create or replace function public.platform_vault_on()
returns boolean language sql stable as $$ select exists (select 1 from pg_extension where extname = 'supabase_vault') $$;

create or replace function public.platform_secret_value(p public.platform_secrets)
returns text language plpgsql stable security definer set search_path = public as $$
declare v text;
begin
  if p.vault_id is not null and public.platform_vault_on() then
    execute 'select decrypted_secret from vault.decrypted_secrets where id = $1' into v using p.vault_id;
    return v;
  end if;
  return p.value;
end $$;

create or replace function public.cp_messaging_setup()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return jsonb_build_object(
    'settings', coalesce((select data from public.platform_settings where key = 'messaging_accounts'), '{}'::jsonb),
    'secrets', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'hint', hint, 'updated_at', updated_at, 'updated_by_name', updated_by_name) order by key)
                           from public.platform_secrets), '[]'::jsonb),
    'templates', coalesce((select data -> 'templates' from public.platform_settings where key = 'messaging'), '{}'::jsonb),
    'vault', public.platform_vault_on());
end $$;

-- p_settings: { "PLATFORM_SMS_PROVIDER": "msg91", … } ('' removes) · p_secrets: { "PLATFORM_MSG91_AUTH_KEY": "…" } ('' removes)
create or replace function public.cp_save_messaging_setup(p_settings jsonb default '{}'::jsonb, p_secrets jsonb default '{}'::jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_name text := (select full_name from public.profiles where id = auth.uid());
  s jsonb := coalesce((select data from public.platform_settings where key = 'messaging_accounts'), '{}'::jsonb);
  k text; v text; r public.platform_secrets; v_vault uuid; v_changed text[] := '{}';
begin
  perform public.cp_require(array['admin']);
  if jsonb_typeof(coalesce(p_settings, '{}'::jsonb)) <> 'object' or jsonb_typeof(coalesce(p_secrets, '{}'::jsonb)) <> 'object' then raise exception 'Settings must be an object.'; end if;
  if exists (select 1 from jsonb_object_keys(coalesce(p_secrets, '{}'::jsonb)) x) and not public.recent_reauth(600) then
    raise exception 'REAUTH_REQUIRED: confirm your password to change API keys.' using errcode = '42501';
  end if;
  for k, v in select key, value #>> '{}' from jsonb_each(coalesce(p_settings, '{}'::jsonb)) loop
    if k !~ '^PLATFORM_[A-Z0-9_]{2,60}$' then raise exception 'Unknown setting %', k; end if;
    if char_length(coalesce(v, '')) > 500 then raise exception '% is too long.', k; end if;
    if exists (select 1 from public.platform_secrets where key = k) then raise exception '% is an API key — save it as a key.', k; end if;
    s := case when coalesce(trim(v), '') = '' then s - k else s || jsonb_build_object(k, trim(v)) end;
    v_changed := v_changed || k;
  end loop;
  insert into public.platform_settings (key, data, updated_at, updated_by) values ('messaging_accounts', s, now(), auth.uid())
  on conflict (key) do update set data = excluded.data, updated_at = now(), updated_by = auth.uid();

  for k, v in select key, value #>> '{}' from jsonb_each(coalesce(p_secrets, '{}'::jsonb)) loop
    if k !~ '^PLATFORM_[A-Z0-9_]{2,60}$' then raise exception 'Unknown key %', k; end if;
    if char_length(coalesce(v, '')) > 8000 then raise exception '% is too long.', k; end if;
    select * into r from public.platform_secrets where key = k;
    if coalesce(v, '') = '' then
      if r.vault_id is not null and public.platform_vault_on() then execute 'delete from vault.secrets where id = $1' using r.vault_id; end if;
      delete from public.platform_secrets where key = k;
    else
      v_vault := r.vault_id;
      if public.platform_vault_on() then
        if v_vault is null then
          execute 'select id from vault.secrets where name = $1' into v_vault using 'hc_' || lower(k);
        end if;
        if v_vault is null then execute 'select vault.create_secret($1, $2, $3)' into v_vault using v, 'hc_' || lower(k), 'Hospital Comrade shared account';
        else execute 'select vault.update_secret($1, $2)' using v_vault, v; end if;
      end if;
      insert into public.platform_secrets (key, value, vault_id, hint, updated_at, updated_by, updated_by_name)
      values (k, case when v_vault is null then v end, v_vault, '••••' || case when char_length(v) >= 12 then right(v, 4) else '' end, now(), auth.uid(), v_name)
      on conflict (key) do update set value = excluded.value, vault_id = excluded.vault_id, hint = excluded.hint, updated_at = now(),
        updated_by = excluded.updated_by, updated_by_name = excluded.updated_by_name;
      s := s - k;   -- a key is never also kept as a plain setting
    end if;
    v_changed := v_changed || k;
  end loop;
  update public.platform_settings set data = s where key = 'messaging_accounts';
  if array_length(v_changed, 1) > 0 then
    insert into public.provider_audit (user_id, user_name, mode, action, target, detail)
    values (auth.uid(), v_name, 'admin', 'messaging:setup', 'shared accounts', jsonb_build_object('changed', to_jsonb(v_changed)));
  end if;
  return public.cp_messaging_setup();
end $$;

-- approved WhatsApp template / DLT IDs on the shared accounts, per event (same shape as before: platform_settings 'messaging')
create or replace function public.cp_save_platform_templates(p_templates jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t jsonb := '{}'::jsonb; k text; v jsonb;
begin
  perform public.cp_require(array['admin']);
  if jsonb_typeof(coalesce(p_templates, '{}'::jsonb)) <> 'object' then raise exception 'Templates must be an object.'; end if;
  for k, v in select key, value from jsonb_each(coalesce(p_templates, '{}'::jsonb)) loop
    if k !~ '^[a-z0-9_:-]{2,64}$' then raise exception 'Unknown event %', k; end if;
    v := jsonb_strip_nulls(jsonb_build_object('waTemplate', nullif(trim(v ->> 'waTemplate'), ''), 'waParams', nullif(trim(v ->> 'waParams'), ''),
                                              'smsTemplateId', nullif(trim(v ->> 'smsTemplateId'), '')));
    if v <> '{}'::jsonb then t := t || jsonb_build_object(k, v); end if;
  end loop;
  insert into public.platform_settings (key, data, updated_at, updated_by) values ('messaging', jsonb_build_object('templates', t), now(), auth.uid())
  on conflict (key) do update set data = public.platform_settings.data || jsonb_build_object('templates', t), updated_at = now(), updated_by = auth.uid();
  insert into public.provider_audit (user_id, user_name, mode, action, target, detail)
  values (auth.uid(), (select full_name from public.profiles where id = auth.uid()), 'admin', 'messaging:templates', 'shared templates', jsonb_build_object('events', (select jsonb_agg(x) from jsonb_object_keys(t) x)));
  return t;
end $$;

-- settings + decrypted keys, for the Edge Functions (service role only)
create or replace function public.platform_env()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare out jsonb := coalesce((select data from public.platform_settings where key = 'messaging_accounts'), '{}'::jsonb); r public.platform_secrets; v text;
begin
  for r in select * from public.platform_secrets loop
    v := public.platform_secret_value(r);
    if v is not null then out := out || jsonb_build_object(r.key, v); end if;
  end loop;
  return out;
end $$;

-- ------------------------------------------------------------------ 2. platform outbox + control-panel devices
create table if not exists public.platform_outbox (
  id               uuid primary key default gen_random_uuid(),
  kind             text not null check (kind in ('alert', 'broadcast', 'test', 'otp')),   -- otp: team sign-in codes (otp_verify.sql)
  ref_id           uuid,
  channel          text not null check (channel in ('email', 'sms', 'whatsapp', 'push')),
  recipient        text not null check (char_length(recipient) between 3 and 200),
  user_id          uuid,
  hospital_id      uuid references public.tenants (id) on delete cascade,   -- not tenant_id: this is no hospital's own data
  subject          text,
  body             text not null default '',
  vars             jsonb not null default '{}'::jsonb,
  status           text not null default 'pending' check (status in ('pending', 'sending', 'sent', 'failed', 'skipped')),
  attempts         int not null default 0,
  error            text,
  provider_ref     text,
  next_attempt_at  timestamptz not null default now(),
  created_at       timestamptz not null default now(),
  sent_at          timestamptz
);
create index if not exists platform_outbox_due_idx on public.platform_outbox (next_attempt_at) where status = 'pending';
create index if not exists platform_outbox_ref_idx on public.platform_outbox (ref_id);
create index if not exists platform_outbox_created_idx on public.platform_outbox (created_at desc);
alter table public.platform_outbox enable row level security;
revoke all on public.platform_outbox from anon, authenticated;
grant all on public.platform_outbox to service_role;

create or replace function public.claim_platform_outbox(p_limit int default 25)
returns setof public.platform_outbox language plpgsql volatile security definer set search_path = public as $$
begin
  -- messages stuck in "sending" for 10 minutes (a crashed run) go back to the queue
  update public.platform_outbox set status = 'pending' where status = 'sending' and next_attempt_at < now() - interval '10 minutes';
  return query
    update public.platform_outbox o set status = 'sending', attempts = o.attempts + 1, next_attempt_at = now()
     where o.id in (select x.id from public.platform_outbox x where x.status = 'pending' and x.next_attempt_at <= now()
                     order by x.created_at limit greatest(1, least(p_limit, 100)) for update skip locked)
    returning o.*;
end $$;

create table if not exists public.cp_push_tokens (
  token         text primary key check (char_length(token) between 20 and 4096),
  user_id       uuid not null references auth.users (id) on delete cascade,
  user_agent    text check (char_length(user_agent) <= 300),
  created_at    timestamptz not null default now(),
  last_seen_at  timestamptz not null default now()
);
create index if not exists cp_push_tokens_user_idx on public.cp_push_tokens (user_id);
alter table public.cp_push_tokens enable row level security;
revoke all on public.cp_push_tokens from anon, authenticated;
grant all on public.cp_push_tokens to service_role;

create or replace function public.cp_register_push(p_token text, p_user_agent text default null)
returns int language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.cp_require();
  if char_length(coalesce(p_token, '')) not between 20 and 4096 then raise exception 'Invalid device token.'; end if;
  insert into public.cp_push_tokens (token, user_id, user_agent) values (p_token, auth.uid(), left(p_user_agent, 300))
  on conflict (token) do update set user_id = auth.uid(), user_agent = excluded.user_agent, last_seen_at = now();
  return (select count(*)::int from public.cp_push_tokens where user_id = auth.uid());
end $$;

create or replace function public.cp_unregister_push(p_token text default null)
returns int language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.cp_require();
  delete from public.cp_push_tokens where user_id = auth.uid() and (p_token is null or token = p_token);
  return (select count(*)::int from public.cp_push_tokens where user_id = auth.uid());
end $$;

-- the Firebase web settings the control panel needs to ask for browser notifications (public values only)
create or replace function public.cp_push_config()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare s jsonb := coalesce((select data from public.platform_settings where key = 'messaging_accounts'), '{}'::jsonb);
begin
  perform public.cp_require();
  if not coalesce((public.ops_config() #>> '{channels,push}')::boolean, false) or coalesce(s ->> 'PLATFORM_FCM_PROJECT_ID', '') = '' then return null; end if;
  return jsonb_build_object('apiKey', s ->> 'PLATFORM_FCM_API_KEY', 'projectId', s ->> 'PLATFORM_FCM_PROJECT_ID', 'messagingSenderId', s ->> 'PLATFORM_FCM_SENDER_ID',
    'appId', s ->> 'PLATFORM_FCM_APP_ID', 'vapidKey', s ->> 'PLATFORM_FCM_VAPID_KEY',
    'devices', (select count(*) from public.cp_push_tokens where user_id = auth.uid()));
end $$;

-- ------------------------------------------------------------------ 3. alerts
create table if not exists public.platform_alerts (
  id          uuid primary key default gen_random_uuid(),
  created_at  timestamptz not null default now(),
  event       text not null,
  severity    text not null check (severity in ('info', 'warning', 'critical')),
  title       text not null check (char_length(title) between 1 and 200),
  body        text not null default '' check (char_length(body) <= 2000),
  link        text check (char_length(link) <= 300),
  dedupe_key  text,
  data        jsonb not null default '{}'::jsonb
);
create index if not exists platform_alerts_created_idx on public.platform_alerts (created_at desc);
create index if not exists platform_alerts_dedupe_idx on public.platform_alerts (dedupe_key, created_at desc) where dedupe_key is not null;
alter table public.platform_alerts enable row level security;
revoke all on public.platform_alerts from anon, authenticated;
grant all on public.platform_alerts to service_role;

create table if not exists public.platform_alert_inbox (
  alert_id  uuid not null references public.platform_alerts (id) on delete cascade,
  user_id   uuid not null references auth.users (id) on delete cascade,
  read_at   timestamptz,
  primary key (alert_id, user_id)
);
create index if not exists platform_alert_inbox_user_idx on public.platform_alert_inbox (user_id, read_at);
alter table public.platform_alert_inbox enable row level security;
revoke all on public.platform_alert_inbox from anon, authenticated;
grant all on public.platform_alert_inbox to service_role;

create table if not exists public.platform_alert_prefs (
  user_id     uuid primary key references auth.users (id) on delete cascade,
  events      jsonb not null default '{}'::jsonb,    -- { "<event>": ["bell", "email", "push", "whatsapp"] }
  whatsapp    text check (whatsapp is null or whatsapp ~ '^[0-9]{10}$'),
  updated_at  timestamptz not null default now()
);
alter table public.platform_alert_prefs enable row level security;
revoke all on public.platform_alert_prefs from anon, authenticated;
grant all on public.platform_alert_prefs to service_role;

create or replace function public.ops_default_channels(p_severity text)
returns text[] language sql immutable as $$ select case when p_severity in ('critical', 'warning') then array['bell', 'email'] else array['bell'] end $$;

create or replace function public.raise_platform_alert(p_event text, p_title text, p_body text default '', p_link text default null,
  p_dedupe text default null, p_dedupe_minutes int default 60, p_severity text default null, p_data jsonb default '{}'::jsonb)
returns uuid language plpgsql volatile security definer set search_path = public as $$
declare
  cfg jsonb := public.ops_config();
  ev jsonb := (select e from jsonb_array_elements(public.ops_alert_catalog()) e where e ->> 'key' = p_event);
  v_sev text; v_id uuid; u record; v_ch text[]; v_subject text; v_text text;
begin
  if ev is null then raise exception 'Unknown alert %', p_event; end if;
  if not coalesce((cfg #>> array['events', p_event, 'enabled'])::boolean, true) then return null; end if;
  v_sev := coalesce(nullif(p_severity, ''), nullif(cfg #>> array['events', p_event, 'severity'], ''), ev ->> 'severity');
  if v_sev not in ('info', 'warning', 'critical') then v_sev := ev ->> 'severity'; end if;
  if p_dedupe is not null and exists (select 1 from public.platform_alerts where dedupe_key = p_dedupe
                                        and created_at > now() - make_interval(mins => greatest(coalesce(p_dedupe_minutes, 60), 1))) then
    return null;
  end if;
  insert into public.platform_alerts (event, severity, title, body, link, dedupe_key, data)
  values (p_event, v_sev, left(p_title, 200), left(coalesce(p_body, ''), 2000), left(p_link, 300), p_dedupe, coalesce(p_data, '{}'::jsonb))
  returning id into v_id;
  v_subject := case v_sev when 'critical' then '[Critical] ' when 'warning' then '[Warning] ' else '' end || left(p_title, 180);
  v_text := p_title || case when coalesce(p_body, '') <> '' then E'\n\n' || p_body else '' end;
  for u in select pu.user_id, pu.role, a.email, pr.events as pevents, pr.whatsapp
             from public.provider_users pu join auth.users a on a.id = pu.user_id
             left join public.platform_alert_prefs pr on pr.user_id = pu.user_id
            where pu.active and (pu.role = 'admin' or pu.role in (select jsonb_array_elements_text(ev -> 'roles'))) loop
    v_ch := case when jsonb_typeof(u.pevents -> p_event) = 'array' then array(select jsonb_array_elements_text(u.pevents -> p_event)) else public.ops_default_channels(v_sev) end;
    v_ch := array(select c from unnest(v_ch) c where coalesce((cfg #>> array['channels', c])::boolean, false));
    if 'bell' = any (v_ch) then insert into public.platform_alert_inbox (alert_id, user_id) values (v_id, u.user_id) on conflict do nothing; end if;
    if 'email' = any (v_ch) and coalesce(u.email, '') <> '' then
      insert into public.platform_outbox (kind, ref_id, channel, recipient, user_id, subject, body, vars)
      values ('alert', v_id, 'email', u.email, u.user_id, v_subject, v_text, jsonb_build_object('title', p_title, 'body', coalesce(p_body, ''), 'link', coalesce(p_link, ''), 'severity', v_sev));
    end if;
    if 'whatsapp' = any (v_ch) and coalesce(u.whatsapp, '') <> '' then
      insert into public.platform_outbox (kind, ref_id, channel, recipient, user_id, subject, body, vars)
      values ('alert', v_id, 'whatsapp', u.whatsapp, u.user_id, v_subject, v_text, jsonb_build_object('title', p_title, 'body', coalesce(p_body, ''), 'link', coalesce(p_link, ''), 'severity', v_sev));
    end if;
    if 'push' = any (v_ch) and exists (select 1 from public.cp_push_tokens t where t.user_id = u.user_id) then
      insert into public.platform_outbox (kind, ref_id, channel, recipient, user_id, subject, body, vars)
      values ('alert', v_id, 'push', u.user_id::text, u.user_id, v_subject, coalesce(nullif(p_body, ''), p_title), jsonb_build_object('title', p_title, 'link', coalesce(p_link, ''), 'severity', v_sev));
    end if;
  end loop;
  return v_id;
end $$;

-- a broken alert must never block the sign-up / payment / lead that caused it
create or replace function public.raise_platform_alert_safe(p_event text, p_title text, p_body text default '', p_link text default null,
  p_dedupe text default null, p_dedupe_minutes int default 60, p_severity text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.raise_platform_alert(p_event, p_title, p_body, p_link, p_dedupe, p_dedupe_minutes, p_severity);
exception when others then
  raise warning 'platform alert % not raised: %', p_event, sqlerrm;
end $$;

create or replace function public.ops_alert_trigger()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_hosp text;
begin
  if tg_table_name = 'platform_signups' then
    perform public.raise_platform_alert_safe('signup_new', 'New sign-up: ' || new.organisation,
      new.contact_name || ' · ' || new.plan || ' plan' || coalesce(' · ' || nullif(new.city, ''), '') || case when new.status = 'pending' then ' · waiting for approval' else '' end, '/signups');
  elsif tg_table_name = 'platform_leads' then
    perform public.raise_platform_alert_safe('lead_new', 'Call-back request: ' || new.organisation,
      new.name || ' · ' || new.phone || coalesce(' · ' || nullif(new.city, ''), '') || coalesce(' · ' || nullif(new.plan, ''), ''), '/leads');
  elsif tg_table_name = 'billing_payments' then
    if new.status is distinct from coalesce(old.status, '') and new.status in ('paid', 'failed') then
      v_hosp := (select name from public.tenants where id = new.tenant_id);
      perform public.raise_platform_alert_safe(case new.status when 'paid' then 'payment_paid' else 'payment_failed' end,
        case new.status when 'paid' then 'Payment received: ' else 'Payment failed: ' end || coalesce(v_hosp, 'hospital'),
        '₹' || to_char(new.total_paise / 100.0, 'FM99,99,99,990.00') || ' · ' || case new.kind when 'plan' then coalesce(new.plan, '') || ' plan' else 'wallet top-up' end,
        '/hospitals/' || new.tenant_id, 'payment:' || new.id || ':' || new.status, 1440);
    end if;
  elsif tg_table_name = 'platform_incidents' then
    perform public.raise_platform_alert_safe('incident_new', 'Incident: ' || new.title,
      initcap(new.severity) || ' severity' || case when new.personal_data then ' · personal data involved' else '' end, '/incidents', null, 60,
      case when new.severity in ('high', 'critical') then 'critical' else 'warning' end);
  end if;
  return new;
end $$;

drop trigger if exists trg_ops_alert on public.platform_signups;
create trigger trg_ops_alert after insert on public.platform_signups for each row execute function public.ops_alert_trigger();
drop trigger if exists trg_ops_alert on public.platform_leads;
create trigger trg_ops_alert after insert on public.platform_leads for each row execute function public.ops_alert_trigger();
drop trigger if exists trg_ops_alert on public.billing_payments;
create trigger trg_ops_alert after insert or update of status on public.billing_payments for each row execute function public.ops_alert_trigger();
drop trigger if exists trg_ops_alert on public.platform_incidents;
create trigger trg_ops_alert after insert on public.platform_incidents for each row execute function public.ops_alert_trigger();

-- hourly: trials ending soon and wallets running low (each at most once a day per hospital)
create or replace function public.run_platform_hourly_alerts()
returns int language plpgsql volatile security definer set search_path = public as $$
declare cfg jsonb := public.ops_config(); t record; n int := 0;
        v_days int := greatest(coalesce((cfg #>> '{thresholds,trialDays}')::int, 3), 1);
        v_low bigint := greatest(coalesce((cfg #>> '{thresholds,walletLowPaise}')::bigint, 0), 0);
begin
  for t in select id, name, trial_ends_at from public.tenants
            where not is_primary and closing_at is null and trial_ends_at between now() and now() + make_interval(days => v_days)
              and coalesce(paid_until, '-infinity'::timestamptz) < trial_ends_at loop
    if public.raise_platform_alert('trial_ending', 'Trial ending: ' || t.name,
         'The free trial ends on ' || to_char(t.trial_ends_at at time zone 'Asia/Kolkata', 'DD Mon YYYY') || ' and no plan has been paid yet.',
         '/hospitals/' || t.id, 'trial:' || t.id || ':' || current_date, 1440) is not null then n := n + 1; end if;
  end loop;
  if v_low > 0 then
    for t in select id, name, wallet_paise from public.tenants
              where not is_primary and closing_at is null and status in ('active', 'grace', 'trial') and wallet_paise < v_low loop
      if public.raise_platform_alert('wallet_low', 'Wallet low: ' || t.name,
           'Balance ₹' || to_char(t.wallet_paise / 100.0, 'FM99,99,99,990.00') || ' — messages beyond the plan stop when it runs out.',
           '/hospitals/' || t.id, 'wallet:' || t.id || ':' || current_date, 1440) is not null then n := n + 1; end if;
    end loop;
  end if;
  return n;
end $$;

-- the signed-in member's bell
create or replace function public.cp_alerts(p_limit int default 30, p_unread_only boolean default false)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require();
  return jsonb_build_object(
    'unread', (select count(*) from public.platform_alert_inbox where user_id = auth.uid() and read_at is null),
    'items', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'created_at', x.created_at, 'event', x.event, 'severity', x.severity,
                         'title', x.title, 'body', x.body, 'link', x.link, 'read_at', x.read_at) order by x.created_at desc)
                         from (select a.*, i.read_at from public.platform_alert_inbox i join public.platform_alerts a on a.id = i.alert_id
                                where i.user_id = auth.uid() and (not p_unread_only or i.read_at is null)
                                order by a.created_at desc limit greatest(1, least(coalesce(p_limit, 30), 200))) x), '[]'::jsonb));
end $$;

create or replace function public.cp_alerts_read(p_ids uuid[] default null)
returns int language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.cp_require();
  update public.platform_alert_inbox set read_at = now() where user_id = auth.uid() and read_at is null and (p_ids is null or alert_id = any (p_ids));
  return (select count(*)::int from public.platform_alert_inbox where user_id = auth.uid() and read_at is null);
end $$;

-- put alerts back to unread (the member's own only)
create or replace function public.cp_alerts_unread(p_ids uuid[])
returns int language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.cp_require();
  update public.platform_alert_inbox set read_at = null where user_id = auth.uid() and read_at is not null and alert_id = any (coalesce(p_ids, '{}'));
  return (select count(*)::int from public.platform_alert_inbox where user_id = auth.uid() and read_at is null);
end $$;

-- the member's own choices, limited to the events their role receives and the channels an admin switched on
create or replace function public.cp_alert_prefs()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_role text := public.cp_require(); cfg jsonb := public.ops_config(); pr public.platform_alert_prefs;
begin
  select * into pr from public.platform_alert_prefs where user_id = auth.uid();
  return jsonb_build_object(
    'channels', cfg -> 'channels',
    'events', coalesce((select jsonb_agg(e || jsonb_build_object(
                  'enabled', coalesce((cfg #>> array['events', e ->> 'key', 'enabled'])::boolean, true),
                  'severity', coalesce(nullif(cfg #>> array['events', e ->> 'key', 'severity'], ''), e ->> 'severity'),
                  'mine', case when jsonb_typeof(pr.events -> (e ->> 'key')) = 'array' then pr.events -> (e ->> 'key')
                               else to_jsonb(public.ops_default_channels(coalesce(nullif(cfg #>> array['events', e ->> 'key', 'severity'], ''), e ->> 'severity'))) end))
                 from jsonb_array_elements(public.ops_alert_catalog()) e where v_role = 'admin' or e -> 'roles' ? v_role), '[]'::jsonb),
    'whatsapp', pr.whatsapp,
    'devices', (select count(*) from public.cp_push_tokens where user_id = auth.uid()));
end $$;

create or replace function public.cp_save_alert_prefs(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v_ev jsonb := '{}'::jsonb; k text; v jsonb; v_wa text := nullif(regexp_replace(coalesce(p ->> 'whatsapp', ''), '\D', '', 'g'), '');
begin
  perform public.cp_require();
  if v_wa is not null then v_wa := right(v_wa, 10); if char_length(v_wa) <> 10 then raise exception 'Enter a 10-digit WhatsApp number.'; end if; end if;
  for k, v in select key, value from jsonb_each(coalesce(p -> 'events', '{}'::jsonb)) loop
    if not exists (select 1 from jsonb_array_elements(public.ops_alert_catalog()) e where e ->> 'key' = k) then raise exception 'Unknown alert %', k; end if;
    if jsonb_typeof(v) <> 'array' or exists (select 1 from jsonb_array_elements_text(v) c where c not in ('bell', 'email', 'push', 'whatsapp')) then
      raise exception 'Unknown channel for %', k;
    end if;
    v_ev := v_ev || jsonb_build_object(k, v);
  end loop;
  insert into public.platform_alert_prefs (user_id, events, whatsapp, updated_at) values (auth.uid(), v_ev, v_wa, now())
  on conflict (user_id) do update set events = excluded.events, whatsapp = excluded.whatsapp, updated_at = now();
  return public.cp_alert_prefs();
end $$;

-- admin: which channels / events exist platform-wide, limits and the address used for health checks and links
create or replace function public.cp_ops_settings()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return public.ops_config() || jsonb_build_object('catalog', public.ops_alert_catalog());
end $$;

create or replace function public.cp_save_ops_settings(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare cur jsonb := public.ops_config(); out jsonb := '{}'::jsonb; v_url text;
begin
  perform public.cp_require(array['admin']);
  p := coalesce(p, '{}'::jsonb);
  -- a section left out keeps its current values
  out := jsonb_build_object('channels', (select jsonb_object_agg(c, coalesce((p #>> array['channels', c])::boolean, (cur #>> array['channels', c])::boolean))
                                          from jsonb_object_keys(cur -> 'channels') c));
  out := out || jsonb_build_object('events', coalesce((select jsonb_object_agg(e ->> 'key', jsonb_build_object(
            'enabled', coalesce((p #>> array['events', e ->> 'key', 'enabled'])::boolean, (cur #>> array['events', e ->> 'key', 'enabled'])::boolean, true),
            'severity', case when p #>> array['events', e ->> 'key', 'severity'] in ('info', 'warning', 'critical') then p #>> array['events', e ->> 'key', 'severity']
                             when cur #>> array['events', e ->> 'key', 'severity'] in ('info', 'warning', 'critical') then cur #>> array['events', e ->> 'key', 'severity']
                             else e ->> 'severity' end))
           from jsonb_array_elements(public.ops_alert_catalog()) e), '{}'::jsonb));
  out := out || jsonb_build_object('thresholds', (select jsonb_object_agg(t, greatest(0, coalesce(nullif(p #>> array['thresholds', t], '')::numeric, (cur #>> array['thresholds', t])::numeric)))
                                                   from jsonb_object_keys(cur -> 'thresholds') t));
  if (out #>> '{thresholds,dbPct}')::numeric > 100 or (out #>> '{thresholds,failurePct}')::numeric > 100 then raise exception 'Percentages must be 100 or less.'; end if;
  v_url := trim(both '/' from trim(coalesce(case when p -> 'health' ? 'siteUrl' then p #>> '{health,siteUrl}' else cur #>> '{health,siteUrl}' end, '')));
  if v_url <> '' and v_url !~ '^https://[a-z0-9.-]+(:[0-9]+)?(/[^ ]*)?$' then raise exception 'Platform address must start with https://'; end if;
  out := out || jsonb_build_object('health', jsonb_build_object('enabled', coalesce((p #>> '{health,enabled}')::boolean, (cur #>> '{health,enabled}')::boolean, true), 'siteUrl', v_url));
  insert into public.platform_settings (key, data, updated_at, updated_by) values ('ops', out, now(), auth.uid())
  on conflict (key) do update set data = excluded.data, updated_at = now(), updated_by = auth.uid();
  insert into public.provider_audit (user_id, user_name, mode, action, target, detail)
  values (auth.uid(), (select full_name from public.profiles where id = auth.uid()), 'admin', 'ops:settings', 'alerts & health', out);
  return public.cp_ops_settings();
end $$;

-- ------------------------------------------------------------------ 4. broadcasts
create table if not exists public.platform_broadcasts (
  id               uuid primary key default gen_random_uuid(),
  title            text not null check (char_length(title) between 3 and 120),
  body             text not null default '' check (char_length(body) <= 2000),
  link             text check (link is null or (link ~ '^https://' and char_length(link) <= 300)),
  level            text not null default 'info' check (level in ('info', 'warning', 'critical')),
  channels         text[] not null default array['inapp'],
  audience         jsonb not null default '{}'::jsonb,   -- { hospitals: [ids]|null, plans: [], statuses: [], roles: [] }
  status           text not null default 'draft' check (status in ('draft', 'scheduled', 'sent', 'cancelled')),
  scheduled_at     timestamptz,
  sent_at          timestamptz,
  announcement_id  uuid references public.platform_announcements (id) on delete set null,
  stats            jsonb not null default '{}'::jsonb,
  created_by       uuid,
  created_by_name  text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  check (channels <@ array['inapp', 'email', 'sms', 'whatsapp', 'push'] and cardinality(channels) > 0)
);
alter table public.platform_broadcasts enable row level security;
revoke all on public.platform_broadcasts from anon, authenticated;
grant all on public.platform_broadcasts to service_role;

-- hospital staff matching an audience (hospitals that are closing are left out)
create or replace function public.broadcast_recipients(p_audience jsonb)
returns table (tenant_id uuid, hospital text, profile_id uuid, role text, full_name text, email text, phone text)
language plpgsql stable security definer set search_path = public as $$
declare
  a jsonb := coalesce(p_audience, '{}'::jsonb);
  v_ids uuid[] := case when jsonb_typeof(a -> 'hospitals') = 'array' and jsonb_array_length(a -> 'hospitals') > 0
                       then (select array_agg(x::uuid) from jsonb_array_elements_text(a -> 'hospitals') x) end;
  v_plans text[] := case when jsonb_typeof(a -> 'plans') = 'array' and jsonb_array_length(a -> 'plans') > 0 then (select array_agg(x) from jsonb_array_elements_text(a -> 'plans') x) end;
  v_statuses text[] := case when jsonb_typeof(a -> 'statuses') = 'array' and jsonb_array_length(a -> 'statuses') > 0 then (select array_agg(x) from jsonb_array_elements_text(a -> 'statuses') x) end;
  v_roles text[] := coalesce(case when jsonb_typeof(a -> 'roles') = 'array' and jsonb_array_length(a -> 'roles') > 0 then (select array_agg(x) from jsonb_array_elements_text(a -> 'roles') x) end, array['owner']);
begin
  if exists (select 1 from unnest(v_roles) x where x not in ('owner', 'doctor', 'receptionist', 'accountant', 'staff')) then raise exception 'Broadcasts go to staff roles only.'; end if;
  return query
    select t.id, t.name, p.id, p.role::text, p.full_name, coalesce(nullif(p.email, ''), u.email), nullif(right(regexp_replace(coalesce(p.phone, ''), '\D', '', 'g'), 10), '')
      from public.tenants t
      join public.profiles p on p.tenant_id = t.id and p.role::text = any (v_roles)
      left join auth.users u on u.id = p.id
     where t.closing_at is null
       and (v_ids is null or t.id = any (v_ids))
       and (v_plans is null or t.plan = any (v_plans))
       and (v_statuses is null or t.status = any (v_statuses))
       and coalesce(u.banned_until, '-infinity'::timestamptz) < now();
end $$;

create or replace function public.cp_broadcast_preview(p_audience jsonb, p_channels text[] default array['inapp'])
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return (select jsonb_build_object(
      'hospitals', count(distinct r.tenant_id), 'people', count(*),
      'email', count(*) filter (where coalesce(r.email, '') ~ '@'),
      'sms', count(*) filter (where char_length(coalesce(r.phone, '')) = 10),
      'whatsapp', count(*) filter (where char_length(coalesce(r.phone, '')) = 10),
      'push', count(*) filter (where exists (select 1 from public.push_tokens k where k.profile_id = r.profile_id)),
      'sample', coalesce((select jsonb_agg(distinct x.hospital) from (select hospital from public.broadcast_recipients(p_audience) limit 50) x), '[]'::jsonb))
    from public.broadcast_recipients(p_audience) r);
end $$;

create or replace function public.cp_save_broadcast(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v_id uuid := nullif(p ->> 'id', '')::uuid; r public.platform_broadcasts; v_ch text[]; v_aud jsonb;
begin
  perform public.cp_require(array['admin']);
  v_ch := coalesce((select array_agg(distinct x) from jsonb_array_elements_text(coalesce(p -> 'channels', '["inapp"]'::jsonb)) x), array['inapp']);
  v_aud := jsonb_build_object('hospitals', coalesce(p #> '{audience,hospitals}', 'null'::jsonb), 'plans', coalesce(p #> '{audience,plans}', '[]'::jsonb),
                              'statuses', coalesce(p #> '{audience,statuses}', '[]'::jsonb), 'roles', coalesce(p #> '{audience,roles}', '["owner"]'::jsonb));
  perform 1 from public.broadcast_recipients(v_aud) limit 1;   -- validates roles
  if v_id is null then
    insert into public.platform_broadcasts (title, body, link, level, channels, audience, created_by, created_by_name)
    values (trim(coalesce(p ->> 'title', '')), trim(coalesce(p ->> 'body', '')), nullif(trim(coalesce(p ->> 'link', '')), ''), coalesce(nullif(p ->> 'level', ''), 'info'),
            v_ch, v_aud, auth.uid(), (select full_name from public.profiles where id = auth.uid()))
    returning * into r;
  else
    update public.platform_broadcasts set title = trim(coalesce(p ->> 'title', title)), body = trim(coalesce(p ->> 'body', body)),
           link = nullif(trim(coalesce(p ->> 'link', '')), ''), level = coalesce(nullif(p ->> 'level', ''), level), channels = v_ch, audience = v_aud, updated_at = now()
     where id = v_id and status in ('draft', 'scheduled') returning * into r;
    if not found then raise exception 'Only drafts and scheduled broadcasts can be changed.'; end if;
  end if;
  return to_jsonb(r);
end $$;

-- queue a broadcast on every chosen channel (called right away, or by the scheduler when its time comes)
create or replace function public.broadcast_dispatch(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare b public.platform_broadcasts; v_ann uuid; v_ids uuid[]; st jsonb := '{}'::jsonb; n int; v_text text;
begin
  select * into b from public.platform_broadcasts where id = p_id for update;
  if not found or b.status not in ('draft', 'scheduled') then raise exception 'This broadcast was already sent or cancelled.'; end if;
  v_text := b.title || case when b.body <> '' then E'\n\n' || b.body else '' end || case when b.link is not null then E'\n\n' || b.link else '' end;
  create temporary table if not exists _bc_people (tenant_id uuid, hospital text, profile_id uuid, role text, full_name text, email text, phone text) on commit drop;
  truncate _bc_people;
  insert into _bc_people select * from public.broadcast_recipients(b.audience);
  if 'inapp' = any (b.channels) then
    v_ids := (select array_agg(distinct tenant_id) from _bc_people);
    insert into public.platform_announcements (title, body, level, hospital_ids, roles, starts_at, ends_at, active, created_by, created_by_name)
    values (left(b.title, 120), left(b.body, 1000), b.level,
            case when jsonb_typeof(b.audience -> 'hospitals') = 'array' or jsonb_array_length(coalesce(b.audience -> 'plans', '[]')) > 0 or jsonb_array_length(coalesce(b.audience -> 'statuses', '[]')) > 0
                 then coalesce(v_ids, array[]::uuid[]) end,
            array(select jsonb_array_elements_text(coalesce(b.audience -> 'roles', '["owner"]'))), now(), now() + interval '14 days', true, b.created_by, b.created_by_name)
    returning id into v_ann;
    st := st || jsonb_build_object('inapp', coalesce(array_length(v_ids, 1), 0));
  end if;
  if 'email' = any (b.channels) then
    insert into public.platform_outbox (kind, ref_id, channel, recipient, hospital_id, subject, body, vars)
    select distinct on (lower(email)) 'broadcast', b.id, 'email', email, tenant_id, b.title, v_text, jsonb_build_object('name', coalesce(full_name, ''), 'hospital', hospital, 'title', b.title, 'link', coalesce(b.link, ''))
      from _bc_people where email ~ '@';
    get diagnostics n = row_count; st := st || jsonb_build_object('email', n);
  end if;
  if 'sms' = any (b.channels) then
    insert into public.platform_outbox (kind, ref_id, channel, recipient, hospital_id, subject, body, vars)
    select distinct on (phone) 'broadcast', b.id, 'sms', phone, tenant_id, b.title, v_text, jsonb_build_object('name', coalesce(full_name, ''), 'hospital', hospital, 'title', b.title, 'link', coalesce(b.link, ''))
      from _bc_people where char_length(coalesce(phone, '')) = 10;
    get diagnostics n = row_count; st := st || jsonb_build_object('sms', n);
  end if;
  if 'whatsapp' = any (b.channels) then
    insert into public.platform_outbox (kind, ref_id, channel, recipient, hospital_id, subject, body, vars)
    select distinct on (phone) 'broadcast', b.id, 'whatsapp', phone, tenant_id, b.title, v_text, jsonb_build_object('name', coalesce(full_name, ''), 'hospital', hospital, 'title', b.title, 'link', coalesce(b.link, ''))
      from _bc_people where char_length(coalesce(phone, '')) = 10;
    get diagnostics n = row_count; st := st || jsonb_build_object('whatsapp', n);
  end if;
  if 'push' = any (b.channels) then
    -- the hospital's own Firebase devices, through its own queue (push costs nothing)
    insert into public.notification_outbox (tenant_id, event, channel, recipient, subject, body, vars, related_table, related_id)
    select p.tenant_id, 'platform_broadcast', 'push', p.profile_id::text, b.title, coalesce(nullif(b.body, ''), b.title), jsonb_build_object('link', coalesce(b.link, '')), 'platform_broadcasts', b.id
      from _bc_people p where exists (select 1 from public.push_tokens k where k.profile_id = p.profile_id);
    get diagnostics n = row_count; st := st || jsonb_build_object('push', n);
  end if;
  update public.platform_broadcasts set status = 'sent', sent_at = now(), announcement_id = v_ann, stats = st, updated_at = now() where id = b.id;
  insert into public.provider_audit (user_id, user_name, mode, action, target, detail)
  values (coalesce(auth.uid(), b.created_by), coalesce((select full_name from public.profiles where id = auth.uid()), b.created_by_name), 'admin', 'broadcast:send', b.title,
          jsonb_build_object('id', b.id, 'channels', to_jsonb(b.channels), 'queued', st));
  return st;
end $$;

create or replace function public.cp_send_broadcast(p_id uuid, p_at timestamptz default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare b public.platform_broadcasts;
begin
  perform public.cp_require(array['admin']);
  select * into b from public.platform_broadcasts where id = p_id;
  if not found then raise exception 'Broadcast not found.'; end if;
  if b.status not in ('draft', 'scheduled') then raise exception 'This broadcast was already sent or cancelled.'; end if;
  if p_at is not null and p_at > now() + interval '1 minute' then
    if p_at > now() + interval '90 days' then raise exception 'Schedule within the next 90 days.'; end if;
    update public.platform_broadcasts set status = 'scheduled', scheduled_at = p_at, updated_at = now() where id = p_id returning * into b;
    return to_jsonb(b);
  end if;
  perform public.broadcast_dispatch(p_id);
  return (select to_jsonb(x) from public.platform_broadcasts x where id = p_id);
end $$;

create or replace function public.cp_cancel_broadcast(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare b public.platform_broadcasts;
begin
  perform public.cp_require(array['admin']);
  select * into b from public.platform_broadcasts where id = p_id;
  if not found then raise exception 'Broadcast not found.'; end if;
  if b.status = 'draft' then delete from public.platform_broadcasts where id = p_id; return null; end if;
  if b.status <> 'scheduled' then raise exception 'Only drafts and scheduled broadcasts can be cancelled.'; end if;
  update public.platform_broadcasts set status = 'cancelled', updated_at = now() where id = p_id returning * into b;
  return to_jsonb(b);
end $$;

create or replace function public.cp_broadcasts(p_limit int default 50)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return coalesce((select jsonb_agg(to_jsonb(b) || jsonb_build_object('delivery', coalesce((
             select jsonb_object_agg(channel, s) from (
               select channel, jsonb_build_object('sent', count(*) filter (where status = 'sent'), 'failed', count(*) filter (where status in ('failed', 'skipped')),
                                                  'pending', count(*) filter (where status in ('pending', 'sending'))) s
                 from (select channel, status from public.platform_outbox where ref_id = b.id
                       union all select channel, status from public.notification_outbox where related_table = 'platform_broadcasts' and related_id = b.id) x
                group by channel) y), '{}'::jsonb)) order by b.created_at desc)
     from (select * from public.platform_broadcasts order by created_at desc limit greatest(1, least(coalesce(p_limit, 50), 200))) b), '[]'::jsonb);
end $$;

create or replace function public.run_due_broadcasts()
returns int language plpgsql volatile security definer set search_path = public as $$
declare r record; n int := 0;
begin
  for r in select id from public.platform_broadcasts where status = 'scheduled' and scheduled_at <= now() order by scheduled_at limit 5 loop
    begin perform public.broadcast_dispatch(r.id); n := n + 1;
    exception when others then raise warning 'broadcast % not sent: %', r.id, sqlerrm; end;
  end loop;
  return n;
end $$;

-- ------------------------------------------------------------------ delivery log (every hospital + the platform)
create or replace function public.cp_delivery_log(p jsonb default '{}'::jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_src text := coalesce(nullif(p ->> 'source', ''), 'all');
  v_status text := nullif(p ->> 'status', ''); v_channel text := nullif(p ->> 'channel', '');
  v_hosp uuid := nullif(p ->> 'hospital', '')::uuid; v_q text := nullif(trim(coalesce(p ->> 'q', '')), '');
  v_limit int := greatest(1, least(coalesce((p ->> 'limit')::int, 100), 300));
begin
  perform public.cp_require(array['admin']);
  return coalesce((select jsonb_agg(x order by x.created_at desc) from (
      select * from (
        select 'hospital' as source, o.id, o.created_at, o.tenant_id as hospital_id, t.name as hospital, o.event as kind, o.channel, o.status, o.attempts, o.error, o.provider_ref,
               case when o.channel = 'push' then 'device' else o.recipient end as recipient, o.subject, o.sent_at
          from public.notification_outbox o left join public.tenants t on t.id = o.tenant_id
         where v_src in ('all', 'hospital')
           and (v_status is null or o.status = v_status or (v_status = 'failed' and o.status = 'skipped'))
           and (v_channel is null or o.channel = v_channel) and (v_hosp is null or o.tenant_id = v_hosp)
           and (v_q is null or o.recipient ilike '%' || v_q || '%' or o.event ilike '%' || v_q || '%' or coalesce(o.error, '') ilike '%' || v_q || '%')
         order by o.created_at desc limit v_limit) a
      union all
      select * from (
        select 'platform', o.id, o.created_at, o.hospital_id, t.name, o.kind, o.channel, o.status, o.attempts, o.error, o.provider_ref,
               case when o.channel = 'push' then 'team device' else o.recipient end, o.subject, o.sent_at
          from public.platform_outbox o left join public.tenants t on t.id = o.hospital_id
         where v_src in ('all', 'platform')
           and (v_status is null or o.status = v_status or (v_status = 'failed' and o.status = 'skipped'))
           and (v_channel is null or o.channel = v_channel) and (v_hosp is null or o.hospital_id = v_hosp)
           and (v_q is null or o.recipient ilike '%' || v_q || '%' or o.kind ilike '%' || v_q || '%' or coalesce(o.error, '') ilike '%' || v_q || '%')
         order by o.created_at desc limit v_limit) b
      order by created_at desc limit v_limit) x), '[]'::jsonb);
end $$;

create or replace function public.cp_retry_message(p_source text, p_id uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  if p_source = 'platform' then
    update public.platform_outbox set status = 'pending', attempts = 0, error = null, next_attempt_at = now() where id = p_id and status in ('failed', 'skipped');
  elsif p_source = 'hospital' then
    update public.notification_outbox set status = 'pending', attempts = 0, error = null, next_attempt_at = now()
     where id = p_id and status in ('failed', 'skipped') and event not in ('otp', 'password_otp', 'test');
  else raise exception 'Unknown source.'; end if;
  if not found then raise exception 'Only failed messages can be retried (one-time codes and tests cannot).'; end if;
  insert into public.provider_audit (user_id, user_name, mode, action, target, detail)
  values (auth.uid(), (select full_name from public.profiles where id = auth.uid()), 'admin', 'message:retry', p_source, jsonb_build_object('id', p_id));
end $$;

-- ------------------------------------------------------------------ 5. health
create table if not exists public.platform_health_checks (
  id          bigint generated always as identity primary key,
  checked_at  timestamptz not null default now(),
  service     text not null check (char_length(service) between 2 and 60),
  status      text not null check (status in ('ok', 'warn', 'fail', 'off')),
  latency_ms  int,
  detail      text check (char_length(detail) <= 500)
);
create index if not exists platform_health_checks_idx on public.platform_health_checks (service, checked_at desc);
create index if not exists platform_health_checks_at_idx on public.platform_health_checks (checked_at);
alter table public.platform_health_checks enable row level security;
revoke all on public.platform_health_checks from anon, authenticated;
grant all on public.platform_health_checks to service_role;

create table if not exists public.platform_health_state (
  service          text primary key,
  label            text,
  grp              text,
  status           text not null,
  since            timestamptz not null default now(),
  last_checked_at  timestamptz not null default now(),
  latency_ms       int,
  detail           text
);
alter table public.platform_health_state enable row level security;
revoke all on public.platform_health_state from anon, authenticated;
grant all on public.platform_health_state to service_role;

-- "last seen" times written by Edge Functions (Razorpay webhook received / rejected)
create table if not exists public.platform_heartbeats (
  key      text primary key check (key ~ '^[a-z0-9_:-]{2,60}$'),
  last_at  timestamptz not null default now(),
  detail   text check (char_length(detail) <= 300),
  count    bigint not null default 1
);
alter table public.platform_heartbeats enable row level security;
revoke all on public.platform_heartbeats from anon, authenticated;
grant all on public.platform_heartbeats to service_role;

create or replace function public.note_heartbeat(p_key text, p_detail text default null)
returns void language sql volatile security definer set search_path = public as $$
  insert into public.platform_heartbeats (key, last_at, detail) values (p_key, now(), left(p_detail, 300))
  on conflict (key) do update set last_at = now(), detail = excluded.detail, count = public.platform_heartbeats.count + 1;
$$;

-- the database's own checks: size, connections, storage, message queues, delivery failures, scheduler, Razorpay webhook
create or replace function public.platform_db_checks()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  th jsonb := public.ops_config() -> 'thresholds';
  v_size bigint := pg_database_size(current_database());
  v_limit numeric := greatest(coalesce((th ->> 'dbLimitMb')::numeric, 8192), 1) * 1024 * 1024;
  v_pct numeric; v_backlog int; v_total int; v_failed int; v_fpct numeric; v_cron boolean := exists (select 1 from pg_extension where extname = 'pg_cron');
  v_last timestamptz; v_bad int := 0; out jsonb := '[]'::jsonb; v_q int := greatest(coalesce((th ->> 'queueBacklog')::int, 200), 1);
  v_conn int; v_max int; v_cpct numeric; v_st bigint; v_slimit numeric; v_spct numeric;
  v_hours int := greatest(coalesce((th ->> 'webhookHours')::int, 24), 1); v_wh timestamptz; v_whbad timestamptz; v_paid int; v_oldest timestamptz;
begin
  -- connections in use vs max_connections
  select count(*) into v_conn from pg_stat_activity;
  v_max := greatest(coalesce(current_setting('max_connections', true)::int, 100), 1);
  v_cpct := round(v_conn * 100.0 / v_max, 1);
  out := out || jsonb_build_object('service', 'db:connections', 'label', 'Database connections', 'group', 'Database',
    'status', case when v_cpct >= greatest(coalesce((th ->> 'connPct')::numeric, 80), 95) then 'fail' when v_cpct >= coalesce((th ->> 'connPct')::numeric, 80) then 'warn' else 'ok' end,
    'detail', v_conn || ' of ' || v_max || ' in use (' || v_cpct || '%)');
  -- file storage used (all buckets) vs the plan's limit
  if exists (select 1 from information_schema.columns where table_schema = 'storage' and table_name = 'objects' and column_name = 'metadata') then
    execute $q$ select coalesce(sum((metadata ->> 'size')::bigint), 0) from storage.objects $q$ into v_st;
    v_slimit := greatest(coalesce((th ->> 'storageLimitMb')::numeric, 102400), 1) * 1024 * 1024;
    v_spct := round(v_st * 100.0 / v_slimit, 1);
    out := out || jsonb_build_object('service', 'storage:usage', 'label', 'File storage used', 'group', 'Database',
      'status', case when v_spct >= greatest(coalesce((th ->> 'storagePct')::numeric, 80), 95) then 'fail' when v_spct >= coalesce((th ->> 'storagePct')::numeric, 80) then 'warn' else 'ok' end,
      'detail', pg_size_pretty(v_st) || ' of ' || pg_size_pretty(v_slimit::bigint) || ' (' || v_spct || '%)');
  end if;
  -- Razorpay webhook: every online payment marked paid should be followed by a webhook
  select last_at into v_wh from public.platform_heartbeats where key = 'razorpay_webhook';
  select last_at into v_whbad from public.platform_heartbeats where key = 'razorpay_webhook_bad';
  select count(*), min(paid_at) into v_paid, v_oldest from public.billing_payments
   where provider = 'razorpay' and status = 'paid' and paid_at > now() - make_interval(hours => v_hours) and paid_at < now() - interval '15 minutes';
  out := out || jsonb_build_object('service', 'webhook:razorpay', 'label', 'Razorpay webhook', 'group', 'Payments',
    'status', case when v_whbad is not null and v_whbad > coalesce(v_wh, '-infinity') and v_whbad > now() - make_interval(hours => v_hours) then 'warn'
                   when v_paid > 0 and coalesce(v_wh, '-infinity') < v_oldest then 'warn'
                   when v_wh is null then 'off' else 'ok' end,
    'detail', case when v_whbad is not null and v_whbad > coalesce(v_wh, '-infinity') and v_whbad > now() - make_interval(hours => v_hours)
                     then 'Webhooks are being rejected (bad signature) — the webhook secret in Razorpay and RAZORPAY_WEBHOOK_SECRET differ'
                   when v_paid > 0 and coalesce(v_wh, '-infinity') < v_oldest
                     then v_paid || ' online payment(s) in the last ' || v_hours || ' h but no webhook since — check Razorpay → Webhooks'
                   when v_wh is null then 'No webhook received yet'
                   else 'Last webhook ' || to_char(v_wh at time zone 'Asia/Kolkata', 'DD Mon HH24:MI') || ' IST' end);

  v_pct := round(v_size * 100.0 / v_limit, 1);
  out := out || jsonb_build_object('service', 'db:size', 'label', 'Database size', 'group', 'Database',
    'status', case when v_pct >= greatest(coalesce((th ->> 'dbPct')::numeric, 80), 95) then 'fail' when v_pct >= coalesce((th ->> 'dbPct')::numeric, 80) then 'warn' else 'ok' end,
    'detail', pg_size_pretty(v_size) || ' of ' || pg_size_pretty(v_limit::bigint) || ' (' || v_pct || '%)');
  select count(*) into v_backlog from (
    select 1 from public.notification_outbox where status = 'pending' and next_attempt_at < now() - interval '5 minutes'
    union all select 1 from public.platform_outbox where status = 'pending' and next_attempt_at < now() - interval '5 minutes') x;
  out := out || jsonb_build_object('service', 'db:queue', 'label', 'Message queue', 'group', 'Messages',
    'status', case when v_backlog >= v_q * 5 then 'fail' when v_backlog >= v_q then 'warn' else 'ok' end,
    'detail', v_backlog || ' messages waiting more than 5 minutes (limit ' || v_q || ')');
  select count(*), count(*) filter (where status in ('failed')) into v_total, v_failed from (
    select status from public.notification_outbox where status in ('sent', 'failed') and created_at > now() - interval '1 hour'
    union all select status from public.platform_outbox where status in ('sent', 'failed') and created_at > now() - interval '1 hour') x;
  v_fpct := case when v_total > 0 then round(v_failed * 100.0 / v_total, 1) else 0 end;
  out := out || jsonb_build_object('service', 'db:delivery', 'label', 'Delivery success', 'group', 'Messages',
    'status', case when v_total >= 10 and v_fpct >= coalesce((th ->> 'failurePct')::numeric, 10) then 'warn' else 'ok' end,
    'detail', case when v_total = 0 then 'No messages in the last hour' else v_failed || ' of ' || v_total || ' failed in the last hour (' || v_fpct || '%)' end);
  if not v_cron then
    out := out || jsonb_build_object('service', 'db:cron', 'label', 'Scheduler', 'group', 'Database', 'status', 'fail', 'detail', 'pg_cron is off — reminders, retries and these checks do not run');
  else
    execute $q$ select max(d.start_time) from cron.job j join cron.job_run_details d on d.jobid = j.jobid where j.jobname = 'dch-notify-flush' $q$ into v_last;
    execute $q$ select count(*) from cron.job j join lateral (select status from cron.job_run_details r where r.jobid = j.jobid order by start_time desc limit 1) d on true
                where j.jobname like 'dch-%' and d.status = 'failed' $q$ into v_bad;
    out := out || jsonb_build_object('service', 'db:cron', 'label', 'Scheduler', 'group', 'Database',
      'status', case when v_last is null or v_last < now() - interval '5 minutes' then 'fail' when v_bad > 0 then 'warn' else 'ok' end,
      'detail', case when v_last is null then 'The every-minute job has not run — turn on automatic delivery'
                     when v_last < now() - interval '5 minutes' then 'Last run ' || to_char(v_last at time zone 'Asia/Kolkata', 'DD Mon HH24:MI') || ' IST'
                     when v_bad > 0 then v_bad || ' job(s) failed on their last run' else 'All jobs running' end);
  end if;
  return out;
end $$;

-- p_results: [{ service, label, group, status: ok|warn|fail|off, latency_ms, detail }] from the ops function
create or replace function public.record_health(p_results jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare r record; v_prev text; v_all jsonb; v_lat int := greatest(coalesce((public.ops_config() #>> '{thresholds,latencyMs}')::int, 3000), 100);
begin
  v_all := coalesce(p_results, '[]'::jsonb) || public.platform_db_checks();
  for r in select * from jsonb_to_recordset(v_all) as x(service text, label text, "group" text, status text, latency_ms int, detail text) loop
    continue when r.service is null or r.status not in ('ok', 'warn', 'fail', 'off');
    if r.status = 'ok' and r.latency_ms is not null and r.latency_ms > v_lat then
      r.status := 'warn'; r.detail := coalesce(r.detail || ' · ', '') || 'slow (' || r.latency_ms || ' ms)';
    end if;
    insert into public.platform_health_checks (service, status, latency_ms, detail) values (left(r.service, 60), r.status, r.latency_ms, left(r.detail, 500));
    select status into v_prev from public.platform_health_state where service = r.service;
    insert into public.platform_health_state (service, label, grp, status, since, last_checked_at, latency_ms, detail)
    values (left(r.service, 60), coalesce(r.label, r.service), r."group", r.status, now(), now(), r.latency_ms, left(r.detail, 500))
    on conflict (service) do update set label = coalesce(r.label, public.platform_health_state.label), grp = coalesce(excluded.grp, public.platform_health_state.grp), status = excluded.status,
      since = case when public.platform_health_state.status = excluded.status then public.platform_health_state.since else now() end,
      last_checked_at = now(), latency_ms = excluded.latency_ms, detail = excluded.detail;
    if v_prev is distinct from r.status then
      if r.status in ('fail', 'warn') and r.service = 'db:cron' then
        perform public.raise_platform_alert_safe('job_late', coalesce(r.label, r.service) || case when r.status = 'fail' then ' stopped' else ' has failing jobs' end,
          coalesce(r.detail, ''), '/health', 'health:' || r.service || ':' || r.status, 60);
      elsif r.status in ('fail', 'warn') and r.service = 'db:delivery' then
        perform public.raise_platform_alert_safe('delivery_spike', 'Message failures spiking', coalesce(r.detail, ''), '/health', 'health:' || r.service || ':' || r.status, 60);
      elsif r.status = 'fail' then
        perform public.raise_platform_alert_safe('health_down', coalesce(r.label, r.service) || ' is down', coalesce(r.detail, ''), '/health', 'health:' || r.service || ':fail', 30);
      elsif r.status = 'warn' and coalesce(v_prev, 'ok') in ('ok', 'off') then
        perform public.raise_platform_alert_safe('threshold', coalesce(r.label, r.service) || ' needs attention', coalesce(r.detail, ''), '/health', 'health:' || r.service || ':warn', 60);
      elsif r.status = 'ok' and v_prev in ('fail', 'warn') then
        perform public.raise_platform_alert_safe('health_recovered', coalesce(r.label, r.service) || ' is back to normal', coalesce(r.detail, ''), '/health');
      end if;
    end if;
  end loop;
  return v_all;
end $$;

-- nightly clean-up (first tick after 02:00 India time): 30 days of health history, 180 of alerts, 90 of platform messages
create or replace function public.ops_nightly_cleanup(p_force boolean default false)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare v_now timestamp := now() at time zone 'Asia/Kolkata'; v_last timestamptz;
begin
  select last_at into v_last from public.platform_heartbeats where key = 'ops_cleanup';
  if not p_force and (extract(hour from v_now) < 2 or (v_last at time zone 'Asia/Kolkata')::date >= v_now::date) then return false; end if;
  delete from public.platform_health_checks where checked_at < now() - interval '30 days';
  delete from public.platform_alerts where created_at < now() - interval '180 days';
  delete from public.platform_outbox where created_at < now() - interval '90 days';
  perform public.note_heartbeat('ops_cleanup', null);
  return true;
end $$;

create or replace function public.cp_health_live()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin', 'support']);
  return jsonb_build_object(
    'last_run', (select max(last_checked_at) from public.platform_health_state),
    'settings', public.ops_config() -> 'health',
    'services', coalesce((select jsonb_agg(jsonb_build_object('service', s.service, 'label', s.label, 'group', s.grp, 'status', s.status, 'since', s.since,
        'last_checked_at', s.last_checked_at, 'latency_ms', s.latency_ms, 'detail', s.detail,
        'uptime24', (select round(100.0 * count(*) filter (where c.status in ('ok', 'warn')) / nullif(count(*) filter (where c.status <> 'off'), 0), 2)
                       from public.platform_health_checks c where c.service = s.service and c.checked_at > now() - interval '24 hours'),
        'uptime7d', (select round(100.0 * count(*) filter (where c.status in ('ok', 'warn')) / nullif(count(*) filter (where c.status <> 'off'), 0), 2)
                       from public.platform_health_checks c where c.service = s.service and c.checked_at > now() - interval '7 days'),
        'days', coalesce((select jsonb_agg(jsonb_build_object('d', d.d, 'ok', d.ok, 'n', d.n, 'ms', d.ms) order by d.d)
                    from (select date_trunc('day', c.checked_at at time zone 'Asia/Kolkata')::date d, count(*) filter (where c.status in ('ok', 'warn'))::int ok,
                                 count(*) filter (where c.status <> 'off')::int n, round(avg(c.latency_ms))::int ms
                            from public.platform_health_checks c where c.service = s.service and c.checked_at > now() - interval '7 days'
                           group by 1) d), '[]'::jsonb),
        'hours', coalesce((select jsonb_agg(jsonb_build_object('h', h.h, 'ok', h.ok, 'n', h.n, 'ms', h.ms) order by h.h)
                    from (select date_trunc('hour', c.checked_at) h, count(*) filter (where c.status in ('ok', 'warn'))::int ok,
                                 count(*) filter (where c.status <> 'off')::int n, round(avg(c.latency_ms))::int ms
                            from public.platform_health_checks c where c.service = s.service and c.checked_at > now() - interval '24 hours'
                           group by 1) h), '[]'::jsonb))
        order by s.grp nulls last, s.service) from public.platform_health_state s), '[]'::jsonb),
    'failures', coalesce((select jsonb_agg(jsonb_build_object('at', c.checked_at, 'service', c.service, 'label', coalesce(s.label, c.service), 'status', c.status, 'detail', c.detail) order by c.checked_at desc)
        from (select * from public.platform_health_checks where status in ('fail', 'warn') order by checked_at desc limit 50) c
        left join public.platform_health_state s on s.service = c.service), '[]'::jsonb));
end $$;

-- ------------------------------------------------------------------ scheduler (every minute, from notify_cron_flush)
create or replace function public.ops_call(p_body jsonb)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare v_url text := public.tenant_secret('notify_function_url'); v_key text := public.tenant_secret('service_role_key');
begin
  if v_url is null or v_key is null or not exists (select 1 from pg_extension where extname = 'pg_net') then return false; end if;
  v_url := regexp_replace(v_url, '/notify$', '/ops');
  execute 'select net.http_post(url := $1, headers := $2, body := $3, timeout_milliseconds := 55000)'
    using v_url, jsonb_build_object('Authorization', 'Bearer ' || v_key, 'Content-Type', 'application/json'), p_body;
  return true;
end $$;

create or replace function public.ops_cron_tick()
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_min int := extract(minute from now())::int;
begin
  perform public.run_due_broadcasts();
  if v_min = 7 then perform public.run_platform_hourly_alerts(); end if;
  perform public.ops_nightly_cleanup();
  if exists (select 1 from public.platform_outbox where status = 'pending' and next_attempt_at <= now()) then perform public.ops_call('{"flush": true}'::jsonb); end if;
  if v_min % 5 = 0 and coalesce((public.ops_config() #>> '{health,enabled}')::boolean, true) then perform public.ops_call('{"health": true}'::jsonb); end if;
exception when others then
  raise warning 'ops tick: %', sqlerrm;
end $$;

-- ------------------------------------------------------------------ grants
revoke all on function public.ops_defaults(), public.ops_alert_catalog(), public.ops_config(), public.platform_vault_on(), public.platform_secret_value(public.platform_secrets),
  public.platform_env(), public.claim_platform_outbox(int), public.ops_default_channels(text),
  public.raise_platform_alert(text, text, text, text, text, int, text, jsonb), public.raise_platform_alert_safe(text, text, text, text, text, int, text),
  public.run_platform_hourly_alerts(), public.broadcast_recipients(jsonb), public.broadcast_dispatch(uuid), public.run_due_broadcasts(),
  public.platform_db_checks(), public.record_health(jsonb), public.note_heartbeat(text, text), public.ops_nightly_cleanup(boolean), public.ops_call(jsonb), public.ops_cron_tick() from public, anon, authenticated;
grant execute on function public.platform_env(), public.claim_platform_outbox(int), public.record_health(jsonb), public.note_heartbeat(text, text), public.raise_platform_alert(text, text, text, text, text, int, text, jsonb) to service_role;

revoke all on function public.cp_messaging_setup(), public.cp_save_messaging_setup(jsonb, jsonb), public.cp_save_platform_templates(jsonb),
  public.cp_register_push(text, text), public.cp_unregister_push(text), public.cp_push_config(), public.cp_alerts(int, boolean), public.cp_alerts_read(uuid[]), public.cp_alerts_unread(uuid[]),
  public.cp_alert_prefs(), public.cp_save_alert_prefs(jsonb), public.cp_ops_settings(), public.cp_save_ops_settings(jsonb),
  public.cp_broadcast_preview(jsonb, text[]), public.cp_save_broadcast(jsonb), public.cp_send_broadcast(uuid, timestamptz), public.cp_cancel_broadcast(uuid),
  public.cp_broadcasts(int), public.cp_delivery_log(jsonb), public.cp_retry_message(text, uuid), public.cp_health_live() from public, anon;
grant execute on function public.cp_messaging_setup(), public.cp_save_messaging_setup(jsonb, jsonb), public.cp_save_platform_templates(jsonb),
  public.cp_register_push(text, text), public.cp_unregister_push(text), public.cp_push_config(), public.cp_alerts(int, boolean), public.cp_alerts_read(uuid[]), public.cp_alerts_unread(uuid[]),
  public.cp_alert_prefs(), public.cp_save_alert_prefs(jsonb), public.cp_ops_settings(), public.cp_save_ops_settings(jsonb),
  public.cp_broadcast_preview(jsonb, text[]), public.cp_save_broadcast(jsonb), public.cp_send_broadcast(uuid, timestamptz), public.cp_cancel_broadcast(uuid),
  public.cp_broadcasts(int), public.cp_delivery_log(jsonb), public.cp_retry_message(text, uuid), public.cp_health_live() to authenticated;


-- =====================================================================================================
--  OTP VERIFICATION — a one-time code after the password (hospital staff / patients and the Hospital Comrade team)
--
--  Hospital:  Settings → Security → "OTP on sign-in"  (app_settings 'app' → security.otp.login)
--             { enabled, channels: ['whatsapp','sms','email'], roles: 'staff' | 'all' }
--  Team:      Control panel → Platform settings → Security (platform_settings 'security' → loginOtp { enabled, channels })
--  Booking:   Settings → Security → "OTP on online booking" (security.otp.booking { enabled, channels }) — see booking.sql
--
--  How it is enforced: a sign-in is verified per Supabase session (the session_id claim of the access token). Until the
--  code is entered, current_tenant() returns null for that hospital account (every tenant table is hidden by the
--  restrictive tenant_isolation policy) and provider_role() returns null for a team account (every cp_* function and
--  the panel's Edge Functions refuse). So skipping the code screen in the browser gets nothing.
--
--    login_otp_status()            what the sign-in screen needs: required? verified? which channels (masked)
--    request_login_otp(channel)    6-digit code, 10 minutes, 1 per 30 s, 5 per hour per account, 10 per hour per connection
--    verify_login_otp(code)        5 attempts per code → this session is verified
--    login_otp_carry(session)      a fresh password sign-in of an already verified session (re-confirm password) keeps it
--
--  Never locks an account out: a person with no deliverable channel (no mobile on file, channel switched off) is let in
--  — the settings screens show who that affects. Turning sign-in OTP on requires the person doing it to have verified a
--  code in this session first, so a broken channel can't lock out the owner / the admin.
--  "Sign in as user" sessions from the control panel count as verified (the admin proved who they are).
-- =====================================================================================================

create table if not exists public.login_otps (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null,
  session_id   text not null,
  scope        text not null check (scope in ('hospital', 'team')),
  hospital_id  uuid,                         -- not tenant_id: read before the hospital is known to the session
  channel      text not null check (channel in ('email', 'sms', 'whatsapp')),
  code_hash    text not null,
  attempts     int not null default 0,
  expires_at   timestamptz not null,
  verified_at  timestamptz,
  ip_hash      text,
  created_at   timestamptz not null default now()
);
create index if not exists login_otps_user_idx on public.login_otps (user_id, created_at desc);
create index if not exists login_otps_ip_idx on public.login_otps (ip_hash, created_at desc) where ip_hash is not null;
alter table public.login_otps enable row level security;   -- no policies: unreachable through the API
revoke all on public.login_otps from anon, authenticated;
grant all on public.login_otps to service_role;

create table if not exists public.login_otp_sessions (
  session_id   text not null,
  scope        text not null check (scope in ('hospital', 'team')),
  user_id      uuid not null,
  channel      text,
  verified_at  timestamptz not null default now(),
  primary key (session_id, scope)
);
create index if not exists login_otp_sessions_user_idx on public.login_otp_sessions (user_id);
alter table public.login_otp_sessions enable row level security;
revoke all on public.login_otp_sessions from anon, authenticated;
grant all on public.login_otp_sessions to service_role;

-- team sign-in codes go out through the control panel's queue (cp_notify.sql) as kind 'otp'
do $$ begin
  if to_regclass('public.platform_outbox') is not null then
    alter table public.platform_outbox drop constraint if exists platform_outbox_kind_check;
    alter table public.platform_outbox add constraint platform_outbox_kind_check check (kind in ('alert', 'broadcast', 'test', 'otp'));
  end if;
end $$;

-- ------------------------------------------------------------------ settings
-- a hospital's OTP settings with defaults (sign-in off; booking on, channels from the Notifications events)
create or replace function public.otp_config(p_tenant uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare s jsonb;
begin
  select data -> 'security' -> 'otp' into s from public.app_settings where key = 'app' and tenant_id = p_tenant;
  s := coalesce(s, '{}'::jsonb);
  return jsonb_build_object(
    'login', jsonb_build_object('enabled', false, 'channels', '["whatsapp","sms","email"]'::jsonb, 'roles', 'staff') || coalesce(s -> 'login', '{}'::jsonb),
    'booking', jsonb_build_object('enabled', true, 'channels', null) || coalesce(s -> 'booking', '{}'::jsonb));
end $$;

create or replace function public.team_otp_config()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('enabled', false, 'channels', '["email","whatsapp","sms"]'::jsonb)
         || coalesce((select data -> 'loginOtp' from public.platform_settings where key = 'security'), '{}'::jsonb)
$$;

-- wording used when a hospital never saved one (the Settings screen saves its own)
create or replace function public.otp_default_template(p_event text)
returns jsonb language sql immutable as $$
  select case p_event
    when 'login_otp' then jsonb_build_object('text', '{code} is your {hospital} sign-in code. It is valid for 10 minutes. Do not share it with anyone.', 'subject', 'Your sign-in code')
    when 'otp' then jsonb_build_object('text', '{code} is your {hospital} booking code. It is valid for 10 minutes. Do not share it with anyone.', 'subject', 'Your booking code')
    else jsonb_build_object('text', '{code} is your verification code. It is valid for 10 minutes.', 'subject', 'Your verification code') end
$$;

create or replace function public.mask_destination(p_channel text, p_to text)
returns text language sql immutable as $$
  select case when p_channel = 'email'
    then left(split_part(p_to, '@', 1), 2) || '•••@' || split_part(p_to, '@', 2)
    else '+91 •••••' || right(p_to, 5) end
$$;

-- ------------------------------------------------------------------ who needs a code, and where it can go
-- [{ channel, to, masked }] — the channels that can reach this person right now, in the order given in the settings
create or replace function public.login_otp_targets(p_scope text, p_user uuid, p_tenant uuid, p_any boolean default false)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  cfg     jsonb;
  allowed text[];
  n       jsonb;
  ch      text;
  v_to    text;
  v_phone text;
  v_email text;
  out     jsonb := '[]'::jsonb;
  acc     jsonb;
  v_demo  boolean := false;
begin
  select lower(email) into v_email from auth.users where id = p_user;
  if p_scope = 'team' then
    cfg := public.team_otp_config();
    select whatsapp into v_phone from public.platform_alert_prefs where user_id = p_user;
    -- which shared accounts exist: saved in the panel, or the last health check reached them (Edge-secret setups)
    select data into acc from public.platform_settings where key = 'messaging_accounts';
  else
    cfg := public.otp_config(p_tenant) -> 'login';
    select phone into v_phone from public.profiles where id = p_user;
    select data -> 'notifications' into n from public.app_settings where key = 'app' and tenant_id = p_tenant;
    -- demo hospital with codes shown on screen: no channel has to be connected (demo.sql)
    v_demo := to_regprocedure('public.demo_otp_screen(uuid)') is not null and public.demo_otp_screen(p_tenant);
  end if;
  v_phone := right(regexp_replace(coalesce(v_phone, ''), '\D', '', 'g'), 10);
  select coalesce(array_agg(x), '{}') into allowed from jsonb_array_elements_text(
    case when p_any then '["whatsapp","sms","email"]'::jsonb else coalesce(cfg -> 'channels', '[]'::jsonb) end) x
   where x in ('whatsapp', 'sms', 'email');
  foreach ch in array allowed loop
    v_to := case when ch = 'email' then v_email else v_phone end;
    continue when v_to is null or (ch = 'email' and v_to !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$') or (ch <> 'email' and v_to !~ '^[6-9][0-9]{9}$');
    if p_scope = 'team' then
      continue when coalesce(acc ->> ('PLATFORM_' || upper(case when ch = 'whatsapp' then 'whatsapp' else ch end) || '_PROVIDER'), '') = ''
        and not exists (select 1 from public.platform_health_state h where h.service = 'provider:' || ch and h.status in ('ok', 'warn')
                          and h.last_checked_at > now() - interval '7 days');
    else
      continue when coalesce((n -> ch ->> 'enabled')::boolean, false) is not true and not v_demo;
    end if;
    out := out || jsonb_build_array(jsonb_build_object('channel', ch, 'to', v_to, 'masked', public.mask_destination(ch, v_to)));
  end loop;
  return out;
exception when undefined_table then
  return out;   -- an older database without the control-panel tables
end $$;

create or replace function public.login_otp_required(p_scope text, p_user uuid, p_tenant uuid)
returns boolean language plpgsql stable security definer set search_path = public as $$
declare cfg jsonb; v_role text;
begin
  if p_scope = 'team' then
    return coalesce((public.team_otp_config() ->> 'enabled')::boolean, false);
  end if;
  if p_tenant is null then return false; end if;
  cfg := public.otp_config(p_tenant) -> 'login';
  if not coalesce((cfg ->> 'enabled')::boolean, false) then return false; end if;
  select role::text into v_role from public.profiles where id = p_user;
  return not (coalesce(cfg ->> 'roles', 'staff') = 'staff' and v_role = 'patient');
end $$;

-- Has this session passed (or does it not need) the sign-in code? Called by current_tenant() / provider_role().
create or replace function public.login_otp_passed(p_scope text, p_tenant uuid default null)
returns boolean language plpgsql stable security definer set search_path = public as $$
declare uid uuid := auth.uid(); sid text;
begin
  if uid is null then return true; end if;
  if not public.login_otp_required(p_scope, uid, p_tenant) then return true; end if;
  sid := public.jwt_session_id();
  if sid is not null and exists (select 1 from public.login_otp_sessions where session_id = sid and scope = p_scope and user_id = uid) then
    return true;
  end if;
  -- "sign in as user" from the control panel: the admin already proved who they are
  if p_scope = 'hospital' and sid is not null and exists (
       select 1 from public.impersonations i where i.session_id = sid and i.target_id = uid and i.ended_at is null and i.expires_at > now()) then
    return true;
  end if;
  -- nowhere to send a code → never lock the account out
  return jsonb_array_length(public.login_otp_targets(p_scope, uid, p_tenant)) = 0;
exception when undefined_table or undefined_function then
  return true;
end $$;

-- the scope and hospital of the signed-in person (team members first)
create or replace function public.login_otp_scope(out scope text, out tenant uuid)
language plpgsql stable security definer set search_path = public as $$
begin
  if exists (select 1 from public.provider_users where user_id = auth.uid() and active) then
    scope := 'team'; tenant := null;
  else
    scope := 'hospital'; select p.tenant_id into tenant from public.profiles p where p.id = auth.uid();
  end if;
end $$;

-- ------------------------------------------------------------------ the sign-in screen
create or replace function public.login_otp_status()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare s record; v_req boolean; v_ok boolean; t jsonb; sid text := public.jwt_session_id();
begin
  if auth.uid() is null then return null; end if;
  select * into s from public.login_otp_scope();
  v_req := public.login_otp_required(s.scope, auth.uid(), s.tenant);
  t := public.login_otp_targets(s.scope, auth.uid(), s.tenant, not v_req);
  v_ok := sid is not null and exists (select 1 from public.login_otp_sessions where session_id = sid and scope = s.scope and user_id = auth.uid());
  return jsonb_build_object(
    'scope', s.scope, 'required', v_req, 'verified', v_ok,
    'passed', public.login_otp_passed(s.scope, s.tenant),
    'channels', coalesce((select jsonb_agg(jsonb_build_object('channel', x ->> 'channel', 'to', x ->> 'masked')) from jsonb_array_elements(t) x), '[]'::jsonb),
    'impersonation', s.scope = 'hospital' and v_req and not v_ok and public.login_otp_passed(s.scope, s.tenant) and jsonb_array_length(t) > 0);
end $$;

create or replace function public.request_login_otp(p_channel text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  uid     uuid := auth.uid();
  sid     text := public.jwt_session_id();
  s       record;
  v_req   boolean;
  t       jsonb;
  pick    jsonb;
  v_code  text;
  v_id    uuid;
  v_ip    text := public.client_ip_hash();
  v_tpl   jsonb;
  v_name  text;
  n       int;
begin
  if uid is null then raise exception 'Sign in first.' using errcode = '42501'; end if;
  if sid is null then raise exception 'This sign-in has no session — please sign in again.'; end if;
  select * into s from public.login_otp_scope();
  v_req := public.login_otp_required(s.scope, uid, s.tenant);
  t := public.login_otp_targets(s.scope, uid, s.tenant, not v_req);
  select x into pick from jsonb_array_elements(t) x where p_channel is null or x ->> 'channel' = p_channel limit 1;
  if pick is null then
    raise exception 'A code can''t be sent on % right now. Choose another way.', coalesce(p_channel, 'any channel');
  end if;
  if exists (select 1 from public.login_otps where user_id = uid and created_at > now() - interval '30 seconds') then
    raise exception 'Please wait 30 seconds before requesting another code.';
  end if;
  if (select count(*) from public.login_otps where user_id = uid and created_at > now() - interval '1 hour') >= 5 then
    raise exception 'Too many codes requested for this account. Please try again in an hour.';
  end if;
  if v_ip is not null and (select count(*) from public.login_otps where ip_hash = v_ip and created_at > now() - interval '1 hour') >= 10 then
    raise exception 'Too many codes requested from this connection. Please try again in an hour.';
  end if;
  delete from public.login_otps where created_at < now() - interval '2 days';

  v_code := lpad(((('x' || encode(extensions.gen_random_bytes(4), 'hex'))::bit(32)::bigint) % 1000000)::text, 6, '0');
  insert into public.login_otps (user_id, session_id, scope, hospital_id, channel, code_hash, expires_at, ip_hash)
  values (uid, sid, s.scope, s.tenant, pick ->> 'channel', extensions.crypt(v_code, extensions.gen_salt('bf', 6)), now() + interval '10 minutes', v_ip)
  returning id into v_id;
  select full_name into v_name from public.profiles where id = uid;

  if s.scope = 'team' then
    insert into public.platform_outbox (kind, ref_id, channel, recipient, user_id, subject, body, vars)
    values ('otp', v_id, pick ->> 'channel', pick ->> 'to', uid, 'Your sign-in code',
            v_code || ' is your control-panel sign-in code. It is valid for 10 minutes. Do not share it with anyone.',
            jsonb_build_object('code', v_code, 'otp', v_code, 'name', coalesce(v_name, '')));
    n := 1;
  else
    -- the hospital is not visible to this session yet: name it for the queue explicitly
    perform set_config('app.tenant_id', s.tenant::text, true);
    v_tpl := coalesce((select data -> 'notifications' -> 'templates' -> 'login_otp' from public.app_settings where key = 'app' and tenant_id = s.tenant), '{}'::jsonb);
    if coalesce(v_tpl ->> 'text', '') = '' then v_tpl := public.otp_default_template('login_otp') || v_tpl - 'text'; end if;
    if coalesce(v_tpl ->> 'subject', '') = '' then v_tpl := v_tpl || jsonb_build_object('subject', 'Your sign-in code'); end if;
    n := public.notify_enqueue_raw('login_otp', v_tpl, array[pick ->> 'channel'],
           case when pick ->> 'channel' = 'email' then null else pick ->> 'to' end,
           case when pick ->> 'channel' = 'email' then pick ->> 'to' else null end, null,
           jsonb_build_object('code', v_code, 'otp', v_code, 'name', coalesce(v_name, '')), 'login_otps', v_id, null);
    perform set_config('app.tenant_id', '', true);
  end if;
  if s.scope = 'hospital' and public.demo_otp_screen(s.tenant) then   -- demo hospital: the code is shown, not sent
    return jsonb_build_object('sent', true, 'ref', v_id, 'scope', s.scope, 'channel', pick ->> 'channel', 'to', pick ->> 'masked', 'expires_in', 600, 'demo_code', v_code);
  end if;
  return jsonb_build_object('sent', n > 0, 'ref', v_id, 'scope', s.scope, 'channel', pick ->> 'channel', 'to', pick ->> 'masked', 'expires_in', 600);
end $$;

create or replace function public.verify_login_otp(p_code text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare uid uuid := auth.uid(); sid text := public.jwt_session_id(); o public.login_otps;
begin
  if uid is null or sid is null then return jsonb_build_object('ok', false, 'error', 'Please sign in again.'); end if;
  select * into o from public.login_otps where user_id = uid and session_id = sid and verified_at is null
   order by created_at desc limit 1 for update;
  if not found or o.expires_at < now() then
    return jsonb_build_object('ok', false, 'error', 'This code has expired. Please request a new one.');
  end if;
  if o.attempts >= 5 then
    return jsonb_build_object('ok', false, 'error', 'Too many wrong attempts. Please request a new code.');
  end if;
  if coalesce(p_code, '') !~ '^[0-9]{6}$' or o.code_hash <> extensions.crypt(p_code, o.code_hash) then
    update public.login_otps set attempts = attempts + 1 where id = o.id;
    return jsonb_build_object('ok', false, 'error',
      case when o.attempts + 1 >= 5 then 'Too many wrong attempts. Please request a new code.'
           else format('That code is not correct — %s attempt%s left.', 4 - o.attempts, case when 4 - o.attempts = 1 then '' else 's' end) end);
  end if;
  update public.login_otps set verified_at = now() where id = o.id;
  insert into public.login_otp_sessions (session_id, scope, user_id, channel) values (sid, o.scope, uid, o.channel)
  on conflict (session_id, scope) do update set verified_at = now(), user_id = excluded.user_id, channel = excluded.channel;
  delete from public.login_otp_sessions where user_id = uid and verified_at < now() - interval '60 days';
  return jsonb_build_object('ok', true, 'scope', o.scope);
end $$;

-- "Confirm your password" signs in again (a new session): keep the verification of the session it came from, if that
-- session is this user's, verified, and still alive (auth.sessions) — so an admin isn't asked for a code on every
-- risky action. A password alone can't use it: the old session id is only inside the old access token.
create or replace function public.login_otp_carry(p_from_session text)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare uid uuid := auth.uid(); sid text := public.jwt_session_id(); n int := 0; alive boolean := true;
begin
  if uid is null or sid is null or p_from_session is null or p_from_session = sid then return false; end if;
  if to_regclass('auth.sessions') is not null then
    execute 'select exists (select 1 from auth.sessions where id::text = $1 and user_id = $2)' into alive using p_from_session, uid;
  end if;
  if not alive then return false; end if;
  insert into public.login_otp_sessions (session_id, scope, user_id, channel)
  select sid, scope, uid, channel from public.login_otp_sessions
   where session_id = p_from_session and user_id = uid and verified_at > now() - interval '24 hours'
  on conflict (session_id, scope) do nothing;
  get diagnostics n = row_count;
  return n > 0;
end $$;

-- ------------------------------------------------------------------ turning it on safely (hospital Settings)
-- Saving Settings with sign-in OTP switched on (or with a narrower channel list) needs a verified session for whoever
-- saves it — proof that at least their own code arrives. The control panel (team) and the database owner are exempt.
create or replace function public.guard_login_otp_settings()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  was jsonb := case when tg_op = 'UPDATE' then old.data -> 'security' -> 'otp' -> 'login' else null end;
  now_ jsonb := new.data -> 'security' -> 'otp' -> 'login';
  sid text := public.jwt_session_id();
  ch text;
begin
  if new.key <> 'app' or now_ is null then return new; end if;
  if jsonb_typeof(now_) <> 'object' then raise exception 'security.otp.login must be an object'; end if;
  if now_ ? 'channels' then
    if jsonb_typeof(now_ -> 'channels') <> 'array' or jsonb_array_length(now_ -> 'channels') = 0 then
      raise exception 'Choose at least one channel for the sign-in code.';
    end if;
    for ch in select jsonb_array_elements_text(now_ -> 'channels') loop
      if ch not in ('whatsapp', 'sms', 'email') then raise exception 'Unknown OTP channel %', ch; end if;
    end loop;
  end if;
  if coalesce(now_ ->> 'roles', 'staff') not in ('staff', 'all') then raise exception 'security.otp.login.roles must be staff or all'; end if;
  if auth.uid() is null or public.provider_role() is not null then return new; end if;
  if coalesce((now_ ->> 'enabled')::boolean, false) and not coalesce((was ->> 'enabled')::boolean, false)
     and not (sid is not null and exists (select 1 from public.login_otp_sessions where session_id = sid and scope = 'hospital' and user_id = auth.uid())) then
    raise exception 'OTP_SETUP: Verify a code on your own account first (Settings → Security → Send me a code), then switch sign-in OTP on.';
  end if;
  return new;
end $$;
drop trigger if exists trg_guard_login_otp on public.app_settings;
create trigger trg_guard_login_otp before insert or update of data on public.app_settings
  for each row execute function public.guard_login_otp_settings();

-- ------------------------------------------------------------------ control panel
-- Platform settings → Security: the team's own sign-in OTP
create or replace function public.cp_security()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return jsonb_build_object('loginOtp', public.team_otp_config(),
    'team', coalesce((select jsonb_agg(jsonb_build_object('user_id', u.user_id, 'email', a.email, 'role', u.role,
                        'channels', (select coalesce(jsonb_agg(x ->> 'channel'), '[]'::jsonb) from jsonb_array_elements(public.login_otp_targets('team', u.user_id, null)) x))
                        order by a.email)
                      from public.provider_users u join auth.users a on a.id = u.user_id where u.active), '[]'::jsonb));
end $$;

create or replace function public.cp_save_security(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare cur jsonb := public.team_otp_config(); nxt jsonb; ch text; sid text := public.jwt_session_id();
begin
  perform public.cp_require(array['admin']);
  if jsonb_typeof(p -> 'loginOtp') <> 'object' then raise exception 'loginOtp must be an object'; end if;
  nxt := cur || jsonb_strip_nulls(jsonb_build_object('enabled', p -> 'loginOtp' -> 'enabled', 'channels', p -> 'loginOtp' -> 'channels'));
  if jsonb_typeof(nxt -> 'enabled') <> 'boolean' then raise exception 'enabled must be true or false'; end if;
  if jsonb_typeof(nxt -> 'channels') <> 'array' or jsonb_array_length(nxt -> 'channels') = 0 then raise exception 'Choose at least one channel.'; end if;
  for ch in select jsonb_array_elements_text(nxt -> 'channels') loop
    if ch not in ('whatsapp', 'sms', 'email') then raise exception 'Unknown OTP channel %', ch; end if;
  end loop;
  if (nxt ->> 'enabled')::boolean and not (cur ->> 'enabled')::boolean
     and not (sid is not null and exists (select 1 from public.login_otp_sessions where session_id = sid and scope = 'team' and user_id = auth.uid())) then
    raise exception 'OTP_SETUP: Verify a code on your own account first (Send me a code), then switch sign-in OTP on.';
  end if;
  insert into public.platform_settings (key, data, updated_at, updated_by) values ('security', jsonb_build_object('loginOtp', nxt), now(), auth.uid())
  on conflict (key) do update set data = public.platform_settings.data || jsonb_build_object('loginOtp', nxt), updated_at = now(), updated_by = auth.uid();
  perform public.provider_log('settings:security', null, jsonb_build_object('loginOtp', nxt));
  return public.cp_security();
end $$;

-- Hospital → Security: that hospital's OTP switches, edited by the team (admin, or support assigned to it)
create or replace function public.cp_hospital_otp(p_tenant uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare cfg jsonb; n jsonb; staff int; reach int;
begin
  perform public.cp_require(array['admin', 'support']);
  if not public.provider_can(p_tenant) then raise exception 'This hospital is not assigned to you.' using errcode = '42501'; end if;
  cfg := public.otp_config(p_tenant);
  select data -> 'notifications' into n from public.app_settings where key = 'app' and tenant_id = p_tenant;
  select count(*), count(*) filter (where jsonb_array_length(public.login_otp_targets('hospital', p.id, p_tenant)) > 0)
    into staff, reach from public.profiles p
   where p.tenant_id = p_tenant and (coalesce(cfg -> 'login' ->> 'roles', 'staff') = 'all' or p.role::text <> 'patient');
  return jsonb_build_object('otp', cfg, 'locked', coalesce((select t.modules ->> 'security' from public.tenants t where t.id = p_tenant), 'provider') <> 'hospital',
    'channels_on', jsonb_build_object('whatsapp', coalesce((n -> 'whatsapp' ->> 'enabled')::boolean, false),
                                      'sms', coalesce((n -> 'sms' ->> 'enabled')::boolean, false),
                                      'email', coalesce((n -> 'email' ->> 'enabled')::boolean, false)),
    'people', staff, 'reachable', reach);
end $$;

create or replace function public.cp_set_hospital_otp(p_tenant uuid, p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare cur jsonb; nxt jsonb; part text; ch text;
begin
  perform public.cp_require(array['admin', 'support']);
  if not public.provider_can(p_tenant) then raise exception 'This hospital is not assigned to you.' using errcode = '42501'; end if;
  if jsonb_typeof(p) <> 'object' then raise exception 'OTP settings must be an object'; end if;
  cur := public.otp_config(p_tenant);
  nxt := cur;
  foreach part in array array['login', 'booking'] loop
    continue when not p ? part;
    if jsonb_typeof(p -> part) <> 'object' then raise exception '% must be an object', part; end if;
    nxt := jsonb_set(nxt, array[part], (cur -> part) || jsonb_strip_nulls(jsonb_build_object(
      'enabled', p -> part -> 'enabled', 'channels', p -> part -> 'channels', 'roles', case when part = 'login' then p -> part -> 'roles' end)));
    if jsonb_typeof(nxt -> part -> 'enabled') <> 'boolean' then raise exception '%.enabled must be true or false', part; end if;
    if jsonb_typeof(nxt -> part -> 'channels') = 'array' then
      if jsonb_array_length(nxt -> part -> 'channels') = 0 then raise exception 'Choose at least one channel.'; end if;
      for ch in select jsonb_array_elements_text(nxt -> part -> 'channels') loop
        if ch not in ('whatsapp', 'sms', 'email') then raise exception 'Unknown OTP channel %', ch; end if;
      end loop;
    end if;
  end loop;
  if coalesce(nxt -> 'login' ->> 'roles', 'staff') not in ('staff', 'all') then raise exception 'roles must be staff or all'; end if;
  perform set_config('app.tenant_id', p_tenant::text, true);   -- the hospital's own audit trail gets the change
  insert into public.app_settings (tenant_id, key, data) values (p_tenant, 'app', jsonb_build_object('security', jsonb_build_object('otp', nxt)))
  on conflict (tenant_id, key) do update set
    data = public.app_settings.data || jsonb_build_object('security', coalesce(public.app_settings.data -> 'security', '{}'::jsonb) || jsonb_build_object('otp', nxt)),
    updated_at = now(), updated_by = auth.uid();
  perform set_config('app.tenant_id', '', true);
  perform public.provider_log('hospital:otp', p_tenant::text, nxt);
  return public.cp_hospital_otp(p_tenant);
end $$;

-- ------------------------------------------------------------------ who may call what
revoke all on function public.otp_config(uuid), public.team_otp_config(), public.login_otp_targets(text, uuid, uuid, boolean),
  public.login_otp_required(text, uuid, uuid), public.login_otp_scope(), public.guard_login_otp_settings() from public, anon, authenticated;
grant execute on function public.login_otp_passed(text, uuid) to anon, authenticated, service_role;
revoke all on function public.login_otp_status(), public.request_login_otp(text), public.verify_login_otp(text), public.login_otp_carry(text),
  public.cp_security(), public.cp_save_security(jsonb), public.cp_hospital_otp(uuid), public.cp_set_hospital_otp(uuid, jsonb) from public, anon;
grant execute on function public.login_otp_status(), public.request_login_otp(text), public.verify_login_otp(text), public.login_otp_carry(text),
  public.cp_security(), public.cp_save_security(jsonb), public.cp_hospital_otp(uuid), public.cp_set_hospital_otp(uuid, jsonb) to authenticated;


-- =====================================================================================================
--  Demo hospital (Hospital Comrade): one hospital — the original DC Hospital — is a public demo.
--
--  • tenants.is_demo marks it (at most one). supabase/demo-hospital.sql turns the primary hospital into the demo,
--    installs the demo data (demo_seed_data(), generated from scripts/seed) and runs the first reset.
--  • demo_reset(): deletes everything visitors added (patients, bookings, sign-ups, messages …) and loads the demo
--    data again, with dates relative to today. Settings and website content come back from the saved baseline
--    (control panel → Platform settings → Demo → "Save current setup as baseline"), else the defaults.
--    Every night at 03:00 IST (pg_cron) and from the control panel button.
--  • Messages: platform_settings 'demo' decides — otp 'screen' (codes are shown on screen, nothing is sent) or 'real';
--    every other message (confirmations, reminders, invites …) is skipped unless messages = true.
--  • Visitors can't save provider keys or connect domains there. Billing never applies (it is the primary hospital).
--  • Every other hospital is real: none of this touches it.
-- =====================================================================================================

alter table public.tenants add column if not exists is_demo boolean not null default false;
create unique index if not exists tenants_one_demo on public.tenants (is_demo) where is_demo;

create or replace function public.demo_tenant()
returns uuid language sql stable security definer set search_path = public as $$
  select id from public.tenants where is_demo limit 1
$$;

create or replace function public.is_demo_tenant(p_tenant uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select is_demo from public.tenants where id = p_tenant), false)
$$;

-- { otp: 'screen' | 'real', messages: false, logins: true, nightly: true } (+ last_reset_at …, never the baseline)
create or replace function public.demo_config()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('otp', 'screen', 'messages', false, 'logins', true, 'nightly', true)
         || coalesce((select data - 'baseline' from public.platform_settings where key = 'demo'), '{}'::jsonb)
$$;

-- in the demo hospital, are one-time codes shown on screen instead of being sent?
create or replace function public.demo_otp_screen(p_tenant uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_demo_tenant(p_tenant) and coalesce(public.demo_config() ->> 'otp', 'screen') <> 'real'
$$;

-- ------------------------------------------------------------------ messages from the demo hospital
create or replace function public.demo_outbox_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare c jsonb;
begin
  if new.status <> 'pending' or not public.is_demo_tenant(new.tenant_id) then return new; end if;
  c := public.demo_config();
  if new.event in ('otp', 'login_otp') then
    if c ->> 'otp' = 'real' then return new; end if;
    new.status := 'skipped'; new.error := 'Demo hospital: the code is shown on screen, nothing is sent';
    return new;
  end if;
  if coalesce((c ->> 'messages')::boolean, false) then return new; end if;
  new.status := 'skipped'; new.error := 'Demo hospital: messages are not sent';
  return new;
end $$;
drop trigger if exists trg_demo_outbox on public.notification_outbox;
create trigger trg_demo_outbox before insert on public.notification_outbox for each row execute function public.demo_outbox_guard();

-- ------------------------------------------------------------------ things visitors must not change there
-- provider keys (app_secrets) and custom domains: only the platform team (or the database itself) in the demo hospital
create or replace function public.demo_guard_locked()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_t uuid := case when tg_op = 'DELETE' then old.tenant_id else new.tenant_id end;
begin
  if auth.uid() is not null and public.provider_role() is null and public.is_demo_tenant(v_t) then
    raise exception 'This is not available in the demo hospital.' using errcode = '42501';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;
drop trigger if exists trg_demo_locked on public.app_secrets;
create trigger trg_demo_locked before insert or update or delete on public.app_secrets for each row execute function public.demo_guard_locked();
drop trigger if exists trg_demo_locked on public.tenant_domains;
create trigger trg_demo_locked before insert or update or delete on public.tenant_domains for each row execute function public.demo_guard_locked();

-- ------------------------------------------------------------------ reset
-- tables that keep their rows: the hospital itself, platform records about it, keys, domains, people (handled
-- through auth.users so the platform team's own profiles stay)
create or replace function public.demo_keep_tables()
returns text[] language sql immutable as $$
  select array['tenants', 'provider_audit', 'provider_assignments', 'tenant_domains', 'billing_payments', 'billing_credit_notes',
               'wallet_ledger', 'message_usage', 'app_secrets', 'profiles']
$$;

create or replace function public.demo_reset()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v       uuid := public.demo_tenant();
  v_tabs  text[];
  v_left  text[];
  tab     text;
  v_pass  int := 0;
  b       jsonb;
  v_users int;
  v_by    text := (select full_name from public.profiles where id = auth.uid());
  v_sub   text := current_setting('request.jwt.claim.sub', true);
  v_jwt   text := current_setting('request.jwt.claims', true);
begin
  if v is null then raise exception 'No demo hospital is set up. Run supabase/demo-hospital.sql once.'; end if;
  if to_regprocedure('public.demo_seed_data()') is null then
    raise exception 'DEMO_SEED_MISSING: Run supabase/demo-hospital.sql once in the SQL editor (it installs the demo data).';
  end if;
  perform set_config('app.tenant_id', v::text, true);
  perform set_config('app.skip_audit', 'on', true);
  -- run as the database itself (like the SQL editor): role guards and the sign-in OTP gate are for people.
  -- Put back before returning.
  perform set_config('request.jwt.claim.sub', '', true);
  perform set_config('request.jwt.claims', '', true);

  -- everyone who signed up there (and the demo accounts, recreated below) — never the platform team
  with gone as (
    delete from auth.users where id in (select id from public.profiles where tenant_id = v)
      and id not in (select user_id from public.provider_users) returning id)
  select count(*) into v_users from gone;
  delete from public.login_otps where hospital_id = v and scope = 'hospital';

  select array_agg(c.table_name::text order by c.table_name) into v_tabs
    from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name and x.table_type = 'BASE TABLE'
   where c.table_schema = 'public' and c.column_name = 'tenant_id' and c.table_name <> all (public.demo_keep_tables());
  -- children first: retry what a foreign key still holds
  v_left := coalesce(v_tabs, '{}');
  while array_length(v_left, 1) > 0 and v_pass < 8 loop
    v_pass := v_pass + 1;
    v_tabs := v_left; v_left := '{}';
    foreach tab in array v_tabs loop
      begin
        execute format('delete from public.%I where tenant_id = $1', tab) using v;
      exception when foreign_key_violation or restrict_violation then v_left := v_left || tab;
      end;
    end loop;
  end loop;
  if array_length(v_left, 1) > 0 then raise exception 'Could not empty: %', array_to_string(v_left, ', '); end if;

  perform public.demo_seed_data();

  -- settings + website content as saved by the team (else the built-in defaults)
  b := (select data -> 'baseline' from public.platform_settings where key = 'demo');
  if jsonb_typeof(b -> 'app_settings') = 'array' then
    insert into public.app_settings (tenant_id, key, data, updated_at)
    select v, e ->> 'key', coalesce(e -> 'data', '{}'::jsonb), now() from jsonb_array_elements(b -> 'app_settings') e
    on conflict (tenant_id, key) do update set data = excluded.data, updated_at = now();
  end if;
  if jsonb_typeof(b -> 'site_content') = 'array' then
    insert into public.site_content (tenant_id, key, data, updated_at)
    select v, e ->> 'key', coalesce(e -> 'data', '{}'::jsonb), now() from jsonb_array_elements(b -> 'site_content') e
    on conflict (tenant_id, key) do update set data = excluded.data, updated_at = now();
  end if;

  insert into public.platform_settings (key, data, updated_at) values ('demo', jsonb_build_object('last_reset_at', now()), now())
  on conflict (key) do update set data = public.platform_settings.data || jsonb_build_object('last_reset_at', now(),
    'last_reset_by', v_by), updated_at = now();
  perform set_config('app.skip_audit', '', true);
  perform set_config('app.tenant_id', '', true);
  perform set_config('request.jwt.claim.sub', coalesce(v_sub, ''), true);
  perform set_config('request.jwt.claims', coalesce(v_jwt, ''), true);
  return jsonb_build_object('ok', true, 'removed_accounts', v_users, 'at', now());
end $$;

-- the nightly job: only when there is a demo hospital, its data is installed and the team left "every night" on
create or replace function public.demo_reset_nightly()
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  if public.demo_tenant() is null or to_regprocedure('public.demo_seed_data()') is null then return; end if;
  if coalesce((public.demo_config() ->> 'nightly')::boolean, true) is not true then return; end if;
  perform public.demo_reset();
end $$;

-- ------------------------------------------------------------------ what the demo website shows
-- anon: on the demo hospital's own site, its one-click logins (when the team allows) and the reset time
create or replace function public.public_demo_info()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare c jsonb; v_logins jsonb := '[]'::jsonb;
begin
  if not public.is_demo_tenant(public.current_tenant()) then return null; end if;
  c := public.demo_config();
  if coalesce((c ->> 'logins')::boolean, true) and to_regprocedure('public.demo_logins()') is not null then
    execute 'select public.demo_logins()' into v_logins;
  end if;
  return jsonb_build_object('demo', true, 'otp', c ->> 'otp', 'nightly', coalesce((c ->> 'nightly')::boolean, true),
    'resets_at', '03:00 IST', 'last_reset_at', c ->> 'last_reset_at', 'logins', coalesce(v_logins -> 'logins', '[]'::jsonb),
    'password', case when jsonb_array_length(coalesce(v_logins -> 'logins', '[]'::jsonb)) > 0 then v_logins ->> 'password' end);
end $$;

-- ------------------------------------------------------------------ control panel → Platform settings → Demo
create or replace function public.cp_demo()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare t public.tenants; s jsonb; v_logins jsonb;
begin
  perform public.cp_require(array['admin']);
  select * into t from public.tenants where is_demo limit 1;
  select data into s from public.platform_settings where key = 'demo';
  if to_regprocedure('public.demo_logins()') is not null then execute 'select public.demo_logins()' into v_logins; end if;
  return jsonb_build_object(
    'hospital', case when t.id is null then null else jsonb_build_object('id', t.id, 'slug', t.slug, 'name', t.name) end,
    'seed_installed', to_regprocedure('public.demo_seed_data()') is not null,
    'config', public.demo_config() - 'last_reset_at' - 'last_reset_by' - 'baseline_at' - 'baseline_by',
    'last_reset_at', s ->> 'last_reset_at', 'last_reset_by', s ->> 'last_reset_by',
    'baseline', case when s ? 'baseline' then jsonb_build_object('at', s ->> 'baseline_at', 'by', s ->> 'baseline_by',
      'settings', jsonb_array_length(coalesce(s -> 'baseline' -> 'app_settings', '[]')), 'pages', jsonb_array_length(coalesce(s -> 'baseline' -> 'site_content', '[]'))) end,
    'logins', coalesce(v_logins -> 'logins', '[]'::jsonb), 'password', v_logins ->> 'password',
    'scheduled', exists (select 1 from pg_extension where extname = 'pg_cron'));
end $$;

create or replace function public.cp_save_demo(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare nxt jsonb := '{}'::jsonb; k text;
begin
  perform public.cp_require(array['admin']);
  if jsonb_typeof(p) <> 'object' then raise exception 'Demo settings must be an object'; end if;
  if p ? 'otp' then
    if p ->> 'otp' not in ('screen', 'real') then raise exception 'otp must be screen or real'; end if;
    nxt := nxt || jsonb_build_object('otp', p ->> 'otp');
  end if;
  foreach k in array array['messages', 'logins', 'nightly'] loop
    continue when not p ? k;
    if jsonb_typeof(p -> k) <> 'boolean' then raise exception '% must be true or false', k; end if;
    nxt := nxt || jsonb_build_object(k, p -> k);
  end loop;
  insert into public.platform_settings (key, data, updated_at, updated_by) values ('demo', nxt, now(), auth.uid())
  on conflict (key) do update set data = public.platform_settings.data || nxt, updated_at = now(), updated_by = auth.uid();
  if coalesce((p ->> 'clearBaseline')::boolean, false) then
    update public.platform_settings set data = data - 'baseline' - 'baseline_at' - 'baseline_by' where key = 'demo';
  end if;
  perform public.provider_log('settings:demo', null, p);
  return public.cp_demo();
end $$;

create or replace function public.cp_demo_reset()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare r jsonb;
begin
  perform public.cp_require(array['admin']);
  r := public.demo_reset();
  perform public.provider_log('demo:reset', null, r);
  return public.cp_demo();
end $$;

-- keep the demo hospital's current settings + website content; every reset restores them
create or replace function public.cp_demo_save_baseline()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v uuid := public.demo_tenant(); b jsonb;
begin
  perform public.cp_require(array['admin']);
  if v is null then raise exception 'No demo hospital is set up.'; end if;
  b := jsonb_build_object(
    'app_settings', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'data', data)) from public.app_settings where tenant_id = v and key <> 'bootstrap'), '[]'::jsonb),
    'site_content', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'data', data)) from public.site_content where tenant_id = v), '[]'::jsonb));
  insert into public.platform_settings (key, data, updated_at, updated_by) values ('demo', '{}'::jsonb, now(), auth.uid()) on conflict (key) do nothing;
  update public.platform_settings set data = data || jsonb_build_object('baseline', b, 'baseline_at', now(),
    'baseline_by', (select full_name from public.profiles where id = auth.uid())), updated_at = now(), updated_by = auth.uid() where key = 'demo';
  perform public.provider_log('demo:baseline', null, jsonb_build_object('settings', jsonb_array_length(b -> 'app_settings'), 'pages', jsonb_array_length(b -> 'site_content')));
  return public.cp_demo();
end $$;

revoke all on function public.demo_tenant(), public.is_demo_tenant(uuid), public.demo_config(), public.demo_otp_screen(uuid),
  public.demo_reset(), public.demo_reset_nightly(), public.demo_keep_tables() from public, anon, authenticated;
grant execute on function public.demo_reset(), public.demo_reset_nightly() to service_role;
revoke all on function public.public_demo_info() from public;
grant execute on function public.public_demo_info() to anon, authenticated;
revoke all on function public.cp_demo(), public.cp_save_demo(jsonb), public.cp_demo_reset(), public.cp_demo_save_baseline() from public, anon;
grant execute on function public.cp_demo(), public.cp_save_demo(jsonb), public.cp_demo_reset(), public.cp_demo_save_baseline() to authenticated;

-- every night at 03:00 IST (21:30 UTC), when pg_cron is on
do $$
declare j bigint;
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    for j in execute $q$ select jobid from cron.job where jobname = 'dch-demo-reset' $q$ loop
      execute 'select cron.unschedule($1)' using j;
    end loop;
    execute $c$ select cron.schedule('dch-demo-reset', '30 21 * * *', 'select public.demo_reset_nightly()') $c$;
  end if;
exception when others then null;   -- no permission for cron here: the control panel button still works
end $$;


-- =====================================================================================================
--  14. GO-LIVE DEFAULTS
-- =====================================================================================================
-- ✏️  The first account created with this e-mail becomes the hospital Owner:
insert into public.app_settings (key, data) values ('bootstrap', jsonb_build_object('owner_email', 'owner@your-hospital.in'))
on conflict (tenant_id, key) do update set data = excluded.data;

-- an existing account with that e-mail (created before running this file) is promoted right away
update public.profiles set role = 'owner'
where lower(email) = lower((select data ->> 'owner_email' from public.app_settings where key = 'bootstrap'))
  and not exists (select 1 from public.profiles where role = 'owner');

commit;

-- Done ✔  —  Now create your account with the e-mail you set above.
